-- ============================================================================
-- HUNTER — AUTOPROVISIONAMENTO DE PROFILES VIA TRIGGER AUTH.USERS
-- ============================================================================
-- Cria automaticamente o registro em public.profiles e public.user_roles
-- quando um novo usuário é cadastrado no Supabase Auth.
-- Blindagem canônica: se o email for 'novaes@adm.28bpm.local', atribui 'superadmin'.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role public.hunter_role;
  v_nome TEXT;
BEGIN
  -- Identifica se é o SuperAdmin mestre
  IF LOWER(NEW.email) = 'novaes@adm.28bpm.local' THEN
    v_role := 'superadmin'::public.hunter_role;
    v_nome := COALESCE(NEW.raw_user_meta_data->>'nome', 'SuperAdmin Hunter (Novaes)');
  ELSE
    v_role := COALESCE(NEW.raw_user_meta_data->>'role', 'cliente')::public.hunter_role;
    v_nome := COALESCE(NEW.raw_user_meta_data->>'nome', split_part(NEW.email, '@', 1));
  END IF;

  -- 1. Cria ou atualiza o perfil em public.profiles
  INSERT INTO public.profiles (id, nome, email, role, ativo)
  VALUES (NEW.id, v_nome, LOWER(NEW.email), v_role, TRUE)
  ON CONFLICT (id) DO UPDATE
  SET nome = EXCLUDED.nome,
      email = EXCLUDED.email;

  -- 2. Vincula a role na tabela user_roles
  INSERT INTO public.user_roles (user_id, role)
  VALUES (NEW.id, v_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  RETURN NEW;
END;
$$;

-- Registra o trigger após INSERT em auth.users
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- ─────────────────────────────────────────────────────────────────────────────
-- BACKFILL: Se algum usuário já foi criado em auth.users (ex: novaes), popula profiles
-- ─────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  r RECORD;
  v_role public.hunter_role;
  v_nome TEXT;
BEGIN
  FOR r IN SELECT id, email, raw_user_meta_data FROM auth.users LOOP
    IF LOWER(r.email) = 'novaes@adm.28bpm.local' THEN
      v_role := 'superadmin'::public.hunter_role;
      v_nome := COALESCE(r.raw_user_meta_data->>'nome', 'SuperAdmin Hunter (Novaes)');
    ELSE
      v_role := COALESCE(r.raw_user_meta_data->>'role', 'cliente')::public.hunter_role;
      v_nome := COALESCE(r.raw_user_meta_data->>'nome', split_part(r.email, '@', 1));
    END IF;

    INSERT INTO public.profiles (id, nome, email, role, ativo)
    VALUES (r.id, v_nome, LOWER(r.email), v_role, TRUE)
    ON CONFLICT (id) DO UPDATE
    SET role = CASE WHEN LOWER(r.email) = 'novaes@adm.28bpm.local' THEN 'superadmin'::public.hunter_role ELSE public.profiles.role END;

    INSERT INTO public.user_roles (user_id, role)
    VALUES (r.id, v_role)
    ON CONFLICT (user_id, role) DO NOTHING;
  END LOOP;
END $$;


-- ============================================================================
-- [3/225] MIGRAÇÃO: 20260918180000_hunter_sigovtr_usuarios_seguranca.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — MIGRAÇÃO SIGOVTR: GESTÃO DE USUÁRIOS, TEMAS E CENTRAL DE SEGURANÇA
-- ============================================================================
-- Diretrizes: DJR-NEW, DJR-APP & DJR-TELA
-- ============================================================================

-- 1. ADICIONAR PREFERÊNCIA DE TEMA EM PROFILES
ALTER TABLE public.profiles 
ADD COLUMN IF NOT EXISTS theme_preference TEXT NOT NULL DEFAULT 'dark';

-- 2. GARANTIR EXTENSÃO PGCRYPTO
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 3. RPC: CADASTRAR USUÁRIO PELO ADMINISTRADOR (PADRÃO SIGOVTR)
CREATE OR REPLACE FUNCTION public.admin_cadastrar_usuario(
  p_nome TEXT,
  p_email TEXT,
  p_senha TEXT,
  p_role public.hunter_role,
  p_modulos TEXT[] DEFAULT ARRAY[]::TEXT[],
  p_plano public.plano_cliente DEFAULT 'basico'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_caller_id UUID := auth.uid();
  v_mod TEXT;
  v_encrypted_pw TEXT;
BEGIN
  -- 1. Validação de privilégio administrativo
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem cadastrar usuarios.';
  END IF;

  -- 2. Validação dos campos obrigatórios
  IF p_nome IS NULL OR trim(p_nome) = '' THEN
    RAISE EXCEPTION 'O nome do usuario e obrigatorio.';
  END IF;

  IF p_email IS NULL OR trim(p_email) = '' THEN
    RAISE EXCEPTION 'O e-mail do usuario e obrigatorio.';
  END IF;

  IF p_senha IS NULL OR length(p_senha) < 6 THEN
    RAISE EXCEPTION 'A senha inicial deve conter pelo menos 6 caracteres.';
  END IF;

  -- 3. Verifica se e-mail já existe
  IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = LOWER(trim(p_email))) THEN
    RAISE EXCEPTION 'Ja existe um usuario cadastrado com este e-mail.';
  END IF;

  -- 4. Criação do usuário em auth.users
  v_user_id := gen_random_uuid();
  v_encrypted_pw := crypt(p_senha, gen_salt('bf', 10));

  INSERT INTO auth.users (
    instance_id,
    id,
    aud,
    role,
    email,
    encrypted_password,
    email_confirmed_at,
    raw_app_meta_data,
    raw_user_meta_data,
    created_at,
    updated_at
  )
  VALUES (
    '00000000-0000-0000-0000-000000000000',
    v_user_id,
    'authenticated',
    'authenticated',
    LOWER(trim(p_email)),
    v_encrypted_pw,
    now(),
    '{"provider":"email","providers":["email"]}',
    jsonb_build_object('nome', p_nome, 'role', p_role),
    now(),
    now()
  );

  -- 5. Perfil em public.profiles (garante caso o trigger não tenha rodado)
  INSERT INTO public.profiles (id, nome, email, role, ativo, theme_preference)
  VALUES (v_user_id, p_nome, LOWER(trim(p_email)), p_role, TRUE, 'dark')
  ON CONFLICT (id) DO UPDATE
  SET nome = EXCLUDED.nome,
      email = EXCLUDED.email,
      role = EXCLUDED.role,
      ativo = TRUE;

  -- 6. Role em public.user_roles
  INSERT INTO public.user_roles (user_id, role)
  VALUES (v_user_id, p_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  -- 7. Módulos concedidos em public.user_module_access
  IF p_modulos IS NOT NULL AND array_length(p_modulos, 1) > 0 THEN
    FOREACH v_mod IN ARRAY p_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_user_id, trim(v_mod), TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  -- 8. Se for cliente, cria registro vinculado em public.clientes
  IF p_role = 'cliente' THEN
    INSERT INTO public.clientes (user_id, nome_razao_social, email, plano, status)
    VALUES (v_user_id, p_nome, LOWER(trim(p_email)), COALESCE(p_plano, 'basico'), 'ativo');
  END IF;

  -- 9. Registro de auditoria forense
  INSERT INTO public.system_activity_logs (usuario_id, acao, detalhe)
  VALUES (
    v_caller_id,
    'CADASTRO_USUARIO',
    'Usuario criado: ' || p_nome || ' (' || LOWER(trim(p_email)) || ') com perfil ' || p_role
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'user_id', v_user_id,
    'message', 'Usuario cadastrado com sucesso.'
  );
END;
$$;

-- 4. RPC: ATUALIZAR USUÁRIO (NOME, ROLE, STATUS, MÓDULOS)
CREATE OR REPLACE FUNCTION public.admin_atualizar_usuario(
  p_user_id UUID,
  p_nome TEXT,
  p_role public.hunter_role,
  p_ativo BOOLEAN,
  p_modulos TEXT[],
  p_plano public.plano_cliente DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_email TEXT;
  v_mod TEXT;
BEGIN
  -- 1. Validação de privilégio
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem alterar usuarios.';
  END IF;

  SELECT email INTO v_user_email FROM public.profiles WHERE id = p_user_id;

  -- 2. Blindagem inegociável do SuperAdmin
  IF LOWER(v_user_email) = 'novaes@adm.28bpm.local' THEN
    IF p_role <> 'superadmin' OR p_ativo = FALSE THEN
      RAISE EXCEPTION 'A conta SuperAdmin mestre e imutavel e nao pode ter perfil ou status alterados.';
    END IF;
  END IF;

  -- 3. Atualiza perfil
  UPDATE public.profiles
  SET nome = p_nome,
      role = p_role,
      ativo = p_ativo,
      updated_at = now()
  WHERE id = p_user_id;

  -- 4. Atualiza role
  DELETE FROM public.user_roles WHERE user_id = p_user_id;
  INSERT INTO public.user_roles (user_id, role) VALUES (p_user_id, p_role);

  -- 5. Atualiza módulos
  DELETE FROM public.user_module_access WHERE user_id = p_user_id;
  IF p_modulos IS NOT NULL AND array_length(p_modulos, 1) > 0 THEN
    FOREACH v_mod IN ARRAY p_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (p_user_id, trim(v_mod), TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  -- 6. Se for cliente, atualiza plano se informado
  IF p_role = 'cliente' AND p_plano IS NOT NULL THEN
    UPDATE public.clientes
    SET plano = p_plano, updated_at = now()
    WHERE user_id = p_user_id;
  END IF;

  -- 7. Log de auditoria
  INSERT INTO public.system_activity_logs (usuario_id, acao, detalhe)
  VALUES (
    v_caller_id,
    'ATUALIZACAO_USUARIO',
    'Usuario atualizado: ' || p_nome || ' (' || v_user_email || ') - Role: ' || p_role || ' - Ativo: ' || p_ativo
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Usuario atualizado com sucesso.'
  );
END;
$$;

-- 5. RPC: REDEFINIR SENHA DO USUÁRIO
CREATE OR REPLACE FUNCTION public.admin_redefinir_senha(
  p_user_id UUID,
  p_nova_senha TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_email TEXT;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem redefinir senhas.';
  END IF;

  IF p_nova_senha IS NULL OR length(p_nova_senha) < 6 THEN
    RAISE EXCEPTION 'A nova senha deve conter pelo menos 6 caracteres.';
  END IF;

  SELECT email INTO v_user_email FROM public.profiles WHERE id = p_user_id;

  -- Atualiza a senha em auth.users
  UPDATE auth.users
  SET encrypted_password = crypt(p_nova_senha, gen_salt('bf', 10)),
      updated_at = now()
  WHERE id = p_user_id;

  -- Log de auditoria
  INSERT INTO public.system_activity_logs (usuario_id, acao, detalhe)
  VALUES (
    v_caller_id,
    'REDEFINICAO_SENHA',
    'Senha redefinida pelo administrador para o usuario: ' || v_user_email
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Senha redefinida com sucesso.'
  );
END;
$$;

-- 6. RPC: EXCLUIR USUÁRIO
CREATE OR REPLACE FUNCTION public.admin_excluir_usuario(
  p_user_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_email TEXT;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem excluir usuarios.';
  END IF;

  SELECT email INTO v_user_email FROM public.profiles WHERE id = p_user_id;

  IF LOWER(v_user_email) = 'novaes@adm.28bpm.local' THEN
    RAISE EXCEPTION 'A conta SuperAdmin mestre e imutavel e nao pode ser excluida.';
  END IF;

  -- Exclui em cascade de auth.users (removerá profiles, roles e modules por FK cascade)
  DELETE FROM auth.users WHERE id = p_user_id;

  -- Log de auditoria
  INSERT INTO public.system_activity_logs (usuario_id, acao, detalhe)
  VALUES (
    v_caller_id,
    'EXCLUSAO_USUARIO',
    'Usuario excluido: ' || v_user_email
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Usuario removido com sucesso.'
  );
END;
$$;

-- 7. RPC: SALVAR PREFERÊNCIA DE TEMA DO USUÁRIO
CREATE OR REPLACE FUNCTION public.salvar_preferencia_tema(
  p_tema TEXT
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
BEGIN
  IF auth.uid() IS NOT NULL THEN
    UPDATE public.profiles
    SET theme_preference = p_tema,
        updated_at = now()
    WHERE id = auth.uid();
  END IF;
END;
$$;


-- ============================================================================
-- [4/225] MIGRAÇÃO: 20260919110000_hunter_telemetria_3d_acidentes.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — MIGRAÇÃO DE TELEMETRIA AVANÇADA, CICLO DE IGNIÇÃO E ALERTAS DE ACIDENTE
-- ============================================================================
-- Diretrizes: DJR-NEW & DJR-APP
-- Versão Alvo: 1.2.0.0
-- ============================================================================

-- 1. Colunas adicionais de sensores físicos na tabela telemetria_posicoes
DO $$ BEGIN
  ALTER TABLE public.telemetria_posicoes ADD COLUMN IF NOT EXISTS inclinacao_graus INT DEFAULT 0;
  ALTER TABLE public.telemetria_posicoes ADD COLUMN IF NOT EXISTS vibracao_g NUMERIC(4,2) DEFAULT 0.00;
  ALTER TABLE public.telemetria_posicoes ADD COLUMN IF NOT EXISTS alerta_acidente BOOLEAN DEFAULT FALSE;
  ALTER TABLE public.telemetria_posicoes ADD COLUMN IF NOT EXISTS alerta_tipo TEXT;
EXCEPTION
  WHEN duplicate_column THEN NULL;
END $$;

-- 2. Tabela de Alertas de Segurança e Acidentes (Impacto, Capotamento e Colisão)
CREATE TABLE IF NOT EXISTS public.alertas_seguranca (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  veiculo_id UUID NOT NULL REFERENCES public.veiculos(id) ON DELETE CASCADE,
  cliente_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,
  tipo TEXT NOT NULL, -- 'colisao_impacto', 'capotamento_inclinacao', 'parada_repentina_colisao'
  gravidade TEXT NOT NULL DEFAULT 'alta', -- 'critica', 'alta', 'media'
  latitude DOUBLE PRECISION NOT NULL,
  longitude DOUBLE PRECISION NOT NULL,
  velocidade INT NOT NULL DEFAULT 0,
  vibracao_g NUMERIC(4,2) DEFAULT 0.00,
  inclinacao_graus INT DEFAULT 0,
  detalhes TEXT NOT NULL,
  reconhecido BOOLEAN NOT NULL DEFAULT FALSE,
  reconhecido_por UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  reconhecido_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_alertas_veiculo ON public.alertas_seguranca(veiculo_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_alertas_cliente ON public.alertas_seguranca(cliente_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_alertas_reconhecido ON public.alertas_seguranca(reconhecido);

-- 3. Função Auxiliar de Verificação de Privilégio Administrativo
CREATE OR REPLACE FUNCTION public.is_admin_or_superadmin(p_user_id UUID DEFAULT auth.uid())
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles 
    WHERE user_id = COALESCE(p_user_id, auth.uid()) AND role IN ('superadmin', 'adm')
  ) OR EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = COALESCE(p_user_id, auth.uid()) AND role IN ('superadmin', 'adm')
  );
$$;

-- 4. Habilitação de RLS na tabela alertas_seguranca
ALTER TABLE public.alertas_seguranca ENABLE ROW LEVEL SECURITY;

-- 5. Políticas de RLS em alertas_seguranca
DROP POLICY IF EXISTS "Alertas visiveis para administradores e operadores" ON public.alertas_seguranca;
CREATE POLICY "Alertas visiveis para administradores e operadores"
ON public.alertas_seguranca FOR SELECT TO authenticated
USING (
  public.is_admin_or_superadmin(auth.uid()) OR
  EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'operador')
);

DROP POLICY IF EXISTS "Alertas visiveis para o cliente proprietario do veiculo" ON public.alertas_seguranca;
CREATE POLICY "Alertas visiveis para o cliente proprietario do veiculo"
ON public.alertas_seguranca FOR SELECT TO authenticated
USING (
  cliente_id IN (SELECT id FROM public.clientes WHERE user_id = auth.uid())
);

DROP POLICY IF EXISTS "Administradores podem gerenciar alertas" ON public.alertas_seguranca;
CREATE POLICY "Administradores podem gerenciar alertas"
ON public.alertas_seguranca FOR ALL TO authenticated
USING (
  public.is_admin_or_superadmin(auth.uid()) OR
  EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'operador')
);

-- 5. RPC para Reconhecimento Operacional do Alerta
CREATE OR REPLACE FUNCTION public.reconhecer_alerta_seguranca(
  p_alerta_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Não autenticado.';
  END IF;

  UPDATE public.alertas_seguranca
  SET
    reconhecido = TRUE,
    reconhecido_por = v_user_id,
    reconhecido_at = NOW()
  WHERE id = p_alerta_id;

  RETURN jsonb_build_object('sucesso', true, 'alerta_id', p_alerta_id);
END;
$$;

-- 6. Função para Processamento de Telemetria e Ciclo de Ignição / Viagem
-- Ao ligar e desligar o veículo, gera 1 evento completo de viagem com velocidade média e km rodado
CREATE OR REPLACE FUNCTION public.processar_telemetria_veiculo(
  p_veiculo_id UUID,
  p_latitude DOUBLE PRECISION,
  p_longitude DOUBLE PRECISION,
  p_velocidade INT,
  p_ignicao BOOLEAN,
  p_odometro INT DEFAULT NULL,
  p_inclinacao INT DEFAULT 0,
  p_vibracao NUMERIC DEFAULT 0.00,
  p_rumo INT DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_veiculo RECORD;
  v_viagem_aberta RECORD;
  v_novo_odometro INT;
  v_distancia_km NUMERIC(8,2) := 0.00;
  v_alerta_gerado BOOLEAN := FALSE;
  v_tipo_alerta TEXT := NULL;
  v_detalhe_alerta TEXT := NULL;
BEGIN
  -- Busca estado atual do veículo
  SELECT id, cliente_id, ignicao_status, velocidade_atual, odometro_km, ultima_latitude, ultima_longitude
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Veículo não encontrado.';
  END IF;

  v_novo_odometro := COALESCE(p_odometro, v_veiculo.odometro_km);

  -- 6.1. Detecção de Anomalias Físicas e Acidentes
  -- Regra 1: Inclinação >= 45 graus (Capotamento ou Tombamento)
  IF p_inclinacao >= 45 THEN
    v_alerta_gerado := TRUE;
    v_tipo_alerta := 'capotamento_inclinacao';
    v_detalhe_alerta := format('Inclinação crítica de %s graus detectada com veículo a %s km/h.', p_inclinacao, p_velocidade);
  
  -- Regra 2: Vibração / Choque extremo >= 2.5G (Impacto Severo / Colisão)
  ELSIF p_vibracao >= 2.50 THEN
    v_alerta_gerado := TRUE;
    v_tipo_alerta := 'colisao_impacto';
    v_detalhe_alerta := format('Força G extrema de %sG detectada com veículo a %s km/h.', p_vibracao, p_velocidade);

  -- Regra 3: Parada repentina de alta velocidade (>= 35 km/h para 0 km/h) com indício de choque
  ELSIF v_veiculo.velocidade_atual >= 35 AND p_velocidade = 0 AND p_vibracao >= 1.50 THEN
    v_alerta_gerado := TRUE;
    v_tipo_alerta := 'parada_repentina_colisao';
    v_detalhe_alerta := format('Desaceleração violenta de %s km/h para 0 km/h com choque de %sG.', v_veiculo.velocidade_atual, p_vibracao);
  END IF;

  -- Se houve alerta crítico, insere em alertas_seguranca
  IF v_alerta_gerado THEN
    INSERT INTO public.alertas_seguranca (
      veiculo_id,
      cliente_id,
      tipo,
      gravidade,
      latitude,
      longitude,
      velocidade,
      vibracao_g,
      inclinacao_graus,
      detalhes
    ) VALUES (
      p_veiculo_id,
      v_veiculo.cliente_id,
      v_tipo_alerta,
      'critica',
      p_latitude,
      p_longitude,
      p_velocidade,
      p_vibracao,
      p_inclinacao,
      v_detalhe_alerta
    );
  END IF;

  -- 6.2. Registro do Ponto Histórico na Telemetria
  INSERT INTO public.telemetria_posicoes (
    veiculo_id,
    latitude,
    longitude,
    velocidade,
    ignicao,
    odometro,
    rumo,
    inclinacao_graus,
    vibracao_g,
    alerta_acidente,
    alerta_tipo,
    data_hora_gps
  ) VALUES (
    p_veiculo_id,
    p_latitude,
    p_longitude,
    p_velocidade,
    p_ignicao,
    v_novo_odometro,
    p_rumo,
    p_inclinacao,
    p_vibracao,
    v_alerta_gerado,
    v_tipo_alerta,
    NOW()
  );

  -- 6.3. Gerenciamento do Ciclo de Ignição e Eventos de Viagem
  -- Caso A: Ignição acabou de ser ligada (transição de FALSE para TRUE)
  IF NOT v_veiculo.ignicao_status AND p_ignicao THEN
    -- Inicia novo registro consolidado de viagem
    INSERT INTO public.viagens_trajetos (
      veiculo_id,
      inicio_at,
      fim_at,
      km_percorrido,
      velocidade_media,
      velocidade_maxima,
      status
    ) VALUES (
      p_veiculo_id,
      NOW(),
      NULL,
      0.00,
      p_velocidade,
      p_velocidade,
      'em_andamento'
    );

  -- Caso B: Ignição acabou de ser desligada (transição de TRUE para FALSE)
  ELSIF v_veiculo.ignicao_status AND NOT p_ignicao THEN
    -- Localiza a viagem em aberto mais recente
    SELECT id, inicio_at, km_percorrido, velocidade_media, velocidade_maxima
    INTO v_viagem_aberta
    FROM public.viagens_trajetos
    WHERE veiculo_id = p_veiculo_id AND status = 'em_andamento'
    ORDER BY inicio_at DESC
    LIMIT 1;

    IF FOUND THEN
      -- Calcula a distância percorrida com base nos pontos daquela viagem
      SELECT
        COALESCE(MAX(odometro) - MIN(odometro), 0),
        COALESCE(ROUND(AVG(velocidade)), 0),
        COALESCE(MAX(velocidade), 0)
      INTO v_distancia_km, v_viagem_aberta.velocidade_media, v_viagem_aberta.velocidade_maxima
      FROM public.telemetria_posicoes
      WHERE veiculo_id = p_veiculo_id
        AND data_hora_gps >= v_viagem_aberta.inicio_at;

      UPDATE public.viagens_trajetos
      SET
        fim_at = NOW(),
        km_percorrido = GREATEST(v_distancia_km, 0.00),
        velocidade_media = v_viagem_aberta.velocidade_media,
        velocidade_maxima = v_viagem_aberta.velocidade_maxima,
        status = 'concluida'
      WHERE id = v_viagem_aberta.id;
    END IF;

  -- Caso C: Veículo continua em movimento com ignição ligada
  ELSIF p_ignicao THEN
    -- Atualiza velocidade máxima da viagem corrente
    UPDATE public.viagens_trajetos
    SET
      velocidade_maxima = GREATEST(velocidade_maxima, p_velocidade)
    WHERE veiculo_id = p_veiculo_id AND status = 'em_andamento';
  END IF;

  -- 6.4. Atualização do Cadastro do Veículo
  UPDATE public.veiculos
  SET
    ignicao_status = p_ignicao,
    velocidade_atual = p_velocidade,
    odometro_km = v_novo_odometro,
    ultima_latitude = p_latitude,
    ultima_longitude = p_longitude,
    ultima_atualizacao = NOW()
  WHERE id = p_veiculo_id;

  RETURN jsonb_build_object(
    'sucesso', true,
    'veiculo_id', p_veiculo_id,
    'alerta_gerado', v_alerta_gerado,
    'tipo_alerta', v_tipo_alerta
  );
END;
$$;


