  END IF;

  -- 4. Se for adm ou superadmin, todos os módulos devem ser liberados automaticamente
  IF p_role IN ('superadmin', 'adm') THEN
    v_modulos_finais := v_modulos_todos;
  ELSE
    v_modulos_finais := p_modulos;
  END IF;

  -- 5. Verifica se já existe em auth.users
  IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = LOWER(trim(p_email))) THEN
    RAISE EXCEPTION 'Ja existe um usuario cadastrado com este e-mail.';
  END IF;

  -- 6. Cria conta em auth.users usando extensions.crypt e extensions.gen_salt
  v_user_id := gen_random_uuid();
  INSERT INTO auth.users (
    id, instance_id, aud, role, email, encrypted_password,
    email_confirmed_at, recovery_sent_at, last_sign_in_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, email_change, email_change_token_new, recovery_token
  ) VALUES (
    v_user_id,
    '00000000-0000-0000-0000-000000000000',
    'authenticated',
    'authenticated',
    LOWER(trim(p_email)),
    extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
    now(), now(), now(),
    '{"provider":"email","providers":["email"]}',
    jsonb_build_object('nome', p_nome, 'role', p_role),
    now(), now(),
    '', '', '', ''
  );

  -- 7. Atualiza ou insere perfil em public.profiles
  INSERT INTO public.profiles (id, nome, email, role, ativo)
  VALUES (v_user_id, p_nome, LOWER(trim(p_email)), p_role, TRUE)
  ON CONFLICT (id) DO UPDATE
  SET nome = EXCLUDED.nome,
      role = EXCLUDED.role,
      ativo = TRUE,
      updated_at = now();

  -- 8. Registra role em public.user_roles
  INSERT INTO public.user_roles (user_id, role)
  VALUES (v_user_id, p_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  -- 9. Atribui módulos permitidos
  IF v_modulos_finais IS NOT NULL AND array_length(v_modulos_finais, 1) > 0 THEN
    FOREACH v_mod IN ARRAY v_modulos_finais LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_user_id, trim(v_mod), TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  -- 10. Se for cliente, cria registro vinculado em public.clientes
  IF p_role = 'cliente' THEN
    INSERT INTO public.clientes (user_id, nome_razao_social, email, plano, status)
    VALUES (v_user_id, p_nome, LOWER(trim(p_email)), COALESCE(p_plano, 'basico'), 'ativo');
  END IF;

  -- 11. Registro de auditoria forense (compatível com user_id e usuario_id)
  INSERT INTO public.system_activity_logs (user_id, usuario_id, acao, detalhe)
  VALUES (
    v_caller_id,
    v_caller_id,
    'CADASTRO_USUARIO',
    'Usuario criado: ' || p_nome || ' (' || LOWER(trim(p_email)) || ') com perfil ' || p_role
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'user_id', v_user_id,
    'message', 'Usuario cadastrado com sucesso.'
  );
END;
$$;

-- 2. Atualização da RPC: admin_redefinir_senha com extensions no search_path e chamada qualificada
CREATE OR REPLACE FUNCTION public.admin_redefinir_senha(
  p_user_id UUID,
  p_nova_senha TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_email TEXT;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem redefinir senhas.';
  END IF;

  IF p_nova_senha IS NULL OR length(p_nova_senha) < 6 THEN
    RAISE EXCEPTION 'A nova senha deve conter pelo menos 6 caracteres.';
  END IF;

  SELECT email INTO v_user_email FROM public.profiles WHERE id = p_user_id;

  -- Atualiza a senha em auth.users usando extensions.crypt e extensions.gen_salt
  UPDATE auth.users
  SET encrypted_password = extensions.crypt(p_nova_senha, extensions.gen_salt('bf', 10)),
      updated_at = now()
  WHERE id = p_user_id;

  -- Log de auditoria (compatível com user_id e usuario_id)
  INSERT INTO public.system_activity_logs (user_id, usuario_id, acao, detalhe)
  VALUES (
    v_caller_id,
    v_caller_id,
    'REDEFINICAO_SENHA',
    'Senha redefinida pelo administrador para o usuario: ' || v_user_email
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Senha redefinida com sucesso.'
  );
END;
$$;


-- ============================================================================
-- [8/225] MIGRAÇÃO: 20260919160000_hunter_telemetria_bateria_carro_e_rastreador.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — TELEMETRIA REAL DE BATERIA DO VEÍCULO E BATERIA INTERNA DO RASTREADOR
-- ============================================================================
-- Padrão: Manual do Rastreador J16 4G (Protocolo Concox / GT06 / Jimi IoT)
-- Bateria do Carro: Alimentação Externa VCC (9V a 90V DC) -> Volts
-- Bateria do Rastreador: Bateria Interna de Backup (3.7V Li-ion) -> Percentual (0-100%)
-- Regra Pétrea: Nenhuma informação inventada. Null/Ausente = Não Informado.
-- ============================================================================

-- 1. Colunas na tabela public.veiculos
DO $$ BEGIN
  -- Bateria principal do carro (Voltagem em Volts, ex: 12.6V, 13.8V, 24.0V)
  ALTER TABLE public.veiculos ADD COLUMN IF NOT EXISTS voltagem NUMERIC(4, 1);
  ALTER TABLE public.veiculos ADD COLUMN IF NOT EXISTS bateria_veiculo_v NUMERIC(4, 1);

  -- Bateria interna de backup do rastreador J16 (0 a 100%)
  ALTER TABLE public.veiculos ADD COLUMN IF NOT EXISTS bateria_rastreador_pct INT;
  ALTER TABLE public.veiculos ADD COLUMN IF NOT EXISTS bateria_rastreador_status TEXT;

  -- Sensores complementares do J16
  ALTER TABLE public.veiculos ADD COLUMN IF NOT EXISTS satelites INT DEFAULT 0;
  ALTER TABLE public.veiculos ADD COLUMN IF NOT EXISTS rumo INT DEFAULT 0;
  ALTER TABLE public.veiculos ADD COLUMN IF NOT EXISTS inclinacao_graus INT DEFAULT 0;
  ALTER TABLE public.veiculos ADD COLUMN IF NOT EXISTS vibracao_g NUMERIC(4,2) DEFAULT 0.00;
  ALTER TABLE public.veiculos ADD COLUMN IF NOT EXISTS alerta_acidente BOOLEAN DEFAULT FALSE;
  ALTER TABLE public.veiculos ADD COLUMN IF NOT EXISTS alerta_tipo TEXT;
EXCEPTION
  WHEN duplicate_column THEN NULL;
END $$;

-- 2. Colunas na tabela public.telemetria_posicoes
DO $$ BEGIN
  ALTER TABLE public.telemetria_posicoes ADD COLUMN IF NOT EXISTS bateria_veiculo_v NUMERIC(4, 1);
  ALTER TABLE public.telemetria_posicoes ADD COLUMN IF NOT EXISTS bateria_rastreador_pct INT;
  ALTER TABLE public.telemetria_posicoes ADD COLUMN IF NOT EXISTS bateria_rastreador_status TEXT;
EXCEPTION
  WHEN duplicate_column THEN NULL;
END $$;

-- 3. Comentários para documentação técnica de schema
COMMENT ON COLUMN public.veiculos.bateria_veiculo_v IS 'Voltagem real da bateria principal do veículo medida pelo rastreador (em Volts)';
COMMENT ON COLUMN public.veiculos.bateria_rastreador_pct IS 'Percentual de carga real da bateria interna de backup do rastreador (0 a 100%)';
COMMENT ON COLUMN public.veiculos.bateria_rastreador_status IS 'Estado da bateria interna (carregando, completa, bateria_interna, critica)';


-- ============================================================================
-- [9/225] MIGRAÇÃO: 20260919163000_hunter_unificacao_cliente_usuario.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — UNIFICAÇÃO ATÔMICA DE CADASTRO DE CLIENTES E USUÁRIOS DE ACESSO
-- ============================================================================
-- Permite ao administrador cadastrar o cliente, gerar o login de acesso
-- (auth.users, profiles, user_roles, user_module_access) e ativar o primeiro
-- veículo em uma única transação atômica ACID, eliminando cadastros duplicados.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.admin_cadastrar_cliente_completo(
  p_nome TEXT,
  p_documento TEXT DEFAULT NULL,
  p_email TEXT DEFAULT NULL,
  p_telefone TEXT DEFAULT NULL,
  p_plano public.plano_cliente DEFAULT 'basico',
  p_dia_vencimento INT DEFAULT 10,
  p_valor_mensalidade NUMERIC DEFAULT 79.90,
  p_dias_historico INT DEFAULT 7,
  p_dias_retencao INT DEFAULT 10,
  p_criar_usuario BOOLEAN DEFAULT TRUE,
  p_senha TEXT DEFAULT NULL,
  p_placa TEXT DEFAULT NULL,
  p_marca_modelo TEXT DEFAULT NULL,
  p_km_inicial INT DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_id UUID := NULL;
  v_cliente_id UUID;
  v_veiculo_id UUID;
  v_mod TEXT;
  v_modulos TEXT[];
BEGIN
  -- 1. Apenas administradores podem cadastrar
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem realizar esta operacao.';
  END IF;

  -- 2. Validações básicas do cliente
  IF p_nome IS NULL OR trim(p_nome) = '' THEN
    RAISE EXCEPTION 'O nome ou razao social do cliente e obrigatorio.';
  END IF;

  -- 3. Criação de usuário em auth.users se solicitado
  IF p_criar_usuario THEN
    IF p_email IS NULL OR trim(p_email) = '' THEN
      RAISE EXCEPTION 'O e-mail e obrigatorio para liberar acesso ao sistema.';
    END IF;

    IF p_senha IS NULL OR length(p_senha) < 6 THEN
      RAISE EXCEPTION 'A senha inicial de acesso deve conter no minimo 6 caracteres.';
    END IF;

    IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = LOWER(trim(p_email))) THEN
      RAISE EXCEPTION 'Ja existe um usuario cadastrado no sistema com este e-mail.';
    END IF;

    -- Cria o ID do usuário
    v_user_id := gen_random_uuid();

    INSERT INTO auth.users (
      id, instance_id, aud, role, email, encrypted_password,
      email_confirmed_at, recovery_sent_at, last_sign_in_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, email_change, email_change_token_new, recovery_token
    ) VALUES (
      v_user_id,
      '00000000-0000-0000-0000-000000000000',
      'authenticated',
      'authenticated',
      LOWER(trim(p_email)),
      extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
      now(), now(), now(),
      '{"provider":"email","providers":["email"]}',
      jsonb_build_object('nome', p_nome, 'role', 'cliente'),
      now(), now(),
      '', '', '', ''
    );

    -- Perfil de acesso do cliente
    INSERT INTO public.profiles (id, nome, email, role, ativo)
    VALUES (v_user_id, p_nome, LOWER(trim(p_email)), 'cliente', TRUE)
    ON CONFLICT (id) DO UPDATE
    SET nome = EXCLUDED.nome,
        role = 'cliente',
        ativo = TRUE,
        updated_at = now();

    -- Role em user_roles
    INSERT INTO public.user_roles (user_id, role)
    VALUES (v_user_id, 'cliente')
    ON CONFLICT (user_id, role) DO NOTHING;

    -- Define módulos conforme plano do cliente
    IF p_plano = 'basico' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades'];
    ELSIF p_plano = 'pro' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao'];
    ELSE
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao', 'central-seguranca'];
    END IF;

    FOREACH v_mod IN ARRAY v_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_user_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  -- 4. Inserção na tabela public.clientes vinculada ao v_user_id
  v_cliente_id := gen_random_uuid();
  INSERT INTO public.clientes (
    id,
    user_id,
    nome_razao_social,
    documento,
    email,
    telefone,
    plano,
    status,
    dia_vencimento,
    valor_mensalidade,
    dias_historico_plano,
    dias_retencao_banco,
    created_at,
    updated_at
  ) VALUES (
    v_cliente_id,
    v_user_id,
    trim(p_nome),
    NULLIF(trim(p_documento), ''),
    NULLIF(LOWER(trim(p_email)), ''),
    NULLIF(trim(p_telefone), ''),
    p_plano,
    'ativo',
    COALESCE(p_dia_vencimento, 10),
    COALESCE(p_valor_mensalidade, 79.90),
    COALESCE(p_dias_historico, 7),
    COALESCE(p_dias_retencao, 10),
    now(),
    now()
  );

  -- 5. Se informou placa, ativa o veículo inicial do cliente
  IF p_placa IS NOT NULL AND trim(p_placa) <> '' THEN
    v_veiculo_id := gen_random_uuid();
    INSERT INTO public.veiculos (
      id,
      cliente_id,
      placa,
      marca_modelo,
      km_inicial,
      odometro_km,
      data_ativacao,
      ativo,
      created_at,
      updated_at
    ) VALUES (
      v_veiculo_id,
      v_cliente_id,
      UPPER(trim(p_placa)),
      COALESCE(NULLIF(trim(p_marca_modelo), ''), 'Veículo Hunter Padrão'),
      COALESCE(p_km_inicial, 0),
      COALESCE(p_km_inicial, 0),
      now(),
      TRUE,
      now(),
      now()
    );

    -- Inicializa itens preventivos via RPC existente
    PERFORM public.inicializar_itens_manutencao_veiculo(v_veiculo_id, COALESCE(p_km_inicial, 0));
  END IF;

  -- 6. Auditoria forense
  INSERT INTO public.system_activity_logs (user_id, usuario_id, acao, detalhe)
  VALUES (
    v_caller_id,
    v_caller_id,
    'CADASTRO_CLIENTE_UNIFICADO',
    format('Cliente %s cadastrado com sucesso. Usuario de acesso gerado: %s. Veiculo inicial: %s.',
           p_nome,
           CASE WHEN p_criar_usuario THEN 'SIM (' || p_email || ')' ELSE 'NAO' END,
           COALESCE(p_placa, 'NENHUM'))
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'cliente_id', v_cliente_id,
    'user_id', v_user_id,
    'veiculo_id', v_veiculo_id,
    'message', 'Cliente e credenciais de acesso cadastrados com sucesso!'
  );
END;
$$;

COMMENT ON FUNCTION public.admin_cadastrar_cliente_completo IS 'Unifica cadastro de clientes, criacao de conta auth.users, definicao de permissoes por plano e ativacao de veiculo em transacao atomica.';


-- ============================================================================
-- [10/225] MIGRAÇÃO: 20260919170000_hunter_alertas_anomalias_socorro.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — SISTEMA AVANÇADO DE ALERTAS DE ACIDENTE, CAPOTAMENTO E ANOMALIAS
-- ============================================================================
-- Diretrizes: DJR-NEW & DJR-APP
-- Versão Alvo: 1.5.1.0
-- Notificação em tempo real para Usuário (Cliente) e Administradores com
-- Guia de Socorro Imediato (SAMU 192, Bombeiros 193, PM 190, PRF 191) e Ficha Cadastral.
-- ============================================================================

-- 1. Habilitar Realtime na tabela de alertas de segurança
DO $$ BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.alertas_seguranca;
EXCEPTION
  WHEN duplicate_object THEN NULL;
  WHEN others THEN NULL;
END $$;

-- 2. Atualizar ou enriquecer função processar_telemetria_veiculo com suporte a baterias reais e anomalias
CREATE OR REPLACE FUNCTION public.processar_telemetria_veiculo(
  p_veiculo_id UUID,
  p_latitude DOUBLE PRECISION,
  p_longitude DOUBLE PRECISION,
  p_velocidade INT,
  p_ignicao BOOLEAN,
  p_odometro INT DEFAULT NULL,
  p_inclinacao INT DEFAULT 0,
  p_vibracao NUMERIC DEFAULT 0.00,
  p_rumo INT DEFAULT 0,
  p_bateria_veiculo_v NUMERIC DEFAULT NULL,
  p_bateria_rastreador_pct INT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_veiculo RECORD;
  v_viagem_aberta RECORD;
  v_novo_odometro INT;
  v_distancia_km NUMERIC(8,2) := 0.00;
  v_alerta_gerado BOOLEAN := FALSE;
  v_tipo_alerta TEXT := NULL;
  v_detalhe_alerta TEXT := NULL;
  v_gravidade TEXT := 'alta';
  v_status_operacional TEXT;
BEGIN
  -- 1. Busca dados cadastrais e estado prévio do veículo
  SELECT id, cliente_id, odometro_km, ignicao_status, velocidade_atual, bloqueado, status_operacional, bateria_veiculo_v
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Veículo % não localizado.', p_veiculo_id;
  END IF;

  v_novo_odometro := COALESCE(p_odometro, v_veiculo.odometro_km);

  -- 2. Detecção Estrita de Anomalias Físicas, Acidentes e Comportamento Anormal
  -- Regra 1: Inclinação Crítica >= 45 graus (Capotamento ou Tombamento)
  IF p_inclinacao >= 45 THEN
    v_alerta_gerado := TRUE;
    v_tipo_alerta := 'capotamento_inclinacao';
    v_gravidade := 'critica';
    v_detalhe_alerta := format('Capotamento/Inclinação crítica de %s° detectada com veículo a %s km/h.', p_inclinacao, p_velocidade);
  
  -- Regra 2: Choque / Vibração extrema >= 2.5G (Impacto Severo / Colisão)
  ELSIF p_vibracao >= 2.50 THEN
    v_alerta_gerado := TRUE;
    v_tipo_alerta := 'colisao_impacto';
    v_gravidade := 'critica';
    v_detalhe_alerta := format('Colisão/Impacto violento com força de %sG detectado a %s km/h.', p_vibracao, p_velocidade);

  -- Regra 3: Parada repentina violenta (desaceleração de >= 35 km/h para 0 com impacto >= 1.5G)
  ELSIF v_veiculo.velocidade_atual >= 35 AND p_velocidade = 0 AND p_vibracao >= 1.50 THEN
    v_alerta_gerado := TRUE;
    v_tipo_alerta := 'parada_repentina_colisao';
    v_gravidade := 'critica';
    v_detalhe_alerta := format('Desaceleração violenta de %s km/h para 0 km/h com choque de %sG.', v_veiculo.velocidade_atual, p_vibracao);

  -- Regra 4: Comportamento Anormal / Condução Perigosa (Inclinação alta em velocidade ou ziguezague/freadas bruscas)
  ELSIF (p_velocidade > 60 AND p_inclinacao >= 22) OR (p_velocidade > 30 AND p_vibracao >= 1.80) THEN
    v_alerta_gerado := TRUE;
    v_tipo_alerta := 'comportamento_anormal';
    v_gravidade := 'alta';
    v_detalhe_alerta := format('Comportamento anormal/direção perigosa detectada: velocidade %s km/h, inclinação %s°, vibração %sG.', p_velocidade, p_inclinacao, p_vibracao);

  -- Regra 5: Corte ou Desconexão da Bateria do Carro (VCC externa cai para < 8V com carro ativo)
  ELSIF p_bateria_veiculo_v IS NOT NULL AND p_bateria_veiculo_v < 8.0 AND (p_ignicao OR p_velocidade > 0 OR v_veiculo.ignicao_status) THEN
    v_alerta_gerado := TRUE;
    v_tipo_alerta := 'bateria_desconectada';
    v_gravidade := 'alta';
    v_detalhe_alerta := format('Alerta de alimentação: Bateria principal do carro caiu para %sV (indício de corte de fiação ou desconexão).', p_bateria_veiculo_v);
  END IF;

  -- 3. Registro do Alerta de Segurança se gerado
  IF v_alerta_gerado THEN
    INSERT INTO public.alertas_seguranca (
      veiculo_id,
      cliente_id,
      tipo,
      gravidade,
      latitude,
      longitude,
      velocidade,
      vibracao_g,
      inclinacao_graus,
      detalhes
    ) VALUES (
      p_veiculo_id,
      v_veiculo.cliente_id,
      v_tipo_alerta,
      v_gravidade,
      p_latitude,
      p_longitude,
      p_velocidade,
      p_vibracao,
      p_inclinacao,
      v_detalhe_alerta
    );
  END IF;

  -- 4. Registro Histórico na Tabela de Posições
  INSERT INTO public.telemetria_posicoes (
    veiculo_id,
    latitude,
    longitude,
    velocidade,
    ignicao,
    odometro,
    rumo,
    inclinacao_graus,
    vibracao_g,
    bateria_veiculo_v,
    bateria_rastreador_pct,
    alerta_acidente,
    alerta_tipo,
    data_hora_gps
  ) VALUES (
    p_veiculo_id,
    p_latitude,
    p_longitude,
    p_velocidade,
    p_ignicao,
    v_novo_odometro,
    p_rumo,
    p_inclinacao,
    p_vibracao,
    p_bateria_veiculo_v,
    p_bateria_rastreador_pct,
    v_alerta_gerado,
    v_tipo_alerta,
    NOW()
  );

  -- 5. Determinação do Status Operacional
  IF v_veiculo.bloqueado THEN
    v_status_operacional := 'bloqueado';
  ELSIF p_velocidade > 0 THEN
    v_status_operacional := 'em_rota';
  ELSIF p_ignicao THEN
    v_status_operacional := 'parado_ligado';
  ELSE
    v_status_operacional := 'estacionado';
  END IF;

  -- 6. Atualização em Tempo Real do Veículo
  UPDATE public.veiculos
  SET
    latitude_atual = p_latitude,
    longitude_atual = p_longitude,
    velocidade_atual = p_velocidade,
    ignicao_status = p_ignicao,
    odometro_km = v_novo_odometro,
    status_operacional = v_status_operacional,
    inclinacao_graus = p_inclinacao,
    vibracao_g = p_vibracao,
    bateria_veiculo_v = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status = CASE
      WHEN p_bateria_veiculo_v IS NOT NULL AND p_bateria_veiculo_v >= 9.0 THEN 'carregando'
      WHEN p_bateria_rastreador_pct IS NOT NULL AND p_bateria_rastreador_pct > 15 THEN 'bateria_interna'
      WHEN p_bateria_rastreador_pct IS NOT NULL AND p_bateria_rastreador_pct <= 15 THEN 'critica'
      ELSE bateria_rastreador_status
    END,
    alerta_acidente = v_alerta_gerado,
    alerta_tipo = v_tipo_alerta,
    ultima_comunicacao = NOW(),
    updated_at = NOW()
  WHERE id = p_veiculo_id;

  RETURN jsonb_build_object(
    'sucesso', true,
    'veiculo_id', p_veiculo_id,
    'alerta_gerado', v_alerta_gerado,
    'tipo_alerta', v_tipo_alerta,
    'status_operacional', v_status_operacional
  );
END;
$$;


-- ============================================================================
-- [11/225] MIGRAÇÃO: 20260919180000_hunter_modulo_instalacao_e_perfil_instalador.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — MÓDULO DE INSTALAÇÃO, PERFIL INSTALADOR E REPASSES FINANCEIROS
-- ============================================================================
-- Diretrizes: DJR-NEW & DJR-APP
-- Versão Alvo: 1.5.2.0
-- ============================================================================

-- 1. Adicionar o papel 'instalador' no ENUM hunter_role (deve rodar fora de bloco DO no Postgres)
ALTER TYPE public.hunter_role ADD VALUE IF NOT EXISTS 'instalador';

-- 2. Adicionar coluna de valor por instalação no perfil do instalador
DO $$ BEGIN
  ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS valor_por_instalacao NUMERIC(10,2) DEFAULT 0.00;
EXCEPTION
  WHEN duplicate_column THEN NULL;
END $$;

-- 3. Tabela de Instalações Técnicas
CREATE TABLE IF NOT EXISTS public.instalacoes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  instalador_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,
  cliente_id UUID NOT NULL REFERENCES public.clientes(id) ON DELETE RESTRICT,
  veiculo_id UUID REFERENCES public.veiculos(id) ON DELETE SET NULL,
  
  -- Dados do Veículo
  placa TEXT NOT NULL,
  marca TEXT NOT NULL,
  modelo TEXT NOT NULL,
  ano INT,
  cor TEXT,
  km_instalacao INT NOT NULL DEFAULT 0,
  
  -- Dados do Rastreador e Dispositivo
  rastreador_imei TEXT NOT NULL,
  rastreador_modelo TEXT DEFAULT 'J16 4G',
  chip_iccid TEXT,
  chip_operadora TEXT,
  posicao_instalacao TEXT,
  
  -- Status Operacional da Instalação
  status TEXT NOT NULL DEFAULT 'nao_instalado' CHECK (status IN ('nao_instalado', 'concluida_com_pendencia', 'concluida')),
  motivo_pendencia_recusa TEXT,
  observacoes TEXT,
  
  -- Financeiro e Repasse ao Instalador
  valor_instalacao NUMERIC(10,2) NOT NULL DEFAULT 0.00,
  status_pagamento TEXT NOT NULL DEFAULT 'pendente' CHECK (status_pagamento IN ('pendente', 'pago')),
  pago_em TIMESTAMPTZ,
  pago_por UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  comprovante_pagamento TEXT,
  
  -- Metadados e Conclusão
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  concluida_at TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_instalacoes_instalador ON public.instalacoes(instalador_id);
CREATE INDEX IF NOT EXISTS idx_instalacoes_cliente ON public.instalacoes(cliente_id);
CREATE INDEX IF NOT EXISTS idx_instalacoes_status ON public.instalacoes(status);
CREATE INDEX IF NOT EXISTS idx_instalacoes_pagamento ON public.instalacoes(status_pagamento);
CREATE INDEX IF NOT EXISTS idx_instalacoes_placa ON public.instalacoes(placa);

-- 4. Tabela de Histórico de Atendimentos da Instalação (Linha do Tempo Imutável)
CREATE TABLE IF NOT EXISTS public.instalacoes_historico_atendimentos (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  instalacao_id UUID NOT NULL REFERENCES public.instalacoes(id) ON DELETE CASCADE,
  instalador_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,
  status_atendimento TEXT NOT NULL,
  motivo TEXT,
  observacoes TEXT,
  km_no_atendimento INT DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_instalacoes_hist_inst ON public.instalacoes_historico_atendimentos(instalacao_id, created_at DESC);

-- 5. Habilitar Realtime
DO $$ BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.instalacoes;
EXCEPTION
  WHEN others THEN NULL;
END $$;

-- 6. Row Level Security (RLS) Estrito
ALTER TABLE public.instalacoes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.instalacoes_historico_atendimentos ENABLE ROW LEVEL SECURITY;

-- 6.1. Políticas de RLS em 'instalacoes'
DROP POLICY IF EXISTS "Instaladores acessam estritamente suas proprias instalacoes" ON public.instalacoes;
CREATE POLICY "Instaladores acessam estritamente suas proprias instalacoes"
ON public.instalacoes FOR SELECT TO authenticated
USING (
  public.is_admin_or_superadmin(auth.uid()) OR
  EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'operador') OR
  instalador_id = auth.uid()
);

DROP POLICY IF EXISTS "Instaladores podem cadastrar instalacoes" ON public.instalacoes;
CREATE POLICY "Instaladores podem cadastrar instalacoes"
ON public.instalacoes FOR INSERT TO authenticated
WITH CHECK (
  public.is_admin_or_superadmin(auth.uid()) OR
  EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'operador') OR
  instalador_id = auth.uid()
);

DROP POLICY IF EXISTS "Instaladores e Administradores podem atualizar instalacoes" ON public.instalacoes;
CREATE POLICY "Instaladores e Administradores podem atualizar instalacoes"
ON public.instalacoes FOR UPDATE TO authenticated
USING (
  public.is_admin_or_superadmin(auth.uid()) OR
  EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'operador') OR
  instalador_id = auth.uid()
);

-- 6.2. Políticas de RLS em 'instalacoes_historico_atendimentos'
DROP POLICY IF EXISTS "Historico visivel para administradores e instalador responsavel" ON public.instalacoes_historico_atendimentos;
CREATE POLICY "Historico visivel para administradores e instalador responsavel"
ON public.instalacoes_historico_atendimentos FOR SELECT TO authenticated
USING (
  public.is_admin_or_superadmin(auth.uid()) OR
  EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'operador') OR
  instalador_id = auth.uid()
);

DROP POLICY IF EXISTS "Historico inserivel por administradores e instaladores" ON public.instalacoes_historico_atendimentos;
CREATE POLICY "Historico inserivel por administradores e instaladores"
ON public.instalacoes_historico_atendimentos FOR INSERT TO authenticated
WITH CHECK (
  public.is_admin_or_superadmin(auth.uid()) OR
  EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'operador') OR
  instalador_id = auth.uid()
);

-- 7. RPC Transacional para Salvar ou Reabrir Atendimento de Instalação
CREATE OR REPLACE FUNCTION public.salvar_atendimento_instalacao(
  p_instalacao_id UUID DEFAULT NULL,
  p_cliente_id UUID DEFAULT NULL,
  p_placa TEXT DEFAULT NULL,
  p_marca TEXT DEFAULT NULL,
  p_modelo TEXT DEFAULT NULL,
  p_ano INT DEFAULT NULL,
  p_cor TEXT DEFAULT NULL,
  p_km_instalacao INT DEFAULT 0,
  p_rastreador_imei TEXT DEFAULT NULL,
  p_rastreador_modelo TEXT DEFAULT 'J16 4G',
  p_chip_iccid TEXT DEFAULT NULL,
  p_chip_operadora TEXT DEFAULT NULL,
  p_posicao_instalacao TEXT DEFAULT NULL,
  p_status TEXT DEFAULT 'nao_instalado',
  p_motivo TEXT DEFAULT NULL,
  p_observacoes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id UUID;
  v_instalador_id UUID;
  v_valor_unitario NUMERIC(10,2) := 0.00;
  v_instalacao_id UUID;
  v_veiculo_id UUID := NULL;
  v_concluida_at TIMESTAMPTZ := NULL;
  v_placa_limpa TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  v_placa_limpa := UPPER(TRIM(REPLACE(COALESCE(p_placa, ''), '-', '')));

  -- Se for nova instalação, o instalador é o usuário logado (ou admin indicando a si)
  IF p_instalacao_id IS NULL THEN
    v_instalador_id := v_user_id;

    -- Carrega o valor por instalação cadastrado no perfil do instalador
    SELECT COALESCE(valor_por_instalacao, 0.00)
    INTO v_valor_unitario
    FROM public.profiles
    WHERE id = v_instalador_id;

    IF p_status = 'concluida' THEN
      v_concluida_at := NOW();
    END IF;

    -- Insere registro mestre da instalação
    INSERT INTO public.instalacoes (
      instalador_id,
      cliente_id,
      placa,
      marca,
      modelo,
      ano,
      cor,
      km_instalacao,
      rastreador_imei,
      rastreador_modelo,
      chip_iccid,
      chip_operadora,
      posicao_instalacao,
      status,
      motivo_pendencia_recusa,
      observacoes,
      valor_instalacao,
      concluida_at
    ) VALUES (
      v_instalador_id,
      p_cliente_id,
      v_placa_limpa,
      p_marca,
      p_modelo,
      p_ano,
      p_cor,
      p_km_instalacao,
      p_rastreador_imei,
      p_rastreador_modelo,
      p_chip_iccid,
      p_chip_operadora,
      p_posicao_instalacao,
      p_status,
      p_motivo,
      p_observacoes,
      v_valor_unitario,
      v_concluida_at
    ) RETURNING id INTO v_instalacao_id;

  ELSE
    -- Atualização / Reabertura de instalação existente
    v_instalacao_id := p_instalacao_id;

    SELECT instalador_id, concluida_at, veiculo_id
    INTO v_instalador_id, v_concluida_at, v_veiculo_id
    FROM public.instalacoes
    WHERE id = v_instalacao_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Instalação não encontrada.';
    END IF;

    IF p_status = 'concluida' AND v_concluida_at IS NULL THEN
      v_concluida_at := NOW();
    END IF;

    UPDATE public.instalacoes
    SET
      cliente_id = COALESCE(p_cliente_id, cliente_id),
      placa = COALESCE(v_placa_limpa, placa),
      marca = COALESCE(p_marca, marca),
      modelo = COALESCE(p_modelo, modelo),
      ano = COALESCE(p_ano, ano),
      cor = COALESCE(p_cor, cor),
      km_instalacao = COALESCE(p_km_instalacao, km_instalacao),
      rastreador_imei = COALESCE(p_rastreador_imei, rastreador_imei),
      rastreador_modelo = COALESCE(p_rastreador_modelo, rastreador_modelo),
      chip_iccid = COALESCE(p_chip_iccid, chip_iccid),
      chip_operadora = COALESCE(p_chip_operadora, chip_operadora),
      posicao_instalacao = COALESCE(p_posicao_instalacao, posicao_instalacao),
      status = p_status,
      motivo_pendencia_recusa = p_motivo,
      observacoes = p_observacoes,
      concluida_at = v_concluida_at,
      updated_at = NOW()
    WHERE id = v_instalacao_id;
  END IF;

  -- Grava o registro histórico imutável na timeline de atendimentos
  INSERT INTO public.instalacoes_historico_atendimentos (
    instalacao_id,
    instalador_id,
    status_atendimento,
    motivo,
    observacoes,
    km_no_atendimento
  ) VALUES (
    v_instalacao_id,
    v_user_id,
    p_status,
    p_motivo,
    p_observacoes,
    p_km_instalacao
  );

  -- Se a instalação for concluída com sucesso, cadastra ou vincula o veículo na frota
  IF p_status = 'concluida' THEN
    -- Verifica se o veículo já existe por placa
    SELECT id INTO v_veiculo_id
    FROM public.veiculos
    WHERE placa = v_placa_limpa
    LIMIT 1;

    IF v_veiculo_id IS NULL THEN
      -- Cadastra o novo veículo
      INSERT INTO public.veiculos (
        cliente_id,
        placa,
        marca_modelo,
        ano,
        cor,
        odometro_km,
        status_operacional,
        rastreador_imei
      ) VALUES (
        p_cliente_id,
        v_placa_limpa,
        format('%s %s', p_marca, p_modelo),
        p_ano,
        p_cor,
        p_km_instalacao,
        'estacionado',
        p_rastreador_imei
      ) RETURNING id INTO v_veiculo_id;
    ELSE
      -- Atualiza odômetro e imei se necessário
      UPDATE public.veiculos
      SET
        odometro_km = GREATEST(odometro_km, p_km_instalacao),
        rastreador_imei = COALESCE(p_rastreador_imei, rastreador_imei),
        updated_at = NOW()
      WHERE id = v_veiculo_id;
    END IF;

    -- Vincula o veiculo_id na instalação
    UPDATE public.instalacoes
    SET veiculo_id = v_veiculo_id
    WHERE id = v_instalacao_id;
  END IF;

  RETURN jsonb_build_object(
    'sucesso', true,
    'instalacao_id', v_instalacao_id,
    'status', p_status,
    'veiculo_id', v_veiculo_id
  );
END;
$$;

-- 8. RPC Administrativa para Marcar Pagamento de Repasse
CREATE OR REPLACE FUNCTION public.marcar_pagamento_instalacao(
  p_instalacao_id UUID,
  p_status_pagamento TEXT, -- 'pago' ou 'pendente'
  p_comprovante TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL OR NOT public.is_admin_or_superadmin(v_user_id) THEN
    RAISE EXCEPTION 'Acesso negado. Apenas administradores podem gerenciar repasses financeiros.';
  END IF;

  IF p_status_pagamento NOT IN ('pago', 'pendente') THEN
    RAISE EXCEPTION 'Status de pagamento inválido.';
  END IF;

  UPDATE public.instalacoes
  SET
    status_pagamento = p_status_pagamento,
    pago_em = CASE WHEN p_status_pagamento = 'pago' THEN NOW() ELSE NULL END,
    pago_por = CASE WHEN p_status_pagamento = 'pago' THEN v_user_id ELSE NULL END,
    comprovante_pagamento = p_comprovante,
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  -- Registra auditoria
  INSERT INTO public.system_activity_logs (
    usuario_id,
    acao,
    detalhe
  ) VALUES (
    v_user_id,
    'REPASSE_INSTALACAO_ALTERADO',
    format('Repasse da instalação %s alterado para %s.', p_instalacao_id, UPPER(p_status_pagamento))
  );

  RETURN jsonb_build_object('sucesso', true, 'instalacao_id', p_instalacao_id, 'status_pagamento', p_status_pagamento);
END;
$$;

-- 9. Atualizar admin_cadastrar_usuario para salvar valor_por_instalacao
CREATE OR REPLACE FUNCTION public.admin_cadastrar_usuario(
  p_nome TEXT,
  p_email TEXT,
  p_senha TEXT,
  p_role public.hunter_role,
  p_modulos TEXT[] DEFAULT ARRAY[]::TEXT[],
  p_plano public.plano_cliente DEFAULT 'basico',
  p_valor_por_instalacao NUMERIC DEFAULT 0.00
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_id UUID;
  v_mod TEXT;
  v_modulos_finais TEXT[];
  v_modulos_todos TEXT[] := ARRAY[
    'monitor-gps', 'atendimento', 'clientes', 'mensalidades',
    'rastreadores', 'central-seguranca', 'logs', 'dispositivos',
    'manutencao', 'usuarios', 'instalacao'
  ];
BEGIN
  -- 1. Apenas administradores podem cadastrar
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem cadastrar usuarios.';
  END IF;

  -- 2. SuperAdmin Mestre tem e-mail reservado
  IF LOWER(trim(p_email)) = 'novaes@adm.28bpm.local' AND p_role <> 'superadmin' THEN
    RAISE EXCEPTION 'O e-mail novaes@adm.28bpm.local e reservado exclusivamente para a conta SuperAdmin Mestre.';
  END IF;

  -- 3. Se for adm ou superadmin, todos os módulos devem ser liberados automaticamente. Se for instalador, apenas 'instalacao'
  IF p_role IN ('superadmin', 'adm') THEN
    v_modulos_finais := v_modulos_todos;
  ELSIF p_role = 'instalador' THEN
    v_modulos_finais := ARRAY['instalacao'];
  ELSE
    v_modulos_finais := p_modulos;
  END IF;

  -- 4. Cria conta em auth.users
  v_user_id := gen_random_uuid();
  INSERT INTO auth.users (
    id, instance_id, aud, role, email, encrypted_password,
    email_confirmed_at, recovery_sent_at, last_sign_in_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, email_change, email_change_token_new, recovery_token
  ) VALUES (
    v_user_id,
    '00000000-0000-0000-0000-000000000000',
    'authenticated',
    'authenticated',
    LOWER(trim(p_email)),
    crypt(p_senha, gen_salt('bf', 10)),
    now(), now(), now(),
    jsonb_build_object('provider', 'email', 'providers', jsonb_build_array('email')),
    jsonb_build_object('nome', p_nome, 'role', p_role),
    now(), now(), '', '', '', ''
  );

  -- 5. Atualiza ou insere perfil em public.profiles
  INSERT INTO public.profiles (id, nome, email, role, ativo, valor_por_instalacao)
  VALUES (v_user_id, p_nome, LOWER(trim(p_email)), p_role, TRUE, COALESCE(p_valor_por_instalacao, 0.00))
  ON CONFLICT (id) DO UPDATE
  SET nome = EXCLUDED.nome,
      role = EXCLUDED.role,
      valor_por_instalacao = COALESCE(EXCLUDED.valor_por_instalacao, public.profiles.valor_por_instalacao),
      ativo = TRUE,
      updated_at = now();

  -- 6. Registra role em public.user_roles
  INSERT INTO public.user_roles (user_id, role)
  VALUES (v_user_id, p_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  -- 7. Atribui módulos permitidos
  IF v_modulos_finais IS NOT NULL AND array_length(v_modulos_finais, 1) > 0 THEN
    FOREACH v_mod IN ARRAY v_modulos_finais LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_user_id, trim(v_mod), TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  -- 8. Se for cliente, cria registro vinculado em public.clientes
  IF p_role = 'cliente' THEN
    INSERT INTO public.clientes (user_id, nome_razao_social, email, plano, status)
    VALUES (v_user_id, p_nome, LOWER(trim(p_email)), COALESCE(p_plano, 'basico'), 'ativo');
  END IF;

  -- 9. Registro de auditoria forense
  INSERT INTO public.system_activity_logs (usuario_id, acao, detalhe)
  VALUES (
    v_caller_id,
    'USUARIO_CRIADO',
    format('Usuario %s (%s) criado com role %s por %s. Valor por instalacao: %s', p_nome, p_email, p_role, v_caller_id, COALESCE(p_valor_por_instalacao, 0.00))
  );

  RETURN jsonb_build_object('success', true, 'message', 'Usuario cadastrado com sucesso!', 'user_id', v_user_id);
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$$;

-- 10. Atualizar admin_atualizar_usuario para salvar valor_por_instalacao
CREATE OR REPLACE FUNCTION public.admin_atualizar_usuario(
  p_user_id UUID,
  p_nome TEXT,
  p_role public.hunter_role,
  p_ativo BOOLEAN,
  p_modulos TEXT[] DEFAULT ARRAY[]::TEXT[],
  p_plano public.plano_cliente DEFAULT NULL,
  p_valor_por_instalacao NUMERIC DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_mod TEXT;
  v_modulos_finais TEXT[];
  v_modulos_todos TEXT[] := ARRAY[
    'monitor-gps', 'atendimento', 'clientes', 'mensalidades',
    'rastreadores', 'central-seguranca', 'logs', 'dispositivos',
    'manutencao', 'usuarios', 'instalacao'
  ];
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem gerenciar usuarios.';
  END IF;

  IF p_role IN ('superadmin', 'adm') THEN
    v_modulos_finais := v_modulos_todos;
  ELSIF p_role = 'instalador' THEN
    v_modulos_finais := ARRAY['instalacao'];
  ELSE
    v_modulos_finais := p_modulos;
  END IF;

  UPDATE public.profiles
  SET nome = p_nome,
      role = p_role,
      ativo = p_ativo,
      valor_por_instalacao = COALESCE(p_valor_por_instalacao, valor_por_instalacao),
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (p_user_id, p_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  DELETE FROM public.user_roles
  WHERE user_id = p_user_id AND role <> p_role;

  UPDATE public.user_module_access
  SET ativo = FALSE
  WHERE user_id = p_user_id;

  IF v_modulos_finais IS NOT NULL AND array_length(v_modulos_finais, 1) > 0 THEN
    FOREACH v_mod IN ARRAY v_modulos_finais LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (p_user_id, trim(v_mod), TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  IF p_role = 'cliente' AND p_plano IS NOT NULL THEN
    UPDATE public.clientes
    SET plano = p_plano, updated_at = now()
    WHERE user_id = p_user_id;
  END IF;

  INSERT INTO public.system_activity_logs (usuario_id, acao, detalhe)
  VALUES (
    v_caller_id,
    'USUARIO_ATUALIZADO',
    format('Usuario %s atualizado para role %s. Ativo: %s', p_user_id, p_role, p_ativo)
  );

  RETURN jsonb_build_object('success', true, 'message', 'Usuario atualizado com sucesso!');
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$$;


-- ============================================================================
-- [12/225] MIGRAÇÃO: 20260919183000_hunter_cliente_aguardando_instalacao_e_busca.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — CLIENTE AGUARDANDO INSTALAÇÃO, ATIVAÇÃO AUTOMÁTICA E CHAVE PIX
-- ============================================================================
-- 1. Adiciona o status 'aguardando_instalacao' ao enum de status_cliente.
-- 2. Adiciona a coluna 'chave_pix' na tabela public.profiles para instaladores.
-- 3. Atualiza admin_cadastrar_usuario e admin_atualizar_usuario para suportar chave_pix.
-- 4. Clientes novos entram com status 'aguardando_instalacao' (veículo não é mais criado no cadastro de cliente).
-- 5. Permite a instaladores consultar a lista de clientes para vincular à instalação.
-- 6. Ao finalizar a instalação (status 'concluida'), o cliente é ativado ('ativo') e o veículo é associado.
-- ============================================================================

-- 1. Atualizar ENUM status_cliente
ALTER TYPE public.status_cliente ADD VALUE IF NOT EXISTS 'aguardando_instalacao';

-- 2. Adicionar coluna chave_pix em profiles
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS chave_pix TEXT;

-- 3. Política de RLS: Permitir que instaladores consultem clientes para associar na instalação física
DROP POLICY IF EXISTS "Instaladores consultam clientes para instalacao" ON public.clientes;
CREATE POLICY "Instaladores consultam clientes para instalacao"
ON public.clientes FOR SELECT TO authenticated
USING (
  EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'instalador')
);

-- 4. Atualizar função de cadastro unificado do cliente (sem exigir/cadastrar veículo antecipadamente)
CREATE OR REPLACE FUNCTION public.admin_cadastrar_cliente_completo(
  p_nome TEXT,
  p_documento TEXT DEFAULT NULL,
  p_email TEXT DEFAULT NULL,
  p_telefone TEXT DEFAULT NULL,
  p_plano public.plano_cliente DEFAULT 'basico',
  p_dia_vencimento INT DEFAULT 10,
  p_valor_mensalidade NUMERIC DEFAULT 79.90,
  p_dias_historico INT DEFAULT 7,
  p_dias_retencao INT DEFAULT 10,
  p_criar_usuario BOOLEAN DEFAULT TRUE,
  p_senha TEXT DEFAULT NULL,
  p_placa TEXT DEFAULT NULL,
  p_marca_modelo TEXT DEFAULT NULL,
  p_km_inicial INT DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_id UUID := NULL;
  v_cliente_id UUID;
  v_mod TEXT;
  v_modulos TEXT[];
BEGIN
  -- 1. Apenas administradores podem cadastrar clientes
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem realizar esta operacao.';
  END IF;

  -- 2. Validações básicas do cliente
  IF p_nome IS NULL OR trim(p_nome) = '' THEN
    RAISE EXCEPTION 'O nome ou razao social do cliente e obrigatorio.';
  END IF;

  -- 3. Criação de usuário em auth.users se solicitado
  IF p_criar_usuario THEN
    IF p_email IS NULL OR trim(p_email) = '' THEN
      RAISE EXCEPTION 'O e-mail e obrigatorio para liberar acesso ao sistema.';
    END IF;

    IF p_senha IS NULL OR length(p_senha) < 6 THEN
      RAISE EXCEPTION 'A senha inicial de acesso deve conter no minimo 6 caracteres.';
    END IF;

    IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = LOWER(trim(p_email))) THEN
      RAISE EXCEPTION 'Ja existe um usuario cadastrado no sistema com este e-mail.';
    END IF;

    -- Cria o ID do usuário
    v_user_id := gen_random_uuid();

    INSERT INTO auth.users (
      id, instance_id, aud, role, email, encrypted_password,
      email_confirmed_at, recovery_sent_at, last_sign_in_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, email_change, email_change_token_new, recovery_token
    ) VALUES (
      v_user_id,
      '00000000-0000-0000-0000-000000000000',
      'authenticated',
      'authenticated',
      LOWER(trim(p_email)),
      extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
      now(), now(), now(),
      '{"provider":"email","providers":["email"]}',
      jsonb_build_object('nome', p_nome, 'role', 'cliente'),
      now(), now(),
      '', '', '', ''
    );

    -- Perfil de acesso do cliente
    INSERT INTO public.profiles (id, nome, email, role, ativo)
    VALUES (v_user_id, p_nome, LOWER(trim(p_email)), 'cliente', TRUE)
    ON CONFLICT (id) DO UPDATE
    SET nome = EXCLUDED.nome,
        role = 'cliente',
        ativo = TRUE,
        updated_at = now();

    -- Role em user_roles
    INSERT INTO public.user_roles (user_id, role)
    VALUES (v_user_id, 'cliente')
    ON CONFLICT (user_id, role) DO NOTHING;

    -- Define módulos conforme plano do cliente
    IF p_plano = 'basico' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades'];
    ELSIF p_plano = 'pro' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao'];
    ELSE
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao'];
    END IF;

    FOREACH v_mod IN ARRAY v_modulos
    LOOP
      INSERT INTO public.user_module_access (user_id, module_name)
      VALUES (v_user_id, v_mod)
      ON CONFLICT (user_id, module_name) DO NOTHING;
    END LOOP;
  END IF;

  -- 4. Criação do cliente com status 'aguardando_instalacao'
  -- O veículo será cadastrado pelo instalador na instalação física
  v_cliente_id := gen_random_uuid();
  INSERT INTO public.clientes (
    id,
    user_id,
    nome_razao_social,
    documento,
    email,
    telefone,
    plano,
    status,
    dia_vencimento,
    valor_mensalidade,
    dias_historico_plano,
    dias_retencao_banco,
    created_at,
    updated_at
  ) VALUES (
    v_cliente_id,
    v_user_id,
    trim(p_nome),
    NULLIF(trim(p_documento), ''),
    NULLIF(LOWER(trim(p_email)), ''),
    NULLIF(trim(p_telefone), ''),
    p_plano,
    'aguardando_instalacao',
    COALESCE(p_dia_vencimento, 10),
    COALESCE(p_valor_mensalidade, 79.90),
    COALESCE(p_dias_historico, 7),
    COALESCE(p_dias_retencao, 10),
    now(),
    now()
  );

  -- 5. Auditoria forense
  INSERT INTO public.system_activity_logs (user_id, usuario_id, acao, detalhe)
  VALUES (
    v_caller_id,
    v_caller_id,
    'CADASTRO_CLIENTE_UNIFICADO',
    format('Cliente %s cadastrado com sucesso. Status: aguardando_instalacao. Login: %s', p_nome, COALESCE(p_email, 'sem login'))
  );

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'cliente_id', v_cliente_id,
    'user_id', v_user_id,
    'email', p_email,
    'status', 'aguardando_instalacao'
  );
END;
$$;

-- 5. Atualizar salvar_atendimento_instalacao para ativar cliente na conclusão
CREATE OR REPLACE FUNCTION public.salvar_atendimento_instalacao(
  p_instalacao_id UUID DEFAULT NULL,
  p_cliente_id UUID DEFAULT NULL,
  p_placa TEXT DEFAULT NULL,
  p_marca TEXT DEFAULT NULL,
  p_modelo TEXT DEFAULT NULL,
  p_ano INT DEFAULT NULL,
  p_cor TEXT DEFAULT NULL,
  p_km_instalacao INT DEFAULT 0,
  p_rastreador_imei TEXT DEFAULT NULL,
  p_rastreador_modelo TEXT DEFAULT 'J16 4G',
  p_chip_iccid TEXT DEFAULT NULL,
  p_chip_operadora TEXT DEFAULT NULL,
  p_posicao_instalacao TEXT DEFAULT NULL,
  p_status TEXT DEFAULT 'nao_instalado',
  p_motivo TEXT DEFAULT NULL,
  p_observacoes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id UUID;
  v_instalador_id UUID;
  v_instalacao_id UUID;
  v_veiculo_id UUID := NULL;
  v_placa_limpa TEXT;
  v_valor_unitario NUMERIC(10,2) := 0.00;
  v_concluida_at TIMESTAMPTZ := NULL;
  v_status_valido BOOLEAN;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso não autenticado.';
  END IF;

  -- Validação de status
  IF p_status NOT IN ('nao_instalado', 'concluida_com_pendencia', 'concluida') THEN
    RAISE EXCEPTION 'Status de instalação inválido: %', p_status;
  END IF;

  -- Se for 'nao_instalado' ou 'concluida_com_pendencia', motivo é estritamente obrigatório
  IF p_status IN ('nao_instalado', 'concluida_com_pendencia') AND (p_motivo IS NULL OR trim(p_motivo) = '') THEN
    RAISE EXCEPTION 'É obrigatório informar o motivo para status de pendência ou não instalado.';
  END IF;

  v_placa_limpa := UPPER(trim(p_placa));

  IF p_instalacao_id IS NULL THEN
    -- Nova Ordem de Instalação
    v_instalador_id := v_user_id;

    -- Obter o valor da instalação configurado no cadastro do instalador
    SELECT COALESCE(valor_por_instalacao, 0.00) INTO v_valor_unitario
    FROM public.profiles
    WHERE id = v_instalador_id;

    IF p_status = 'concluida' THEN
      v_concluida_at := NOW();
    END IF;

    INSERT INTO public.instalacoes (
      instalador_id,
      cliente_id,
      placa,
      marca,
      modelo,
      ano,
      cor,
      km_instalacao,
      rastreador_imei,
      rastreador_modelo,
      chip_iccid,
      chip_operadora,
      posicao_instalacao,
      status,
      motivo_pendencia_recusa,
      observacoes,
      valor_instalacao,
      concluida_at
    ) VALUES (
      v_instalador_id,
      p_cliente_id,
      v_placa_limpa,
      p_marca,
      p_modelo,
      p_ano,
      p_cor,
      p_km_instalacao,
      p_rastreador_imei,
      p_rastreador_modelo,
      p_chip_iccid,
      p_chip_operadora,
      p_posicao_instalacao,
      p_status,
      p_motivo,
      p_observacoes,
      v_valor_unitario,
      v_concluida_at
    ) RETURNING id INTO v_instalacao_id;

  ELSE
    -- Atualização / Reabertura de instalação existente
    v_instalacao_id := p_instalacao_id;

    SELECT instalador_id, concluida_at, veiculo_id
    INTO v_instalador_id, v_concluida_at, v_veiculo_id
    FROM public.instalacoes
    WHERE id = v_instalacao_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Instalação não encontrada.';
    END IF;

    IF p_status = 'concluida' AND v_concluida_at IS NULL THEN
      v_concluida_at := NOW();
    END IF;

    UPDATE public.instalacoes
    SET
      cliente_id = COALESCE(p_cliente_id, cliente_id),
      placa = COALESCE(v_placa_limpa, placa),
      marca = COALESCE(p_marca, marca),
      modelo = COALESCE(p_modelo, modelo),
      ano = COALESCE(p_ano, ano),
      cor = COALESCE(p_cor, cor),
      km_instalacao = COALESCE(p_km_instalacao, km_instalacao),
      rastreador_imei = COALESCE(p_rastreador_imei, rastreador_imei),
      rastreador_modelo = COALESCE(p_rastreador_modelo, rastreador_modelo),
      chip_iccid = COALESCE(p_chip_iccid, chip_iccid),
      chip_operadora = COALESCE(p_chip_operadora, chip_operadora),
      posicao_instalacao = COALESCE(p_posicao_instalacao, posicao_instalacao),
      status = p_status,
      motivo_pendencia_recusa = p_motivo,
      observacoes = p_observacoes,
      concluida_at = v_concluida_at,
      updated_at = NOW()
    WHERE id = v_instalacao_id;
  END IF;

  -- Grava o registro histórico imutável na timeline de atendimentos
  INSERT INTO public.instalacoes_historico_atendimentos (
    instalacao_id,
    instalador_id,
    status_atendimento,
    motivo,
    observacoes,
    km_no_atendimento
  ) VALUES (
    v_instalacao_id,
    v_user_id,
    p_status,
    p_motivo,
    p_observacoes,
    p_km_instalacao
  );

  -- Se a instalação for concluída com sucesso:
  -- 1. Cadastra ou vincula o veículo na frota
  -- 2. Ativa o cliente associado (que estava 'aguardando_instalacao')
  IF p_status = 'concluida' THEN
    -- Verifica se o veículo já existe por placa
    SELECT id INTO v_veiculo_id
    FROM public.veiculos
    WHERE placa = v_placa_limpa
    LIMIT 1;

    IF v_veiculo_id IS NULL THEN
      -- Cadastra o novo veículo associado ao cliente
      INSERT INTO public.veiculos (
        cliente_id,
        placa,
        marca_modelo,
        ano,
        cor,
        odometro_km,
        status_operacional,
        rastreador_imei
      ) VALUES (
        p_cliente_id,
        v_placa_limpa,
        format('%s %s', p_marca, p_modelo),
        p_ano,
        p_cor,
        p_km_instalacao,
        'estacionado',
        p_rastreador_imei
      ) RETURNING id INTO v_veiculo_id;

      -- Inicializa manutenção preventiva
      PERFORM public.inicializar_itens_manutencao_veiculo(v_veiculo_id, p_km_instalacao);
    ELSE
      -- Atualiza veículo existente
      UPDATE public.veiculos
      SET
        cliente_id = COALESCE(p_cliente_id, cliente_id),
        odometro_km = GREATEST(odometro_km, p_km_instalacao),
        rastreador_imei = COALESCE(p_rastreador_imei, rastreador_imei),
        updated_at = NOW()
      WHERE id = v_veiculo_id;
    END IF;

    -- Vincula o veiculo_id na ordem de instalação
    UPDATE public.instalacoes
    SET veiculo_id = v_veiculo_id
    WHERE id = v_instalacao_id;

    -- Ativa o cliente associado que estava com status 'aguardando_instalacao'
    IF p_cliente_id IS NOT NULL THEN
      UPDATE public.clientes
      SET status = 'ativo', updated_at = NOW()
      WHERE id = p_cliente_id AND status = 'aguardando_instalacao';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso', true,
    'instalacao_id', v_instalacao_id,
    'status', p_status,
    'veiculo_id', v_veiculo_id
  );
END;
$$;

-- 6. Atualizar admin_cadastrar_usuario para salvar chave_pix
CREATE OR REPLACE FUNCTION public.admin_cadastrar_usuario(
  p_nome TEXT,
  p_email TEXT,
  p_senha TEXT,
  p_role public.hunter_role,
  p_modulos TEXT[] DEFAULT ARRAY[]::TEXT[],
  p_plano public.plano_cliente DEFAULT 'basico',
  p_valor_por_instalacao NUMERIC DEFAULT 0.00,
  p_chave_pix TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_id UUID;
  v_mod TEXT;
  v_modulos_finais TEXT[];
  v_modulos_todos TEXT[] := ARRAY[
    'monitor-gps', 'atendimento', 'clientes', 'mensalidades',
    'rastreadores', 'central-seguranca', 'logs', 'dispositivos',
    'manutencao', 'usuarios', 'instalacao'
  ];
BEGIN
  -- 1. Apenas administradores podem cadastrar
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem cadastrar usuarios.';
  END IF;

  -- 2. SuperAdmin Mestre tem e-mail reservado
  IF LOWER(trim(p_email)) = 'novaes@adm.28bpm.local' AND p_role <> 'superadmin' THEN
    RAISE EXCEPTION 'O e-mail novaes@adm.28bpm.local e reservado exclusivamente para a conta SuperAdmin Mestre.';
  END IF;

  -- 3. Módulos por perfil
  IF p_role IN ('superadmin', 'adm') THEN
    v_modulos_finais := v_modulos_todos;
  ELSIF p_role = 'instalador' THEN
    v_modulos_finais := ARRAY['instalacao'];
  ELSE
    v_modulos_finais := p_modulos;
  END IF;

  -- 4. Cria conta em auth.users
  v_user_id := gen_random_uuid();
  INSERT INTO auth.users (
    id, instance_id, aud, role, email, encrypted_password,
    email_confirmed_at, recovery_sent_at, last_sign_in_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, email_change, email_change_token_new, recovery_token
  ) VALUES (
    v_user_id,
    '00000000-0000-0000-0000-000000000000',
    'authenticated',
    'authenticated',
    LOWER(trim(p_email)),
    crypt(p_senha, gen_salt('bf', 10)),
    now(), now(), now(),
    jsonb_build_object('provider', 'email', 'providers', jsonb_build_array('email')),
    jsonb_build_object('nome', p_nome, 'role', p_role),
    now(), now(), '', '', '', ''
  );

  -- 5. Atualiza ou insere perfil em public.profiles com valor_por_instalacao e chave_pix
  INSERT INTO public.profiles (id, nome, email, role, ativo, valor_por_instalacao, chave_pix)
  VALUES (
    v_user_id,
    p_nome,
    LOWER(trim(p_email)),
    p_role,
    TRUE,
    COALESCE(p_valor_por_instalacao, 0.00),
    NULLIF(trim(p_chave_pix), '')
  )
  ON CONFLICT (id) DO UPDATE
  SET nome = EXCLUDED.nome,
      role = EXCLUDED.role,
      valor_por_instalacao = COALESCE(EXCLUDED.valor_por_instalacao, public.profiles.valor_por_instalacao),
      chave_pix = COALESCE(EXCLUDED.chave_pix, public.profiles.chave_pix),
      ativo = TRUE,
      updated_at = now();

  -- 6. Registra role em public.user_roles
  INSERT INTO public.user_roles (user_id, role)
  VALUES (v_user_id, p_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  -- 7. Atribui módulos permitidos
  IF v_modulos_finais IS NOT NULL AND array_length(v_modulos_finais, 1) > 0 THEN
    FOREACH v_mod IN ARRAY v_modulos_finais LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_user_id, trim(v_mod), TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  -- 8. Registro de auditoria forense
  INSERT INTO public.system_activity_logs (usuario_id, acao, detalhe)
  VALUES (
    v_caller_id,
    'USUARIO_CRIADO',
    format('Usuario %s (%s) criado com role %s por %s. PIX: %s', p_nome, p_email, p_role, v_caller_id, COALESCE(p_chave_pix, 'Nao informada'))
  );

  RETURN jsonb_build_object('success', true, 'message', 'Usuario cadastrado com sucesso!', 'user_id', v_user_id);
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$$;

-- 7. Atualizar admin_atualizar_usuario para salvar chave_pix
CREATE OR REPLACE FUNCTION public.admin_atualizar_usuario(
  p_user_id UUID,
  p_nome TEXT,
  p_role public.hunter_role,
  p_ativo BOOLEAN,
  p_modulos TEXT[] DEFAULT ARRAY[]::TEXT[],
  p_plano public.plano_cliente DEFAULT NULL,
  p_valor_por_instalacao NUMERIC DEFAULT NULL,
  p_chave_pix TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_mod TEXT;
  v_modulos_finais TEXT[];
  v_modulos_todos TEXT[] := ARRAY[
    'monitor-gps', 'atendimento', 'clientes', 'mensalidades',
    'rastreadores', 'central-seguranca', 'logs', 'dispositivos',
    'manutencao', 'usuarios', 'instalacao'
  ];
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem gerenciar usuarios.';
  END IF;

  IF p_role IN ('superadmin', 'adm') THEN
    v_modulos_finais := v_modulos_todos;
  ELSIF p_role = 'instalador' THEN
    v_modulos_finais := ARRAY['instalacao'];
  ELSE
    v_modulos_finais := p_modulos;
  END IF;

  UPDATE public.profiles
  SET nome = p_nome,
      role = p_role,
      ativo = p_ativo,
      valor_por_instalacao = COALESCE(p_valor_por_instalacao, valor_por_instalacao),
      chave_pix = COALESCE(p_chave_pix, chave_pix),
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (p_user_id, p_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  DELETE FROM public.user_roles
  WHERE user_id = p_user_id AND role <> p_role;

  UPDATE public.user_module_access
  SET ativo = FALSE
  WHERE user_id = p_user_id;

  IF v_modulos_finais IS NOT NULL AND array_length(v_modulos_finais, 1) > 0 THEN
    FOREACH v_mod IN ARRAY v_modulos_finais LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (p_user_id, trim(v_mod), TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  INSERT INTO public.system_activity_logs (usuario_id, acao, detalhe)
  VALUES (
    v_caller_id,
    'USUARIO_ATUALIZADO',
    format('Usuario %s atualizado por %s', p_user_id, v_caller_id)
  );

  RETURN jsonb_build_object('success', true, 'message', 'Usuario atualizado com sucesso!');
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$$;

-- 8. RPC Administrativa para Quitar em Lote todas as instalações pendentes de um instalador
CREATE OR REPLACE FUNCTION public.marcar_pagamento_lote_instalador(
  p_instalador_id UUID,
  p_comprovante TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id UUID;
  v_qtd INT;
  v_total NUMERIC(10,2);
BEGIN
  v_user_id := auth.uid();
  IF NOT (
    public.is_admin_or_superadmin(v_user_id) OR
    EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = v_user_id AND role = 'operador')
  ) THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem registrar pagamento.';
  END IF;

  -- Contabiliza e atualiza todas as ordens pendentes
  SELECT COUNT(*), COALESCE(SUM(valor_instalacao), 0.00)
  INTO v_qtd, v_total
  FROM public.instalacoes
  WHERE instalador_id = p_instalador_id AND status_pagamento = 'pendente';

  IF v_qtd = 0 THEN
    RETURN jsonb_build_object('sucesso', false, 'message', 'Não há instalações pendentes para este instalador.');
  END IF;

  UPDATE public.instalacoes
  SET status_pagamento = 'pago',
      pago_em = NOW(),
      pago_por = v_user_id,
      comprovante_pagamento = COALESCE(p_comprovante, comprovante_pagamento),
      updated_at = NOW()
  WHERE instalador_id = p_instalador_id AND status_pagamento = 'pendente';

  INSERT INTO public.system_activity_logs (usuario_id, acao, detalhe)
  VALUES (
    v_user_id,
    'REPASSE_INSTALACOES_LOTE_PAGO',
    format('Repasse em lote de %s instalações do instalador %s quitado. Total: R$ %s', v_qtd, p_instalador_id, v_total)
  );

  RETURN jsonb_build_object(
    'sucesso', true,
    'instalador_id', p_instalador_id,
    'total_quitadas', v_qtd,
    'valor_total', v_total
  );
END;
$$;


-- ============================================================================
-- [13/225] MIGRAÇÃO: 20260919190000_hunter_atualizacao_cliente_unificada.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — ATUALIZAÇÃO UNIFICADA DE CLIENTES E CREDENCIAIS DE ACESSO
-- ============================================================================
-- Permite ao administrador atualizar todos os dados cadastrais, status, plano,
-- parâmetros financeiros e senha/login de acesso do cliente de forma atômica.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.admin_atualizar_cliente_completo(
  p_cliente_id UUID,
  p_nome TEXT,
  p_documento TEXT DEFAULT NULL,
  p_email TEXT DEFAULT NULL,
  p_telefone TEXT DEFAULT NULL,
  p_status public.status_cliente DEFAULT 'ativo',
  p_plano public.plano_cliente DEFAULT 'basico',
  p_dia_vencimento INT DEFAULT 10,
  p_valor_mensalidade NUMERIC DEFAULT 79.90,
  p_dias_historico INT DEFAULT 7,
  p_dias_retencao INT DEFAULT 10,
  p_senha TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_mod TEXT;
  v_modulos TEXT[];
  v_email_antigo TEXT;
BEGIN
  -- 1. Apenas administradores podem atualizar clientes
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem realizar esta operacao.';
  END IF;

  -- 2. Validações do cliente
  IF p_nome IS NULL OR trim(p_nome) = '' THEN
    RAISE EXCEPTION 'O nome ou razao social do cliente e obrigatorio.';
  END IF;

  -- 3. Obter dados atuais do cliente
  SELECT user_id, email INTO v_user_id, v_email_antigo
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente nao encontrado.';
  END IF;

  -- 4. Tratamento do usuário em auth.users e profiles
  -- Caso A: Cliente ainda não tem user_id, mas foi informado e-mail e senha
  IF v_user_id IS NULL AND p_email IS NOT NULL AND trim(p_email) <> '' AND p_senha IS NOT NULL AND length(p_senha) >= 6 THEN
    SELECT id INTO v_user_id FROM auth.users WHERE LOWER(email) = LOWER(trim(p_email));

    IF v_user_id IS NULL THEN
      v_user_id := gen_random_uuid();
      INSERT INTO auth.users (
        id, instance_id, aud, role, email, encrypted_password,
        email_confirmed_at, recovery_sent_at, last_sign_in_at,
        raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
        confirmation_token, email_change, email_change_token_new, recovery_token
      ) VALUES (
        v_user_id,
        '00000000-0000-0000-0000-000000000000',
        'authenticated',
        'authenticated',
        LOWER(trim(p_email)),
        extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
        now(), now(), now(),
        '{"provider":"email","providers":["email"]}',
        jsonb_build_object('nome', p_nome, 'role', 'cliente'),
        now(), now(),
        '', '', '', ''
      );
    ELSE
      UPDATE auth.users
      SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

    -- Cria / atualiza profile
    INSERT INTO public.profiles (id, nome, email, role, ativo)
    VALUES (v_user_id, p_nome, LOWER(trim(p_email)), 'cliente', (p_status = 'ativo' OR p_status = 'aguardando_instalacao'))
    ON CONFLICT (id) DO UPDATE
    SET nome = EXCLUDED.nome,
        email = EXCLUDED.email,
        role = 'cliente',
        ativo = EXCLUDED.ativo,
        updated_at = now();

    INSERT INTO public.user_roles (user_id, role)
    VALUES (v_user_id, 'cliente')
    ON CONFLICT (user_id, role) DO NOTHING;

  -- Caso B: Cliente já possui user_id vinculado
  ELSIF v_user_id IS NOT NULL THEN
    IF p_email IS NOT NULL AND trim(p_email) <> '' THEN
      UPDATE auth.users
      SET email = LOWER(trim(p_email)),
          raw_user_meta_data = jsonb_build_object('nome', p_nome, 'role', 'cliente'),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

    IF p_senha IS NOT NULL AND length(p_senha) >= 6 THEN
      UPDATE auth.users
      SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

    UPDATE public.profiles
    SET nome = trim(p_nome),
        email = COALESCE(NULLIF(LOWER(trim(p_email)), ''), email),
        ativo = (p_status = 'ativo' OR p_status = 'aguardando_instalacao'),
        updated_at = now()
    WHERE id = v_user_id;
  END IF;

  -- Sincroniza os módulos com base no plano comercial
  IF v_user_id IS NOT NULL THEN
    IF p_plano = 'basico' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades'];
    ELSIF p_plano = 'pro' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao'];
    ELSE
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao', 'central-seguranca'];
    END IF;

    DELETE FROM public.user_module_access WHERE user_id = v_user_id;
    FOREACH v_mod IN ARRAY v_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_user_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  -- 5. Atualização atômica na tabela public.clientes
  UPDATE public.clientes
  SET user_id = COALESCE(v_user_id, clientes.user_id),
      nome_razao_social = trim(p_nome),
      documento = NULLIF(trim(p_documento), ''),
      email = NULLIF(LOWER(trim(p_email)), ''),
      telefone = NULLIF(trim(p_telefone), ''),
      status = p_status,
      plano = p_plano,
      dia_vencimento = COALESCE(p_dia_vencimento, dia_vencimento),
      valor_mensalidade = COALESCE(p_valor_mensalidade, valor_mensalidade),
      dias_historico_plano = COALESCE(p_dias_historico, dias_historico_plano),
      dias_retencao_banco = COALESCE(p_dias_retencao, dias_retencao_banco),
      updated_at = now()
  WHERE id = p_cliente_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Ficha do cliente e credenciais atualizadas com sucesso.',
    'cliente_id', p_cliente_id,
    'user_id', v_user_id
  );
END;
$$;


-- ============================================================================
-- [14/225] MIGRAÇÃO: 20260919200000_hunter_agendamento_instalacoes_e_endereco.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — AGENDAMENTO DE INSTALAÇÃO, ENDEREÇO DO TÉCNICO E VINCULAÇÃO
-- ============================================================================
-- Versão: 1.5.4.0
-- 1. Endereço do local de instalação no cadastro do instalador.
-- 2. Atribuição de instalador no cadastro/edição de clientes pelo administrador.
-- 3. Definição de dia e hora pelo instalador no seu módulo.
-- 4. Painel de status e agendamento para o cliente no login.
-- ============================================================================

-- 1. Coluna de endereço da oficina / ponto de instalação no perfil
DO $$ BEGIN
  ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS endereco_instalacao TEXT;
EXCEPTION
  WHEN duplicate_column THEN NULL;
END $$;

-- 2. Colunas de instalador e agendamento na tabela de clientes
DO $$ BEGIN
  ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS instalador_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL;
EXCEPTION
  WHEN duplicate_column THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS data_agendamento DATE;
EXCEPTION
  WHEN duplicate_column THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS hora_agendamento TEXT;
EXCEPTION
  WHEN duplicate_column THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS status_agendamento TEXT DEFAULT 'aguardando_agendamento';
EXCEPTION
  WHEN duplicate_column THEN NULL;
END $$;

CREATE INDEX IF NOT EXISTS idx_clientes_instalador ON public.clientes(instalador_id);
CREATE INDEX IF NOT EXISTS idx_clientes_agendamento ON public.clientes(status_agendamento);

-- 3. RPC para o instalador definir dia e hora do agendamento
CREATE OR REPLACE FUNCTION public.instalador_definir_agendamento(
  p_cliente_id UUID,
  p_data DATE,
  p_hora TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_instalador_id UUID;
  v_cliente_nome TEXT;
BEGIN
  -- 1. Obter dados do cliente
  SELECT instalador_id, nome_razao_social INTO v_instalador_id, v_cliente_nome
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente nao encontrado.';
  END IF;

  -- 2. Verificar se o chamador é o instalador atribuído ou administrador
  IF v_caller_id <> v_instalador_id AND NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas o instalador atribuido ou administrador podem agendar este atendimento.';
  END IF;

  -- 3. Validar data e hora
  IF p_data IS NULL THEN
    RAISE EXCEPTION 'A data do agendamento e obrigatoria.';
  END IF;

  IF p_hora IS NULL OR trim(p_hora) = '' THEN
    RAISE EXCEPTION 'O horario do agendamento e obrigatorio.';
  END IF;

  -- 4. Atualizar o agendamento
  UPDATE public.clientes
  SET data_agendamento = p_data,
      hora_agendamento = trim(p_hora),
      status_agendamento = 'agendado',
      updated_at = now()
  WHERE id = p_cliente_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Agendamento confirmado para o cliente ' || v_cliente_nome || ' em ' || to_char(p_data, 'DD/MM/YYYY') || ' as ' || trim(p_hora) || '.',
    'cliente_id', p_cliente_id,
    'data', p_data,
    'hora', trim(p_hora)
  );
END;
$$;

-- 4. Atualizar RPC admin_cadastrar_cliente_completo com instalador_id
CREATE OR REPLACE FUNCTION public.admin_cadastrar_cliente_completo(
  p_nome TEXT,
  p_documento TEXT DEFAULT NULL,
  p_email TEXT DEFAULT NULL,
  p_telefone TEXT DEFAULT NULL,
  p_plano public.plano_cliente DEFAULT 'basico',
  p_dia_vencimento INT DEFAULT 10,
  p_valor_mensalidade NUMERIC DEFAULT 79.90,
  p_dias_historico INT DEFAULT 7,
  p_dias_retencao INT DEFAULT 10,
  p_criar_usuario BOOLEAN DEFAULT TRUE,
  p_senha TEXT DEFAULT NULL,
  p_placa TEXT DEFAULT NULL,
  p_marca_modelo TEXT DEFAULT NULL,
  p_km_inicial INT DEFAULT 0,
  p_instalador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_id UUID := NULL;
  v_cliente_id UUID;
  v_veiculo_id UUID;
  v_mod TEXT;
  v_modulos TEXT[];
BEGIN
  -- 1. Apenas administradores podem cadastrar
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem realizar esta operacao.';
  END IF;

  -- 2. Validações básicas do cliente
  IF p_nome IS NULL OR trim(p_nome) = '' THEN
    RAISE EXCEPTION 'O nome ou razao social do cliente e obrigatorio.';
  END IF;

  -- 3. Criação de usuário em auth.users se solicitado
  IF p_criar_usuario THEN
    IF p_email IS NULL OR trim(p_email) = '' THEN
      RAISE EXCEPTION 'O e-mail e obrigatorio para liberar acesso ao sistema.';
    END IF;

    IF p_senha IS NULL OR length(p_senha) < 6 THEN
      RAISE EXCEPTION 'A senha inicial de acesso deve conter no minimo 6 caracteres.';
    END IF;

    IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = LOWER(trim(p_email))) THEN
      RAISE EXCEPTION 'Ja existe um usuario cadastrado no sistema com este e-mail.';
    END IF;

    v_user_id := gen_random_uuid();

    INSERT INTO auth.users (
      id, instance_id, aud, role, email, encrypted_password,
      email_confirmed_at, recovery_sent_at, last_sign_in_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, email_change, email_change_token_new, recovery_token
    ) VALUES (
      v_user_id,
      '00000000-0000-0000-0000-000000000000',
      'authenticated',
      'authenticated',
      LOWER(trim(p_email)),
      extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
      now(), now(), now(),
      '{"provider":"email","providers":["email"]}',
      jsonb_build_object('nome', p_nome, 'role', 'cliente'),
      now(), now(),
      '', '', '', ''
    );

    INSERT INTO public.profiles (id, nome, email, role, ativo)
    VALUES (v_user_id, p_nome, LOWER(trim(p_email)), 'cliente', TRUE)
    ON CONFLICT (id) DO UPDATE
    SET nome = EXCLUDED.nome,
        role = 'cliente',
        ativo = TRUE,
        updated_at = now();

    INSERT INTO public.user_roles (user_id, role)
    VALUES (v_user_id, 'cliente')
    ON CONFLICT (user_id, role) DO NOTHING;

    IF p_plano = 'basico' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades'];
    ELSIF p_plano = 'pro' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao'];
    ELSE
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao', 'central-seguranca'];
    END IF;

    FOREACH v_mod IN ARRAY v_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_user_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  -- 4. Inserção na tabela public.clientes vinculada ao v_user_id e ao instalador_id
  v_cliente_id := gen_random_uuid();
  INSERT INTO public.clientes (
    id,
    user_id,
    instalador_id,
    nome_razao_social,
    documento,
    email,
    telefone,
    plano,
    status,
    status_agendamento,
    dia_vencimento,
    valor_mensalidade,
    dias_historico_plano,
    dias_retencao_banco,
    created_at,
    updated_at
  ) VALUES (
    v_cliente_id,
    v_user_id,
    p_instalador_id,
    trim(p_nome),
    NULLIF(trim(p_documento), ''),
    NULLIF(LOWER(trim(p_email)), ''),
    NULLIF(trim(p_telefone), ''),
    p_plano,
    'aguardando_instalacao',
    'aguardando_agendamento',
    COALESCE(p_dia_vencimento, 10),
    COALESCE(p_valor_mensalidade, 79.90),
    COALESCE(p_dias_historico, 7),
    COALESCE(p_dias_retencao, 10),
    now(),
    now()
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Cliente cadastrado com sucesso. Status: aguardando instalacao.',
    'cliente_id', v_cliente_id,
    'user_id', v_user_id,
    'instalador_id', p_instalador_id
  );
END;
$$;

-- 5. Atualizar RPC admin_atualizar_cliente_completo com instalador_id e agendamento
CREATE OR REPLACE FUNCTION public.admin_atualizar_cliente_completo(
  p_cliente_id UUID,
  p_nome TEXT,
  p_documento TEXT DEFAULT NULL,
  p_email TEXT DEFAULT NULL,
  p_telefone TEXT DEFAULT NULL,
  p_status public.status_cliente DEFAULT 'ativo',
  p_plano public.plano_cliente DEFAULT 'basico',
  p_dia_vencimento INT DEFAULT 10,
  p_valor_mensalidade NUMERIC DEFAULT 79.90,
  p_dias_historico INT DEFAULT 7,
  p_dias_retencao INT DEFAULT 10,
  p_senha TEXT DEFAULT NULL,
  p_instalador_id UUID DEFAULT NULL,
  p_data_agendamento DATE DEFAULT NULL,
  p_hora_agendamento TEXT DEFAULT NULL,
  p_status_agendamento TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_mod TEXT;
  v_modulos TEXT[];
  v_email_antigo TEXT;
BEGIN
  -- 1. Apenas administradores podem atualizar clientes
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem realizar esta operacao.';
  END IF;

  -- 2. Validações do cliente
  IF p_nome IS NULL OR trim(p_nome) = '' THEN
    RAISE EXCEPTION 'O nome ou razao social do cliente e obrigatorio.';
  END IF;

  -- 3. Obter dados atuais do cliente
  SELECT user_id, email INTO v_user_id, v_email_antigo
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente nao encontrado.';
  END IF;

  -- 4. Tratamento do usuário em auth.users e profiles
  IF v_user_id IS NULL AND p_email IS NOT NULL AND trim(p_email) <> '' AND p_senha IS NOT NULL AND length(p_senha) >= 6 THEN
    SELECT id INTO v_user_id FROM auth.users WHERE LOWER(email) = LOWER(trim(p_email));

    IF v_user_id IS NULL THEN
      v_user_id := gen_random_uuid();
      INSERT INTO auth.users (
        id, instance_id, aud, role, email, encrypted_password,
        email_confirmed_at, recovery_sent_at, last_sign_in_at,
        raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
        confirmation_token, email_change, email_change_token_new, recovery_token
      ) VALUES (
        v_user_id,
        '00000000-0000-0000-0000-000000000000',
        'authenticated',
        'authenticated',
        LOWER(trim(p_email)),
        extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
        now(), now(), now(),
        '{"provider":"email","providers":["email"]}',
        jsonb_build_object('nome', p_nome, 'role', 'cliente'),
        now(), now(),
        '', '', '', ''
      );
    ELSE
      UPDATE auth.users
      SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

    INSERT INTO public.profiles (id, nome, email, role, ativo)
    VALUES (v_user_id, p_nome, LOWER(trim(p_email)), 'cliente', (p_status = 'ativo' OR p_status = 'aguardando_instalacao'))
    ON CONFLICT (id) DO UPDATE
    SET nome = EXCLUDED.nome,
        email = EXCLUDED.email,
        role = 'cliente',
        ativo = EXCLUDED.ativo,
        updated_at = now();

    INSERT INTO public.user_roles (user_id, role)
    VALUES (v_user_id, 'cliente')
    ON CONFLICT (user_id, role) DO NOTHING;

  ELSIF v_user_id IS NOT NULL THEN
    IF p_email IS NOT NULL AND trim(p_email) <> '' THEN
      UPDATE auth.users
      SET email = LOWER(trim(p_email)),
          raw_user_meta_data = jsonb_build_object('nome', p_nome, 'role', 'cliente'),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

    IF p_senha IS NOT NULL AND length(p_senha) >= 6 THEN
      UPDATE auth.users
      SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

    UPDATE public.profiles
    SET nome = trim(p_nome),
        email = COALESCE(NULLIF(LOWER(trim(p_email)), ''), email),
        ativo = (p_status = 'ativo' OR p_status = 'aguardando_instalacao'),
        updated_at = now()
    WHERE id = v_user_id;
  END IF;

  IF v_user_id IS NOT NULL THEN
    IF p_plano = 'basico' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades'];
    ELSIF p_plano = 'pro' THEN
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao'];
    ELSE
      v_modulos := ARRAY['monitor-gps', 'atendimento', 'mensalidades', 'manutencao', 'central-seguranca'];
    END IF;

    DELETE FROM public.user_module_access WHERE user_id = v_user_id;
    FOREACH v_mod IN ARRAY v_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_user_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  -- 5. Atualização atômica na tabela public.clientes
  UPDATE public.clientes
  SET user_id = COALESCE(v_user_id, clientes.user_id),
      instalador_id = COALESCE(p_instalador_id, clientes.instalador_id),
      nome_razao_social = trim(p_nome),
      documento = NULLIF(trim(p_documento), ''),
      email = NULLIF(LOWER(trim(p_email)), ''),
      telefone = NULLIF(trim(p_telefone), ''),
      status = p_status,
      plano = p_plano,
      data_agendamento = COALESCE(p_data_agendamento, clientes.data_agendamento),
      hora_agendamento = COALESCE(p_hora_agendamento, clientes.hora_agendamento),
      status_agendamento = COALESCE(p_status_agendamento, clientes.status_agendamento),
      dia_vencimento = COALESCE(p_dia_vencimento, dia_vencimento),
      valor_mensalidade = COALESCE(p_valor_mensalidade, valor_mensalidade),
      dias_historico_plano = COALESCE(p_dias_historico, dias_historico_plano),
      dias_retencao_banco = COALESCE(p_dias_retencao, dias_retencao_banco),
      updated_at = now()
  WHERE id = p_cliente_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Ficha do cliente e credenciais atualizadas com sucesso.',
    'cliente_id', p_cliente_id,
    'user_id', v_user_id,
    'instalador_id', p_instalador_id
  );
END;
$$;

-- 6. Atualizar RPC admin_cadastrar_usuario e admin_atualizar_usuario para endereco_instalacao
CREATE OR REPLACE FUNCTION public.admin_cadastrar_usuario(
  p_email TEXT,
  p_senha TEXT,
  p_nome TEXT,
  p_role public.hunter_role,
  p_plano public.plano_cliente DEFAULT 'basico',
  p_modulos TEXT[] DEFAULT ARRAY[]::TEXT[],
  p_valor_por_instalacao NUMERIC DEFAULT 0.00,
  p_chave_pix TEXT DEFAULT NULL,
  p_endereco_instalacao TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_novo_user_id UUID;
  v_mod TEXT;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem criar novos usuarios.';
  END IF;

  IF p_email IS NULL OR trim(p_email) = '' THEN
    RAISE EXCEPTION 'O e-mail e obrigatorio.';
  END IF;

  IF p_senha IS NULL OR length(p_senha) < 6 THEN
    RAISE EXCEPTION 'A senha deve conter no minimo 6 caracteres.';
  END IF;

  IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = LOWER(trim(p_email))) THEN
    RAISE EXCEPTION 'Ja existe um usuario cadastrado com este e-mail.';
  END IF;

  v_novo_user_id := gen_random_uuid();

  INSERT INTO auth.users (
    id, instance_id, aud, role, email, encrypted_password,
    email_confirmed_at, recovery_sent_at, last_sign_in_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, email_change, email_change_token_new, recovery_token
  ) VALUES (
    v_novo_user_id,
    '00000000-0000-0000-0000-000000000000',
    'authenticated',
    'authenticated',
    LOWER(trim(p_email)),
    extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
    now(), now(), now(),
    '{"provider":"email","providers":["email"]}',
    jsonb_build_object('nome', p_nome, 'role', p_role),
    now(), now(),
    '', '', '', ''
  );

  INSERT INTO public.profiles (id, nome, email, role, valor_por_instalacao, chave_pix, endereco_instalacao, ativo)
  VALUES (v_novo_user_id, p_nome, LOWER(trim(p_email)), p_role, p_valor_por_instalacao, p_chave_pix, p_endereco_instalacao, TRUE)
  ON CONFLICT (id) DO UPDATE
  SET nome = EXCLUDED.nome,
      role = EXCLUDED.role,
      valor_por_instalacao = EXCLUDED.valor_por_instalacao,
      chave_pix = EXCLUDED.chave_pix,
      endereco_instalacao = EXCLUDED.endereco_instalacao,
      ativo = TRUE,
      updated_at = now();

  INSERT INTO public.user_roles (user_id, role)
  VALUES (v_novo_user_id, p_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  IF p_role = 'instalador' THEN
    p_modulos := ARRAY['instalacao'];
  END IF;

  IF p_modulos IS NOT NULL THEN
    FOREACH v_mod IN ARRAY p_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_novo_user_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Usuario criado com sucesso.',
    'user_id', v_novo_user_id
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_atualizar_usuario(
  p_usuario_id UUID,
  p_nome TEXT,
  p_role public.hunter_role,
  p_ativo BOOLEAN,
  p_plano public.plano_cliente DEFAULT 'basico',
  p_modulos TEXT[] DEFAULT ARRAY[]::TEXT[],
  p_valor_por_instalacao NUMERIC DEFAULT 0.00,
  p_chave_pix TEXT DEFAULT NULL,
  p_endereco_instalacao TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_mod TEXT;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem atualizar usuarios.';
  END IF;

  IF EXISTS (SELECT 1 FROM auth.users WHERE id = p_usuario_id AND email = 'novaes@adm.28bpm.local') THEN
    IF p_role <> 'superadmin' OR p_ativo = FALSE THEN
      RAISE EXCEPTION 'A conta SuperAdmin mestre e imutavel e blindada contra rebaixamento ou inativacao.';
    END IF;
  END IF;

  UPDATE public.profiles
  SET nome = p_nome,
      role = p_role,
      ativo = p_ativo,
      valor_por_instalacao = p_valor_por_instalacao,
      chave_pix = p_chave_pix,
      endereco_instalacao = p_endereco_instalacao,
      updated_at = now()
  WHERE id = p_usuario_id;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (p_usuario_id, p_role)
  ON CONFLICT (user_id, role) DO UPDATE SET role = EXCLUDED.role;

  IF p_role = 'instalador' THEN
    p_modulos := ARRAY['instalacao'];
  END IF;

  DELETE FROM public.user_module_access WHERE user_id = p_usuario_id;
  IF p_modulos IS NOT NULL THEN
    FOREACH v_mod IN ARRAY p_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (p_usuario_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Usuario atualizado com sucesso.'
  );
END;
$$;

-- 7. Políticas de RLS para o cliente ler seu próprio cadastro com dados do instalador
DROP POLICY IF EXISTS "Clientes leem seus proprios dados de cliente" ON public.clientes;
CREATE POLICY "Clientes leem seus proprios dados de cliente"
ON public.clientes FOR SELECT TO authenticated
USING (
  public.is_admin_or_superadmin(auth.uid()) OR
  user_id = auth.uid() OR
  instalador_id = auth.uid() OR
  EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'operador')
);

-- Permissão para que clientes consultem o perfil público do instalador atribuído
DROP POLICY IF EXISTS "Clientes leem perfil do seu instalador" ON public.profiles;
CREATE POLICY "Clientes leem perfil do seu instalador"
ON public.profiles FOR SELECT TO authenticated
USING (
  public.is_admin_or_superadmin(auth.uid()) OR
  id = auth.uid() OR
  role = 'instalador' OR
  EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role IN ('operador', 'instalador'))
);

-- 8. Ativação de Realtime no Banco de Dados para sincronização instantânea sem cache
ALTER TABLE public.clientes REPLICA IDENTITY FULL;
ALTER TABLE public.instalacoes REPLICA IDENTITY FULL;
ALTER TABLE public.profiles REPLICA IDENTITY FULL;

DO $$ BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.clientes;
EXCEPTION
  WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.profiles;
EXCEPTION
  WHEN duplicate_object THEN NULL;
END $$;



