-- Migration: 20260919235500_hunter_geracao_e_adm_mensalidades.sql
-- Objetivo: Funcoes RPC para geracao em lote de mensalidades por competencia e atualizacao de vencidos

-- 1. Funcao para atualizacao de mensalidades vencidas automaticamente
CREATE OR REPLACE FUNCTION public.admin_atualizar_status_mensalidades_vencidas()
RETURNS INT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_afetados INT := 0;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem atualizar status de mensalidades.';
  END IF;

  UPDATE public.mensalidades
  SET status = 'vencido',
      updated_at = NOW()
  WHERE status = 'pendente'
    AND data_vencimento < CURRENT_DATE;

  GET DIAGNOSTICS v_afetados = ROW_COUNT;
  RETURN v_afetados;
END;
$$;

-- 2. Funcao para geracao em lote de mensalidades por competencia (mes e ano)
CREATE OR REPLACE FUNCTION public.admin_gerar_mensalidades_mes(
  p_mes INT,
  p_ano INT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_cliente RECORD;
  v_dia_max INT;
  v_dia_final INT;
  v_data_venc DATE;
  v_status_inicial public.status_mensalidade;
  v_total_clientes INT := 0;
  v_geradas INT := 0;
  v_ja_existentes INT := 0;
  v_inserido BOOLEAN;
BEGIN
  -- Validacao de seguranca SuperAdmin e Adm
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem gerar mensalidades em lote.';
  END IF;

  IF p_mes < 1 OR p_mes > 12 THEN
    RAISE EXCEPTION 'Mes de referencia invalido: deve estar entre 1 e 12.';
  END IF;

  IF p_ano < 2024 OR p_ano > 2099 THEN
    RAISE EXCEPTION 'Ano de referencia invalido.';
  END IF;

  -- Calcular o ultimo dia valido do mes (ex: 28, 29, 30 ou 31)
  v_dia_max := EXTRACT(DAY FROM (DATE_TRUNC('month', make_date(p_ano, p_mes, 1)) + INTERVAL '1 month - 1 day'))::INT;

  FOR v_cliente IN
    SELECT id, dia_vencimento, valor_mensalidade, nome_razao_social
    FROM public.clientes
    WHERE status <> 'bloqueado'
      AND valor_mensalidade > 0
  LOOP
    v_total_clientes := v_total_clientes + 1;

    -- Ajustar o dia de vencimento para nao ultrapassar o ultimo dia do mes
    v_dia_final := LEAST(COALESCE(v_cliente.dia_vencimento, 10), v_dia_max);
    v_data_venc := make_date(p_ano, p_mes, v_dia_final);

    -- Determinar se ja esta vencido em relacao a data atual
    IF v_data_venc < CURRENT_DATE THEN
      v_status_inicial := 'vencido';
    ELSE
      v_status_inicial := 'pendente';
    END IF;

    -- Inserir ignorando duplicidade pela constraint uq_cliente_mensalidade
    INSERT INTO public.mensalidades (
      cliente_id,
      mes_referencia,
      ano_referencia,
      valor,
      data_vencimento,
      status,
      created_at,
      updated_at
    ) VALUES (
      v_cliente.id,
      p_mes,
      p_ano,
      v_cliente.valor_mensalidade,
      v_data_venc,
      v_status_inicial,
      NOW(),
      NOW()
    )
    ON CONFLICT (cliente_id, mes_referencia, ano_referencia) DO NOTHING;

    IF FOUND THEN
      v_geradas := v_geradas + 1;
    ELSE
      v_ja_existentes := v_ja_existentes + 1;
    END IF;
  END LOOP;

  -- Registrar log de atividade do sistema
  INSERT INTO public.system_activity_logs (
    user_id,
    acao,
    detalhe,
    created_at
  ) VALUES (
    auth.uid(),
    'GERACAO_MENSALIDADES_LOTE',
    'Competencia: ' || LPAD(p_mes::TEXT, 2, '0') || '/' || p_ano::TEXT ||
    ' | Geradas: ' || v_geradas::TEXT ||
    ' | Ja existentes: ' || v_ja_existentes::TEXT ||
    ' | Total clientes aptos: ' || v_total_clientes::TEXT,
    NOW()
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'mes_referencia', p_mes,
    'ano_referencia', p_ano,
    'geradas', v_geradas,
    'ja_existentes', v_ja_existentes,
    'total_clientes', v_total_clientes
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_atualizar_status_mensalidades_vencidas() TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_gerar_mensalidades_mes(INT, INT) TO authenticated;

COMMENT ON FUNCTION public.admin_gerar_mensalidades_mes(INT, INT) IS 'Gera em lote as mensalidades de todos os clientes aptos para uma competencia especifica (mes e ano) sem duplicidades.';


-- ============================================================================
-- [20/225] MIGRAÇÃO: 20260919235600_hunter_modulo_financeiro_integrado.sql
-- ============================================================================

-- Migration: 20260919235600_hunter_modulo_financeiro_integrado.sql
-- Objetivo: Criacao do Ledger de Transacoes Financeiras, Triggers de Sincronizacao de Mensalidades e Instalacoes

-- 1. ENUMS FINANCEIROS
DO $$ BEGIN
  CREATE TYPE public.tipo_transacao_financeira AS ENUM ('entrada', 'saida');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  CREATE TYPE public.status_transacao_financeira AS ENUM ('pendente', 'concluido', 'cancelado');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  CREATE TYPE public.categoria_transacao_financeira AS ENUM (
    'mensalidade',
    'repasse_instalador',
    'chips_conectividade',
    'infraestrutura_servidores',
    'aquisicao_equipamentos',
    'material_consumo',
    'despesa_administrativa',
    'receita_avulsa',
    'outros'
  );
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

-- 2. TABELA DE TRANSACOES FINANCEIRAS (LIVRO-RAZAO / LEDGER)
CREATE TABLE IF NOT EXISTS public.transacoes_financeiras (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tipo public.tipo_transacao_financeira NOT NULL,
  categoria public.categoria_transacao_financeira NOT NULL DEFAULT 'outros',
  descricao TEXT NOT NULL,
  valor NUMERIC(10, 2) NOT NULL CHECK (valor > 0),
  data_competencia DATE NOT NULL DEFAULT CURRENT_DATE,
  data_vencimento DATE,
  data_pagamento TIMESTAMPTZ,
  status public.status_transacao_financeira NOT NULL DEFAULT 'pendente',
  mensalidade_id UUID REFERENCES public.mensalidades(id) ON DELETE CASCADE,
  instalacao_id UUID REFERENCES public.instalacoes(id) ON DELETE CASCADE,
  cliente_id UUID REFERENCES public.clientes(id) ON DELETE SET NULL,
  instalador_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  comprovante_url TEXT,
  observacoes TEXT,
  created_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_transacao_mensalidade UNIQUE (mensalidade_id),
  CONSTRAINT uq_transacao_instalacao UNIQUE (instalacao_id)
);

-- Indices para performance de filtros por data, tipo e status
CREATE INDEX IF NOT EXISTS idx_transacoes_data_competencia ON public.transacoes_financeiras(data_competencia DESC);
CREATE INDEX IF NOT EXISTS idx_transacoes_tipo_status ON public.transacoes_financeiras(tipo, status);
CREATE INDEX IF NOT EXISTS idx_transacoes_categoria ON public.transacoes_financeiras(categoria);
CREATE INDEX IF NOT EXISTS idx_transacoes_cliente ON public.transacoes_financeiras(cliente_id);
CREATE INDEX IF NOT EXISTS idx_transacoes_instalador ON public.transacoes_financeiras(instalador_id);

-- 3. RLS ESTRITO: APENAS SUPERADMIN E ADM GERENCIAM TRANSACOES
ALTER TABLE public.transacoes_financeiras ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Admins gerenciam transacoes financeiras" ON public.transacoes_financeiras;
CREATE POLICY "Admins gerenciam transacoes financeiras"
ON public.transacoes_financeiras FOR ALL TO authenticated
USING (public.is_adm())
WITH CHECK (public.is_adm());

-- 4. TRIGGER: SINCRONIZACAO ATOMICA DE MENSALIDADES -> TRANSACOES
CREATE OR REPLACE FUNCTION public.trg_sync_mensalidade_transacao()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_cliente_nome TEXT;
  v_status_trans public.status_transacao_financeira;
  v_desc TEXT;
BEGIN
  -- Obter nome do cliente para enriquecer o extrato
  SELECT nome_razao_social INTO v_cliente_nome
  FROM public.clientes WHERE id = NEW.cliente_id;

  v_desc := 'Mensalidade ' || LPAD(NEW.mes_referencia::TEXT, 2, '0') || '/' || NEW.ano_referencia::TEXT ||
            ' - ' || COALESCE(v_cliente_nome, 'Cliente');

  IF NEW.status = 'pago' THEN
    v_status_trans := 'concluido';
  ELSE
    v_status_trans := 'pendente';
  END IF;

  INSERT INTO public.transacoes_financeiras (
    tipo,
    categoria,
    descricao,
    valor,
    data_competencia,
    data_vencimento,
    data_pagamento,
    status,
    mensalidade_id,
    cliente_id,
    comprovante_url,
    updated_at
  ) VALUES (
    'entrada',
    'mensalidade',
    v_desc,
    NEW.valor,
    make_date(NEW.ano_referencia, NEW.mes_referencia, 1),
    NEW.data_vencimento,
    NEW.data_pagamento,
    v_status_trans,
    NEW.id,
    NEW.cliente_id,
    NEW.comprovante_url,
    NOW()
  )
  ON CONFLICT (mensalidade_id) DO UPDATE SET
    valor = EXCLUDED.valor,
    descricao = EXCLUDED.descricao,
    data_vencimento = EXCLUDED.data_vencimento,
    data_pagamento = EXCLUDED.data_pagamento,
    status = EXCLUDED.status,
    comprovante_url = EXCLUDED.comprovante_url,
    updated_at = NOW();

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_mensalidade_transacao ON public.mensalidades;
CREATE TRIGGER trg_sync_mensalidade_transacao
AFTER INSERT OR UPDATE ON public.mensalidades
FOR EACH ROW EXECUTE FUNCTION public.trg_sync_mensalidade_transacao();

-- 5. TRIGGER: SINCRONIZACAO ATOMICA DE INSTALACOES (REPASSES) -> TRANSACOES
CREATE OR REPLACE FUNCTION public.trg_sync_instalacao_transacao()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_instalador_nome TEXT;
  v_cliente_nome TEXT;
  v_status_trans public.status_transacao_financeira;
  v_desc TEXT;
BEGIN
  -- Verificar se ha valor de repasse definido
  IF NEW.valor_repasse IS NULL OR NEW.valor_repasse <= 0 THEN
    RETURN NEW;
  END IF;

  SELECT nome INTO v_instalador_nome
  FROM public.profiles WHERE id = NEW.instalador_id;

  SELECT c.nome_razao_social INTO v_cliente_nome
  FROM public.veiculos v
  JOIN public.clientes c ON v.cliente_id = c.id
  WHERE v.id = NEW.veiculo_id;

  v_desc := 'Repasse Instalador (' || COALESCE(v_instalador_nome, 'Tecnico') || ') - Veiculo Cliente ' || COALESCE(v_cliente_nome, '');

  IF NEW.status_pagamento = 'pago' THEN
    v_status_trans := 'concluido';
  ELSE
    v_status_trans := 'pendente';
  END IF;

  INSERT INTO public.transacoes_financeiras (
    tipo,
    categoria,
    descricao,
    valor,
    data_competencia,
    data_vencimento,
    data_pagamento,
    status,
    instalacao_id,
    instalador_id,
    comprovante_url,
    updated_at
  ) VALUES (
    'saida',
    'repasse_instalador',
    v_desc,
    NEW.valor_repasse,
    COALESCE(NEW.data_instalacao::DATE, CURRENT_DATE),
    COALESCE(NEW.data_instalacao::DATE, CURRENT_DATE),
    NEW.data_pagamento_repasse,
    v_status_trans,
    NEW.id,
    NEW.instalador_id,
    NEW.comprovante_pagamento_url,
    NOW()
  )
  ON CONFLICT (instalacao_id) DO UPDATE SET
    valor = EXCLUDED.valor,
    descricao = EXCLUDED.descricao,
    data_pagamento = EXCLUDED.data_pagamento,
    status = EXCLUDED.status,
    comprovante_url = EXCLUDED.comprovante_url,
    updated_at = NOW();

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_instalacao_transacao ON public.instalacoes;
CREATE TRIGGER trg_sync_instalacao_transacao
AFTER INSERT OR UPDATE ON public.instalacoes
FOR EACH ROW EXECUTE FUNCTION public.trg_sync_instalacao_transacao();

-- 6. BACKFILL INICIAL PARA SINCRONIZAR MENSALIDADES E INSTALACOES EXISTENTES
DO $$
DECLARE
  v_m RECORD;
  v_inst RECORD;
  v_cliente_nome TEXT;
  v_instalador_nome TEXT;
BEGIN
  -- Backfill de mensalidades existentes
  FOR v_m IN SELECT * FROM public.mensalidades LOOP
    SELECT nome_razao_social INTO v_cliente_nome FROM public.clientes WHERE id = v_m.cliente_id;
    INSERT INTO public.transacoes_financeiras (
      tipo, categoria, descricao, valor, data_competencia, data_vencimento,
      data_pagamento, status, mensalidade_id, cliente_id, comprovante_url
    ) VALUES (
      'entrada',
      'mensalidade',
      'Mensalidade ' || LPAD(v_m.mes_referencia::TEXT, 2, '0') || '/' || v_m.ano_referencia::TEXT || ' - ' || COALESCE(v_cliente_nome, 'Cliente'),
      v_m.valor,
      make_date(v_m.ano_referencia, v_m.mes_referencia, 1),
      v_m.data_vencimento,
      v_m.data_pagamento,
      CASE WHEN v_m.status = 'pago' THEN 'concluido'::public.status_transacao_financeira ELSE 'pendente'::public.status_transacao_financeira END,
      v_m.id,
      v_m.cliente_id,
      v_m.comprovante_url
    ) ON CONFLICT (mensalidade_id) DO NOTHING;
  END LOOP;

  -- Backfill de instalacoes existentes
  FOR v_inst IN SELECT * FROM public.instalacoes WHERE valor_repasse > 0 LOOP
    SELECT nome INTO v_instalador_nome FROM public.profiles WHERE id = v_inst.instalador_id;
    INSERT INTO public.transacoes_financeiras (
      tipo, categoria, descricao, valor, data_competencia, data_vencimento,
      data_pagamento, status, instalacao_id, instalador_id, comprovante_url
    ) VALUES (
      'saida',
      'repasse_instalador',
      'Repasse Instalador (' || COALESCE(v_instalador_nome, 'Tecnico') || ')',
      v_inst.valor_repasse,
      COALESCE(v_inst.data_instalacao::DATE, CURRENT_DATE),
      COALESCE(v_inst.data_instalacao::DATE, CURRENT_DATE),
      v_inst.data_pagamento_repasse,
      CASE WHEN v_inst.status_pagamento = 'pago' THEN 'concluido'::public.status_transacao_financeira ELSE 'pendente'::public.status_transacao_financeira END,
      v_inst.id,
      v_inst.instalador_id,
      v_inst.comprovante_pagamento_url
    ) ON CONFLICT (instalacao_id) DO NOTHING;
  END LOOP;
END $$;

-- 7. ADICIONAR MODULO 'financeiro' AO CATALOGO DE PERMISSOES
DO $$
DECLARE
  v_admin RECORD;
BEGIN
  FOR v_admin IN
    SELECT id FROM public.profiles WHERE role IN ('superadmin', 'adm')
  LOOP
    INSERT INTO public.user_module_access (user_id, module, ativo)
    VALUES (v_admin.id, 'financeiro', TRUE)
    ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
  END LOOP;
END $$;

COMMENT ON TABLE public.transacoes_financeiras IS 'Livro-Razao unificado com todas as movimentacoes de receitas, despesas, repasses e fluxo de caixa da plataforma Hunter.';


-- ============================================================================
-- [21/225] MIGRAÇÃO: 20260919235800_hunter_remover_veiculos_mock_e_dados_irreais.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — CORREÇÃO: TRANSAÇÕES FINANCEIRAS, RELOAD SCHEMA E EXPURGO DE MOCKS
-- ============================================================================
-- Versão Alvo: 1.5.5.5
-- 1. Garante tabela public.transacoes_financeiras e RLS
-- 2. Recarrega o schema cache do PostgREST
-- 3. Desativa e remove veículos e telemetria fictícia (Frota Hunter Operacional)
-- ============================================================================

-- 1. GARANTIR TABELA TRANSAÇÕES FINANCEIRAS
CREATE TABLE IF NOT EXISTS public.transacoes_financeiras (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tipo TEXT NOT NULL CHECK (tipo IN ('receita', 'despesa')),
  categoria TEXT NOT NULL,
  descricao TEXT NOT NULL,
  valor NUMERIC(10, 2) NOT NULL CHECK (valor > 0),
  data_competencia DATE NOT NULL,
  data_vencimento DATE NOT NULL,
  data_pagamento TIMESTAMPTZ,
  status TEXT NOT NULL DEFAULT 'pendente' CHECK (status IN ('pendente', 'pago', 'cancelado', 'estornado')),
  mensalidade_id UUID REFERENCES public.mensalidades(id) ON DELETE SET NULL,
  instalacao_id UUID REFERENCES public.instalacoes(id) ON DELETE SET NULL,
  cliente_id UUID REFERENCES public.clientes(id) ON DELETE SET NULL,
  instalador_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  comprovante_url TEXT,
  observacoes TEXT,
  created_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Índices de performance
CREATE INDEX IF NOT EXISTS idx_transacoes_data_competencia ON public.transacoes_financeiras(data_competencia DESC);
CREATE INDEX IF NOT EXISTS idx_transacoes_tipo_status ON public.transacoes_financeiras(tipo, status);
CREATE INDEX IF NOT EXISTS idx_transacoes_categoria ON public.transacoes_financeiras(categoria);
CREATE INDEX IF NOT EXISTS idx_transacoes_cliente ON public.transacoes_financeiras(cliente_id);
CREATE INDEX IF NOT EXISTS idx_transacoes_instalador ON public.transacoes_financeiras(instalador_id);

-- Habilitar RLS
ALTER TABLE public.transacoes_financeiras ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Admins gerenciam transacoes financeiras" ON public.transacoes_financeiras;
CREATE POLICY "Admins gerenciam transacoes financeiras"
ON public.transacoes_financeiras FOR ALL TO authenticated
USING (public.is_adm())
WITH CHECK (public.is_adm());

-- Sincronizar mensalidades já existentes no livro-razão caso a tabela esteja vazia
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.transacoes_financeiras LIMIT 1) THEN
    -- Inserir receitas de mensalidades pagas
    INSERT INTO public.transacoes_financeiras (
      tipo, categoria, descricao, valor, data_competencia, data_vencimento, data_pagamento, status, mensalidade_id, cliente_id, created_at
    )
    SELECT
      'receita',
      'mensalidade_rastreamento',
      format('Mensalidade Ref. %s/%s - %s', m.mes_referencia, m.ano_referencia, c.nome_razao_social),
      m.valor,
      make_date(m.ano_referencia, m.mes_referencia, 1),
      m.data_vencimento,
      m.data_pagamento,
      CASE WHEN m.status = 'paga' THEN 'pago' ELSE 'pendente' END,
      m.id,
      m.cliente_id,
      m.created_at
    FROM public.mensalidades m
    INNER JOIN public.clientes c ON m.cliente_id = c.id
    ON CONFLICT DO NOTHING;

    -- Inserir despesas de repasse de instalação aos técnicos parceiros
    INSERT INTO public.transacoes_financeiras (
      tipo, categoria, descricao, valor, data_competencia, data_vencimento, data_pagamento, status, instalacao_id, cliente_id, instalador_id, created_at
    )
    SELECT
      'despesa',
      'repasse_instalacao',
      format('Repasse de Instalação/Atendimento - OS #%s', substring(i.id::text, 1, 8)),
      i.valor_repasse,
      COALESCE(i.data_instalacao::date, CURRENT_DATE),
      COALESCE(i.data_instalacao::date, CURRENT_DATE),
      i.data_pagamento_repasse,
      CASE WHEN i.status_pagamento = 'pago' THEN 'pago' ELSE 'pendente' END,
      i.id,
      i.cliente_id,
      i.instalador_id,
      i.created_at
    FROM public.instalacoes i
    WHERE i.valor_repasse > 0
    ON CONFLICT DO NOTHING;
  END IF;
END $$;

-- 2. EXPURGO E DESATIVAÇÃO DE VEÍCULOS E DADOS FICTÍCIOS
-- Remove os veículos de demonstração 'HTR4G16', 'HUN1T26' e quaisquer veículos fictícios de teste
DO $$
DECLARE
  v_fake_ids UUID[];
BEGIN
  -- Identifica IDs dos veículos fictícios da 'Frota Hunter' ou placas de teste
  SELECT ARRAY_AGG(id) INTO v_fake_ids
  FROM public.veiculos
  WHERE placa IN ('HTR4G16', 'HUN1T26')
     OR marca_modelo ILIKE '%Frota Hunter%'
     OR marca_modelo ILIKE '%Simula%';

  IF v_fake_ids IS NOT NULL AND array_length(v_fake_ids, 1) > 0 THEN
    -- Remove posições de telemetria simuladas
    DELETE FROM public.telemetria_posicoes WHERE veiculo_id = ANY(v_fake_ids);
    -- Remove viagens simuladas
    DELETE FROM public.viagens_trajetos WHERE veiculo_id = ANY(v_fake_ids);
    -- Remove alertas simulados
    DELETE FROM public.alertas_seguranca WHERE veiculo_id = ANY(v_fake_ids);
    -- Remove itens de manutenção simulados
    DELETE FROM public.itens_manutencao_preventiva WHERE veiculo_id = ANY(v_fake_ids);
    -- Desativa ou remove o veículo
    DELETE FROM public.veiculos WHERE id = ANY(v_fake_ids);
  END IF;

  -- Remove clientes de demonstração chamados "Frota Hunter Operacional" se existirem
  DELETE FROM public.clientes WHERE nome_razao_social ILIKE '%Frota Hunter%';
END $$;

-- 3. NOTIFICAR O POSTGREST PARA RECARREGAR O SCHEMA CACHE IMEDIATAMENTE
NOTIFY pgrst, 'reload schema';


