-- ============================================================================
-- [30/225] MIGRAÇÃO: 20260921223000_hunter_preferencia_tema_mapa.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — PERSISTÊNCIA UNIVERSAL DO TEMA DE MAPA NO PERFIL (DJR-NEW)
-- ============================================================================
-- Define o padrão geral do sistema como Mapa Claro ('streets').
-- Persiste a preferência individual de mapa do usuário na nuvem (profiles),
-- garantindo que a escolha se mantenha entre logins, logouts e dispositivos.
-- ============================================================================

-- 1. Adiciona coluna map_theme_preference em public.profiles
ALTER TABLE public.profiles
ADD COLUMN IF NOT EXISTS map_theme_preference TEXT NOT NULL DEFAULT 'streets';

-- 2. Atualiza registros existentes que estejam nulos ou vazios para 'streets'
UPDATE public.profiles
SET map_theme_preference = 'streets'
WHERE map_theme_preference IS NULL OR map_theme_preference = '';

-- 3. Cria função RPC segura para salvar a preferência de mapa do usuário logado
CREATE OR REPLACE FUNCTION public.salvar_preferencia_mapa(
  p_mapa TEXT
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
BEGIN
  IF auth.uid() IS NOT NULL THEN
    IF p_mapa IN ('streets', 'dark', 'satellite') THEN
      UPDATE public.profiles
      SET map_theme_preference = p_mapa,
          updated_at = now()
      WHERE id = auth.uid();
    END IF;
  END IF;
END;
$$;

-- Concede permissão de execução aos usuários autenticados
GRANT EXECUTE ON FUNCTION public.salvar_preferencia_mapa(TEXT) TO authenticated;


-- ============================================================================
-- [31/225] MIGRAÇÃO: 20260922180000_hunter_instalador_autonomia_e_pendencias.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — AUTONOMIA DO INSTALADOR E SINCRONIZAÇÃO DE PENDÊNCIAS (DJR-NEW)
-- ============================================================================
-- 1. Permite ao instalador gerenciar sua própria chave PIX e endereço de oficina.
-- 2. Reforça a integridade da RPC de geração de pendências para instaladores.
-- ============================================================================

-- 1. RPC para o instalador atualizar seus próprios dados de repasse e endereço
CREATE OR REPLACE FUNCTION public.instalador_atualizar_proprios_dados(
  p_chave_pix TEXT,
  p_endereco_instalacao TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuário não autenticado.';
  END IF;

  SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_user_id;

  -- Apenas instalador, administrador ou operador podem invocar
  IF v_role NOT IN ('instalador', 'superadmin', 'operador') THEN
    RAISE EXCEPTION 'Acesso não autorizado para alteração de dados de instalador.';
  END IF;

  UPDATE public.profiles
  SET
    chave_pix = NULLIF(TRIM(p_chave_pix), ''),
    endereco_instalacao = NULLIF(TRIM(p_endereco_instalacao), ''),
    updated_at = now()
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'sucesso', true,
    'mensagem', 'Dados de atendimento e chave PIX atualizados com sucesso.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_atualizar_proprios_dados(TEXT, TEXT) TO authenticated;

-- 2. Reforço de RLS para o próprio instalador atualizar sua chave PIX e endereço
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies 
    WHERE schemaname = 'public' 
      AND tablename = 'profiles' 
      AND policyname = 'Instaladores atualizam seus proprios dados de contato'
  ) THEN
    CREATE POLICY "Instaladores atualizam seus proprios dados de contato"
    ON public.profiles FOR UPDATE TO authenticated
    USING (id = auth.uid())
    WITH CHECK (id = auth.uid());
  END IF;
END;
$$;

