-- 3. RPC Atômica para Solicitar Apenas Retirada (Cancelamento ou Inadimplência)
CREATE OR REPLACE FUNCTION public.solicitar_retirada_rastreador(
  p_veiculo_id UUID,
  p_instalador_id UUID,
  p_valor_retirada NUMERIC DEFAULT 0.00,
  p_motivo TEXT DEFAULT NULL,
  p_observacoes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_veiculo RECORD;
  v_nova_os_id UUID;
  v_valor_final NUMERIC(10,2);
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso nao autenticado.';
  END IF;

  SELECT v.id, v.cliente_id, v.placa, v.marca_modelo, v.ano, v.cor, v.odometro_km,
         v.rastreador_id, v.rastreador_imei, r.chip_id, c.iccid, c.operadora
  INTO v_veiculo
  FROM public.veiculos v
  LEFT JOIN public.rastreadores r ON r.id = v.rastreador_id
  LEFT JOIN public.chips c ON c.id = r.chip_id
  WHERE v.id = p_veiculo_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Veiculo nao encontrado para retirada.';
  END IF;

  IF v_veiculo.rastreador_imei IS NULL AND v_veiculo.rastreador_id IS NULL THEN
    RAISE EXCEPTION 'O veiculo selecionado nao possui rastreador vinculado para retirada.';
  END IF;

  v_valor_final := GREATEST(COALESCE(p_valor_retirada, 0.00), 0.00);

  INSERT INTO public.instalacoes (
    instalador_id,
    cliente_id,
    veiculo_id,
    tipo_servico,
    placa,
    marca,
    modelo,
    ano,
    cor,
    km_instalacao,
    rastreador_imei,
    chip_iccid,
    chip_operadora,
    status,
    motivo_pendencia_recusa,
    observacoes,
    valor_instalacao,
    status_pagamento
  ) VALUES (
    p_instalador_id,
    v_veiculo.cliente_id,
    v_veiculo.id,
    'retirada',
    v_veiculo.placa,
    SPLIT_PART(COALESCE(v_veiculo.marca_modelo, 'Veiculo'), ' ', 1),
    COALESCE(SUBSTRING(v_veiculo.marca_modelo FROM ' +(.*)'), 'Modelo'),
    v_veiculo.ano,
    v_veiculo.cor,
    COALESCE(v_veiculo.odometro_km, 0),
    COALESCE(v_veiculo.rastreador_imei, 'A CONFERIR'),
    v_veiculo.iccid,
    v_veiculo.operadora,
    'nao_instalado',
    p_motivo,
    p_observacoes,
    v_valor_final,
    'pendente'
  )
  RETURNING id INTO v_nova_os_id;

  -- Histórico do atendimento inicial
  INSERT INTO public.instalacoes_historico_atendimentos (
    instalacao_id,
    instalador_id,
    status_atendimento,
    motivo,
    observacoes,
    km_no_atendimento
  ) VALUES (
    v_nova_os_id,
    v_user_id,
    'nao_instalado',
    p_motivo,
    COALESCE(p_observacoes, 'Ordem de retirada emitida pela gestao Hunter.'),
    COALESCE(v_veiculo.odometro_km, 0)
  );

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'instalacao_id', v_nova_os_id,
    'tipo_servico', 'retirada'
  );
END;
$$;

-- 4. RPC Atômica para Solicitar Remanejamento de Rastreador (Troca de Veículo / Cliente)
CREATE OR REPLACE FUNCTION public.solicitar_remanejamento_rastreador(
  p_veiculo_origem_id UUID,
  p_cliente_destino_id UUID,
  p_novo_veiculo_placa TEXT,
  p_novo_veiculo_marca TEXT,
  p_novo_veiculo_modelo TEXT,
  p_novo_veiculo_ano INT DEFAULT NULL,
  p_novo_veiculo_cor TEXT DEFAULT NULL,
  p_instalador_id UUID DEFAULT NULL,
  p_valor_retirada NUMERIC DEFAULT 0.00,
  p_valor_instalacao NUMERIC DEFAULT 350.00,
  p_observacoes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_origem RECORD;
  v_os_retirada_id UUID;
  v_os_instalacao_id UUID;
  v_placa_nova TEXT;
  v_valor_retirada_final NUMERIC(10,2);
  v_valor_instalacao_final NUMERIC(10,2);
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso nao autenticado.';
  END IF;

  v_placa_nova := UPPER(TRIM(p_novo_veiculo_placa));
  IF v_placa_nova IS NULL OR v_placa_nova = '' THEN
    RAISE EXCEPTION 'A placa do novo veiculo e obrigatoria.';
  END IF;

  -- 1. Busca veiculo e rastreador de origem
  SELECT v.id, v.cliente_id, v.placa, v.marca_modelo, v.ano, v.cor, v.odometro_km,
         v.rastreador_id, v.rastreador_imei, r.chip_id, c.iccid, c.operadora
  INTO v_origem
  FROM public.veiculos v
  LEFT JOIN public.rastreadores r ON r.id = v.rastreador_id
  LEFT JOIN public.chips c ON c.id = r.chip_id
  WHERE v.id = p_veiculo_origem_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Veiculo de origem nao encontrado.';
  END IF;

  IF v_origem.rastreador_imei IS NULL AND v_origem.rastreador_id IS NULL THEN
    RAISE EXCEPTION 'O veiculo de origem nao possui rastreador para remanejamento.';
  END IF;

  v_valor_retirada_final := GREATEST(COALESCE(p_valor_retirada, 0.00), 0.00);
  v_valor_instalacao_final := GREATEST(COALESCE(p_valor_instalacao, 0.00), 0.00);

  -- 2. Cria OS 1: Retirada no Veículo de Origem
  INSERT INTO public.instalacoes (
    instalador_id,
    cliente_id,
    veiculo_id,
    tipo_servico,
    placa,
    marca,
    modelo,
    ano,
    cor,
    km_instalacao,
    rastreador_imei,
    chip_iccid,
    chip_operadora,
    status,
    motivo_pendencia_recusa,
    observacoes,
    valor_instalacao,
    status_pagamento
  ) VALUES (
    p_instalador_id,
    v_origem.cliente_id,
    v_origem.id,
    'retirada',
    v_origem.placa,
    SPLIT_PART(COALESCE(v_origem.marca_modelo, 'Veiculo'), ' ', 1),
    COALESCE(SUBSTRING(v_origem.marca_modelo FROM ' +(.*)'), 'Modelo'),
    v_origem.ano,
    v_origem.cor,
    COALESCE(v_origem.odometro_km, 0),
    COALESCE(v_origem.rastreador_imei, 'A CONFERIR'),
    v_origem.iccid,
    v_origem.operadora,
    'nao_instalado',
    'Remanejamento para novo veiculo: ' || v_placa_nova,
    p_observacoes,
    v_valor_retirada_final,
    'pendente'
  )
  RETURNING id INTO v_os_retirada_id;

  -- 3. Cria OS 2: Instalação no Novo Veículo de Destino
  INSERT INTO public.instalacoes (
    instalador_id,
    cliente_id,
    veiculo_id,
    tipo_servico,
    placa,
    marca,
    modelo,
    ano,
    cor,
    km_instalacao,
    rastreador_imei,
    chip_iccid,
    chip_operadora,
    status,
    motivo_pendencia_recusa,
    observacoes,
    valor_instalacao,
    status_pagamento,
    ordem_vinculada_id
  ) VALUES (
    p_instalador_id,
    COALESCE(p_cliente_destino_id, v_origem.cliente_id),
    NULL, -- Sera vinculado ou criado ao concluir a instalacao
    'instalacao',
    v_placa_nova,
    TRIM(p_novo_veiculo_marca),
    TRIM(p_novo_veiculo_modelo),
    p_novo_veiculo_ano,
    p_novo_veiculo_cor,
    0,
    COALESCE(v_origem.rastreador_imei, 'A CONFERIR'),
    v_origem.iccid,
    v_origem.operadora,
    'nao_instalado',
    'Aguardando conclusao da retirada do veiculo ' || v_origem.placa,
    p_observacoes,
    v_valor_instalacao_final,
    'pendente',
    v_os_retirada_id
  )
  RETURNING id INTO v_os_instalacao_id;

  -- 4. Vincula reciprocamente a OS de Retirada a OS de Instalacao
  UPDATE public.instalacoes
  SET ordem_vinculada_id = v_os_instalacao_id
  WHERE id = v_os_retirada_id;

  -- 5. Histórico da Retirada
  INSERT INTO public.instalacoes_historico_atendimentos (
    instalacao_id,
    instalador_id,
    status_atendimento,
    motivo,
    observacoes,
    km_no_atendimento
  ) VALUES (
    v_os_retirada_id,
    v_user_id,
    'nao_instalado',
    'Remanejamento / Troca de Veiculo',
    'Ordem de retirada gerada em conjunto com a instalacao da placa ' || v_placa_nova,
    COALESCE(v_origem.odometro_km, 0)
  );

  -- 6. Histórico da Instalação
  INSERT INTO public.instalacoes_historico_atendimentos (
    instalacao_id,
    instalador_id,
    status_atendimento,
    motivo,
    observacoes,
    km_no_atendimento
  ) VALUES (
    v_os_instalacao_id,
    v_user_id,
    'nao_instalado',
    'Remanejamento / Troca de Veiculo',
    'Ordem de instalacao gerada em conjunto com a retirada da placa ' || v_origem.placa,
    0
  );

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'ordem_retirada_id', v_os_retirada_id,
    'ordem_instalacao_id', v_os_instalacao_id
  );
END;
$$;

-- 5. Atualização da RPC salvar_atendimento_instalacao para suportar Retiradas e Instalações com isolamento
DROP FUNCTION IF EXISTS public.salvar_atendimento_instalacao(UUID, UUID, TEXT, TEXT, TEXT, INT, TEXT, INT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT);
DROP FUNCTION IF EXISTS public.salvar_atendimento_instalacao(UUID, UUID, TEXT, TEXT, TEXT, INT, TEXT, INT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, BOOLEAN);

CREATE OR REPLACE FUNCTION public.salvar_atendimento_instalacao(
  p_instalacao_id UUID DEFAULT NULL,
  p_cliente_id UUID DEFAULT NULL,
  p_placa TEXT DEFAULT NULL,
  p_marca TEXT DEFAULT NULL,
  p_modelo TEXT DEFAULT NULL,
  p_ano INT DEFAULT NULL,
  p_cor TEXT DEFAULT NULL,
  p_km_instalacao INT DEFAULT 0,
  p_rastreador_imei TEXT DEFAULT NULL,
  p_rastreador_modelo TEXT DEFAULT 'J16 4G',
  p_chip_iccid TEXT DEFAULT NULL,
  p_chip_operadora TEXT DEFAULT NULL,
  p_posicao_instalacao TEXT DEFAULT NULL,
  p_status TEXT DEFAULT 'nao_instalado',
  p_motivo TEXT DEFAULT NULL,
  p_observacoes TEXT DEFAULT NULL,
  p_bloqueador_instalado BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_instalador_id UUID;
  v_instalacao_id UUID;
  v_veiculo_id UUID := NULL;
  v_rastreador_id UUID := NULL;
  v_chip_id UUID := NULL;
  v_placa_limpa TEXT;
  v_imei_limpo TEXT;
  v_iccid_limpo TEXT;
  v_cliente_instalador_id UUID := NULL;
  v_valor_unitario NUMERIC(10,2) := 0.00;
  v_concluida_at TIMESTAMPTZ := NULL;
  v_bloqueador BOOLEAN := COALESCE(p_bloqueador_instalado, TRUE);
  v_tipo_servico TEXT := 'instalacao';
  v_ordem RECORD;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso nao autenticado.';
  END IF;

  IF p_status NOT IN ('nao_instalado', 'concluida_com_pendencia', 'concluida') THEN
    RAISE EXCEPTION 'Status de atendimento invalido: %', p_status;
  END IF;

  IF p_status IN ('nao_instalado', 'concluida_com_pendencia') AND (p_motivo IS NULL OR TRIM(p_motivo) = '') THEN
    RAISE EXCEPTION 'E obrigatorio informar o motivo para status de pendencia ou nao executado.';
  END IF;

  v_placa_limpa := UPPER(TRIM(p_placa));
  v_imei_limpo := NULLIF(TRIM(p_rastreador_imei), '');
  v_iccid_limpo := NULLIF(TRIM(p_chip_iccid), '');

  IF p_status = 'concluida' AND (v_imei_limpo IS NULL OR v_imei_limpo = '') THEN
    RAISE EXCEPTION 'O IMEI do rastreador e obrigatorio para concluir o atendimento.';
  END IF;

  -- 1. Busca dados da instalação se existente
  IF p_instalacao_id IS NOT NULL THEN
    SELECT * INTO v_ordem FROM public.instalacoes WHERE id = p_instalacao_id;
    IF FOUND THEN
      v_tipo_servico := COALESCE(v_ordem.tipo_servico, 'instalacao');
      v_instalacao_id := v_ordem.id;
      v_veiculo_id := v_ordem.veiculo_id;
    END IF;
  END IF;

  -- =========================================================================
  -- CASO A: ORDEM DE RETIRADA / DESINSTALAÇÃO
  -- =========================================================================
  IF v_tipo_servico = 'retirada' THEN
    IF p_status = 'concluida' AND v_concluida_at IS NULL THEN
      v_concluida_at := NOW();
    END IF;

    UPDATE public.instalacoes
    SET
      status = p_status,
      km_instalacao = COALESCE(p_km_instalacao, km_instalacao),
      motivo_pendencia_recusa = p_motivo,
      observacoes = p_observacoes,
      concluida_at = v_concluida_at,
      updated_at = NOW()
    WHERE id = v_instalacao_id;

    -- Histórico do atendimento
    INSERT INTO public.instalacoes_historico_atendimentos (
      instalacao_id,
      instalador_id,
      status_atendimento,
      motivo,
      observacoes,
      km_no_atendimento
    ) VALUES (
      v_instalacao_id,
      v_user_id,
      p_status,
      p_motivo,
      p_observacoes,
      p_km_instalacao
    );

    IF p_status = 'concluida' THEN
      -- Identifica veículo
      IF v_veiculo_id IS NULL AND v_placa_limpa IS NOT NULL THEN
        SELECT id INTO v_veiculo_id FROM public.veiculos WHERE placa = v_placa_limpa LIMIT 1;
      END IF;

      -- Desvincula veículo e inativa do mapa
      IF v_veiculo_id IS NOT NULL THEN
        UPDATE public.veiculos
        SET
          rastreador_id = NULL,
          rastreador_imei = NULL,
          ativo = FALSE,
          status_operacional = 'desinstalado',
          odometro_km = GREATEST(odometro_km, p_km_instalacao),
          updated_at = NOW()
        WHERE id = v_veiculo_id;
      END IF;

      -- Atualiza rastreador físico para status 'em_estoque'
      IF v_imei_limpo IS NOT NULL THEN
        UPDATE public.rastreadores
        SET
          veiculo_id = NULL,
          status = 'em_estoque',
          updated_at = NOW()
        WHERE imei = v_imei_limpo;
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'sucesso', TRUE,
      'tipo_servico', 'retirada',
      'instalacao_id', v_instalacao_id,
      'veiculo_id', v_veiculo_id
    );
  END IF;

  -- =========================================================================
  -- CASO B: ORDEM DE INSTALAÇÃO PADRÃO OU REINSTALAÇÃO
  -- =========================================================================
  -- Auto-provisionamento de Chip SIM
  IF v_iccid_limpo IS NOT NULL THEN
    SELECT id INTO v_chip_id FROM public.chips WHERE iccid = v_iccid_limpo LIMIT 1;
    IF v_chip_id IS NULL THEN
      INSERT INTO public.chips (iccid, operadora, status)
      VALUES (v_iccid_limpo, COALESCE(NULLIF(TRIM(p_chip_operadora), ''), 'Vivo'), 'ativo')
      RETURNING id INTO v_chip_id;
    END IF;
  END IF;

  -- Auto-provisionamento ou ativação do Rastreador
  IF v_imei_limpo IS NOT NULL THEN
    SELECT id INTO v_rastreador_id FROM public.rastreadores WHERE imei = v_imei_limpo LIMIT 1;
    IF v_rastreador_id IS NULL THEN
      INSERT INTO public.rastreadores (imei, modelo, chip_id, status)
      VALUES (v_imei_limpo, COALESCE(NULLIF(TRIM(p_rastreador_modelo), ''), 'J16 4G'), v_chip_id, 'ativo')
      RETURNING id INTO v_rastreador_id;
    ELSE
      UPDATE public.rastreadores
      SET
        chip_id = COALESCE(v_chip_id, chip_id),
        modelo = COALESCE(NULLIF(TRIM(p_rastreador_modelo), ''), modelo),
        status = 'ativo',
        updated_at = NOW()
      WHERE id = v_rastreador_id;
    END IF;
  END IF;

  IF p_instalacao_id IS NULL THEN
    SELECT id INTO v_instalador_id FROM public.profiles WHERE id = v_user_id AND role = 'instalador';
    IF v_instalador_id IS NULL THEN
      SELECT instalador_id INTO v_instalador_id FROM public.clientes WHERE id = p_cliente_id;
      IF v_instalador_id IS NULL THEN
        SELECT id INTO v_instalador_id FROM public.profiles WHERE role = 'instalador' AND ativo = TRUE LIMIT 1;
      END IF;
    END IF;

    IF v_instalador_id IS NULL THEN
      RAISE EXCEPTION 'Nao foi possivel determinar o instalador credenciado.';
    END IF;

    SELECT valor_por_instalacao INTO v_valor_unitario FROM public.profiles WHERE id = v_instalador_id;
    v_valor_unitario := COALESCE(v_valor_unitario, 350.00);

    IF p_status = 'concluida' THEN
      v_concluida_at := NOW();
    END IF;

    INSERT INTO public.instalacoes (
      instalador_id,
      cliente_id,
      placa,
      marca,
      modelo,
      ano,
      cor,
      km_instalacao,
      rastreador_imei,
      rastreador_modelo,
      chip_iccid,
      chip_operadora,
      posicao_instalacao,
      status,
      motivo_pendencia_recusa,
      observacoes,
      valor_instalacao,
      concluida_at,
      bloqueador_instalado
    ) VALUES (
      v_instalador_id,
      p_cliente_id,
      v_placa_limpa,
      p_marca,
      p_modelo,
      p_ano,
      p_cor,
      p_km_instalacao,
      v_imei_limpo,
      COALESCE(NULLIF(TRIM(p_rastreador_modelo), ''), 'J16 4G'),
      v_iccid_limpo,
      p_chip_operadora,
      p_posicao_instalacao,
      p_status,
      p_motivo,
      p_observacoes,
      v_valor_unitario,
      v_concluida_at,
      v_bloqueador
    )
    RETURNING id INTO v_instalacao_id;
  ELSE
    v_instalacao_id := p_instalacao_id;

    IF p_status = 'concluida' AND v_concluida_at IS NULL THEN
      v_concluida_at := NOW();
    END IF;

    UPDATE public.instalacoes
    SET
      cliente_id = COALESCE(p_cliente_id, cliente_id),
      placa = COALESCE(v_placa_limpa, placa),
      marca = COALESCE(p_marca, marca),
      modelo = COALESCE(p_modelo, modelo),
      ano = COALESCE(p_ano, ano),
      cor = COALESCE(p_cor, cor),
      km_instalacao = COALESCE(p_km_instalacao, km_instalacao),
      rastreador_imei = COALESCE(v_imei_limpo, rastreador_imei),
      rastreador_modelo = COALESCE(NULLIF(TRIM(p_rastreador_modelo), ''), rastreador_modelo),
      chip_iccid = COALESCE(v_iccid_limpo, chip_iccid),
      chip_operadora = COALESCE(p_chip_operadora, chip_operadora),
      posicao_instalacao = COALESCE(p_posicao_instalacao, posicao_instalacao),
      status = p_status,
      motivo_pendencia_recusa = p_motivo,
      observacoes = p_observacoes,
      concluida_at = v_concluida_at,
      bloqueador_instalado = v_bloqueador,
      updated_at = NOW()
    WHERE id = v_instalacao_id;
  END IF;

  -- Registro de histórico imutável
  INSERT INTO public.instalacoes_historico_atendimentos (
    instalacao_id,
    instalador_id,
    status_atendimento,
    motivo,
    observacoes,
    km_no_atendimento
  ) VALUES (
    v_instalacao_id,
    v_user_id,
    p_status,
    p_motivo,
    p_observacoes,
    p_km_instalacao
  );

  -- Conclusão da Instalação: ativação do veículo
  IF p_status = 'concluida' THEN
    SELECT id INTO v_veiculo_id FROM public.veiculos WHERE placa = v_placa_limpa LIMIT 1;

    -- Se o veículo não existia, cria NOVO com ID novo (isolamento total de telemetria)
    IF v_veiculo_id IS NULL THEN
      INSERT INTO public.veiculos (
        cliente_id,
        placa,
        marca_modelo,
        ano,
        cor,
        odometro_km,
        rastreador_id,
        rastreador_imei,
        status_operacional,
        ativo,
        bloqueador_instalado
      ) VALUES (
        p_cliente_id,
        v_placa_limpa,
        FORMAT('%s %s', p_marca, p_modelo),
        p_ano,
        p_cor,
        p_km_instalacao,
        v_rastreador_id,
        v_imei_limpo,
        'estacionado',
        TRUE,
        v_bloqueador
      ) RETURNING id INTO v_veiculo_id;

      BEGIN
        PERFORM public.inicializar_itens_manutencao_veiculo(v_veiculo_id, p_km_instalacao);
      EXCEPTION
        WHEN OTHERS THEN NULL;
      END;
    ELSE
      -- Veículo já existente: dá continuidade ao histórico daquele carro
      UPDATE public.veiculos
      SET
        cliente_id = COALESCE(p_cliente_id, cliente_id),
        odometro_km = GREATEST(odometro_km, p_km_instalacao),
        rastreador_id = COALESCE(v_rastreador_id, rastreador_id),
        rastreador_imei = COALESCE(v_imei_limpo, rastreador_imei),
        status_operacional = 'estacionado',
        ativo = TRUE,
        bloqueador_instalado = v_bloqueador,
        updated_at = NOW()
      WHERE id = v_veiculo_id;
    END IF;

    -- Vincula rastreador ao veículo ativo
    IF v_rastreador_id IS NOT NULL AND v_veiculo_id IS NOT NULL THEN
      UPDATE public.rastreadores
      SET
        veiculo_id = v_veiculo_id,
        status = 'ativo',
        updated_at = NOW()
      WHERE id = v_rastreador_id;
    END IF;

    UPDATE public.instalacoes
    SET veiculo_id = v_veiculo_id
    WHERE id = v_instalacao_id AND (veiculo_id IS NULL OR veiculo_id <> v_veiculo_id);

    IF p_cliente_id IS NOT NULL THEN
      UPDATE public.clientes
      SET
        status = 'ativo',
        status_agendamento = 'concluido',
        updated_at = NOW()
      WHERE id = p_cliente_id AND status <> 'ativo';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'tipo_servico', 'instalacao',
    'instalacao_id', v_instalacao_id,
    'veiculo_id', v_veiculo_id,
    'bloqueador_instalado', v_bloqueador
  );
END;
$$;

-- Permissões
GRANT EXECUTE ON FUNCTION public.solicitar_retirada_rastreador TO authenticated;
GRANT EXECUTE ON FUNCTION public.solicitar_remanejamento_rastreador TO authenticated;
GRANT EXECUTE ON FUNCTION public.salvar_atendimento_instalacao(UUID, UUID, TEXT, TEXT, TEXT, INT, TEXT, INT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, BOOLEAN) TO authenticated;


-- ============================================================================
-- [57/225] MIGRAÇÃO: 20260926110000_hunter_devolucao_kit_estoque_na_retirada.sql
-- ============================================================================

-- =========================================================================
-- HUNTER: Retorno Automático de Kit e Materiais ao Estoque na Retirada
-- Garante que rastreador, relé de bloqueio, chicote e demais insumos
-- baixados na instalação retornem integralmente ao estoque da empresa.
-- =========================================================================

-- 1. Função para consultar os materiais/kits que foram instalados no veículo
CREATE OR REPLACE FUNCTION public.obter_itens_instalados_veiculo(p_veiculo_id UUID)
RETURNS TABLE (
  item_id UUID,
  nome TEXT,
  codigo_sku TEXT,
  unidade_medida TEXT,
  quantidade_instalada NUMERIC,
  custo_unitario NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN QUERY
  SELECT 
    m.item_id,
    i.nome,
    i.codigo_sku,
    i.unidade_medida,
    SUM(CASE WHEN m.tipo = 'saida_instalacao' THEN m.quantidade WHEN m.tipo = 'estorno_instalacao' THEN -m.quantidade ELSE 0 END)::NUMERIC AS quantidade_instalada,
    COALESCE(MAX(m.custo_unitario), i.custo_medio_unitario)::NUMERIC AS custo_unitario
  FROM public.estoque_movimentacoes m
  JOIN public.estoque_itens i ON i.id = m.item_id
  WHERE m.veiculo_id = p_veiculo_id
  GROUP BY m.item_id, i.nome, i.codigo_sku, i.unidade_medida, i.custo_medio_unitario
  HAVING SUM(CASE WHEN m.tipo = 'saida_instalacao' THEN m.quantidade WHEN m.tipo = 'estorno_instalacao' THEN -m.quantidade ELSE 0 END) > 0;
END;
$$;

-- 2. Atualização da RPC salvar_atendimento_instalacao para devolver todos os materiais
-- instalados no veículo de volta ao estoque quando o status for 'concluida' na retirada
CREATE OR REPLACE FUNCTION public.salvar_atendimento_instalacao(
  p_instalacao_id UUID DEFAULT NULL,
  p_cliente_id UUID DEFAULT NULL,
  p_placa TEXT DEFAULT NULL,
  p_marca TEXT DEFAULT NULL,
  p_modelo TEXT DEFAULT NULL,
  p_ano INT DEFAULT NULL,
  p_cor TEXT DEFAULT NULL,
  p_km_instalacao INT DEFAULT 0,
  p_rastreador_imei TEXT DEFAULT NULL,
  p_rastreador_modelo TEXT DEFAULT 'J16 4G',
  p_chip_iccid TEXT DEFAULT NULL,
  p_chip_operadora TEXT DEFAULT NULL,
  p_posicao_instalacao TEXT DEFAULT NULL,
  p_status TEXT DEFAULT 'nao_instalado',
  p_motivo TEXT DEFAULT NULL,
  p_observacoes TEXT DEFAULT NULL,
  p_bloqueador_instalado BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_instalador_id UUID;
  v_instalacao_id UUID;
  v_veiculo_id UUID := NULL;
  v_rastreador_id UUID := NULL;
  v_chip_id UUID := NULL;
  v_placa_limpa TEXT;
  v_imei_limpo TEXT;
  v_iccid_limpo TEXT;
  v_cliente_instalador_id UUID := NULL;
  v_valor_unitario NUMERIC(10,2) := 0.00;
  v_concluida_at TIMESTAMPTZ := NULL;
  v_bloqueador BOOLEAN := COALESCE(p_bloqueador_instalado, TRUE);
  v_tipo_servico TEXT := 'instalacao';
  v_ordem RECORD;
  v_item_rec RECORD;
  v_item_estoque RECORD;
  v_saldo_ant NUMERIC;
  v_saldo_post NUMERIC;
  v_materiais_devolvidos INT := 0;
BEGIN
  v_user_id := auth.uid();
  v_placa_limpa := UPPER(TRIM(p_placa));
  v_imei_limpo := NULLIF(TRIM(p_rastreador_imei), '');
  v_iccid_limpo := NULLIF(TRIM(p_chip_iccid), '');

  IF p_instalacao_id IS NOT NULL THEN
    SELECT * INTO v_ordem FROM public.instalacoes WHERE id = p_instalacao_id;
    IF FOUND THEN
      v_instalacao_id := v_ordem.id;
      v_veiculo_id := v_ordem.veiculo_id;
      v_instalador_id := v_ordem.instalador_id;
      v_tipo_servico := COALESCE(v_ordem.tipo_servico, 'instalacao');
      v_concluida_at := v_ordem.concluida_at;
      IF v_placa_limpa IS NULL THEN
        v_placa_limpa := v_ordem.placa;
      END IF;
      IF v_imei_limpo IS NULL THEN
        v_imei_limpo := v_ordem.rastreador_imei;
      END IF;
    END IF;
  END IF;

  -- =========================================================================
  -- CASO A: ORDEM DE RETIRADA / DESINSTALAÇÃO
  -- =========================================================================
  IF v_tipo_servico = 'retirada' THEN
    IF p_status = 'concluida' AND v_concluida_at IS NULL THEN
      v_concluida_at := NOW();
    END IF;

    UPDATE public.instalacoes
    SET
      status = p_status,
      km_instalacao = COALESCE(p_km_instalacao, km_instalacao),
      motivo_pendencia_recusa = p_motivo,
      observacoes = p_observacoes,
      concluida_at = v_concluida_at,
      updated_at = NOW()
    WHERE id = v_instalacao_id;

    -- Histórico do atendimento
    INSERT INTO public.instalacoes_historico_atendimentos (
      instalacao_id,
      instalador_id,
      status_atendimento,
      motivo,
      observacoes,
      km_no_atendimento
    ) VALUES (
      v_instalacao_id,
      v_user_id,
      p_status,
      p_motivo,
      p_observacoes,
      p_km_instalacao
    );

    IF p_status = 'concluida' THEN
      -- Identifica veículo
      IF v_veiculo_id IS NULL AND v_placa_limpa IS NOT NULL THEN
        SELECT id INTO v_veiculo_id FROM public.veiculos WHERE placa = v_placa_limpa LIMIT 1;
      END IF;

      -- 1. Desvincula veículo e inativa do mapa
      IF v_veiculo_id IS NOT NULL THEN
        UPDATE public.veiculos
        SET
          rastreador_id = NULL,
          rastreador_imei = NULL,
          ativo = FALSE,
          status_operacional = 'desinstalado',
          odometro_km = GREATEST(odometro_km, p_km_instalacao),
          updated_at = NOW()
        WHERE id = v_veiculo_id;
      END IF;

      -- 2. Atualiza rastreador físico para status 'em_estoque'
      IF v_imei_limpo IS NOT NULL THEN
        UPDATE public.rastreadores
        SET
          veiculo_id = NULL,
          status = 'em_estoque',
          updated_at = NOW()
        WHERE imei = v_imei_limpo;
      END IF;

      -- 3. Devolução de todos os materiais e itens de kit instalados no veículo ao estoque
      IF v_veiculo_id IS NOT NULL THEN
        FOR v_item_rec IN (
          SELECT m.item_id, 
                 SUM(CASE WHEN m.tipo = 'saida_instalacao' THEN m.quantidade WHEN m.tipo = 'estorno_instalacao' THEN -m.quantidade ELSE 0 END) AS qtd_recolhida
          FROM public.estoque_movimentacoes m
          WHERE m.veiculo_id = v_veiculo_id
          GROUP BY m.item_id
          HAVING SUM(CASE WHEN m.tipo = 'saida_instalacao' THEN m.quantidade WHEN m.tipo = 'estorno_instalacao' THEN -m.quantidade ELSE 0 END) > 0
        ) LOOP
          SELECT * INTO v_item_estoque FROM public.estoque_itens WHERE id = v_item_rec.item_id FOR UPDATE;
          IF FOUND THEN
            v_saldo_ant := v_item_estoque.quantidade_atual;
            v_saldo_post := v_saldo_ant + v_item_rec.qtd_recolhida;

            UPDATE public.estoque_itens
            SET quantidade_atual = v_saldo_post, updated_at = NOW()
            WHERE id = v_item_estoque.id;

            INSERT INTO public.estoque_movimentacoes (
              item_id, tipo, quantidade, custo_unitario, valor_total,
              saldo_anterior, saldo_posterior, instalacao_id, veiculo_id,
              instalador_id, observacao, data_movimento
            ) VALUES (
              v_item_estoque.id, 'estorno_instalacao', v_item_rec.qtd_recolhida, v_item_estoque.custo_medio_unitario,
              ROUND(v_item_rec.qtd_recolhida * v_item_estoque.custo_medio_unitario, 2),
              v_saldo_ant, v_saldo_post, v_instalacao_id, v_veiculo_id,
              COALESCE(v_instalador_id, v_user_id),
              'Devolução ao estoque: Material e kit recolhidos na retirada do veículo placa ' || COALESCE(v_placa_limpa, ''),
              NOW()
            );
            v_materiais_devolvidos := v_materiais_devolvidos + 1;
          END IF;
        END LOOP;
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'sucesso', TRUE,
      'tipo_servico', 'retirada',
      'instalacao_id', v_instalacao_id,
      'veiculo_id', v_veiculo_id,
      'materiais_devolvidos', v_materiais_devolvidos
    );
  END IF;

  -- =========================================================================
  -- CASO B: ORDEM DE INSTALAÇÃO PADRÃO OU REINSTALAÇÃO
  -- =========================================================================
  -- Auto-provisionamento de Chip SIM
  IF v_iccid_limpo IS NOT NULL THEN
    SELECT id INTO v_chip_id FROM public.chips WHERE iccid = v_iccid_limpo LIMIT 1;
    IF v_chip_id IS NULL THEN
      INSERT INTO public.chips (iccid, operadora, status)
      VALUES (v_iccid_limpo, COALESCE(p_chip_operadora, 'Vivo'), 'ativo')
      RETURNING id INTO v_chip_id;
    END IF;
  END IF;

  -- Auto-provisionamento de Rastreador
  IF v_imei_limpo IS NOT NULL THEN
    SELECT id INTO v_rastreador_id FROM public.rastreadores WHERE imei = v_imei_limpo LIMIT 1;
    IF v_rastreador_id IS NULL THEN
      INSERT INTO public.rastreadores (imei, modelo, status, chip_id)
      VALUES (v_imei_limpo, COALESCE(p_rastreador_modelo, 'J16 4G'), 'ativo', v_chip_id)
      RETURNING id INTO v_rastreador_id;
    ELSE
      UPDATE public.rastreadores
      SET status = 'ativo',
          chip_id = COALESCE(v_chip_id, chip_id),
          updated_at = NOW()
      WHERE id = v_rastreador_id;
    END IF;
  END IF;

  -- Obter veículo
  IF v_placa_limpa IS NOT NULL THEN
    SELECT id INTO v_veiculo_id FROM public.veiculos WHERE placa = v_placa_limpa LIMIT 1;
    IF v_veiculo_id IS NULL THEN
      INSERT INTO public.veiculos (
        cliente_id, placa, marca_modelo, ano, cor,
        odometro_km, rastreador_id, rastreador_imei,
        ativo, bloqueador_instalado, status_operacional
      ) VALUES (
        p_cliente_id,
        v_placa_limpa,
        CONCAT(COALESCE(p_marca, 'Veículo'), ' ', COALESCE(p_modelo, '')),
        p_ano,
        p_cor,
        COALESCE(p_km_instalacao, 0),
        v_rastreador_id,
        v_imei_limpo,
        (p_status = 'concluida'),
        v_bloqueador,
        CASE WHEN p_status = 'concluida' THEN 'ativo' ELSE 'aguardando_instalacao' END
      )
      RETURNING id INTO v_veiculo_id;
    ELSE
      UPDATE public.veiculos
      SET
        cliente_id = COALESCE(p_cliente_id, cliente_id),
        marca_modelo = CONCAT(COALESCE(p_marca, 'Veículo'), ' ', COALESCE(p_modelo, '')),
        ano = COALESCE(p_ano, ano),
        cor = COALESCE(p_cor, cor),
        odometro_km = GREATEST(odometro_km, COALESCE(p_km_instalacao, 0)),
        rastreador_id = COALESCE(v_rastreador_id, rastreador_id),
        rastreador_imei = COALESCE(v_imei_limpo, rastreador_imei),
        ativo = (p_status = 'concluida'),
        bloqueador_instalado = v_bloqueador,
        status_operacional = CASE WHEN p_status = 'concluida' THEN 'ativo' ELSE 'aguardando_instalacao' END,
        updated_at = NOW()
      WHERE id = v_veiculo_id;
    END IF;
  END IF;

  -- Vincular veículo ao rastreador
  IF v_rastreador_id IS NOT NULL AND v_veiculo_id IS NOT NULL THEN
    UPDATE public.rastreadores
    SET veiculo_id = v_veiculo_id, status = 'ativo', updated_at = NOW()
    WHERE id = v_rastreador_id;
  END IF;

  -- Se for novo registro
  IF v_instalacao_id IS NULL THEN
    IF p_cliente_id IS NOT NULL THEN
      SELECT instalador_id INTO v_cliente_instalador_id FROM public.clientes WHERE id = p_cliente_id;
    END IF;
    v_instalador_id := COALESCE(v_cliente_instalador_id, v_user_id);

    SELECT valor_por_instalacao INTO v_valor_unitario
    FROM public.profiles
    WHERE id = v_instalador_id;
    v_valor_unitario := COALESCE(v_valor_unitario, 50.00);

    INSERT INTO public.instalacoes (
      instalador_id,
      cliente_id,
      veiculo_id,
      placa,
      marca,
      modelo,
      ano,
      cor,
      km_instalacao,
      rastreador_imei,
      rastreador_modelo,
      chip_iccid,
      chip_operadora,
      posicao_instalacao,
      status,
      motivo_pendencia_recusa,
      observacoes,
      valor_instalacao,
      status_pagamento,
      bloqueador_instalado,
      tipo_servico
    ) VALUES (
      v_instalador_id,
      p_cliente_id,
      v_veiculo_id,
      v_placa_limpa,
      COALESCE(p_marca, 'Veículo'),
      COALESCE(p_modelo, 'Modelo'),
      p_ano,
      p_cor,
      p_km_instalacao,
      COALESCE(v_imei_limpo, 'A CONFERIR'),
      COALESCE(p_rastreador_modelo, 'J16 4G'),
      v_iccid_limpo,
      p_chip_operadora,
      p_posicao_instalacao,
      p_status,
      p_motivo,
      p_observacoes,
      v_valor_unitario,
      'pendente',
      v_bloqueador,
      'instalacao'
    )
    RETURNING id INTO v_instalacao_id;
  ELSE
    UPDATE public.instalacoes
    SET
      cliente_id = COALESCE(p_cliente_id, cliente_id),
      veiculo_id = COALESCE(v_veiculo_id, veiculo_id),
      placa = v_placa_limpa,
      marca = COALESCE(p_marca, marca),
      modelo = COALESCE(p_modelo, modelo),
      ano = COALESCE(p_ano, ano),
      cor = COALESCE(p_cor, cor),
      km_instalacao = p_km_instalacao,
      rastreador_imei = COALESCE(v_imei_limpo, rastreador_imei),
      rastreador_modelo = COALESCE(p_rastreador_modelo, rastreador_modelo),
      chip_iccid = COALESCE(v_iccid_limpo, chip_iccid),
      chip_operadora = COALESCE(p_chip_operadora, chip_operadora),
      posicao_instalacao = COALESCE(p_posicao_instalacao, posicao_instalacao),
      status = p_status,
      motivo_pendencia_recusa = p_motivo,
      observacoes = p_observacoes,
      bloqueador_instalado = v_bloqueador,
      concluida_at = CASE WHEN p_status = 'concluida' AND concluida_at IS NULL THEN NOW() ELSE concluida_at END,
      updated_at = NOW()
    WHERE id = v_instalacao_id;
  END IF;

  -- Histórico do atendimento
  INSERT INTO public.instalacoes_historico_atendimentos (
    instalacao_id,
    instalador_id,
    status_atendimento,
    motivo,
    observacoes,
    km_no_atendimento
  ) VALUES (
    v_instalacao_id,
    v_user_id,
    p_status,
    p_motivo,
    p_observacoes,
    p_km_instalacao
  );

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'instalacao_id', v_instalacao_id,
    'veiculo_id', v_veiculo_id,
    'tipo_servico', 'instalacao'
  );
END;
$$;


-- ============================================================================
-- [58/225] MIGRAÇÃO: 20260926120000_hunter_convites_auto_cadastro_instalador.sql
-- ============================================================================

-- =========================================================================
-- HUNTER: Convite de Uso Único e Auto-Cadastro de Instalador Técnico
-- Permite que o operador ou administrador gere um link de uso único.
-- O técnico preenche seus dados cadastrais (PIX, endereço, login, senha).
-- A conta é criada OBRIGATORIAMENTE INATIVA (ativo = false) aguardando aprovação.
-- O token é de uso estritamente único e expira após o envio.
-- =========================================================================

CREATE TABLE IF NOT EXISTS public.convites_instalador (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  token UUID UNIQUE NOT NULL DEFAULT gen_random_uuid(),
  criado_por UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  usado BOOLEAN NOT NULL DEFAULT FALSE,
  usado_em TIMESTAMPTZ,
  usado_por_user_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  expira_em TIMESTAMPTZ NOT NULL DEFAULT (NOW() + INTERVAL '7 days'),
  observacoes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE public.convites_instalador ENABLE ROW LEVEL SECURITY;

-- Políticas de RLS
DROP POLICY IF EXISTS "Operadores e administradores podem gerenciar convites" ON public.convites_instalador;
CREATE POLICY "Operadores e administradores podem gerenciar convites"
  ON public.convites_instalador
  FOR ALL
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND p.role IN ('superadmin', 'adm', 'operador')
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = auth.uid()
        AND p.role IN ('superadmin', 'adm', 'operador')
    )
  );

DROP POLICY IF EXISTS "Leitura pública de token de convite válido" ON public.convites_instalador;
CREATE POLICY "Leitura pública de token de convite válido"
  ON public.convites_instalador
  FOR SELECT
  TO public
  USING (usado = FALSE AND expira_em > NOW());

-- 1. RPC para Gerar Novo Convite de Uso Único
CREATE OR REPLACE FUNCTION public.gerar_convite_instalador(p_observacoes TEXT DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_novo_token UUID;
  v_convite_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso nao autorizado. Faca login no sistema.';
  END IF;

  SELECT role INTO v_role FROM public.profiles WHERE id = v_user_id;
  IF v_role NOT IN ('superadmin', 'adm', 'operador') THEN
    RAISE EXCEPTION 'Apenas operadores e administradores podem gerar links de convite para instalador.';
  END IF;

  INSERT INTO public.convites_instalador (
    criado_por,
    observacoes
  ) VALUES (
    v_user_id,
    p_observacoes
  )
  RETURNING id, token INTO v_convite_id, v_novo_token;

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'convite_id', v_convite_id,
    'token', v_novo_token,
    'expira_em', (NOW() + INTERVAL '7 days')
  );
END;
$$;

-- 2. RPC para Validar se o Convite é Válido e não foi Usado
CREATE OR REPLACE FUNCTION public.validar_convite_instalador(p_token UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions
AS $$
DECLARE
  v_convite RECORD;
BEGIN
  IF p_token IS NULL THEN
    RETURN jsonb_build_object('valido', FALSE, 'mensagem', 'Link de convite invalido.');
  END IF;

  SELECT * INTO v_convite FROM public.convites_instalador WHERE token = p_token;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valido', FALSE, 'mensagem', 'Link de convite nao encontrado ou inexistente.');
  END IF;

  IF v_convite.usado THEN
    RETURN jsonb_build_object('valido', FALSE, 'mensagem', 'Este link de convite ja foi utilizado anteriormente e nao pode ser reutilizado.');
  END IF;

  IF v_convite.expira_em <= NOW() THEN
    RETURN jsonb_build_object('valido', FALSE, 'mensagem', 'Este link de convite expirou o prazo limite de validade.');
  END IF;

  RETURN jsonb_build_object(
    'valido', TRUE,
    'mensagem', 'Convite valido para auto-cadastro de instalador tecnico.',
    'token', v_convite.token,
    'expira_em', v_convite.expira_em
  );
END;
$$;

-- 3. RPC para Realizar o Auto-Cadastro do Instalador via Convite
CREATE OR REPLACE FUNCTION public.cadastrar_instalador_por_convite(
  p_token UUID,
  p_nome TEXT,
  p_email TEXT,
  p_senha TEXT,
  p_telefone TEXT DEFAULT NULL,
  p_chave_pix TEXT DEFAULT NULL,
  p_endereco_instalacao TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions
AS $$
DECLARE
  v_convite RECORD;
  v_user_id UUID;
  v_encrypted_pw TEXT;
  v_email_limpo TEXT;
  v_nome_limpo TEXT;
BEGIN
  -- 1. Validar Token de Uso Único
  IF p_token IS NULL THEN
    RAISE EXCEPTION 'Token de convite obrigatorio.';
  END IF;

  SELECT * INTO v_convite 
  FROM public.convites_instalador 
  WHERE token = p_token 
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Link de convite nao encontrado.';
  END IF;

  IF v_convite.usado THEN
    RAISE EXCEPTION 'Este link de convite ja foi utilizado. Solicite um novo link a administracao.';
  END IF;

  IF v_convite.expira_em <= NOW() THEN
    RAISE EXCEPTION 'Este link de convite expirou.';
  END IF;

  -- 2. Validar Dados
  v_nome_limpo := TRIM(p_nome);
  v_email_limpo := LOWER(TRIM(p_email));

  IF v_nome_limpo IS NULL OR v_nome_limpo = '' THEN
    RAISE EXCEPTION 'Nome completo e obrigatorio.';
  END IF;

  IF v_email_limpo IS NULL OR v_email_limpo = '' THEN
    RAISE EXCEPTION 'E-mail e obrigatorio.';
  END IF;

  IF p_senha IS NULL OR LENGTH(p_senha) < 6 THEN
    RAISE EXCEPTION 'A senha deve conter no minimo 6 caracteres.';
  END IF;

  IF EXISTS (SELECT 1 FROM auth.users WHERE email = v_email_limpo) THEN
    RAISE EXCEPTION 'Este e-mail ja esta cadastrado no sistema.';
  END IF;

  -- 3. Gerar Hash de Senha Seguro
  v_encrypted_pw := crypt(p_senha, gen_salt('bf'));
  v_user_id := gen_random_uuid();

  -- 4. Criar Conta em auth.users
  INSERT INTO auth.users (
    instance_id, id, aud, role, email, encrypted_password,
    email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
    created_at, updated_at
  ) VALUES (
    '00000000-0000-0000-0000-000000000000',
    v_user_id,
    'authenticated',
    'authenticated',
    v_email_limpo,
    v_encrypted_pw,
    NOW(),
    '{"provider":"email","providers":["email"]}'::JSONB,
    jsonb_build_object(
      'nome', v_nome_limpo,
      'role', 'instalador',
      'telefone', p_telefone
    ),
    NOW(),
    NOW()
  );

  -- 5. Criar Perfil em public.profiles: OBRIGATORIAMENTE INATIVO (ativo = false)
  INSERT INTO public.profiles (
    id, nome, email, role, ativo,
    telefone, chave_pix, endereco_instalacao,
    valor_por_instalacao, created_at, updated_at
  ) VALUES (
    v_user_id,
    v_nome_limpo,
    v_email_limpo,
    'instalador',
    FALSE, -- OBRIGATORIAMENTE SEM ESTAR ATIVA E HABILITADA
    p_telefone,
    p_chave_pix,
    p_endereco_instalacao,
    50.00,
    NOW(),
    NOW()
  )
  ON CONFLICT (id) DO UPDATE
  SET
    role = 'instalador',
    ativo = FALSE,
    telefone = EXCLUDED.telefone,
    chave_pix = EXCLUDED.chave_pix,
    endereco_instalacao = EXCLUDED.endereco_instalacao,
    updated_at = NOW();

  -- 6. Liberar Acesso ao Módulo de Instalações
  INSERT INTO public.user_module_access (user_id, module, ativo)
  VALUES (v_user_id, 'instalacao', TRUE)
  ON CONFLICT (user_id, module) DO NOTHING;

  -- 7. Queimar o Token de Convite (Uso Único Imediato)
  UPDATE public.convites_instalador
  SET
    usado = TRUE,
    usado_em = NOW(),
    usado_por_user_id = v_user_id
  WHERE id = v_convite.id;

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'mensagem', 'Cadastro realizado com sucesso! Sua conta foi enviada para analise e aguarda habilitacao pela administracao.',
    'user_id', v_user_id
  );
END;
$$;


-- ============================================================================
-- [59/225] MIGRAÇÃO: 20260926130000_hunter_privacidade_localizacao_superadm.sql
-- ============================================================================

-- ==============================================================================
-- MIGRATION: 20260926130000_hunter_privacidade_localizacao_superadm.sql
-- DESCRIÇÃO: Modo de Privacidade Canônica do Hunter
-- 1. Cria coluna privacidade_localizacao (padrão TRUE) em clientes e veiculos.
-- 2. Blindagem de segurança: Somente SuperADM (novaes@adm.28bpm.local) pode
--    alterar a privacidade de TRUE para FALSE.
-- 3. Propagação automática de privacidade entre clientes e seus veículos.
-- ==============================================================================

-- 1. Adicionar colunas se não existirem
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'clientes' AND column_name = 'privacidade_localizacao'
    ) THEN
        ALTER TABLE public.clientes ADD COLUMN privacidade_localizacao BOOLEAN NOT NULL DEFAULT true;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'veiculos' AND column_name = 'privacidade_localizacao'
    ) THEN
        ALTER TABLE public.veiculos ADD COLUMN privacidade_localizacao BOOLEAN NOT NULL DEFAULT true;
    END IF;
END $$;

-- Garantir valor padrão true nos registros existentes
UPDATE public.clientes SET privacidade_localizacao = true WHERE privacidade_localizacao IS NULL;
UPDATE public.veiculos SET privacidade_localizacao = true WHERE privacidade_localizacao IS NULL;

-- 2. Função e Trigger para blindagem: Somente SuperADM ou o Cliente titular podem desativar a privacidade
CREATE OR REPLACE FUNCTION public.fn_blindar_privacidade_superadm()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
    v_user_email TEXT;
    v_is_superadm BOOLEAN := FALSE;
    v_is_cliente_titular BOOLEAN := FALSE;
    v_cliente_user_id UUID;
BEGIN
    -- Se a privacidade não está sendo desativada (permanece true, ou mudou de false para true), permite
    IF NOT (OLD.privacidade_localizacao = TRUE AND NEW.privacidade_localizacao = FALSE) THEN
        RETURN NEW;
    END IF;

    v_user_id := auth.uid();
    v_user_email := auth.jwt() ->> 'email';

    -- 1. SuperADM imutável
    IF v_user_email = 'novaes@adm.28bpm.local' THEN
        v_is_superadm := TRUE;
    ELSE
        SELECT (role = 'superadmin') INTO v_is_superadm
        FROM public.profiles
        WHERE id = v_user_id;
    END IF;

    IF COALESCE(v_is_superadm, FALSE) THEN
        RETURN NEW;
    END IF;

    -- 2. Cliente titular do registro
    IF TG_TABLE_NAME = 'clientes' THEN
        IF OLD.user_id IS NOT NULL AND OLD.user_id = v_user_id THEN
            v_is_cliente_titular := TRUE;
        END IF;
    ELSIF TG_TABLE_NAME = 'veiculos' THEN
        IF OLD.cliente_id IS NOT NULL THEN
            SELECT user_id INTO v_cliente_user_id
            FROM public.clientes
            WHERE id = OLD.cliente_id;

            IF v_cliente_user_id IS NOT NULL AND v_cliente_user_id = v_user_id THEN
                v_is_cliente_titular := TRUE;
            END IF;
        END IF;
    END IF;

    IF COALESCE(v_is_cliente_titular, FALSE) THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'Acesso Negado: Apenas o SuperADM ou o Cliente titular possuem autorização para desmarcar a privacidade de localização do veículo.'
        USING ERRCODE = '42501';

    RETURN NEW;
END;
$$;

-- Triggers de blindagem em clientes e veiculos
DROP TRIGGER IF EXISTS trg_blindar_privacidade_clientes ON public.clientes;
CREATE TRIGGER trg_blindar_privacidade_clientes
    BEFORE UPDATE OF privacidade_localizacao ON public.clientes
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_blindar_privacidade_superadm();

DROP TRIGGER IF EXISTS trg_blindar_privacidade_veiculos ON public.veiculos;
CREATE TRIGGER trg_blindar_privacidade_veiculos
    BEFORE UPDATE OF privacidade_localizacao ON public.veiculos
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_blindar_privacidade_superadm();

-- 3. Sincronizar privacidade do cliente para seus veículos automaticamente
CREATE OR REPLACE FUNCTION public.fn_sync_privacidade_cliente_veiculos()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    IF NEW.privacidade_localizacao IS DISTINCT FROM OLD.privacidade_localizacao THEN
        UPDATE public.veiculos
        SET privacidade_localizacao = NEW.privacidade_localizacao
        WHERE cliente_id = NEW.id;
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_privacidade_cliente_veiculos ON public.clientes;
CREATE TRIGGER trg_sync_privacidade_cliente_veiculos
    AFTER UPDATE OF privacidade_localizacao ON public.clientes
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_sync_privacidade_cliente_veiculos();

-- 4. Ao cadastrar novo veículo, herdar privacidade do cliente
CREATE OR REPLACE FUNCTION public.fn_herdar_privacidade_cliente_novo_veiculo()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_privacidade_cliente BOOLEAN;
BEGIN
    IF NEW.cliente_id IS NOT NULL THEN
        SELECT privacidade_localizacao INTO v_privacidade_cliente
        FROM public.clientes
        WHERE id = NEW.cliente_id;

        IF v_privacidade_cliente IS NOT NULL THEN
            NEW.privacidade_localizacao := v_privacidade_cliente;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_herdar_privacidade_cliente_novo_veiculo ON public.veiculos;
CREATE TRIGGER trg_herdar_privacidade_cliente_novo_veiculo
    BEFORE INSERT ON public.veiculos
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_herdar_privacidade_cliente_novo_veiculo();

-- Recarregar o cache de schema do PostgREST imediatamente
NOTIFY pgrst, 'reload schema';



-- ============================================================================
-- [60/225] MIGRAÇÃO: 20260926145000_hunter_alterar_email_e_blindar_superadm_edicao.sql
-- ============================================================================

-- Migration: 20260926145000_hunter_alterar_email_e_blindar_superadm_edicao.sql
-- Objetivo: Permitir alteração de e-mail de usuários e clientes sem bloqueio
-- e blindar o SuperADM para que ao alterar o nome mantenha sempre o cargo SuperADM sem regressão.

-- 1. Limpar versões anteriores de admin_atualizar_usuario
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN (
    SELECT oid::regprocedure AS func_sig
    FROM pg_proc
    WHERE proname = 'admin_atualizar_usuario'
      AND pronamespace = 'public'::regnamespace
  ) LOOP
    EXECUTE 'DROP FUNCTION IF EXISTS ' || r.func_sig || ' CASCADE;';
  END LOOP;
END $$;

-- 2. Criar RPC admin_atualizar_usuario definitiva
CREATE OR REPLACE FUNCTION public.admin_atualizar_usuario(
  p_usuario_id UUID,
  p_nome TEXT,
  p_role public.hunter_role,
  p_ativo BOOLEAN,
  p_plano public.plano_cliente DEFAULT 'basico',
  p_modulos TEXT[] DEFAULT ARRAY[]::TEXT[],
  p_valor_por_instalacao NUMERIC DEFAULT 0.00,
  p_chave_pix TEXT DEFAULT NULL,
  p_endereco_instalacao TEXT DEFAULT NULL,
  p_email TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_mod TEXT;
  v_email_atual TEXT;
  v_email_novo TEXT;
  v_role_atual public.hunter_role;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem atualizar usuarios.';
  END IF;

  SELECT email INTO v_email_atual FROM auth.users WHERE id = p_usuario_id;
  SELECT role INTO v_role_atual FROM public.profiles WHERE id = p_usuario_id;

  -- Blindagem canônica do SuperADM (novaes@adm.28bpm.local):
  -- Permite alterar o NOME, mas blinda o e-mail e preserva 100% o papel de SuperADM sem regressão de privilégio.
  IF LOWER(COALESCE(v_email_atual, '')) = 'novaes@adm.28bpm.local' 
     OR p_usuario_id = '00000000-0000-0000-0000-000000000001'::UUID 
     OR v_role_atual = 'superadmin' THEN
    
    UPDATE public.profiles
    SET nome = trim(p_nome),
        role = 'superadmin',
        ativo = TRUE,
        updated_at = now()
    WHERE id = p_usuario_id;

    UPDATE auth.users
    SET raw_user_meta_data = raw_user_meta_data || jsonb_build_object('nome', trim(p_nome), 'role', 'superadmin'),
        email_confirmed_at = COALESCE(email_confirmed_at, now()),
        updated_at = now()
    WHERE id = p_usuario_id;

    -- Concede todos os módulos da governança
    DELETE FROM public.user_module_access WHERE user_id = p_usuario_id;
    INSERT INTO public.user_module_access (user_id, module, ativo)
    SELECT p_usuario_id, m, TRUE
    FROM unnest(ARRAY[
      'monitor-gps', 'atendimento', 'clientes', 'rastreadores', 'dispositivos', 
      'instalacao', 'manutencao', 'mensalidades', 'financeiro', 'estoque', 
      'whatsapp', 'temas', 'usuarios'
    ]) AS m;

    RETURN jsonb_build_object(
      'success', TRUE,
      'message', 'Perfil SuperADM atualizado com sucesso. Privilégios e governança mantidos integralmente.'
    );
  END IF;

  -- Para outros usuários: processa alteração de e-mail se informada
  v_email_novo := LOWER(trim(COALESCE(p_email, v_email_atual)));
  IF v_email_novo IS NOT NULL AND v_email_novo <> '' AND v_email_novo <> LOWER(COALESCE(v_email_atual, '')) THEN
    -- Validar se já existe em auth.users
    IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = v_email_novo AND id <> p_usuario_id) THEN
      RAISE EXCEPTION 'O e-mail informado já está em uso por outro usuário.';
    END IF;

    -- Atualiza auth.users
    UPDATE auth.users
    SET email = v_email_novo,
        raw_user_meta_data = raw_user_meta_data || jsonb_build_object('email', v_email_novo),
        updated_at = now()
    WHERE id = p_usuario_id;

    -- Atualiza auth.identities
    UPDATE auth.identities
    SET identity_data = jsonb_set(identity_data, '{email}', to_jsonb(v_email_novo)),
        provider_id = v_email_novo
    WHERE user_id = p_usuario_id AND provider = 'email';
  END IF;

  -- Atualiza public.profiles
  UPDATE public.profiles
  SET nome = trim(p_nome),
      email = v_email_novo,
      role = p_role,
      ativo = p_ativo,
      valor_por_instalacao = p_valor_por_instalacao,
      chave_pix = p_chave_pix,
      endereco_instalacao = p_endereco_instalacao,
      updated_at = now()
  WHERE id = p_usuario_id;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (p_usuario_id, p_role)
  ON CONFLICT (user_id, role) DO UPDATE SET role = EXCLUDED.role;

  UPDATE auth.users
  SET raw_user_meta_data = jsonb_build_object('nome', trim(p_nome), 'role', p_role),
      email_confirmed_at = COALESCE(email_confirmed_at, now()),
      updated_at = now()
  WHERE id = p_usuario_id;

  -- Módulos
  DELETE FROM public.user_module_access WHERE user_id = p_usuario_id;
  IF p_role = 'superadmin' OR p_role = 'adm' THEN
    INSERT INTO public.user_module_access (user_id, module, ativo)
    SELECT p_usuario_id, m, TRUE
    FROM unnest(ARRAY[
      'monitor-gps', 'atendimento', 'clientes', 'rastreadores', 'dispositivos', 
      'instalacao', 'manutencao', 'mensalidades', 'financeiro', 'estoque', 
      'whatsapp', 'temas', 'usuarios'
    ]) AS m;
  ELSIF p_role = 'instalador' THEN
    INSERT INTO public.user_module_access (user_id, module, ativo)
    VALUES (p_usuario_id, 'instalacao', TRUE);
  ELSIF p_modulos IS NOT NULL AND array_length(p_modulos, 1) > 0 THEN
    FOREACH v_mod IN ARRAY p_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (p_usuario_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  RETURN jsonb_build_object('success', TRUE, 'message', 'Usuário e acessos atualizados com sucesso.');
END;
$$;

-- 3. Atualizar RPC admin_atualizar_cliente_completo para sincronizar e-mail em auth.users, auth.identities e profiles
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN (
    SELECT oid::regprocedure AS func_sig
    FROM pg_proc
    WHERE proname = 'admin_atualizar_cliente_completo'
      AND pronamespace = 'public'::regnamespace
  ) LOOP
    EXECUTE 'DROP FUNCTION IF EXISTS ' || r.func_sig || ' CASCADE;';
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.admin_atualizar_cliente_completo(
  p_cliente_id UUID,
  p_nome TEXT,
  p_documento TEXT DEFAULT NULL,
  p_email TEXT DEFAULT NULL,
  p_telefone TEXT DEFAULT NULL,
  p_status public.status_cliente DEFAULT 'aguardando_instalacao',
  p_plano public.plano_cliente DEFAULT 'basico',
  p_dia_vencimento INT DEFAULT 10,
  p_valor_mensalidade NUMERIC DEFAULT 79.90,
  p_dias_historico INT DEFAULT 7,
  p_dias_retencao INT DEFAULT 10,
  p_senha TEXT DEFAULT NULL,
  p_instalador_id UUID DEFAULT NULL,
  p_meses_contrato INT DEFAULT 12,
  p_data_inicio_contrato DATE DEFAULT CURRENT_DATE,
  p_tipo_renovacao TEXT DEFAULT 'mesma_vigencia',
  p_meses_renovacao INT DEFAULT 12,
  p_foro_comarca TEXT DEFAULT 'Volta Redonda/RJ',
  p_gerar_parcelas_ausentes BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_user_id UUID;
  v_email_antigo TEXT;
  v_email_limpo TEXT := LOWER(trim(COALESCE(p_email, '')));
  v_meses_c INT;
  v_data_inicio DATE;
  v_data_fim DATE;
  v_resultado_parcelas JSONB;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem realizar esta operacao.';
  END IF;

  IF p_cliente_id IS NULL THEN
    RAISE EXCEPTION 'ID do cliente e obrigatorio.';
  END IF;

  IF p_nome IS NULL OR trim(p_nome) = '' THEN
    RAISE EXCEPTION 'O nome ou razao social do cliente e obrigatorio.';
  END IF;

  SELECT user_id, email, data_inicio_contrato INTO v_user_id, v_email_antigo, v_data_inicio
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente nao encontrado.';
  END IF;

  v_meses_c := GREATEST(1, COALESCE(p_meses_contrato, 12));
  v_data_inicio := COALESCE(p_data_inicio_contrato, v_data_inicio, CURRENT_DATE);
  v_data_fim := (v_data_inicio + (v_meses_c || ' months')::INTERVAL)::DATE;

  -- Se o cliente já possui usuário cadastrado em auth.users:
  IF v_user_id IS NOT NULL THEN
    -- Sincronizar e-mail se foi alterado
    IF v_email_limpo <> '' AND v_email_limpo <> LOWER(COALESCE(v_email_antigo, '')) THEN
      IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = v_email_limpo AND id <> v_user_id) THEN
        RAISE EXCEPTION 'O e-mail informado já está em uso por outro usuário.';
      END IF;

      UPDATE auth.users
      SET email = v_email_limpo,
          raw_user_meta_data = raw_user_meta_data || jsonb_build_object('nome', trim(p_nome), 'email', v_email_limpo),
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE public.profiles
      SET email = v_email_limpo,
          nome = trim(p_nome),
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE auth.identities
      SET identity_data = jsonb_set(identity_data, '{email}', to_jsonb(v_email_limpo)),
          provider_id = v_email_limpo
      WHERE user_id = v_user_id AND provider = 'email';
    ELSE
      -- Atualiza apenas o nome se o e-mail não mudou
      UPDATE public.profiles
      SET nome = trim(p_nome),
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE auth.users
      SET raw_user_meta_data = raw_user_meta_data || jsonb_build_object('nome', trim(p_nome)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

    -- Se forneceu nova senha, atualiza credencial
    IF p_senha IS NOT NULL AND length(p_senha) >= 6 THEN
      UPDATE auth.users
      SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

  -- Se não possui usuário ainda, mas tem e-mail e senha: cria conta
  ELSIF v_email_limpo <> '' AND p_senha IS NOT NULL AND length(p_senha) >= 6 THEN
    SELECT id INTO v_user_id FROM auth.users WHERE LOWER(email) = v_email_limpo;
    IF v_user_id IS NULL THEN
      v_user_id := gen_random_uuid();
      INSERT INTO auth.users (
        id, instance_id, aud, role, email, encrypted_password,
        email_confirmed_at, recovery_sent_at, last_sign_in_at,
        raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
        confirmation_token, email_change, email_change_token_new, recovery_token
      ) VALUES (
        v_user_id,
        '00000000-0000-0000-0000-000000000000',
        'authenticated',
        'authenticated',
        v_email_limpo,
        extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
        now(), now(), now(),
        '{"provider":"email","providers":["email"]}',
        jsonb_build_object('nome', trim(p_nome), 'role', 'cliente', 'email', v_email_limpo),
        now(), now(),
        '', '', '', ''
      );

      INSERT INTO auth.identities (
        id, user_id, identity_data, provider, provider_id, last_sign_in_at, created_at, updated_at
      ) VALUES (
        gen_random_uuid(),
        v_user_id,
        jsonb_build_object('sub', v_user_id::text, 'email', v_email_limpo),
        'email',
        v_email_limpo,
        now(), now(), now()
      );

      INSERT INTO public.profiles (id, nome, email, role, ativo, created_at, updated_at)
      VALUES (v_user_id, trim(p_nome), v_email_limpo, 'cliente', TRUE, now(), now())
      ON CONFLICT (id) DO UPDATE SET
        nome = trim(p_nome),
        email = v_email_limpo,
        role = 'cliente',
        ativo = TRUE,
        updated_at = now();

      INSERT INTO public.user_roles (user_id, role)
      VALUES (v_user_id, 'cliente')
      ON CONFLICT (user_id, role) DO UPDATE SET role = 'cliente';

      -- Módulos padrão do cliente
      INSERT INTO public.user_module_access (user_id, module, ativo)
      SELECT v_user_id, m, TRUE
      FROM unnest(ARRAY['monitor-gps', 'manutencao', 'mensalidades', 'atendimento']) AS m
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END IF;
  END IF;

  -- Atualizar registro em public.clientes
  UPDATE public.clientes
  SET nome_razao_social = trim(p_nome),
      documento = NULLIF(trim(p_documento), ''),
      email = NULLIF(v_email_limpo, ''),
      telefone = NULLIF(trim(p_telefone), ''),
      user_id = COALESCE(user_id, v_user_id),
      plano = p_plano,
      status = p_status,
      dia_vencimento = COALESCE(p_dia_vencimento, dia_vencimento),
      valor_mensalidade = COALESCE(p_valor_mensalidade, valor_mensalidade),
      dias_historico_plano = COALESCE(p_dias_historico, dias_historico_plano),
      dias_retencao_banco = COALESCE(p_dias_retencao, dias_retencao_banco),
      instalador_id = p_instalador_id,
      meses_contrato = v_meses_c,
      data_inicio_contrato = v_data_inicio,
      data_fim_contrato = v_data_fim,
      tipo_renovacao = COALESCE(p_tipo_renovacao, tipo_renovacao),
      meses_renovacao = COALESCE(p_meses_renovacao, meses_renovacao),
      foro_comarca = COALESCE(p_foro_comarca, 'Volta Redonda/RJ'),
      updated_at = now()
  WHERE id = p_cliente_id;

  IF p_gerar_parcelas_ausentes THEN
    v_resultado_parcelas := public.admin_gerar_parcelas_contrato(p_cliente_id);
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Dados do cliente e credenciais atualizados com sucesso.',
    'cliente_id', p_cliente_id,
    'user_id', v_user_id,
    'meses_contrato', v_meses_c,
    'data_inicio_contrato', v_data_inicio,
    'data_fim_contrato', v_data_fim,
    'parcelas', v_resultado_parcelas
  );
END;
$$;

-- 4. Permissões
GRANT EXECUTE ON FUNCTION public.admin_atualizar_usuario(UUID, TEXT, public.hunter_role, BOOLEAN, public.plano_cliente, TEXT[], NUMERIC, TEXT, TEXT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_atualizar_cliente_completo(UUID, TEXT, TEXT, TEXT, TEXT, public.status_cliente, public.plano_cliente, INT, NUMERIC, INT, INT, TEXT, UUID, INT, DATE, TEXT, INT, TEXT, BOOLEAN) TO authenticated;


