-- ============================================================================
-- [71/225] MIGRAÇÃO: 20260929120000_hunter_jammer_deteccao_servidor.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — DETECÇÃO DE JAMMER NO SERVIDOR (INDEPENDENTE DE CLIENTE ATIVO)
-- ============================================================================
-- Versão Alvo: 1.10.2.4+
-- Objetivo: Detectar veículos em trânsito que cessaram comunicação abruptamente
-- (suspeita de jammer ou sabotagem elétrica) e disparar Push VAPID via o
-- trigger trg_push_vapid_notificacao_nova já existente no banco.
-- Execução: Chamada via RPC pela rota /api/alertas/verificar-jammers do
-- Cloudflare Workers Cron (scheduled trigger a cada 5 minutos).
-- ============================================================================

-- 1. Função principal de detecção de jammer no servidor
CREATE OR REPLACE FUNCTION public.verificar_jammers_servidor(
  p_timeout_minutos INT DEFAULT 3
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_veiculo          RECORD;
  v_cliente_user_id  UUID;
  v_diff_minutos     NUMERIC;
  v_alertas_criados  INT := 0;
  v_ultima_notif_at  TIMESTAMPTZ;
  v_descricao        TEXT;
  v_notif_id         UUID;
BEGIN
  -- Itera sobre veículos que atendiam aos critérios de trânsito na última telemetria
  -- e estão silenciados há mais de p_timeout_minutos sem evento normal de desligamento.
  FOR v_veiculo IN
    SELECT
      v.id,
      v.cliente_id,
      v.placa,
      v.marca_modelo,
      v.ignicao_status,
      v.velocidade_atual,
      v.ultima_atualizacao,
      v.ultima_latitude,
      v.ultima_longitude,
      EXTRACT(EPOCH FROM (now() - v.ultima_atualizacao)) / 60.0 AS minutos_sem_sinal
    FROM public.veiculos v
    WHERE
      v.ativo = true
      AND v.ultima_atualizacao IS NOT NULL
      -- Estava em trânsito: ignição ligada OU velocidade > 10 km/h
      AND (v.ignicao_status = true OR v.velocidade_atual > 10)
      -- Silenciado há mais de p_timeout_minutos
      AND (now() - v.ultima_atualizacao) > (p_timeout_minutos * interval '1 minute')
      -- Confirma que o último pacote registrado em telemetria_posicoes indica trânsito
      AND EXISTS (
        SELECT 1
        FROM (
          SELECT tp.ignicao, tp.velocidade
          FROM public.telemetria_posicoes tp
          WHERE tp.veiculo_id = v.id
          ORDER BY tp.data_hora_gps DESC
          LIMIT 1
        ) ult
        WHERE ult.ignicao = true OR ult.velocidade > 10
      )
  LOOP
    -- ── Deduplicação: não dispara se já existe alerta de jammer nos últimos 10 minutos ──
    SELECT created_at INTO v_ultima_notif_at
    FROM public.alertas_seguranca
    WHERE
      veiculo_id = v_veiculo.id
      AND tipo = 'suspeita_jammer'
    ORDER BY created_at DESC
    LIMIT 1;

    -- Pula se já há alerta de jammer nos últimos 10 minutos
    IF v_ultima_notif_at IS NOT NULL AND
       (now() - v_ultima_notif_at) < interval '10 minutes' THEN
      CONTINUE;
    END IF;

    v_diff_minutos := ROUND(v_veiculo.minutos_sem_sinal::NUMERIC, 1);

    v_descricao := format(
      'Veículo %s (%s) perdeu contato abruptamente enquanto estava em trânsito (%s km/h, ignição %s). '
      'Ausência de pacotes há %s min sem evento de desligamento normal. '
      'Suspeita de bloqueador de sinal celular/GPS ou sabotagem elétrica.',
      v_veiculo.placa,
      v_veiculo.marca_modelo,
      COALESCE(v_veiculo.velocidade_atual, 0),
      CASE WHEN v_veiculo.ignicao_status THEN 'ligada' ELSE 'desligada' END,
      v_diff_minutos
    );

    -- ── Persiste na Central de Alertas (gravidade crítica) ──
    INSERT INTO public.alertas_seguranca (
      veiculo_id,
      cliente_id,
      tipo,
      gravidade,
      latitude,
      longitude,
      velocidade,
      detalhes,
      reconhecido,
      created_at
    ) VALUES (
      v_veiculo.id,
      v_veiculo.cliente_id,
      'suspeita_jammer',
      'critica',
      COALESCE(v_veiculo.ultima_latitude, 0.0),
      COALESCE(v_veiculo.ultima_longitude, 0.0),
      COALESCE(v_veiculo.velocidade_atual, 0),
      v_descricao,
      false,
      now()
    );

    -- ── Busca dados de contato do cliente para direcionar o push ──
    SELECT user_id INTO v_cliente_user_id
    FROM public.clientes
    WHERE id = v_veiculo.cliente_id
    LIMIT 1;

    -- ── Insere em notificacoes_sistema → dispara trg_push_vapid_notificacao_nova ──
    -- O trigger existente cuida do Push VAPID via pg_net automaticamente.
    INSERT INTO public.notificacoes_sistema (
      destinatario_user_id,
      destinatario_cliente_id,
      titulo,
      mensagem,
      tipo,
      url,
      placa,
      lida,
      created_at
    ) VALUES (
      v_cliente_user_id,          -- user_id do cliente para Push VAPID
      v_veiculo.cliente_id,       -- cliente_id para Realtime WebSocket
      '🚨 Suspeita de Jammer / Silenciamento Súbito',
      v_descricao,
      'suspeita_jammer',
      '/monitor-gps',
      v_veiculo.placa,
      false,
      now()
    )
    RETURNING id INTO v_notif_id;

    v_alertas_criados := v_alertas_criados + 1;

  END LOOP;

  RETURN jsonb_build_object(
    'sucesso', true,
    'alertas_criados', v_alertas_criados,
    'verificado_em', now()
  );

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[JAMMER-CHECKER] Erro durante verificação de jammers: %', SQLERRM;
  RETURN jsonb_build_object(
    'sucesso', false,
    'erro', SQLERRM
  );
END;
$$;

-- 2. Permissão de execução apenas para service_role (chamada segura via RPC do servidor)
REVOKE ALL ON FUNCTION public.verificar_jammers_servidor(INT) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.verificar_jammers_servidor(INT) FROM anon;
REVOKE ALL ON FUNCTION public.verificar_jammers_servidor(INT) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.verificar_jammers_servidor(INT) TO service_role;

-- 3. Comentário de auditoria
COMMENT ON FUNCTION public.verificar_jammers_servidor(INT) IS
  'Detecta veículos em trânsito silenciados (suspeita de jammer ou sabotagem) '
  'e dispara Push VAPID via inserção em notificacoes_sistema → trigger pg_net. '
  'Executada pelo Cloudflare Workers Cron via /api/alertas/verificar-jammers a cada 5 min. '
  'Deduplicação: não dispara se já existe alerta de jammer no mesmo veículo nos últimos 10 min.';


-- ============================================================================
-- [72/225] MIGRAÇÃO: 20260929130000_hunter_sync_sessao_ativa_trigger.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — SINCRONIZAÇÃO AUTOMÁTICA DE SESSÃO ATIVA E LOGOUT NO PERFIL
-- ============================================================================
-- Migration: 20260929130000_hunter_sync_sessao_ativa_trigger.sql
-- Objetivo: Garantir que profiles.sessao_ativa, ultimo_login e ultimo_logout
-- estejam sempre sincronizados com os eventos de login/logout em tempo real,
-- prevenindo que usuários logados e offline apareçam indevidamente como deslogados.
-- ============================================================================

-- 1. Função Trigger para atualizar profiles automaticamente a partir de system_login_logs
CREATE OR REPLACE FUNCTION public.sincronizar_sessao_perfil_ao_logar()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  IF NEW.status = 'sucesso' THEN
    UPDATE public.profiles
    SET
      sessao_ativa = true,
      ultimo_login = COALESCE(NEW.created_at, now())
    WHERE id = NEW.user_id OR (NEW.user_id IS NULL AND LOWER(email) = LOWER(trim(NEW.email)));
  ELSIF NEW.status = 'logout' THEN
    UPDATE public.profiles
    SET
      sessao_ativa = false,
      ultimo_logout = COALESCE(NEW.created_at, now())
    WHERE id = NEW.user_id OR (NEW.user_id IS NULL AND LOWER(email) = LOWER(trim(NEW.email)));
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Resiliente: falha no trigger de sincronização de perfil não deve impedir o registro do log
  RAISE WARNING '[SESSAO-SYNC] Erro ao sincronizar perfil a partir de login_logs: %', SQLERRM;
  RETURN NEW;
END;
$$;

-- 2. Criação do Trigger AFTER INSERT em system_login_logs
DROP TRIGGER IF EXISTS trg_sync_profile_sessao ON public.system_login_logs;
CREATE TRIGGER trg_sync_profile_sessao
AFTER INSERT ON public.system_login_logs
FOR EACH ROW
EXECUTE FUNCTION public.sincronizar_sessao_perfil_ao_logar();

-- 3. Reconciliação imediata do estado atual de todos os perfis com base no histórico real
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT
      p.id,
      p.email,
      (SELECT MAX(created_at) FROM public.system_login_logs l WHERE (l.user_id = p.id OR LOWER(l.email) = LOWER(p.email)) AND l.status = 'sucesso') AS ult_login,
      (SELECT MAX(created_at) FROM public.system_login_logs lo WHERE (lo.user_id = p.id OR LOWER(lo.email) = LOWER(p.email)) AND lo.status = 'logout') AS ult_logout
    FROM public.profiles p
  LOOP
    IF r.ult_login IS NOT NULL THEN
      IF r.ult_logout IS NULL OR r.ult_login > r.ult_logout THEN
        -- Tem login posterior ao logout -> Sessão ativa mantida (Standby / Offline)
        UPDATE public.profiles
        SET
          sessao_ativa = true,
          ultimo_login = COALESCE(ultimo_login, r.ult_login),
          ultimo_logout = r.ult_logout
        WHERE id = r.id;
      ELSE
        -- Tem logout igual ou posterior ao login -> Deslogado
        UPDATE public.profiles
        SET
          sessao_ativa = false,
          ultimo_login = COALESCE(ultimo_login, r.ult_login),
          ultimo_logout = r.ult_logout
        WHERE id = r.id;
      END IF;
    END IF;
  END LOOP;
END $$;


-- ============================================================================
-- [73/225] MIGRAÇÃO: 20260929140000_hunter_rpc_registrar_acesso.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — RPC REGISTRAR ACESSO DO USUÁRIO E ATUALIZAÇÃO RLS DE PERFIL
-- ============================================================================
-- Migration: 20260929140000_hunter_rpc_registrar_acesso.sql
-- Objetivo: Permitir que usuários autenticados registrem seu acesso em tempo real
-- atualizando profiles.ultimo_login e sessao_ativa com SECURITY DEFINER,
-- além de permitir que usuários atualizem seus próprios perfis via RLS.
-- ============================================================================

-- 1. RPC Segura com SECURITY DEFINER para registrar o acesso do usuário atual
CREATE OR REPLACE FUNCTION public.registrar_acesso_usuario()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_agora TIMESTAMPTZ := now();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Não autenticado');
  END IF;

  UPDATE public.profiles
  SET
    sessao_ativa = true,
    ultimo_login = v_agora,
    updated_at = v_agora
  WHERE id = v_uid;

  RETURN jsonb_build_object('sucesso', true, 'ultimo_login', v_agora);
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_acesso_usuario() TO authenticated;

-- 2. Política de RLS para permitir que usuários atualizem seu próprio perfil
DROP POLICY IF EXISTS "Usuarios atualizam seu proprio perfil" ON public.profiles;
CREATE POLICY "Usuarios atualizam seu proprio perfil"
ON public.profiles FOR UPDATE TO authenticated
USING (id = auth.uid())
WITH CHECK (id = auth.uid());

-- 3. Atualiza os perfis que possuem sessao_ativa = true para terem o ultimo_login condizente se necessário
UPDATE public.profiles
SET ultimo_login = now()
WHERE sessao_ativa = true AND (ultimo_login IS NULL OR ultimo_login < (now() - interval '24 hours'));


-- ============================================================================
-- [74/225] MIGRAÇÃO: 20260929150000_hunter_alertas_telemetria_servidor.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — MOTOR DE ALERTAS DE TELEMETRIA NO SERVIDOR (INDEPENDENTE DE CLIENTE)
-- ============================================================================
-- Versão Alvo: 1.10.2.9
-- Objetivo: Disparar alertas de velocidade, ignição fora de horário e movimento
--           diretamente via trigger PostgreSQL ao receber atualização de telemetria,
--           sem depender de nenhum cliente (app fechado, tela bloqueada — sempre funciona).
-- Root Cause: O motor de alertas anterior rodava APENAS no browser (React useEffect),
--             portanto nunca disparava se o usuário não estivesse na tela de Monitor GPS.
-- Solução:   Trigger AFTER UPDATE na tabela `veiculos` → avalia regras e horários →
--             insere em `notificacoes_sistema` → trg_push_vapid dispara Push VAPID.
-- ============================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- 1. TABELA DE CONTROLE DE COOLDOWN (anti-flood server-side)
-- Garante que o mesmo tipo de alerta não seja disparado mais de 1x a cada 5 min
-- por veículo, mesmo com múltiplas atualizações de telemetria por segundo.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.alertas_telemetria_cooldown (
  veiculo_id  UUID        NOT NULL REFERENCES public.veiculos(id) ON DELETE CASCADE,
  tipo_alerta TEXT        NOT NULL,
  ultimo_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (veiculo_id, tipo_alerta)
);

COMMENT ON TABLE public.alertas_telemetria_cooldown IS
  'Controla o cooldown de 5 min entre alertas do mesmo tipo por veículo (anti-flood server-side).';

-- RLS desabilitado — tabela interna só acessada por triggers SECURITY DEFINER
ALTER TABLE public.alertas_telemetria_cooldown DISABLE ROW LEVEL SECURITY;

-- ─────────────────────────────────────────────────────────────────────────────
-- 2. FUNÇÃO AUXILIAR: Verifica se o horário atual está dentro da janela permitida
--    para o veículo. Retorna TRUE se FORA do horário (=> alerta).
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.hunter_horario_proibido(
  p_veiculo_id UUID,
  p_agora      TIMESTAMPTZ DEFAULT now()
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_hora_inicio  TIME;
  v_hora_fim     TIME;
  v_dias_semana  INT[];
  v_fim_semana   BOOLEAN;
  v_dia_semana   INT;
  v_hora_agora   TIME;
BEGIN
  -- Busca a regra de horário ativa para o veículo
  SELECT
    hora_inicio::TIME,
    hora_fim::TIME,
    dias_semana,
    permitir_fim_de_semana
  INTO
    v_hora_inicio,
    v_hora_fim,
    v_dias_semana,
    v_fim_semana
  FROM public.horarios_utilizacao
  WHERE veiculo_id = p_veiculo_id
    AND ativo = true
  LIMIT 1;

  -- Sem regra configurada → horário sempre permitido → NOT proibido
  IF NOT FOUND THEN
    RETURN FALSE;
  END IF;

  v_dia_semana := EXTRACT(DOW FROM p_agora AT TIME ZONE 'America/Sao_Paulo')::INT;
  v_hora_agora := (p_agora AT TIME ZONE 'America/Sao_Paulo')::TIME;

  -- Verifica fim de semana
  IF (v_dia_semana = 0 OR v_dia_semana = 6) AND NOT v_fim_semana THEN
    RETURN TRUE; -- proibido
  END IF;

  -- Verifica dia da semana permitido
  IF NOT (v_dia_semana = ANY(v_dias_semana)) THEN
    RETURN TRUE; -- proibido
  END IF;

  -- Verifica janela de horário
  IF v_hora_agora < v_hora_inicio OR v_hora_agora > v_hora_fim THEN
    RETURN TRUE; -- proibido
  END IF;

  RETURN FALSE;
END;
$$;

COMMENT ON FUNCTION public.hunter_horario_proibido(UUID, TIMESTAMPTZ) IS
  'Retorna TRUE se o horário atual está FORA da janela permitida para o veículo.';

-- ─────────────────────────────────────────────────────────────────────────────
-- 3. FUNÇÃO PRINCIPAL DO TRIGGER DE ALERTAS DE TELEMETRIA
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.hunter_avaliar_alertas_telemetria()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_velocidade_limite   NUMERIC;
  v_cliente_user_id     UUID;
  v_horario_proibido    BOOLEAN;
  v_cooldown_ok         BOOLEAN;
  v_hora_inicio_str     TEXT;
  v_hora_fim_str        TEXT;
  v_titulo              TEXT;
  v_mensagem            TEXT;
  v_tipo                TEXT;
  v_gravidade           TEXT;
  COOLDOWN_INTERVAL CONSTANT INTERVAL := INTERVAL '5 minutes';
BEGIN
  -- ── Ignora se não há cliente associado ao veículo ──
  IF NEW.cliente_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- ── Busca o user_id do cliente para endereçar o Push VAPID ──
  SELECT user_id INTO v_cliente_user_id
  FROM public.clientes
  WHERE id = NEW.cliente_id
  LIMIT 1;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA A: EXCESSO DE VELOCIDADE
  -- Condição: velocidade atual > limite configurado em regras_veiculo
  -- ─────────────────────────────────────────────────────────────────────────
  IF COALESCE(NEW.velocidade_atual, 0) > 0 THEN
    -- Busca limite configurado (padrão 110 se não houver registro)
    SELECT COALESCE(limite_velocidade_geral, 110)
    INTO v_velocidade_limite
    FROM public.regras_veiculo
    WHERE veiculo_id = NEW.id
    LIMIT 1;

    IF NOT FOUND THEN
      v_velocidade_limite := 110;
    END IF;

    IF NEW.velocidade_atual > v_velocidade_limite THEN
      -- Verifica cooldown
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'excesso_velocidade'
            AND ultimo_at > (now() - COOLDOWN_INTERVAL)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo    := format('Excesso de Velocidade — %s', COALESCE(NEW.placa, ''));
        v_mensagem  := format(
          'Veículo %s atingiu %s km/h, ultrapassando o limite configurado de %s km/h.',
          COALESCE(NEW.placa, ''),
          ROUND(NEW.velocidade_atual),
          ROUND(v_velocidade_limite)
        );
        v_tipo      := 'excesso_velocidade';
        v_gravidade := 'alta';

        -- Upsert cooldown
        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        -- Persiste alerta na central
        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        -- Dispara notificação → trigger pg_net → Push VAPID
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA B: IGNIÇÃO FORA DO HORÁRIO CONFIGURADO
  -- Condição: ignição ligada E horário atual fora da janela permitida
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = true THEN
    v_horario_proibido := public.hunter_horario_proibido(NEW.id);

    IF v_horario_proibido THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'ignicao_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_INTERVAL)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        -- Busca os horários para montar a mensagem descritiva
        SELECT
          hora_inicio::TEXT,
          hora_fim::TEXT
        INTO v_hora_inicio_str, v_hora_fim_str
        FROM public.horarios_utilizacao
        WHERE veiculo_id = NEW.id AND ativo = true
        LIMIT 1;

        v_titulo   := format('Ignição Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Motor acionado fora do horário habitual configurado (%s às %s). Veículo: %s.',
          COALESCE(v_hora_inicio_str, ''), COALESCE(v_hora_fim_str, ''),
          COALESCE(NEW.placa, '')
        );
        v_tipo      := 'ignicao_fora_horario';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA C: MOVIMENTO FORA DO HORÁRIO (ignição DESLIGADA + velocidade > 3 km/h)
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = false AND COALESCE(NEW.velocidade_atual, 0) > 3 THEN
    v_horario_proibido := public.hunter_horario_proibido(NEW.id);

    IF v_horario_proibido THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'movimento_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_INTERVAL)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo   := format('Deslocamento Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Veículo %s em deslocamento (%s km/h) fora da janela habitual configurada (motor desligado).',
          COALESCE(NEW.placa, ''),
          ROUND(NEW.velocidade_atual)
        );
        v_tipo      := 'movimento_fora_horario';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA D: GUINCHO / FURTO (ignição DESLIGADA + velocidade > 5 km/h, sempre)
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = false AND COALESCE(NEW.velocidade_atual, 0) > 5 THEN
    SELECT (
      NOT EXISTS (
        SELECT 1 FROM public.alertas_telemetria_cooldown
        WHERE veiculo_id = NEW.id
          AND tipo_alerta = 'guincho'
          AND ultimo_at > (now() - COOLDOWN_INTERVAL)
      )
    ) INTO v_cooldown_ok;

    IF v_cooldown_ok THEN
      v_titulo   := format('🚨 Veículo em Movimento com Motor Desligado — %s', COALESCE(NEW.placa, ''));
      v_mensagem := format(
        'Veículo %s detectado a %s km/h com ignição desligada. Possível reboque ou furto em andamento.',
        COALESCE(NEW.placa, ''),
        ROUND(NEW.velocidade_atual)
      );
      v_tipo      := 'guincho';
      v_gravidade := 'critica';

      INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
      VALUES (NEW.id, v_tipo, now())
      ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

      INSERT INTO public.alertas_seguranca (
        veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
        velocidade, detalhes, reconhecido, created_at
      ) VALUES (
        NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
        COALESCE(NEW.ultima_latitude, 0),
        COALESCE(NEW.ultima_longitude, 0),
        COALESCE(NEW.velocidade_atual::INT, 0),
        v_mensagem, false, now()
      );

      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id, destinatario_cliente_id,
        titulo, mensagem, tipo, url, placa, lida, created_at
      ) VALUES (
        v_cliente_user_id, NEW.cliente_id,
        v_titulo, v_mensagem, v_tipo, '/monitor-gps',
        COALESCE(NEW.placa, ''), false, now()
      );
    END IF;
  END IF;

  RETURN NEW;

EXCEPTION WHEN OTHERS THEN
  -- NUNCA bloqueia a atualização de telemetria por falha de alerta
  RAISE WARNING '[HUNTER-ALERTAS-TELEMETRIA] Erro ao avaliar alertas para veículo %: %',
    NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.hunter_avaliar_alertas_telemetria() IS
  'Trigger AFTER UPDATE na tabela veiculos. Avalia regras de velocidade, '
  'horário e ignição a cada pacote de telemetria. Insere em alertas_seguranca '
  'e notificacoes_sistema (→ trg_push_vapid → Push VAPID via pg_net). '
  'Cooldown de 5 min por tipo/veículo. Independente de qualquer cliente ativo.';

-- ─────────────────────────────────────────────────────────────────────────────
-- 4. CRIA O TRIGGER NA TABELA veiculos
-- ─────────────────────────────────────────────────────────────────────────────
DROP TRIGGER IF EXISTS trg_hunter_alertas_telemetria ON public.veiculos;

CREATE TRIGGER trg_hunter_alertas_telemetria
AFTER UPDATE OF velocidade_atual, ignicao_status, ultima_atualizacao
ON public.veiculos
FOR EACH ROW
WHEN (
  -- Só executa se houver mudança real em velocidade ou ignição (evita disparos vazios)
  (
    OLD.velocidade_atual IS DISTINCT FROM NEW.velocidade_atual
    OR OLD.ignicao_status IS DISTINCT FROM NEW.ignicao_status
  )
  AND NEW.cliente_id IS NOT NULL
  AND NEW.ativo = true
)
EXECUTE FUNCTION public.hunter_avaliar_alertas_telemetria();

-- ─────────────────────────────────────────────────────────────────────────────
-- 5. TAMBÉM AVALIA AO INSERIR TELEMETRIA_POSICOES (gateway de hardware)
-- Garante funcionamento via triggers na tabela de telemetria, caso o
-- gateway atualize telemetria_posicoes sem atualizar veiculos diretamente.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.hunter_atualizar_veiculo_pos_telemetria()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Sincroniza os campos de estado do veículo a partir da nova telemetria
  -- para garantir que o trigger trg_hunter_alertas_telemetria seja acionado.
  UPDATE public.veiculos
  SET
    velocidade_atual     = COALESCE(NEW.velocidade, velocidade_atual),
    ignicao_status       = COALESCE(NEW.ignicao, ignicao_status),
    ultima_latitude      = COALESCE(NEW.latitude, ultima_latitude),
    ultima_longitude     = COALESCE(NEW.longitude, ultima_longitude),
    ultima_atualizacao   = COALESCE(NEW.data_hora_gps, now())
  WHERE id = NEW.veiculo_id;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[HUNTER-POS-TELEMETRIA] Erro ao sincronizar veículo %: %',
    NEW.veiculo_id, SQLERRM;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_hunter_sync_veiculo_telemetria ON public.telemetria_posicoes;

CREATE TRIGGER trg_hunter_sync_veiculo_telemetria
AFTER INSERT ON public.telemetria_posicoes
FOR EACH ROW
EXECUTE FUNCTION public.hunter_atualizar_veiculo_pos_telemetria();

COMMENT ON FUNCTION public.hunter_atualizar_veiculo_pos_telemetria() IS
  'Sincroniza o estado do veículo (velocidade, ignição, lat/lon) a cada '
  'novo pacote de telemetria recebido, garantindo que o motor de alertas '
  'server-side seja acionado via trg_hunter_alertas_telemetria.';

-- ─────────────────────────────────────────────────────────────────────────────
-- 6. RPC PÚBLICA: TESTE DE NOTIFICAÇÃO (disparo manual com alerta real simulado)
-- Permite testar o pipeline completo sem depender de telemetria de hardware.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.hunter_testar_notificacao(
  p_veiculo_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id     UUID := auth.uid();
  v_cliente_id  UUID;
  v_placa       TEXT;
  v_notif_id    UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Usuário não autenticado.');
  END IF;

  -- Busca o cliente do usuário autenticado
  SELECT id INTO v_cliente_id
  FROM public.clientes
  WHERE user_id = v_user_id
  LIMIT 1;

  -- Se um veículo_id foi passado, usa a placa dele
  IF p_veiculo_id IS NOT NULL THEN
    SELECT placa INTO v_placa
    FROM public.veiculos
    WHERE id = p_veiculo_id AND cliente_id = v_cliente_id;
  END IF;

  -- Insere notificação de teste → trigger pg_net → Push VAPID → dispositivo
  INSERT INTO public.notificacoes_sistema (
    destinatario_user_id,
    destinatario_cliente_id,
    titulo,
    mensagem,
    tipo,
    url,
    placa,
    lida,
    created_at
  ) VALUES (
    v_user_id,
    v_cliente_id,
    '🔔 Teste de Notificação — GD Rastreamento',
    format(
      'Canal de alertas operacional. Notificações de velocidade, ignição e movimento estão ativas e funcionando.%s',
      CASE WHEN v_placa IS NOT NULL THEN format(' Veículo: %s.', v_placa) ELSE '' END
    ),
    'teste',
    '/monitor-gps',
    v_placa,
    false,
    now()
  )
  RETURNING id INTO v_notif_id;

  RETURN jsonb_build_object(
    'sucesso', true,
    'notificacao_id', v_notif_id,
    'mensagem', 'Notificação de teste enviada. Você deve receber o push em segundos.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.hunter_testar_notificacao(UUID) TO authenticated;

COMMENT ON FUNCTION public.hunter_testar_notificacao(UUID) IS
  'Dispara uma notificação de teste para o usuário autenticado via inserção '
  'em notificacoes_sistema → trg_push_vapid → Push VAPID. '
  'Permite validar o pipeline completo sem telemetria real.';


-- ============================================================================
-- [75/225] MIGRAÇÃO: 20260929160000_hunter_fix_alerta_movimento_fora_horario.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — FIX: ALERTA C — MOVIMENTO FORA DO HORÁRIO (COM IGNIÇÃO LIGADA)
-- ============================================================================
-- Versão Alvo: 1.10.2.10
-- Root Cause: O Alerta C avaliava ignicao_status = false (motor desligado),
--             cobrindo apenas guincho/reboque. O cenário real de "movimento
--             fora do horário" é o veículo se deslocar com MOTOR LIGADO fora
--             da janela configurada — que nunca era avaliado.
-- Fix:        Alerta C → ignicao_status = true AND velocidade_atual > 0
--             Alerta D (Guincho) permanece inalterado: ignicao = false + vel > 5
-- ============================================================================

CREATE OR REPLACE FUNCTION public.hunter_avaliar_alertas_telemetria()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_velocidade_limite   NUMERIC;
  v_cliente_user_id     UUID;
  v_horario_proibido    BOOLEAN;
  v_cooldown_ok         BOOLEAN;
  v_hora_inicio_str     TEXT;
  v_hora_fim_str        TEXT;
  v_titulo              TEXT;
  v_mensagem            TEXT;
  v_tipo                TEXT;
  v_gravidade           TEXT;
  COOLDOWN_INTERVAL CONSTANT INTERVAL := INTERVAL '5 minutes';
BEGIN
  -- ── Ignora se não há cliente associado ao veículo ──
  IF NEW.cliente_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- ── Busca o user_id do cliente para endereçar o Push VAPID ──
  SELECT user_id INTO v_cliente_user_id
  FROM public.clientes
  WHERE id = NEW.cliente_id
  LIMIT 1;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA A: EXCESSO DE VELOCIDADE
  -- Condição: velocidade atual > limite configurado em regras_veiculo
  -- ─────────────────────────────────────────────────────────────────────────
  IF COALESCE(NEW.velocidade_atual, 0) > 0 THEN
    -- Busca limite configurado (padrão 110 se não houver registro)
    SELECT COALESCE(limite_velocidade_geral, 110)
    INTO v_velocidade_limite
    FROM public.regras_veiculo
    WHERE veiculo_id = NEW.id
    LIMIT 1;

    IF NOT FOUND THEN
      v_velocidade_limite := 110;
    END IF;

    IF NEW.velocidade_atual > v_velocidade_limite THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'excesso_velocidade'
            AND ultimo_at > (now() - COOLDOWN_INTERVAL)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo    := format('Excesso de Velocidade — %s', COALESCE(NEW.placa, ''));
        v_mensagem  := format(
          'Veículo %s atingiu %s km/h, ultrapassando o limite configurado de %s km/h.',
          COALESCE(NEW.placa, ''),
          ROUND(NEW.velocidade_atual),
          ROUND(v_velocidade_limite)
        );
        v_tipo      := 'excesso_velocidade';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA B: IGNIÇÃO FORA DO HORÁRIO CONFIGURADO
  -- Condição: ignição ligada E horário atual fora da janela permitida
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = true THEN
    v_horario_proibido := public.hunter_horario_proibido(NEW.id);

    IF v_horario_proibido THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'ignicao_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_INTERVAL)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        SELECT
          hora_inicio::TEXT,
          hora_fim::TEXT
        INTO v_hora_inicio_str, v_hora_fim_str
        FROM public.horarios_utilizacao
        WHERE veiculo_id = NEW.id AND ativo = true
        LIMIT 1;

        v_titulo   := format('Ignição Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Motor acionado fora do horário habitual configurado (%s às %s). Veículo: %s.',
          COALESCE(v_hora_inicio_str, ''), COALESCE(v_hora_fim_str, ''),
          COALESCE(NEW.placa, '')
        );
        v_tipo      := 'ignicao_fora_horario';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA C: MOVIMENTO FORA DO HORÁRIO (ignição LIGADA + velocidade > 0)
  -- FIX v1.10.2.10: Antes avaliava ignicao=false (guincho). Corrigido para
  -- ignicao=true — cobre o cenário real de deslocamento autorizado fora da
  -- janela habitual configurada pelo usuário.
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = true AND COALESCE(NEW.velocidade_atual, 0) > 0 THEN
    v_horario_proibido := public.hunter_horario_proibido(NEW.id);

    IF v_horario_proibido THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'movimento_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_INTERVAL)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo   := format('Deslocamento Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Veículo %s em deslocamento (%s km/h) fora da janela habitual configurada.',
          COALESCE(NEW.placa, ''),
          ROUND(NEW.velocidade_atual)
        );
        v_tipo      := 'movimento_fora_horario';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA D: GUINCHO / FURTO (ignição DESLIGADA + velocidade > 5 km/h, sempre)
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = false AND COALESCE(NEW.velocidade_atual, 0) > 5 THEN
    SELECT (
      NOT EXISTS (
        SELECT 1 FROM public.alertas_telemetria_cooldown
        WHERE veiculo_id = NEW.id
          AND tipo_alerta = 'guincho'
          AND ultimo_at > (now() - COOLDOWN_INTERVAL)
      )
    ) INTO v_cooldown_ok;

    IF v_cooldown_ok THEN
      v_titulo   := format('🚨 Veículo em Movimento com Motor Desligado — %s', COALESCE(NEW.placa, ''));
      v_mensagem := format(
        'Veículo %s detectado a %s km/h com ignição desligada. Possível reboque ou furto em andamento.',
        COALESCE(NEW.placa, ''),
        ROUND(NEW.velocidade_atual)
      );
      v_tipo      := 'guincho';
      v_gravidade := 'critica';

      INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
      VALUES (NEW.id, v_tipo, now())
      ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

      INSERT INTO public.alertas_seguranca (
        veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
        velocidade, detalhes, reconhecido, created_at
      ) VALUES (
        NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
        COALESCE(NEW.ultima_latitude, 0),
        COALESCE(NEW.ultima_longitude, 0),
        COALESCE(NEW.velocidade_atual::INT, 0),
        v_mensagem, false, now()
      );

      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id, destinatario_cliente_id,
        titulo, mensagem, tipo, url, placa, lida, created_at
      ) VALUES (
        v_cliente_user_id, NEW.cliente_id,
        v_titulo, v_mensagem, v_tipo, '/monitor-gps',
        COALESCE(NEW.placa, ''), false, now()
      );
    END IF;
  END IF;

  RETURN NEW;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[HUNTER-ALERTAS-TELEMETRIA] Erro ao avaliar alertas para veículo %: %',
    NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.hunter_avaliar_alertas_telemetria() IS
  'v1.10.2.10 — FIX: Alerta C corrigido para ignicao=true + velocidade>0, '
  'cobrindo deslocamento com motor ligado fora do horário. '
  'Alerta D (Guincho) permanece: ignicao=false + velocidade>5. '
  'Trigger AFTER UPDATE na tabela veiculos. Cooldown 5 min por tipo/veículo. '
  'Independente de qualquer cliente ativo.';


-- ============================================================================
-- [76/225] MIGRAÇÃO: 20260929170000_hunter_estoque_custo_frete_e_base.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — SUPORTE A CUSTO BASE, FRETE UNITÁRIO E MARKUP EM ESTOQUE_ITENS
-- ============================================================================
-- Data: 29/09/2026
-- Objetivo: Permitir que o frete unitário componha o custo total do material
--           em estoque, somando ao final do markup sem incidência de lucro.
-- ============================================================================

DO $$
BEGIN
  -- 1. Custo Base (aquisição direta da peça)
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'estoque_itens' AND column_name = 'custo_base'
  ) THEN
    ALTER TABLE public.estoque_itens ADD COLUMN custo_base NUMERIC(12, 2) DEFAULT 0;
  END IF;

  -- 2. Custo do Frete Unitário (rateio do frete por unidade)
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'estoque_itens' AND column_name = 'custo_frete'
  ) THEN
    ALTER TABLE public.estoque_itens ADD COLUMN custo_frete NUMERIC(12, 2) DEFAULT 0;
  END IF;

  -- 3. Preço de Venda
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'estoque_itens' AND column_name = 'preco_venda'
  ) THEN
    ALTER TABLE public.estoque_itens ADD COLUMN preco_venda NUMERIC(12, 2) DEFAULT 0;
  END IF;

  -- 4. Markup Percentual
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'estoque_itens' AND column_name = 'markup_percentual'
  ) THEN
    ALTER TABLE public.estoque_itens ADD COLUMN markup_percentual NUMERIC(12, 2) DEFAULT 0;
  END IF;
END $$;


-- ============================================================================
-- [77/225] MIGRAÇÃO: 20260929180000_hunter_modulo_motoristas.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — MÓDULO MOTORISTAS
-- Versão: 1.11.0.0
-- Diretrizes: DJR-NEW · DJR-APP · Anti-Polling · RLS Estrito · Zero Mock
-- ============================================================================

-- ============================================================================
-- 1. ADICIONAR 'motorista' AO ENUM hunter_role
-- ============================================================================
DO $$ BEGIN
  ALTER TYPE public.hunter_role ADD VALUE IF NOT EXISTS 'motorista';
EXCEPTION
  WHEN duplicate_object THEN NULL;
  WHEN others THEN NULL;
END $$;

-- ============================================================================
-- 2. TABELA PRINCIPAL: motoristas
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.motoristas (
  id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  cliente_id            UUID NOT NULL REFERENCES public.clientes(id) ON DELETE CASCADE,
  user_id               UUID REFERENCES auth.users(id) ON DELETE SET NULL,

  -- Dados pessoais
  nome                  TEXT NOT NULL,
  cpf                   TEXT,
  data_nascimento       DATE,
  telefone              TEXT,
  email                 TEXT NOT NULL,

  -- CNH
  cnh_numero            TEXT,
  cnh_categoria         TEXT,        -- A, B, AB, C, D, E, ACC, etc.
  cnh_validade          DATE,
  cnh_primeira_habilitacao DATE,
  cnh_renach            TEXT,
  cnh_observacoes       TEXT,
  cnh_foto_url          TEXT,        -- URL do arquivo no Storage (original)

  -- Controle de acesso ao mapa operacional
  acesso_mapa           BOOLEAN NOT NULL DEFAULT FALSE,

  -- Status
  ativo                 BOOLEAN NOT NULL DEFAULT TRUE,

  -- Auditoria
  created_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  -- Unicidade: e-mail único por cliente
  CONSTRAINT uq_motorista_email UNIQUE (email),
  -- CPF único quando preenchido (por cliente)
  CONSTRAINT uq_motorista_cpf_cliente UNIQUE (cliente_id, cpf)
);

-- Índices de performance
CREATE INDEX IF NOT EXISTS idx_motoristas_cliente    ON public.motoristas(cliente_id);
CREATE INDEX IF NOT EXISTS idx_motoristas_user_id    ON public.motoristas(user_id);
CREATE INDEX IF NOT EXISTS idx_motoristas_cnh_val    ON public.motoristas(cnh_validade);
CREATE INDEX IF NOT EXISTS idx_motoristas_ativo      ON public.motoristas(cliente_id, ativo);

-- ============================================================================
-- 3. TABELA: motorista_veiculos (vinculação motorista ↔ veículo)
-- Motoristas só operam veículos explicitamente associados pelo cliente.
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.motorista_veiculos (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  motorista_id  UUID NOT NULL REFERENCES public.motoristas(id) ON DELETE CASCADE,
  veiculo_id    UUID NOT NULL REFERENCES public.veiculos(id)   ON DELETE CASCADE,
  ativo         BOOLEAN NOT NULL DEFAULT TRUE,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_motorista_veiculo UNIQUE (motorista_id, veiculo_id)
);

CREATE INDEX IF NOT EXISTS idx_motveic_motorista ON public.motorista_veiculos(motorista_id);
CREATE INDEX IF NOT EXISTS idx_motveic_veiculo   ON public.motorista_veiculos(veiculo_id);

-- ============================================================================
-- 4. TABELA: motorista_abastecimentos
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.motorista_abastecimentos (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  motorista_id  UUID NOT NULL REFERENCES public.motoristas(id) ON DELETE CASCADE,
  veiculo_id    UUID NOT NULL REFERENCES public.veiculos(id)   ON DELETE RESTRICT,
  cliente_id    UUID NOT NULL REFERENCES public.clientes(id)   ON DELETE CASCADE,

  data_abastecimento  DATE NOT NULL,
  km_atual            NUMERIC(10,2),
  litros              NUMERIC(10,3) NOT NULL,
  valor_total         NUMERIC(12,2) NOT NULL,
  valor_por_litro     NUMERIC(10,4),
  combustivel         TEXT NOT NULL DEFAULT 'gasolina', -- gasolina, etanol, diesel, gnv, eletrico
  posto_nome          TEXT,
  posto_cidade        TEXT,
  nf_numero           TEXT,
  -- Ciclo de vida do arquivo NF no Storage (bucket: nfs-temp)
  nf_foto_url         TEXT,             -- path no Storage (null = sem arquivo ou expirado)
  nf_upload_em        TIMESTAMPTZ,      -- quando o motorista fez upload
  nf_baixado          BOOLEAN NOT NULL DEFAULT FALSE,
  nf_baixado_em       TIMESTAMPTZ,
  nf_ciente_em        TIMESTAMPTZ,      -- cliente confirmou ciencia de expiracao
  nf_expirado         BOOLEAN NOT NULL DEFAULT FALSE, -- arquivo deletado do Storage
  observacoes         TEXT,

  created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_abast_motorista  ON public.motorista_abastecimentos(motorista_id);
CREATE INDEX IF NOT EXISTS idx_abast_veiculo    ON public.motorista_abastecimentos(veiculo_id);
CREATE INDEX IF NOT EXISTS idx_abast_cliente    ON public.motorista_abastecimentos(cliente_id);
CREATE INDEX IF NOT EXISTS idx_abast_data       ON public.motorista_abastecimentos(data_abastecimento DESC);

-- ============================================================================
-- 5. TABELA: motorista_despesas
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.motorista_despesas (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  motorista_id  UUID NOT NULL REFERENCES public.motoristas(id) ON DELETE CASCADE,
  veiculo_id    UUID NOT NULL REFERENCES public.veiculos(id)   ON DELETE RESTRICT,
  cliente_id    UUID NOT NULL REFERENCES public.clientes(id)   ON DELETE CASCADE,

  data_despesa        DATE NOT NULL,
  categoria           TEXT NOT NULL, -- pedagio, estacionamento, lavagem, multa, outro
  descricao           TEXT NOT NULL,
  valor               NUMERIC(12,2) NOT NULL,
  km_atual            NUMERIC(10,2),
  nf_numero           TEXT,
  -- Ciclo de vida do arquivo NF no Storage (bucket: nfs-temp)
  nf_foto_url         TEXT,
  nf_upload_em        TIMESTAMPTZ,
  nf_baixado          BOOLEAN NOT NULL DEFAULT FALSE,
  nf_baixado_em       TIMESTAMPTZ,
  nf_ciente_em        TIMESTAMPTZ,
  nf_expirado         BOOLEAN NOT NULL DEFAULT FALSE,
  observacoes         TEXT,

  created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_despesas_motorista ON public.motorista_despesas(motorista_id);
CREATE INDEX IF NOT EXISTS idx_despesas_veiculo   ON public.motorista_despesas(veiculo_id);
CREATE INDEX IF NOT EXISTS idx_despesas_cliente   ON public.motorista_despesas(cliente_id);
CREATE INDEX IF NOT EXISTS idx_despesas_data      ON public.motorista_despesas(data_despesa DESC);

-- ============================================================================
-- 6. TRIGGER: atualizar updated_at automaticamente
-- ============================================================================
CREATE OR REPLACE FUNCTION public.set_updated_at_motoristas()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END; $$;

DO $$ BEGIN
  CREATE TRIGGER trg_motoristas_updated_at
    BEFORE UPDATE ON public.motoristas
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_motoristas();
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TRIGGER trg_abast_updated_at
    BEFORE UPDATE ON public.motorista_abastecimentos
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_motoristas();
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TRIGGER trg_despesas_updated_at
    BEFORE UPDATE ON public.motorista_despesas
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_motoristas();
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- ============================================================================
-- 7. HELPER: retorna o motorista_id do usuário autenticado
-- ============================================================================
CREATE OR REPLACE FUNCTION public.get_motorista_id()
RETURNS UUID
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
  SELECT id FROM public.motoristas
  WHERE user_id = auth.uid() AND ativo = TRUE
  LIMIT 1;
$$;

-- ============================================================================
-- 8. RLS: ATIVAR E DEFINIR POLÍTICAS
-- ============================================================================

-- motoristas
ALTER TABLE public.motoristas ENABLE ROW LEVEL SECURITY;

-- Clientes veem apenas seus motoristas
CREATE POLICY "motoristas_select_cliente" ON public.motoristas
  FOR SELECT USING (
    cliente_id IN (SELECT id FROM public.clientes WHERE user_id = auth.uid())
    OR (SELECT role FROM public.profiles WHERE id = auth.uid()) IN ('superadmin','adm','operador')
  );

-- Clientes inserem motoristas no próprio cliente
CREATE POLICY "motoristas_insert_cliente" ON public.motoristas
  FOR INSERT WITH CHECK (
    cliente_id IN (SELECT id FROM public.clientes WHERE user_id = auth.uid())
    OR (SELECT role FROM public.profiles WHERE id = auth.uid()) IN ('superadmin','adm')
  );

-- Clientes editam apenas seus motoristas
CREATE POLICY "motoristas_update_cliente" ON public.motoristas
  FOR UPDATE USING (
    cliente_id IN (SELECT id FROM public.clientes WHERE user_id = auth.uid())
    OR (SELECT role FROM public.profiles WHERE id = auth.uid()) IN ('superadmin','adm')
  );

-- Clientes excluem apenas seus motoristas
CREATE POLICY "motoristas_delete_cliente" ON public.motoristas
  FOR DELETE USING (
    cliente_id IN (SELECT id FROM public.clientes WHERE user_id = auth.uid())
    OR (SELECT role FROM public.profiles WHERE id = auth.uid()) IN ('superadmin','adm')
  );

-- Motorista vê seu próprio registro
CREATE POLICY "motoristas_select_self" ON public.motoristas
  FOR SELECT USING (user_id = auth.uid());

-- Motorista pode atualizar dados do próprio perfil
CREATE POLICY "motoristas_update_self" ON public.motoristas
  FOR UPDATE USING (user_id = auth.uid());

-- motorista_veiculos
ALTER TABLE public.motorista_veiculos ENABLE ROW LEVEL SECURITY;

CREATE POLICY "motveic_select" ON public.motorista_veiculos
  FOR SELECT USING (
