-- [78/225] MIGRAÇÃO: 20260929190000_hunter_fix_cadastrar_motorista_pgcrypto.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — FIX: CADASTRAR MOTORISTA — pgcrypto + ENUM hunter_role
-- ============================================================================
-- Root Cause: A função cadastrar_motorista usa crypt() e gen_salt() sem
--   qualificar o schema 'extensions.', causando erro
--   "function gen_salt(unknown, integer) does not exist".
--   Adicionalmente, o ENUM hunter_role não continha o valor 'motorista',
--   causando falha no INSERT INTO public.profiles com role = 'motorista'.
-- Fix:
--   1. ALTER TYPE hunter_role ADD VALUE IF NOT EXISTS 'motorista'
--   2. Recriar cadastrar_motorista com extensions.crypt / extensions.gen_salt
--      e search_path = public, extensions, auth, pg_temp
-- ============================================================================

-- ── 1. Adicionar 'motorista' ao ENUM hunter_role ─────────────────────────────
ALTER TYPE public.hunter_role ADD VALUE IF NOT EXISTS 'motorista';

-- ── 2. Recriar a função com schema correto para pgcrypto ─────────────────────
CREATE OR REPLACE FUNCTION public.cadastrar_motorista(
  p_cliente_id      UUID,
  p_nome            TEXT,
  p_email           TEXT,
  p_senha           TEXT,
  p_cpf             TEXT          DEFAULT NULL,
  p_telefone        TEXT          DEFAULT NULL,
  p_data_nascimento DATE          DEFAULT NULL,
  p_cnh_numero      TEXT          DEFAULT NULL,
  p_cnh_categoria   TEXT          DEFAULT NULL,
  p_cnh_validade    DATE          DEFAULT NULL,
  p_cnh_primeira    DATE          DEFAULT NULL,
  p_cnh_renach      TEXT          DEFAULT NULL,
  p_cnh_observacoes TEXT          DEFAULT NULL,
  p_cnh_foto_url    TEXT          DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER
-- CRÍTICO: 'extensions' deve vir antes de 'public' para que crypt/gen_salt
--          do pgcrypto sejam encontrados sem qualificação de schema.
SET search_path = extensions, public, auth, pg_temp
AS $$
DECLARE
  v_caller_id   UUID := auth.uid();
  v_user_id     UUID;
  v_motorista   UUID;
  v_enc_pw      TEXT;
BEGIN
  -- 1. Verificar que o chamador é o dono do cliente ou é adm/superadm
  IF NOT EXISTS (
    SELECT 1 FROM public.clientes WHERE id = p_cliente_id AND user_id = v_caller_id
  ) AND NOT EXISTS (
    SELECT 1 FROM public.profiles WHERE id = v_caller_id AND role IN ('superadmin','adm')
  ) THEN
    RAISE EXCEPTION 'Acesso negado: cliente nao autorizado.';
  END IF;

  -- 2. Validações básicas
  IF p_nome IS NULL OR trim(p_nome) = '' THEN
    RAISE EXCEPTION 'Nome do motorista e obrigatorio.';
  END IF;
  IF p_email IS NULL OR trim(p_email) = '' THEN
    RAISE EXCEPTION 'E-mail do motorista e obrigatorio.';
  END IF;
  IF p_senha IS NULL OR length(p_senha) < 6 THEN
    RAISE EXCEPTION 'Senha deve ter no minimo 6 caracteres.';
  END IF;
  IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = LOWER(trim(p_email))) THEN
    RAISE EXCEPTION 'Ja existe um usuario com este e-mail.';
  END IF;

  -- 3. Criar usuário no auth com senha criptografada via pgcrypto (schema extensions)
  v_user_id := gen_random_uuid();
  v_enc_pw  := extensions.crypt(p_senha, extensions.gen_salt('bf', 10));

  INSERT INTO auth.users (
    instance_id, id, aud, role, email, encrypted_password,
    email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
    created_at, updated_at
  ) VALUES (
    '00000000-0000-0000-0000-000000000000',
    v_user_id, 'authenticated', 'authenticated',
    LOWER(trim(p_email)), v_enc_pw, NOW(),
    jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
    jsonb_build_object('nome', p_nome),
    NOW(), NOW()
  );

  -- 4. Criar identity para login por e-mail
  INSERT INTO auth.identities (
    id, user_id, provider_id, identity_data, provider,
    last_sign_in_at, created_at, updated_at
  ) VALUES (
    gen_random_uuid(), v_user_id, LOWER(trim(p_email)),
    jsonb_build_object('sub', v_user_id::TEXT, 'email', LOWER(trim(p_email))),
    'email', NOW(), NOW(), NOW()
  )
  ON CONFLICT DO NOTHING;

  -- 5. Criar profile com role motorista (agora ENUM contém 'motorista')
  INSERT INTO public.profiles (id, nome, email, role, ativo)
  VALUES (
    v_user_id,
    trim(p_nome),
    LOWER(trim(p_email)),
    'motorista'::public.hunter_role,
    TRUE
  )
  ON CONFLICT (id) DO UPDATE
    SET role = 'motorista'::public.hunter_role,
        nome = EXCLUDED.nome,
        email = EXCLUDED.email,
        ativo = TRUE;

  -- 6. Criar registro do motorista
  INSERT INTO public.motoristas (
    cliente_id, user_id, nome, email, cpf, telefone, data_nascimento,
    cnh_numero, cnh_categoria, cnh_validade, cnh_primeira_habilitacao,
    cnh_renach, cnh_observacoes, cnh_foto_url, acesso_mapa, ativo
  ) VALUES (
    p_cliente_id,
    v_user_id,
    trim(p_nome),
    LOWER(trim(p_email)),
    NULLIF(trim(COALESCE(p_cpf, '')), ''),
    NULLIF(trim(COALESCE(p_telefone, '')), ''),
    p_data_nascimento,
    NULLIF(trim(COALESCE(p_cnh_numero, '')), ''),
    NULLIF(trim(COALESCE(p_cnh_categoria, '')), ''),
    p_cnh_validade,
    p_cnh_primeira,
    NULLIF(trim(COALESCE(p_cnh_renach, '')), ''),
    NULLIF(trim(COALESCE(p_cnh_observacoes, '')), ''),
    NULLIF(trim(COALESCE(p_cnh_foto_url, '')), ''),
    FALSE,  -- acesso_mapa desativado por padrão
    TRUE    -- ativo
  ) RETURNING id INTO v_motorista;

  RETURN jsonb_build_object(
    'motorista_id', v_motorista,
    'user_id',      v_user_id
  );

EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION '[HUNTER-MOTORISTA] Erro ao cadastrar motorista: %', SQLERRM;
END;
$$;

-- Permissão de execução para usuários autenticados (cliente cadastra seu próprio motorista)
GRANT EXECUTE ON FUNCTION public.cadastrar_motorista(
  UUID, TEXT, TEXT, TEXT, TEXT, TEXT, DATE, TEXT, TEXT, DATE, DATE, TEXT, TEXT, TEXT
) TO authenticated;

COMMENT ON FUNCTION public.cadastrar_motorista IS
  'v1.11.0.7 — FIX: Usa extensions.crypt/extensions.gen_salt para compatibilidade '
  'com Supabase. ENUM hunter_role agora inclui ''motorista''. '
  'Cria auth.user + auth.identity + profile + motorista atomicamente. '
  'SECURITY DEFINER. search_path = extensions, public, auth, pg_temp.';


-- ============================================================================
-- [79/225] MIGRAÇÃO: 20260929200000_hunter_fix_pgrst_reload_motorista_schema.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — FIX: Recarregar cache do PostgREST após adição do ENUM 'motorista'
-- ============================================================================
-- O PostgREST armazena em cache o schema do banco. Quando adicionamos um novo
-- valor ao ENUM hunter_role ('motorista'), o PostgREST não recarrega
-- automaticamente, causando "Database error querying schema" ao fazer login
-- com um usuário de role=motorista.
-- Este comando força a reinicialização do schema cache do PostgREST.
-- ============================================================================

-- Forçar recarga do cache do PostgREST
NOTIFY pgrst, 'reload schema';

-- Também garantir que o ENUM está correto (idempotente)
ALTER TYPE public.hunter_role ADD VALUE IF NOT EXISTS 'motorista';

-- Confirmar que pgcrypto está instalado no schema 'extensions'
CREATE EXTENSION IF NOT EXISTS pgcrypto SCHEMA extensions;

-- Garantir que a função cadastrar_motorista tem GRANT correto
GRANT EXECUTE ON FUNCTION public.cadastrar_motorista(
  UUID, TEXT, TEXT, TEXT, TEXT, TEXT, DATE, TEXT, TEXT, DATE, DATE, TEXT, TEXT, TEXT
) TO authenticated;

-- ============================================================================
-- Atualizar TAMBÉM a função admin_redefinir_senha para aceitar role=motorista
-- (garantir que adm pode redefinir senha de motorista)
-- ============================================================================
-- Verificar e GRANT admin_redefinir_senha para authenticated
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON p.pronamespace = n.oid
    WHERE n.nspname = 'public' AND p.proname = 'admin_redefinir_senha'
  ) THEN
    EXECUTE 'GRANT EXECUTE ON FUNCTION public.admin_redefinir_senha(UUID, TEXT) TO authenticated';
  END IF;
END
$$;


-- ============================================================================
-- [80/225] MIGRAÇÃO: 20260929210000_hunter_fix_auth_users_null_columns.sql
-- ============================================================================

-- ====================================================================================
-- MIGRAÇÃO: Correção de inserção na auth.users (Supabase GoTrue NULL values)
-- ====================================================================================

-- Função corrigida para incluir confirmation_token, recovery_token, email_change_token_new, email_change como strings vazias.
-- Caso fiquem NULL, o GoTrue falha no login com 'Database error querying schema'.

CREATE OR REPLACE FUNCTION public.admin_criar_motorista(
  p_cliente_id UUID,
  p_nome TEXT,
  p_email TEXT,
  p_senha TEXT,
  p_cpf TEXT,
  p_data_nascimento DATE,
  p_telefone TEXT,
  p_cnh_numero TEXT,
  p_cnh_categoria TEXT,
  p_cnh_validade DATE,
  p_cnh_primeira_habilitacao DATE,
  p_cnh_renach TEXT,
  p_cnh_observacoes TEXT,
  p_acesso_mapa BOOLEAN
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user_id UUID;
  v_enc_pw TEXT;
  v_cliente_existe BOOLEAN;
  v_motorista_id UUID;
BEGIN
  -- 1. Verificar permissões
  IF auth.role() != 'authenticated' THEN
    RAISE EXCEPTION 'Não autorizado. Faça login primeiro.';
  END IF;

  -- 2. Validar Cliente
  SELECT EXISTS(SELECT 1 FROM public.clientes WHERE id = p_cliente_id) INTO v_cliente_existe;
  IF NOT v_cliente_existe THEN
    RAISE EXCEPTION 'Cliente % não encontrado.', p_cliente_id;
  END IF;

  -- Criptografar senha
  v_enc_pw := extensions.crypt(p_senha, extensions.gen_salt('bf'));

  -- 3. Inserir no auth.users
  v_user_id := extensions.gen_random_uuid();

  INSERT INTO auth.users (
    instance_id, id, aud, role, email, encrypted_password,
    email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
    created_at, updated_at,
    confirmation_token, recovery_token, email_change_token_new, email_change
  ) VALUES (
    '00000000-0000-0000-0000-000000000000',
    v_user_id, 'authenticated', 'authenticated',
    LOWER(trim(p_email)), v_enc_pw, NOW(),
    jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
    jsonb_build_object('nome', p_nome),
    NOW(), NOW(),
    '', '', '', ''
  );

  -- 4. Criar identity para login por e-mail
  INSERT INTO auth.identities (
    id, user_id, provider_id, identity_data, provider,
    last_sign_in_at, created_at, updated_at
  ) VALUES (
    extensions.gen_random_uuid(), v_user_id, LOWER(trim(p_email)),
    jsonb_build_object('sub', v_user_id::TEXT, 'email', LOWER(trim(p_email))),
    'email', NOW(), NOW(), NOW()
  );

  -- 5. Inserir na tabela de motoristas (gerado o perfil publico)
  INSERT INTO public.motoristas (
    cliente_id, user_id, nome, cpf, data_nascimento, telefone, email,
    cnh_numero, cnh_categoria, cnh_validade, cnh_primeira_habilitacao,
    cnh_renach, cnh_observacoes, acesso_mapa, ativo
  ) VALUES (
    p_cliente_id, v_user_id, p_nome, p_cpf, p_data_nascimento, p_telefone, LOWER(trim(p_email)),
    p_cnh_numero, p_cnh_categoria, p_cnh_validade, p_cnh_primeira_habilitacao,
    p_cnh_renach, p_cnh_observacoes, p_acesso_mapa, true
  )
  RETURNING id INTO v_motorista_id;

  -- 6. Inserir perfil (para a autenticação/autorização unificada)
  INSERT INTO public.profiles (
    id, nome, email, role, ativo, primeiro_acesso, cliente_id
  ) VALUES (
    v_user_id, p_nome, LOWER(trim(p_email)), 'motorista', true, true, p_cliente_id
  );

  RETURN jsonb_build_object(
    'status', 'success',
    'motorista_id', v_motorista_id,
    'user_id', v_user_id
  );
END;
$$;


-- ============================================================================
-- [81/225] MIGRAÇÃO: 20260930011854_hunter_fix_rpc_motorista_volatile.sql
-- ============================================================================

-- Remove STABLE marker from get_meu_perfil_motorista to fix auth.uid() being null in PostgREST cache.
-- PostgREST evaluates STABLE functions outside of the transaction where request.jwt.claims is set.

CREATE OR REPLACE FUNCTION public.get_meu_perfil_motorista()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'id',            m.id,
    'nome',          m.nome,
    'email',         m.email,
    'cpf',           m.cpf,
    'telefone',      m.telefone,
    'cnh_numero',    m.cnh_numero,
    'cnh_categoria', m.cnh_categoria,
    'cnh_validade',  m.cnh_validade,
    'cnh_foto_url',  m.cnh_foto_url,
    'acesso_mapa',   m.acesso_mapa,
    'cliente_id',    m.cliente_id,
    'cliente_nome',  c.nome_razao_social
  )
  INTO v_result
  FROM public.motoristas m
  INNER JOIN public.clientes c ON c.id = m.cliente_id
  WHERE m.user_id = auth.uid() AND m.ativo = TRUE
  LIMIT 1;

  IF v_result IS NULL THEN
    RAISE EXCEPTION 'Perfil de motorista nao encontrado.';
  END IF;

  RETURN v_result;
END;
$$;

-- Também remover STABLE de get_motorista_id
CREATE OR REPLACE FUNCTION public.get_motorista_id()
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $$
  SELECT id FROM public.motoristas
  WHERE user_id = auth.uid() AND ativo = TRUE
  LIMIT 1;
$$;


-- ============================================================================
-- [82/225] MIGRAÇÃO: 20260930013000_hunter_motorista_veiculos_rls_completo.sql
-- ============================================================================

-- ============================================================================
-- GD RASTREAMENTO — MÓDULO MOTORISTAS: VEÍCULOS DO CLIENTE E RLS COMPLETO
-- ============================================================================

-- 1. Função auxiliar VOLATILE para obter o cliente_id do motorista autenticado
CREATE OR REPLACE FUNCTION public.get_motorista_cliente_id()
RETURNS UUID
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
  SELECT cliente_id FROM public.motoristas
  WHERE (user_id = auth.uid() OR LOWER(email) = LOWER((SELECT email FROM auth.users WHERE id = auth.uid())))
    AND ativo = TRUE
  LIMIT 1;
$$;

-- 2. Atualiza get_motorista_id com fallback por e-mail e auto-vínculo
CREATE OR REPLACE FUNCTION public.get_motorista_id()
RETURNS UUID
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
  SELECT id FROM public.motoristas
  WHERE (user_id = auth.uid() OR LOWER(email) = LOWER((SELECT email FROM auth.users WHERE id = auth.uid())))
    AND ativo = TRUE
  LIMIT 1;
$$;

-- 3. Atualiza get_meu_perfil_motorista com auto-cura de user_id caso necessário
CREATE OR REPLACE FUNCTION public.get_meu_perfil_motorista()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_email TEXT;
  v_result JSONB;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessao expirada. Faca login novamente.';
  END IF;

  SELECT email INTO v_email FROM auth.users WHERE id = v_uid;

  -- Auto-cura: se o motorista foi cadastrado com este e-mail mas user_id ficou divergente
  UPDATE public.motoristas
  SET user_id = v_uid
  WHERE user_id IS DISTINCT FROM v_uid
    AND LOWER(email) = LOWER(v_email)
    AND ativo = TRUE;

  SELECT jsonb_build_object(
    'id',            m.id,
    'nome',          m.nome,
    'email',         m.email,
    'cpf',           m.cpf,
    'telefone',      m.telefone,
    'cnh_numero',    m.cnh_numero,
    'cnh_categoria', m.cnh_categoria,
    'cnh_validade',  m.cnh_validade,
    'cnh_foto_url',  m.cnh_foto_url,
    'acesso_mapa',   m.acesso_mapa,
    'cliente_id',    m.cliente_id,
    'cliente_nome',  c.nome_razao_social
  )
  INTO v_result
  FROM public.motoristas m
  INNER JOIN public.clientes c ON c.id = m.cliente_id
  WHERE m.user_id = v_uid AND m.ativo = TRUE
  LIMIT 1;

  IF v_result IS NULL THEN
    RAISE EXCEPTION 'Perfil de motorista nao encontrado.';
  END IF;

  RETURN v_result;
END;
$$;

-- 4. RPC para listar os veículos disponíveis do cliente do motorista autenticado
-- Se houver veículos especificamente vinculados em motorista_veiculos, retorna-os;
-- caso contrário, retorna todos os veículos ativos do cliente ao qual o motorista pertence.
CREATE OR REPLACE FUNCTION public.listar_veiculos_portal_motorista()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_motorista_id UUID;
  v_cliente_id UUID;
  v_tem_vinculo BOOLEAN;
  v_result JSONB;
BEGIN
  SELECT id, cliente_id INTO v_motorista_id, v_cliente_id
  FROM public.motoristas
  WHERE user_id = v_uid AND ativo = TRUE
  LIMIT 1;

  IF v_motorista_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.motorista_veiculos
    WHERE motorista_id = v_motorista_id AND ativo = TRUE
  ) INTO v_tem_vinculo;

  IF v_tem_vinculo THEN
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', mv.id,
        'motorista_id', mv.motorista_id,
        'veiculo_id', v.id,
        'ativo', mv.ativo,
        'created_at', mv.created_at,
        'veiculo_placa', v.placa,
        'veiculo_modelo', v.marca_modelo,
        'veiculo_cor', v.cor,
        'odometro_km', COALESCE(v.odometro_km, 0),
        'ultima_latitude', v.ultima_latitude,
        'ultima_longitude', v.ultima_longitude,
        'ignicao_status', COALESCE(v.ignicao_status, FALSE),
        'velocidade_atual', COALESCE(v.velocidade_atual, 0)
      ) ORDER BY v.placa ASC
    ), '[]'::jsonb)
    INTO v_result
    FROM public.motorista_veiculos mv
    INNER JOIN public.veiculos v ON v.id = mv.veiculo_id
    WHERE mv.motorista_id = v_motorista_id
      AND mv.ativo = TRUE
      AND v.ativo = TRUE;
  ELSE
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', v.id,
        'motorista_id', v_motorista_id,
        'veiculo_id', v.id,
        'ativo', TRUE,
        'created_at', v.created_at,
        'veiculo_placa', v.placa,
        'veiculo_modelo', v.marca_modelo,
        'veiculo_cor', v.cor,
        'odometro_km', COALESCE(v.odometro_km, 0),
        'ultima_latitude', v.ultima_latitude,
        'ultima_longitude', v.ultima_longitude,
        'ignicao_status', COALESCE(v.ignicao_status, FALSE),
        'velocidade_atual', COALESCE(v.velocidade_atual, 0)
      ) ORDER BY v.placa ASC
    ), '[]'::jsonb)
    INTO v_result
    FROM public.veiculos v
    WHERE v.cliente_id = v_cliente_id
      AND v.ativo = TRUE
      AND v.placa NOT IN ('HTR4G16', 'HUN1T26');
  END IF;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;

-- 5. Garantir primeiro_acesso = false para motoristas (senha já definida pelo cliente)
UPDATE public.profiles
SET primeiro_acesso = FALSE
WHERE role = 'motorista' AND primeiro_acesso IS DISTINCT FROM FALSE;

-- 6. Políticas RLS para Motorista acessar estritamente os veículos e manutenção do seu cliente

-- 6.1 Clientes (SELECT do próprio cliente vinculado ao motorista, necessário para joins de veículos)
DROP POLICY IF EXISTS "Motoristas visualizam seu cliente vinculado" ON public.clientes;
CREATE POLICY "Motoristas visualizam seu cliente vinculado"
ON public.clientes FOR SELECT TO authenticated
USING (id = public.get_motorista_cliente_id());

-- 6.2 Veículos (SELECT e UPDATE de odômetro restritos aos veículos do cliente do motorista)
DROP POLICY IF EXISTS "Motoristas visualizam veiculos do seu cliente" ON public.veiculos;
CREATE POLICY "Motoristas visualizam veiculos do seu cliente"
ON public.veiculos FOR SELECT TO authenticated
USING (cliente_id = public.get_motorista_cliente_id());

DROP POLICY IF EXISTS "Motoristas atualizam odometro de veiculos do seu cliente" ON public.veiculos;
CREATE POLICY "Motoristas atualizam odometro de veiculos do seu cliente"
ON public.veiculos FOR UPDATE TO authenticated
USING (cliente_id = public.get_motorista_cliente_id())
WITH CHECK (cliente_id = public.get_motorista_cliente_id());

-- 6.3 Telemetria (SELECT para motoristas do cliente)
DROP POLICY IF EXISTS "Motoristas visualizam telemetria de veiculos do seu cliente" ON public.telemetria_posicoes;
CREATE POLICY "Motoristas visualizam telemetria de veiculos do seu cliente"
ON public.telemetria_posicoes FOR SELECT TO authenticated
USING (
  veiculo_id IN (
    SELECT id FROM public.veiculos WHERE cliente_id = public.get_motorista_cliente_id()
  )
);

-- 6.4 Manutenção Preventiva (SELECT, INSERT, UPDATE para alimentar troca de óleo e revisões)
DROP POLICY IF EXISTS "Motoristas gerenciam manutencao dos veiculos do seu cliente" ON public.planos_manutencao_preventiva;
CREATE POLICY "Motoristas gerenciam manutencao dos veiculos do seu cliente"
ON public.planos_manutencao_preventiva FOR ALL TO authenticated
USING (
  veiculo_id IN (
    SELECT id FROM public.veiculos WHERE cliente_id = public.get_motorista_cliente_id()
  )
)
WITH CHECK (
  veiculo_id IN (
    SELECT id FROM public.veiculos WHERE cliente_id = public.get_motorista_cliente_id()
  )
);

-- 6.5 Agendamentos de Manutenção
DROP POLICY IF EXISTS "Motoristas visualizam e criam agendamentos do seu cliente" ON public.agendamentos_manutencao;
CREATE POLICY "Motoristas visualizam e criam agendamentos do seu cliente"
ON public.agendamentos_manutencao FOR ALL TO authenticated
USING (cliente_id = public.get_motorista_cliente_id())
WITH CHECK (cliente_id = public.get_motorista_cliente_id());

-- 6.6 Alertas de Segurança (INSERT e SELECT para alertas de NF e manutenção)
DROP POLICY IF EXISTS "Motoristas registram alertas nos veiculos do seu cliente" ON public.alertas_seguranca;
CREATE POLICY "Motoristas registram alertas nos veiculos do seu cliente"
ON public.alertas_seguranca FOR ALL TO authenticated
USING (
  veiculo_id IN (
    SELECT id FROM public.veiculos WHERE cliente_id = public.get_motorista_cliente_id()
  )
)
WITH CHECK (
  veiculo_id IN (
    SELECT id FROM public.veiculos WHERE cliente_id = public.get_motorista_cliente_id()
  )
);

NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [83/225] MIGRAÇÃO: 20260930140000_hunter_anti_falso_alerta_guincho.sql
-- ============================================================================

-- ============================================================================
-- HUNTER / GD RASTREAMENTO — FIX: ANTI-FALSO-POSITIVO ALERTA DE GUINCHO / REBOQUE
-- ============================================================================
-- Versão Alvo: 1.11.0.16
-- Root Cause: O Alerta D (Guincho) disparava com ignicao = false e velocidade > 5.
--             Isso gerava falsos positivos graves em dois cenários:
--             1. No exato instante em que o motorista desliga a chave do motor
--                (OLD.ignicao = true, NEW.ignicao = false) enquanto desacelera (ex: 6 km/h).
--             2. Flutuação/ruído de satélite GPS com veículo estacionado (antena oscilando
--                espuriamente entre 6 e 12 km/h sem deslocamento físico do veículo).
-- Fix:        1. Ignora se o motor acabou de ser desligado (OLD.ignicao_status = true).
--             2. Exige que o veículo já estivesse com motor desligado (OLD.ignicao_status = false).
--             3. Calcula a distância geodésica real Haversine entre a coordenada anterior e atual.
--             4. Exige deslocamento real >= 35 metros E velocidade >= 10 km/h,
--                OU velocidade sustentada >= 15 km/h.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.hunter_avaliar_alertas_telemetria()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_velocidade_limite   NUMERIC;
  v_cliente_user_id     UUID;
  v_horario_proibido    BOOLEAN;
  v_cooldown_ok         BOOLEAN;
  v_hora_inicio_str     TEXT;
  v_hora_fim_str        TEXT;
  v_titulo              TEXT;
  v_mensagem            TEXT;
  v_tipo                TEXT;
  v_gravidade           TEXT;
  v_dist_metros         DOUBLE PRECISION := 0;
  v_dlat                DOUBLE PRECISION;
  v_dlon                DOUBLE PRECISION;
  v_a                   DOUBLE PRECISION;
  COOLDOWN_INTERVAL CONSTANT INTERVAL := INTERVAL '5 minutes';
BEGIN
  -- ── Ignora se não há cliente associado ao veículo ──
  IF NEW.cliente_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- ── Busca o user_id do cliente para endereçar o Push VAPID ──
  SELECT user_id INTO v_cliente_user_id
  FROM public.clientes
  WHERE id = NEW.cliente_id
  LIMIT 1;

  -- ── Cálculo geodésico de deslocamento Haversine em metros entre OLD e NEW ──
  IF OLD.ultima_latitude IS NOT NULL 
     AND OLD.ultima_longitude IS NOT NULL 
     AND NEW.ultima_latitude IS NOT NULL 
     AND NEW.ultima_longitude IS NOT NULL
     AND (OLD.ultima_latitude <> 0 OR OLD.ultima_longitude <> 0)
     AND (NEW.ultima_latitude <> 0 OR NEW.ultima_longitude <> 0)
     AND (OLD.ultima_latitude <> NEW.ultima_latitude OR OLD.ultima_longitude <> NEW.ultima_longitude) THEN
    
    v_dlat := radians(NEW.ultima_latitude - OLD.ultima_latitude);
    v_dlon := radians(NEW.ultima_longitude - OLD.ultima_longitude);
    v_a := sin(v_dlat / 2.0)^2 + cos(radians(OLD.ultima_latitude)) * cos(radians(NEW.ultima_latitude)) * sin(v_dlon / 2.0)^2;
    v_dist_metros := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(GREATEST(0.0, 1.0 - v_a)));
  ELSE
    v_dist_metros := 0;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA A: EXCESSO DE VELOCIDADE
  -- Condição: velocidade atual > limite configurado em regras_veiculo
  -- ─────────────────────────────────────────────────────────────────────────
  IF COALESCE(NEW.velocidade_atual, 0) > 0 THEN
    SELECT COALESCE(limite_velocidade_geral, 110)
    INTO v_velocidade_limite
    FROM public.regras_veiculo
    WHERE veiculo_id = NEW.id
    LIMIT 1;

    IF NOT FOUND THEN
      v_velocidade_limite := 110;
    END IF;

    IF NEW.velocidade_atual > v_velocidade_limite THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'excesso_velocidade'
            AND ultimo_at > (now() - COOLDOWN_INTERVAL)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo    := format('Excesso de Velocidade — %s', COALESCE(NEW.placa, ''));
        v_mensagem  := format(
          'Veículo %s atingiu %s km/h, ultrapassando o limite configurado de %s km/h.',
          COALESCE(NEW.placa, ''),
          ROUND(NEW.velocidade_atual),
          ROUND(v_velocidade_limite)
        );
        v_tipo      := 'excesso_velocidade';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA B: IGNIÇÃO FORA DO HORÁRIO CONFIGURADO
  -- Condição: ignição ligada E horário atual fora da janela permitida
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = true THEN
    v_horario_proibido := public.hunter_horario_proibido(NEW.id);

    IF v_horario_proibido THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'ignicao_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_INTERVAL)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        SELECT
          hora_inicio::TEXT,
          hora_fim::TEXT
        INTO v_hora_inicio_str, v_hora_fim_str
        FROM public.horarios_utilizacao
        WHERE veiculo_id = NEW.id AND ativo = true
        LIMIT 1;

        v_titulo   := format('Ignição Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Motor acionado fora do horário habitual configurado (%s às %s). Veículo: %s.',
          COALESCE(v_hora_inicio_str, ''), COALESCE(v_hora_fim_str, ''),
          COALESCE(NEW.placa, '')
        );
        v_tipo      := 'ignicao_fora_horario';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA C: MOVIMENTO FORA DO HORÁRIO (ignição LIGADA + velocidade > 0)
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = true AND COALESCE(NEW.velocidade_atual, 0) > 0 THEN
    v_horario_proibido := public.hunter_horario_proibido(NEW.id);

    IF v_horario_proibido THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'movimento_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_INTERVAL)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo   := format('Deslocamento Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Veículo %s em deslocamento (%s km/h) fora da janela habitual configurada.',
          COALESCE(NEW.placa, ''),
          ROUND(NEW.velocidade_atual)
        );
        v_tipo      := 'movimento_fora_horario';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA D: GUINCHO / FURTO / REBOQUE NÃO AUTORIZADO
  -- Condição: ignição DESLIGADA com deslocamento real ou velocidade sustentada
  -- Anti-Falso-Positivo:
  -- 1. Descarta desaceleração ao desligar o motor (OLD.ignicao_status = true)
  -- 2. Descarta oscilação de satélite parado (velocidade < 15 e deslocamento < 35m)
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = false
     AND COALESCE(OLD.ignicao_status, false) = false
     AND (
       COALESCE(NEW.velocidade_atual, 0) >= 15
       OR (COALESCE(NEW.velocidade_atual, 0) >= 10 AND v_dist_metros >= 35.0)
     ) THEN
    SELECT (
      NOT EXISTS (
        SELECT 1 FROM public.alertas_telemetria_cooldown
        WHERE veiculo_id = NEW.id
          AND tipo_alerta = 'guincho'
          AND ultimo_at > (now() - COOLDOWN_INTERVAL)
      )
    ) INTO v_cooldown_ok;

    IF v_cooldown_ok THEN
      v_titulo   := format('🚨 Veículo em Movimento com Motor Desligado — %s', COALESCE(NEW.placa, ''));
      v_mensagem := format(
        'Veículo %s detectado a %s km/h com ignição desligada. Possível reboque ou furto em andamento.',
        COALESCE(NEW.placa, ''),
        ROUND(NEW.velocidade_atual)
      );
      v_tipo      := 'guincho';
      v_gravidade := 'critica';

      INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
      VALUES (NEW.id, v_tipo, now())
      ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

      INSERT INTO public.alertas_seguranca (
        veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
        velocidade, detalhes, reconhecido, created_at
      ) VALUES (
        NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
        COALESCE(NEW.ultima_latitude, 0),
        COALESCE(NEW.ultima_longitude, 0),
        COALESCE(NEW.velocidade_atual::INT, 0),
        v_mensagem, false, now()
      );

      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id, destinatario_cliente_id,
        titulo, mensagem, tipo, url, placa, lida, created_at
      ) VALUES (
        v_cliente_user_id, NEW.cliente_id,
        v_titulo, v_mensagem, v_tipo, '/monitor-gps',
        COALESCE(NEW.placa, ''), false, now()
      );
    END IF;
  END IF;

  RETURN NEW;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[HUNTER-ALERTAS-TELEMETRIA] Erro ao avaliar alertas para veículo %: %',
    NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;

NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [84/225] MIGRAÇÃO: 20260930150000_hunter_admin_excluir_cliente.sql
-- ============================================================================

-- ============================================================================
-- HUNTER / GD RASTREAMENTO — RPC ADMIN_EXCLUIR_CLIENTE COM CASCADE COMPLETO
-- ============================================================================
-- Versão Alvo: 1.11.0.17
-- Permite que SuperADM e Administradores excluam clientes de forma segura e atômica,
-- removendo em cascata todos os vínculos dependentes (veículos, agendamentos, instalações,
-- motoristas, parcelas, proteções, histórico e usuário de autenticação correspondente),
-- respeitando a blindagem das contas SuperADM.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.admin_excluir_cliente(
  p_cliente_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_cliente_user_id UUID;
  v_cliente_nome TEXT;
  r_veic RECORD;
  r_mot RECORD;
BEGIN
  -- 1. Verificação de permissões do operador/administrador
  v_user_id := auth.uid();
  IF v_user_id IS NOT NULL THEN
    SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_user_id;
    IF v_role NOT IN ('superadmin', 'adm') THEN
      RAISE EXCEPTION 'Acesso negado: apenas SuperADM e Administradores podem excluir clientes.';
    END IF;
  END IF;

  -- 2. Busca dados do cliente
  SELECT nome_razao_social, user_id
  INTO v_cliente_nome, v_cliente_user_id
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado.';
  END IF;

  -- 3. Blindagem SuperADM: Proibido excluir contas protegidas
  IF v_cliente_user_id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM auth.users
      WHERE id = v_cliente_user_id
        AND LOWER(email) IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br')
    ) THEN
      RAISE EXCEPTION 'Ação não permitida: conta SuperADM é imutável e blindada contra exclusão.';
    END IF;
  END IF;

  -- 4. Exclui veículos do cliente usando a RPC de exclusão de veículo (que desvincula instalações e limpa telemetria)
  FOR r_veic IN SELECT id FROM public.veiculos WHERE cliente_id = p_cliente_id LOOP
    -- Limpa cooldowns de telemetria do veículo
    DELETE FROM public.alertas_telemetria_cooldown WHERE veiculo_id = r_veic.id;
    -- Desvincula e exclui veículo
    PERFORM public.admin_excluir_veiculo(r_veic.id);
  END LOOP;

  -- 5. Exclui agendamentos e desvincula instalações do cliente
  DELETE FROM public.agendamentos_instalacao WHERE cliente_id = p_cliente_id;
  UPDATE public.instalacoes SET cliente_id = NULL WHERE cliente_id = p_cliente_id;
  DELETE FROM public.instalacoes WHERE cliente_id = p_cliente_id;

  -- 6. Exclui motoristas vinculados e suas credenciais de acesso
  FOR r_mot IN SELECT id, user_id FROM public.motoristas WHERE cliente_id = p_cliente_id LOOP
    DELETE FROM public.motorista_veiculos WHERE motorista_id = r_mot.id;
    DELETE FROM public.motoristas WHERE id = r_mot.id;
    IF r_mot.user_id IS NOT NULL THEN
      DELETE FROM public.user_module_access WHERE user_id = r_mot.user_id;
      DELETE FROM public.profiles WHERE id = r_mot.user_id;
      DELETE FROM auth.users WHERE id = r_mot.user_id;
    END IF;
  END LOOP;

  -- 7. Limpa lançamentos do portal do motorista do cliente
  DELETE FROM public.motorista_abastecimentos WHERE cliente_id = p_cliente_id;
  DELETE FROM public.motorista_despesas WHERE cliente_id = p_cliente_id;

  -- 8. Limpa proteções e geofences do cliente
  DELETE FROM public.areas_seguras_geofence WHERE cliente_id = p_cliente_id;
  DELETE FROM public.horarios_utilizacao WHERE cliente_id = p_cliente_id;
  DELETE FROM public.recursos_protecao_veiculo WHERE cliente_id = p_cliente_id;

  -- 9. Limpa contratos, parcelas, financeiro e histórico
  DELETE FROM public.parcelas_contrato_cliente WHERE cliente_id = p_cliente_id;
  UPDATE public.transacoes_financeiras SET cliente_id = NULL WHERE cliente_id = p_cliente_id;
  DELETE FROM public.historico_cliente_eventos WHERE cliente_id = p_cliente_id;
  DELETE FROM public.compartilhamentos_veiculo WHERE cliente_id = p_cliente_id;
  DELETE FROM public.user_push_subscriptions WHERE cliente_id = p_cliente_id;

  -- 10. Limpa alertas e notificações
  DELETE FROM public.alertas_seguranca WHERE cliente_id = p_cliente_id;
  DELETE FROM public.notificacoes_sistema WHERE destinatario_cliente_id = p_cliente_id;

  -- 11. Exclui o registro do cliente
  DELETE FROM public.clientes WHERE id = p_cliente_id;

  -- 12. Se o cliente possuía usuário de acesso em auth.users, remove o perfil e o login
  IF v_cliente_user_id IS NOT NULL THEN
    DELETE FROM public.user_module_access WHERE user_id = v_cliente_user_id;
    DELETE FROM public.profiles WHERE id = v_cliente_user_id;
    DELETE FROM auth.users WHERE id = v_cliente_user_id;
  END IF;

  RETURN jsonb_build_object(
    'sucesso', true,
    'cliente_id', p_cliente_id,
    'cliente_nome', v_cliente_nome,
    'mensagem', format('Cliente %s e todos os seus vínculos foram excluídos com sucesso.', v_cliente_nome)
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_excluir_cliente(UUID) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';


