-- Retorna tipo_veiculo e created_at para alimentar o ícone 3D e contador progressivo
-- ============================================================================

CREATE OR REPLACE FUNCTION public.consultar_veiculo_por_token_publico(p_token TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_share RECORD;
  v_veiculo RECORD;
  v_lat DOUBLE PRECISION;
  v_lng DOUBLE PRECISION;
  v_rumo DOUBLE PRECISION;
  v_vel NUMERIC;
  v_ign BOOLEAN;
  v_status TEXT;
  v_ult_atualizacao TEXT;
BEGIN
  -- 1. Busca o compartilhamento ativo
  SELECT * INTO v_share
  FROM public.compartilhamentos_temporarios
  WHERE token = p_token
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Link de compartilhamento não localizado.');
  END IF;

  -- 2. Verifica revogação ou expiração
  IF v_share.revogado = TRUE THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Este compartilhamento foi revogado pelo proprietário.');
  END IF;

  IF v_share.expira_em IS NOT NULL AND v_share.expira_em < now() THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Este link de compartilhamento expirou.');
  END IF;

  -- 3. Busca dados do veículo
  SELECT * INTO v_veiculo
  FROM public.veiculos
  WHERE id = v_share.veiculo_id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Veículo não localizado.');
  END IF;

  IF v_share.stealth_ativo = TRUE THEN
    -- Posição congelada e camuflada (Modo Stealth)
    v_lat := COALESCE(v_share.stealth_latitude, v_veiculo.ultima_latitude);
    v_lng := COALESCE(v_share.stealth_longitude, v_veiculo.ultima_longitude);
    v_rumo := COALESCE(v_share.stealth_rumo, v_veiculo.rumo, 0);
    v_vel := 0;
    v_ign := FALSE;
    v_status := 'estacionado';
    v_ult_atualizacao := to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
  ELSE
    -- Posição em tempo real com conversão segura de timestamp para texto
    v_lat := v_veiculo.ultima_latitude;
    v_lng := v_veiculo.ultima_longitude;
    v_rumo := v_veiculo.rumo;
    v_vel := COALESCE(v_veiculo.velocidade_atual, 0);
    v_ign := COALESCE(v_veiculo.ignicao_status, FALSE);
    v_status := COALESCE(v_veiculo.status_operacional, 'estacionado');
    v_ult_atualizacao := to_char(COALESCE(v_veiculo.ultima_atualizacao, now()), 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
  END IF;

  RETURN jsonb_build_object(
    'sucesso', true,
    'veiculo', jsonb_build_object(
      'id', v_veiculo.id,
      'placa', v_veiculo.placa,
      'marca_modelo', v_veiculo.marca_modelo,
      'cor', v_veiculo.cor,
      'tipo_veiculo', COALESCE(v_veiculo.tipo_veiculo, 'carro'),
      'ignicao', v_ign,
      'velocidade', v_vel,
      'latitude', v_lat,
      'longitude', v_lng,
      'ultima_atualizacao', v_ult_atualizacao,
      'status_operacional', v_status,
      'rumo', v_rumo
    ),
    'expira_em', v_share.expira_em,
    'created_at', v_share.created_at
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.consultar_veiculo_por_token_publico(TEXT) TO anon, authenticated, service_role;
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [95/225] MIGRAÇÃO: 20261001115000_hunter_alertas_veiculo_realtime_e_persistente.sql
-- ============================================================================

-- ============================================================================
-- MIGRATION: Hunter - Persistência Realtime e Unificada de Alertas do Veículo
-- Garante que configurações de alertas e notificações sejam persistentes por veículo,
-- compartilhadas por todos os usuários autorizados e sincronizadas instantaneamente
-- entre todos os dispositivos via Supabase Realtime (Anti-Polling Total).
-- ============================================================================

-- 1. Adiciona coluna alertas_ativos em regras_veiculo caso não exista
ALTER TABLE public.regras_veiculo 
ADD COLUMN IF NOT EXISTS alertas_ativos JSONB NOT NULL 
DEFAULT '{"movimento_fora_horario":true,"ignicao_fora_horario":true,"saida_area":true,"entrada_area":false,"excesso_velocidade":true,"perda_comunicacao":true,"baixa_tensao":true,"desvio_rota":true,"guincho":true}'::jsonb;

-- 2. Habilita Realtime para as tabelas de proteção e regras
DO $$ BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.regras_veiculo;
EXCEPTION WHEN others THEN NULL; END $$;

DO $$ BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.horarios_utilizacao;
EXCEPTION WHEN others THEN NULL; END $$;

DO $$ BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.notificacoes_configuracoes;
EXCEPTION WHEN others THEN NULL; END $$;

-- 3. Atualiza o trigger de telemetria do servidor para respeitar estritamente as preferências configuradas
CREATE OR REPLACE FUNCTION public.trigger_avaliar_alertas_telemetria()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_cliente_user_id UUID;
  v_velocidade_limite NUMERIC := 110;
  v_alerta_mov_regras BOOLEAN := true;
  v_alerta_ign_regras BOOLEAN := true;
  v_alertas_ativos JSONB;
  v_horario_proibido BOOLEAN := false;
  v_hora_inicio_str TEXT;
  v_hora_fim_str TEXT;
  v_cooldown_ok BOOLEAN;
  v_titulo TEXT;
  v_mensagem TEXT;
  v_tipo TEXT;
  v_gravidade TEXT;
  COOLDOWN_INTERVAL CONSTANT INTERVAL := INTERVAL '5 minutes';
  v_dlat DOUBLE PRECISION;
  v_dlon DOUBLE PRECISION;
  v_a DOUBLE PRECISION;
  v_dist_metros DOUBLE PRECISION := 0;
BEGIN
  -- ── Ignora se não há cliente associado ao veículo ──
  IF NEW.cliente_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- ── Busca o user_id do cliente para endereçar o Push VAPID ──
  SELECT user_id INTO v_cliente_user_id
  FROM public.clientes
  WHERE id = NEW.cliente_id
  LIMIT 1;

  -- ── Busca parâmetros de regras e preferências ativas do veículo ──
  SELECT 
    COALESCE(limite_velocidade_geral, 110),
    COALESCE(alerta_movimento_nao_autorizado, true),
    COALESCE(alerta_ignicao_fora_horario, true),
    alertas_ativos
  INTO 
    v_velocidade_limite,
    v_alerta_mov_regras,
    v_alerta_ign_regras,
    v_alertas_ativos
  FROM public.regras_veiculo
  WHERE veiculo_id = NEW.id
  LIMIT 1;

  IF NOT FOUND THEN
    v_velocidade_limite := 110;
    v_alerta_mov_regras := true;
    v_alerta_ign_regras := true;
    v_alertas_ativos := '{"movimento_fora_horario":true,"ignicao_fora_horario":true,"saida_area":true,"entrada_area":false,"excesso_velocidade":true,"perda_comunicacao":true,"baixa_tensao":true,"desvio_rota":true,"guincho":true}'::jsonb;
  END IF;

  -- ── Cálculo geodésico de deslocamento Haversine em metros entre OLD e NEW ──
  IF OLD.ultima_latitude IS NOT NULL 
     AND OLD.ultima_longitude IS NOT NULL 
     AND NEW.ultima_latitude IS NOT NULL 
     AND NEW.ultima_longitude IS NOT NULL
     AND (OLD.ultima_latitude <> 0 OR OLD.ultima_longitude <> 0)
     AND (NEW.ultima_latitude <> 0 OR NEW.ultima_longitude <> 0)
     AND (OLD.ultima_latitude <> NEW.ultima_latitude OR OLD.ultima_longitude <> NEW.ultima_longitude) THEN
    
    v_dlat := radians(NEW.ultima_latitude - OLD.ultima_latitude);
    v_dlon := radians(NEW.ultima_longitude - OLD.ultima_longitude);
    v_a := sin(v_dlat / 2.0)^2 + cos(radians(OLD.ultima_latitude)) * cos(radians(NEW.ultima_latitude)) * sin(v_dlon / 2.0)^2;
    v_dist_metros := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(GREATEST(0.0, 1.0 - v_a)));
  ELSE
    v_dist_metros := 0;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA A: EXCESSO DE VELOCIDADE
  -- Respeita regras_veiculo.alertas_ativos->>'excesso_velocidade'
  -- ─────────────────────────────────────────────────────────────────────────
  IF COALESCE(NEW.velocidade_atual, 0) > 0 
     AND COALESCE((v_alertas_ativos->>'excesso_velocidade')::BOOLEAN, true) = true THEN

    IF NEW.velocidade_atual > v_velocidade_limite THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'excesso_velocidade'
            AND ultimo_at > (now() - COOLDOWN_INTERVAL)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo    := format('Excesso de Velocidade — %s', COALESCE(NEW.placa, ''));
        v_mensagem  := format(
          'Veículo %s atingiu %s km/h, ultrapassando o limite configurado de %s km/h.',
          COALESCE(NEW.placa, ''),
          ROUND(NEW.velocidade_atual),
          ROUND(v_velocidade_limite)
        );
        v_tipo      := 'excesso_velocidade';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA B: IGNIÇÃO FORA DO HORÁRIO CONFIGURADO
  -- Respeita regras_veiculo.alerta_ignicao_fora_horario e alertas_ativos->>'ignicao_fora_horario'
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = true 
     AND v_alerta_ign_regras = true
     AND COALESCE((v_alertas_ativos->>'ignicao_fora_horario')::BOOLEAN, true) = true THEN

    v_horario_proibido := public.hunter_horario_proibido(NEW.id);

    IF v_horario_proibido THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'ignicao_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_INTERVAL)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        SELECT
          hora_inicio::TEXT,
          hora_fim::TEXT
        INTO v_hora_inicio_str, v_hora_fim_str
        FROM public.horarios_utilizacao
        WHERE veiculo_id = NEW.id AND ativo = true
        LIMIT 1;

        v_titulo   := format('Ignição Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Motor acionado fora do horário habitual configurado (%s às %s). Veículo: %s.',
          COALESCE(v_hora_inicio_str, ''), COALESCE(v_hora_fim_str, ''),
          COALESCE(NEW.placa, '')
        );
        v_tipo      := 'ignicao_fora_horario';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA C: MOVIMENTO FORA DO HORÁRIO (ignição LIGADA + velocidade > 0)
  -- Respeita regras_veiculo.alerta_movimento_nao_autorizado e alertas_ativos->>'movimento_fora_horario'
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = true 
     AND COALESCE(NEW.velocidade_atual, 0) > 0 
     AND v_alerta_mov_regras = true
     AND COALESCE((v_alertas_ativos->>'movimento_fora_horario')::BOOLEAN, true) = true THEN

    v_horario_proibido := public.hunter_horario_proibido(NEW.id);

    IF v_horario_proibido THEN
      SELECT (
        NOT EXISTS (
          SELECT 1 FROM public.alertas_telemetria_cooldown
          WHERE veiculo_id = NEW.id
            AND tipo_alerta = 'movimento_fora_horario'
            AND ultimo_at > (now() - COOLDOWN_INTERVAL)
        )
      ) INTO v_cooldown_ok;

      IF v_cooldown_ok THEN
        v_titulo   := format('Deslocamento Fora do Horário — %s', COALESCE(NEW.placa, ''));
        v_mensagem := format(
          'Veículo %s em deslocamento (%s km/h) fora da janela habitual configurada.',
          COALESCE(NEW.placa, ''),
          ROUND(NEW.velocidade_atual)
        );
        v_tipo      := 'movimento_fora_horario';
        v_gravidade := 'alta';

        INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
        VALUES (NEW.id, v_tipo, now())
        ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

        INSERT INTO public.alertas_seguranca (
          veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
          velocidade, detalhes, reconhecido, created_at
        ) VALUES (
          NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
          COALESCE(NEW.ultima_latitude, 0),
          COALESCE(NEW.ultima_longitude, 0),
          COALESCE(NEW.velocidade_atual::INT, 0),
          v_mensagem, false, now()
        );

        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id, destinatario_cliente_id,
          titulo, mensagem, tipo, url, placa, lida, created_at
        ) VALUES (
          v_cliente_user_id, NEW.cliente_id,
          v_titulo, v_mensagem, v_tipo, '/monitor-gps',
          COALESCE(NEW.placa, ''), false, now()
        );
      END IF;
    END IF;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- ALERTA D: GUINCHO / FURTO / REBOQUE NÃO AUTORIZADO
  -- Respeita regras_veiculo.alertas_ativos->>'guincho'
  -- ─────────────────────────────────────────────────────────────────────────
  IF NEW.ignicao_status = false
     AND COALESCE(OLD.ignicao_status, false) = false
     AND (
       COALESCE(NEW.velocidade_atual, 0) >= 15
       OR (COALESCE(NEW.velocidade_atual, 0) >= 10 AND v_dist_metros >= 35.0)
     )
     AND COALESCE((v_alertas_ativos->>'guincho')::BOOLEAN, true) = true THEN

    SELECT (
      NOT EXISTS (
        SELECT 1 FROM public.alertas_telemetria_cooldown
        WHERE veiculo_id = NEW.id
          AND tipo_alerta = 'guincho'
          AND ultimo_at > (now() - COOLDOWN_INTERVAL)
      )
    ) INTO v_cooldown_ok;

    IF v_cooldown_ok THEN
      v_titulo   := format('🚨 Veículo em Movimento com Motor Desligado — %s', COALESCE(NEW.placa, ''));
      v_mensagem := format(
        'Veículo %s detectado a %s km/h com ignição desligada. Possível reboque ou furto em andamento.',
        COALESCE(NEW.placa, ''),
        ROUND(NEW.velocidade_atual)
      );
      v_tipo      := 'guincho';
      v_gravidade := 'critica';

      INSERT INTO public.alertas_telemetria_cooldown(veiculo_id, tipo_alerta, ultimo_at)
      VALUES (NEW.id, v_tipo, now())
      ON CONFLICT (veiculo_id, tipo_alerta) DO UPDATE SET ultimo_at = now();

      INSERT INTO public.alertas_seguranca (
        veiculo_id, cliente_id, tipo, gravidade, latitude, longitude,
        velocidade, detalhes, reconhecido, created_at
      ) VALUES (
        NEW.id, NEW.cliente_id, v_tipo, v_gravidade,
        COALESCE(NEW.ultima_latitude, 0),
        COALESCE(NEW.ultima_longitude, 0),
        COALESCE(NEW.velocidade_atual::INT, 0),
        v_mensagem, false, now()
      );

      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id, destinatario_cliente_id,
        titulo, mensagem, tipo, url, placa, lida, created_at
      ) VALUES (
        v_cliente_user_id, NEW.cliente_id,
        v_titulo, v_mensagem, v_tipo, '/monitor-gps',
        COALESCE(NEW.placa, ''), false, now()
      );
    END IF;
  END IF;

  RETURN NEW;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[HUNTER-ALERTAS-TELEMETRIA] Erro ao avaliar alertas para veículo %: %',
    NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;

NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [96/225] MIGRAÇÃO: 20261001142500_hunter_compartilhamento_acessos_e_trajeto.sql
-- ============================================================================

-- ============================================================================
-- MIGRATION: Hunter - Rastreamento e Auditoria de Acessos a Links de Compartilhamento
-- Registra IP, data, hora, tempo de acesso, local de início, local de término,
-- histórico do trajeto percorrido e auditoria de período com Modo Stealth ativado.
-- ============================================================================
-- Protocolo: DJR-NEW e HUNTER-GUARDIAN
-- ============================================================================

-- 1. Colunas de auditoria de Modo Stealth em public.compartilhamentos_temporarios
ALTER TABLE public.compartilhamentos_temporarios
  ADD COLUMN IF NOT EXISTS stealth_ativo BOOLEAN NOT NULL DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS stealth_latitude NUMERIC,
  ADD COLUMN IF NOT EXISTS stealth_longitude NUMERIC,
  ADD COLUMN IF NOT EXISTS stealth_rumo NUMERIC,
  ADD COLUMN IF NOT EXISTS stealth_ativado_em TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS stealth_desativado_em TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS stealth_periodos JSONB NOT NULL DEFAULT '[]'::jsonb;

-- 2. Atualização canônica de alternar_stealth_compartilhamento com gravação de períodos
CREATE OR REPLACE FUNCTION public.alternar_stealth_compartilhamento(
  p_token TEXT,
  p_ativo BOOLEAN
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_share RECORD;
  v_veiculo RECORD;
  v_periodos JSONB;
BEGIN
  SELECT id, veiculo_id, revogado, expira_em, stealth_ativo, stealth_ativado_em, stealth_periodos
  INTO v_share
  FROM public.compartilhamentos_temporarios
  WHERE token = p_token;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Link de compartilhamento não localizado.');
  END IF;

  IF v_share.revogado THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Este link foi revogado.');
  END IF;

  IF v_share.expira_em IS NOT NULL AND v_share.expira_em < now() THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Este link expirou.');
  END IF;

  IF p_ativo THEN
    -- Busca posição atual do veículo para congelar
    SELECT ultima_latitude, ultima_longitude, rumo
    INTO v_veiculo
    FROM public.veiculos
    WHERE id = v_share.veiculo_id;

    UPDATE public.compartilhamentos_temporarios
    SET
      stealth_ativo = TRUE,
      stealth_latitude = v_veiculo.ultima_latitude,
      stealth_longitude = v_veiculo.ultima_longitude,
      stealth_rumo = v_veiculo.rumo,
      stealth_ativado_em = now()
    WHERE token = p_token;

    RETURN jsonb_build_object(
      'sucesso', true,
      'stealth_ativo', true,
      'stealth_ativado_em', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'mensagem', 'Modo Stealth ativado: posição congelada com sucesso.'
    );
  ELSE
    -- Desativação: adiciona período completo ao histórico
    v_periodos := COALESCE(v_share.stealth_periodos, '[]'::jsonb);
    IF v_share.stealth_ativado_em IS NOT NULL THEN
      v_periodos := v_periodos || jsonb_build_array(
        jsonb_build_object(
          'ativado_em', to_char(v_share.stealth_ativado_em, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
          'desativado_em', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
          'duracao_segundos', GREATEST(0, EXTRACT(EPOCH FROM (now() - v_share.stealth_ativado_em))::INTEGER)
        )
      );
    END IF;

    UPDATE public.compartilhamentos_temporarios
    SET
      stealth_ativo = FALSE,
      stealth_desativado_em = now(),
      stealth_periodos = v_periodos
    WHERE token = p_token;

    RETURN jsonb_build_object(
      'sucesso', true,
      'stealth_ativo', false,
      'stealth_desativado_em', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'mensagem', 'Modo Stealth desativado: tempo real restabelecido.'
    );
  END IF;
END;
$$;
GRANT EXECUTE ON FUNCTION public.alternar_stealth_compartilhamento(TEXT, BOOLEAN) TO authenticated, anon, service_role;

-- 3. Criação da tabela de acessos aos compartilhamentos com rastreamento de Stealth
CREATE TABLE IF NOT EXISTS public.compartilhamentos_acessos (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  compartilhamento_id UUID REFERENCES public.compartilhamentos_temporarios(id) ON DELETE CASCADE,
  token TEXT NOT NULL,
  veiculo_id UUID REFERENCES public.veiculos(id) ON DELETE CASCADE NOT NULL,
  ip TEXT,
  user_agent TEXT,
  iniciado_em TIMESTAMPTZ NOT NULL DEFAULT now(),
  ultimo_ping_em TIMESTAMPTZ NOT NULL DEFAULT now(),
  finalizado_em TIMESTAMPTZ,
  duracao_segundos INTEGER NOT NULL DEFAULT 0,
  inicio_latitude DOUBLE PRECISION,
  inicio_longitude DOUBLE PRECISION,
  inicio_endereco TEXT,
  fim_latitude DOUBLE PRECISION,
  fim_longitude DOUBLE PRECISION,
  fim_endereco TEXT,
  distancia_percorrida_km NUMERIC(8,2) NOT NULL DEFAULT 0,
  velocidade_maxima INTEGER NOT NULL DEFAULT 0,
  stealth_observado BOOLEAN NOT NULL DEFAULT FALSE,
  stealth_inicio_em TIMESTAMPTZ,
  stealth_fim_em TIMESTAMPTZ,
  stealth_duracao_segundos INTEGER NOT NULL DEFAULT 0,
  stealth_periodos JSONB NOT NULL DEFAULT '[]'::jsonb,
  trajeto JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Garante existência das colunas se tabela já foi criada anteriormente
ALTER TABLE public.compartilhamentos_acessos
  ADD COLUMN IF NOT EXISTS stealth_observado BOOLEAN NOT NULL DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS stealth_inicio_em TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS stealth_fim_em TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS stealth_duracao_segundos INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS stealth_periodos JSONB NOT NULL DEFAULT '[]'::jsonb;

-- 4. Índices de alta performance
CREATE INDEX IF NOT EXISTS idx_comp_acessos_token ON public.compartilhamentos_acessos(token);
CREATE INDEX IF NOT EXISTS idx_comp_acessos_compartilhamento_id ON public.compartilhamentos_acessos(compartilhamento_id);
CREATE INDEX IF NOT EXISTS idx_comp_acessos_veiculo_id ON public.compartilhamentos_acessos(veiculo_id);
CREATE INDEX IF NOT EXISTS idx_comp_acessos_iniciado_em ON public.compartilhamentos_acessos(iniciado_em DESC);

-- 5. Habilita RLS Estrito
ALTER TABLE public.compartilhamentos_acessos ENABLE ROW LEVEL SECURITY;

-- 6. Políticas de RLS
DROP POLICY IF EXISTS "Acesso seguro leitura compartilhamentos_acessos" ON public.compartilhamentos_acessos;
CREATE POLICY "Acesso seguro leitura compartilhamentos_acessos"
ON public.compartilhamentos_acessos FOR SELECT TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM public.veiculos v
    WHERE v.id = compartilhamentos_acessos.veiculo_id
      AND public.check_acesso_cliente_veiculo(v.cliente_id)
  ) OR EXISTS (
    SELECT 1 FROM public.compartilhamentos_temporarios ct
    WHERE ct.id = compartilhamentos_acessos.compartilhamento_id
      AND public.check_acesso_cliente_veiculo(ct.cliente_id)
  )
);

DROP POLICY IF EXISTS "Service role gerencia compartilhamentos_acessos" ON public.compartilhamentos_acessos;
CREATE POLICY "Service role gerencia compartilhamentos_acessos"
ON public.compartilhamentos_acessos FOR ALL TO service_role
USING (true)
WITH CHECK (true);

-- 7. RPC Pública Segura para Registrar Início de Acesso ao Link
CREATE OR REPLACE FUNCTION public.registrar_acesso_link_publico(
  p_token TEXT,
  p_ip TEXT DEFAULT NULL,
  p_user_agent TEXT DEFAULT NULL,
  p_endereco_inicio TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_share RECORD;
  v_veiculo RECORD;
  v_lat DOUBLE PRECISION;
  v_lng DOUBLE PRECISION;
  v_vel INTEGER;
  v_ign BOOLEAN;
  v_acesso_id UUID;
  v_trajeto JSONB;
  v_is_stealth BOOLEAN;
  v_stealth_inicio TIMESTAMPTZ;
  v_stealth_fim TIMESTAMPTZ;
BEGIN
  -- 1. Valida o link de compartilhamento
  SELECT * INTO v_share
  FROM public.compartilhamentos_temporarios
  WHERE token = p_token
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Link não localizado.');
  END IF;

  IF v_share.revogado = TRUE THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Link revogado.');
  END IF;

  IF v_share.expira_em IS NOT NULL AND v_share.expira_em < now() THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Link expirado.');
  END IF;

  -- 2. Busca veículo
  SELECT * INTO v_veiculo
  FROM public.veiculos
  WHERE id = v_share.veiculo_id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Veículo não localizado.');
  END IF;

  -- 3. Resolve posição inicial e estado de Stealth
  v_is_stealth := (v_share.stealth_ativo = TRUE);
  IF v_is_stealth THEN
    v_lat := COALESCE(v_share.stealth_latitude, v_veiculo.ultima_latitude);
    v_lng := COALESCE(v_share.stealth_longitude, v_veiculo.ultima_longitude);
    v_vel := 0;
    v_ign := false;
    v_stealth_inicio := now();
    v_stealth_fim := now();
  ELSE
    v_lat := v_veiculo.ultima_latitude;
    v_lng := v_veiculo.ultima_longitude;
    v_vel := COALESCE(v_veiculo.velocidade_atual, 0);
    v_ign := COALESCE(v_veiculo.ignicao_status, false);
    v_stealth_inicio := NULL;
    v_stealth_fim := NULL;
  END IF;

  -- Trajeto inicial com o ponto de abertura
  IF v_lat IS NOT NULL AND v_lng IS NOT NULL THEN
    v_trajeto := jsonb_build_array(
      jsonb_build_object(
        'lat', v_lat,
        'lng', v_lng,
        't', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'vel', v_vel,
        'ign', v_ign,
        'stealth', v_is_stealth
      )
    );
  ELSE
    v_trajeto := '[]'::jsonb;
  END IF;

  -- 4. Cria o registro de acesso
  INSERT INTO public.compartilhamentos_acessos (
    compartilhamento_id,
    token,
    veiculo_id,
    ip,
    user_agent,
    iniciado_em,
    ultimo_ping_em,
    inicio_latitude,
    inicio_longitude,
    inicio_endereco,
    fim_latitude,
    fim_longitude,
    fim_endereco,
    distancia_percorrida_km,
    velocidade_maxima,
    stealth_observado,
    stealth_inicio_em,
    stealth_fim_em,
    stealth_duracao_segundos,
    trajeto
  ) VALUES (
    v_share.id,
    p_token,
    v_share.veiculo_id,
    COALESCE(p_ip, 'Desconhecido'),
    p_user_agent,
    now(),
    now(),
    v_lat,
    v_lng,
    p_endereco_inicio,
    v_lat,
    v_lng,
    p_endereco_inicio,
    0,
    v_vel,
    v_is_stealth,
    v_stealth_inicio,
    v_stealth_fim,
    0,
    v_trajeto
  ) RETURNING id INTO v_acesso_id;

  RETURN jsonb_build_object(
    'sucesso', true,
    'acesso_id', v_acesso_id,
    'inicio_latitude', v_lat,
    'inicio_longitude', v_lng,
    'stealth_observado', v_is_stealth
  );
END;
$$;

-- 8. RPC Pública Segura para Ping / Heartbeat e Acúmulo de Trajeto e Período Stealth
CREATE OR REPLACE FUNCTION public.ping_acesso_link_publico(
  p_acesso_id UUID,
  p_token TEXT,
  p_endereco_atual TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_acesso RECORD;
  v_share RECORD;
  v_veiculo RECORD;
  v_lat DOUBLE PRECISION;
  v_lng DOUBLE PRECISION;
  v_vel INTEGER;
  v_ign BOOLEAN;
  v_duracao INTEGER;
  v_trajeto JSONB;
  v_ultimo_ponto JSONB;
  v_ultimo_lat DOUBLE PRECISION;
  v_ultimo_lng DOUBLE PRECISION;
  v_dist_km NUMERIC;
  v_novo_trajeto JSONB;
  v_vel_max INTEGER;
  v_is_stealth BOOLEAN;
  v_stealth_observado BOOLEAN;
  v_stealth_inicio TIMESTAMPTZ;
  v_stealth_fim TIMESTAMPTZ;
  v_stealth_duracao INTEGER;
  v_delta_segundos INTEGER;
BEGIN
  -- 1. Busca o acesso existente
  SELECT * INTO v_acesso
  FROM public.compartilhamentos_acessos
  WHERE id = p_acesso_id AND token = p_token
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Sessão de acesso não localizada.');
  END IF;

  -- 2. Busca compartilhamento
  SELECT * INTO v_share
  FROM public.compartilhamentos_temporarios
  WHERE id = v_acesso.compartilhamento_id
  LIMIT 1;

  -- 3. Busca veículo
  SELECT * INTO v_veiculo
  FROM public.veiculos
  WHERE id = v_acesso.veiculo_id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Veículo não localizado.');
  END IF;

  v_is_stealth := (v_share.stealth_ativo = TRUE);

  -- Se stealth ativo, mantém posição congelada
  IF v_is_stealth THEN
    v_lat := COALESCE(v_share.stealth_latitude, v_veiculo.ultima_latitude);
    v_lng := COALESCE(v_share.stealth_longitude, v_veiculo.ultima_longitude);
    v_vel := 0;
    v_ign := false;
  ELSE
    v_lat := v_veiculo.ultima_latitude;
    v_lng := v_veiculo.ultima_longitude;
    v_vel := COALESCE(v_veiculo.velocidade_atual, 0);
    v_ign := COALESCE(v_veiculo.ignicao_status, false);
  END IF;

  -- 4. Cálculo de tempo e período Stealth
  v_duracao := GREATEST(0, EXTRACT(EPOCH FROM (now() - v_acesso.iniciado_em))::INTEGER);
  v_delta_segundos := GREATEST(1, EXTRACT(EPOCH FROM (now() - v_acesso.ultimo_ping_em))::INTEGER);

  v_stealth_observado := COALESCE(v_acesso.stealth_observado, false);
  v_stealth_inicio := v_acesso.stealth_inicio_em;
  v_stealth_fim := v_acesso.stealth_fim_em;
  v_stealth_duracao := COALESCE(v_acesso.stealth_duracao_segundos, 0);

  IF v_is_stealth THEN
    v_stealth_observado := TRUE;
    IF v_stealth_inicio IS NULL THEN
      v_stealth_inicio := now();
    END IF;
    v_stealth_fim := now();
    v_stealth_duracao := v_stealth_duracao + v_delta_segundos;
  END IF;

  v_trajeto := COALESCE(v_acesso.trajeto, '[]'::jsonb);
  v_novo_trajeto := v_trajeto;
  v_dist_km := COALESCE(v_acesso.distancia_percorrida_km, 0);
  v_vel_max := GREATEST(COALESCE(v_acesso.velocidade_maxima, 0), v_vel);

  -- 5. Adiciona novo ponto ao trajeto se houver deslocamento significativo
  IF v_lat IS NOT NULL AND v_lng IS NOT NULL THEN
    IF jsonb_array_length(v_trajeto) > 0 THEN
      v_ultimo_ponto := v_trajeto->(jsonb_array_length(v_trajeto) - 1);
      v_ultimo_lat := (v_ultimo_ponto->>'lat')::DOUBLE PRECISION;
      v_ultimo_lng := (v_ultimo_ponto->>'lng')::DOUBLE PRECISION;

      -- Verifica se houve mudança significativa de posição (> 0.00008 grau ~ 8 metros) ou alteração de estado stealth
      IF ABS(v_lat - v_ultimo_lat) > 0.00008 OR ABS(v_lng - v_ultimo_lng) > 0.00008 THEN
        v_novo_trajeto := v_trajeto || jsonb_build_object(
          'lat', v_lat,
          'lng', v_lng,
          't', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
          'vel', v_vel,
          'ign', v_ign,
          'stealth', v_is_stealth
        );
        -- Estimativa haversine do trecho em km
        v_dist_km := v_dist_km + ROUND((111.0 * SQRT(POW(v_lat - v_ultimo_lat, 2) + POW((v_lng - v_ultimo_lng) * COS(RADIANS(v_lat)), 2)))::NUMERIC, 2);
      END IF;
    ELSE
      v_novo_trajeto := jsonb_build_array(
        jsonb_build_object(
          'lat', v_lat,
          'lng', v_lng,
          't', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
          'vel', v_vel,
          'ign', v_ign,
          'stealth', v_is_stealth
        )
      );
    END IF;
  END IF;

  -- 6. Atualiza sessão de acesso
  UPDATE public.compartilhamentos_acessos
  SET
    ultimo_ping_em = now(),
    duracao_segundos = v_duracao,
    fim_latitude = v_lat,
    fim_longitude = v_lng,
    fim_endereco = COALESCE(p_endereco_atual, fim_endereco),
    distancia_percorrida_km = v_dist_km,
    velocidade_maxima = v_vel_max,
    stealth_observado = v_stealth_observado,
    stealth_inicio_em = v_stealth_inicio,
    stealth_fim_em = v_stealth_fim,
    stealth_duracao_segundos = v_stealth_duracao,
    trajeto = v_novo_trajeto,
    updated_at = now()
  WHERE id = p_acesso_id;

  RETURN jsonb_build_object(
    'sucesso', true,
    'duracao_segundos', v_duracao,
    'pontos_trajeto', jsonb_array_length(v_novo_trajeto),
    'stealth_observado', v_stealth_observado,
    'stealth_duracao_segundos', v_stealth_duracao
  );
END;
$$;

-- 9. RPC Pública Segura para Finalizar Acesso ao Link
CREATE OR REPLACE FUNCTION public.finalizar_acesso_link_publico(
  p_acesso_id UUID,
  p_token TEXT,
  p_endereco_fim TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_acesso RECORD;
  v_share RECORD;
  v_duracao INTEGER;
  v_stealth_fim TIMESTAMPTZ;
BEGIN
  SELECT * INTO v_acesso
  FROM public.compartilhamentos_acessos
  WHERE id = p_acesso_id AND token = p_token
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'mensagem', 'Sessão de acesso não localizada.');
  END IF;

  SELECT * INTO v_share
  FROM public.compartilhamentos_temporarios
  WHERE id = v_acesso.compartilhamento_id
  LIMIT 1;

  v_duracao := GREATEST(0, EXTRACT(EPOCH FROM (now() - v_acesso.iniciado_em))::INTEGER);

  IF v_share.stealth_ativo = TRUE THEN
    v_stealth_fim := now();
  ELSE
    v_stealth_fim := v_acesso.stealth_fim_em;
  END IF;

  UPDATE public.compartilhamentos_acessos
  SET
    finalizado_em = now(),
    ultimo_ping_em = now(),
    duracao_segundos = v_duracao,
    fim_endereco = COALESCE(p_endereco_fim, fim_endereco),
    stealth_fim_em = COALESCE(v_stealth_fim, stealth_fim_em),
    updated_at = now()
  WHERE id = p_acesso_id;

  RETURN jsonb_build_object('sucesso', true, 'duracao_segundos', v_duracao);
END;
$$;

-- 10. Concessão de permissões GRANT
GRANT EXECUTE ON FUNCTION public.registrar_acesso_link_publico(TEXT, TEXT, TEXT, TEXT) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.ping_acesso_link_publico(UUID, TEXT, TEXT) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.finalizar_acesso_link_publico(UUID, TEXT, TEXT) TO anon, authenticated, service_role;

-- 11. Realtime para a tabela de acessos
DO $$ BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.compartilhamentos_acessos;
EXCEPTION WHEN others THEN NULL; END $$;

NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [97/225] MIGRAÇÃO: 20261001190000_hunter_fix_linter_rls_cooldown_e_view_cnh.sql
-- ============================================================================

-- ==============================================================================
-- HUNTER — CORREÇÃO DE LINTER: RLS EM COOLDOWN E SECURITY INVOKER EM VIEW CNH
-- Data: 01/10/2026
-- Objetivo:
-- 1. Habilitar RLS estrito em public.alertas_telemetria_cooldown com policy por cliente
-- 2. Recriar public.alertas_cnh_motoristas com security_invoker = true para respeitar RLS
-- Zero downtime e zero interrupção operacional
-- ==============================================================================

-- 1. Habilitar RLS em public.alertas_telemetria_cooldown
ALTER TABLE public.alertas_telemetria_cooldown ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Clientes acessam cooldown de seus proprios veiculos" ON public.alertas_telemetria_cooldown;
CREATE POLICY "Clientes acessam cooldown de seus proprios veiculos"
  ON public.alertas_telemetria_cooldown FOR ALL TO authenticated
  USING (
    veiculo_id IN (
      SELECT id FROM public.veiculos
      WHERE cliente_id IN (SELECT cliente_id FROM public.profiles WHERE id = auth.uid())
         OR (SELECT role::text FROM public.profiles WHERE id = auth.uid()) IN ('adm', 'superadmin')
    )
  )
  WITH CHECK (
    veiculo_id IN (
      SELECT id FROM public.veiculos
      WHERE cliente_id IN (SELECT cliente_id FROM public.profiles WHERE id = auth.uid())
         OR (SELECT role::text FROM public.profiles WHERE id = auth.uid()) IN ('adm', 'superadmin')
    )
  );

-- 2. Atualizar View public.alertas_cnh_motoristas com WITH (security_invoker = true)
CREATE OR REPLACE VIEW public.alertas_cnh_motoristas
WITH (security_invoker = true) AS
SELECT
  m.id              AS motorista_id,
  m.cliente_id,
  m.nome,
  m.email,
  m.cnh_numero,
  m.cnh_categoria,
  m.cnh_validade,
  CASE
    WHEN m.cnh_validade IS NULL       THEN 'sem_data'
    WHEN m.cnh_validade < CURRENT_DATE THEN 'vencida'
    WHEN m.cnh_validade <= CURRENT_DATE + INTERVAL '30 days' THEN 'a_vencer'
    ELSE 'ok'
  END AS status_cnh,
  (m.cnh_validade - CURRENT_DATE) AS dias_para_vencer
FROM public.motoristas m
WHERE m.ativo = TRUE;

GRANT SELECT ON public.alertas_cnh_motoristas TO authenticated;

-- Notificar PostgREST para recarregar o schema
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [98/225] MIGRAÇÃO: 20261002120000_hunter_alerta_bateria_notificacao_e_coords_fix.sql
-- ============================================================================

-- ============================================================================
-- MIGRATION: 20261002120000_hunter_alerta_bateria_notificacao_e_coords_fix.sql
-- Descrição:
-- 1. Corrige o fallback de coordenadas (Zero Null Island) na RPC registrar_alerta_seguranca:
--    se latitude/longitude forem 0 ou nulas, herda automaticamente a última localização
--    real e válida registrada do veículo na tabela veiculos.
-- 2. Respeita estritamente as preferências configuradas pelo cliente em regras_veiculo.alertas_ativos
--    (suporte a "bateria_desconectada" e "baixa_tensao").
-- 3. Entrega automática ao cliente: ao registrar alerta crítico (como corte/desconexão de bateria),
--    grava imediatamente em notificacoes_sistema, acionando o Supabase Realtime e o trigger
--    pg_net para envio imediato de Web Push VAPID para os dispositivos do cliente.
-- ============================================================================

-- 1. Garante que o valor padrão de alertas_ativos em regras_veiculo suporte bateria_desconectada
ALTER TABLE public.regras_veiculo 
ALTER COLUMN alertas_ativos SET DEFAULT '{"movimento_fora_horario":true,"ignicao_fora_horario":true,"saida_area":true,"entrada_area":false,"excesso_velocidade":true,"perda_comunicacao":true,"baixa_tensao":true,"bateria_desconectada":true,"desvio_rota":true,"guincho":true}'::jsonb;

-- 2. Atualiza a RPC atômica registrar_alerta_seguranca
CREATE OR REPLACE FUNCTION public.registrar_alerta_seguranca(
  p_veiculo_id UUID,
  p_tipo TEXT,
  p_detalhes TEXT,
  p_gravidade TEXT DEFAULT 'alta',
  p_latitude DOUBLE PRECISION DEFAULT 0.0,
  p_longitude DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade INT DEFAULT 0,
  p_vibracao_g NUMERIC DEFAULT 0.0,
  p_inclinacao_graus INT DEFAULT 0,
  p_cliente_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_cliente_id UUID;
  v_cliente_user_id UUID;
  v_placa TEXT;
  v_ult_lat DOUBLE PRECISION;
  v_ult_lon DOUBLE PRECISION;
  v_ult_vel NUMERIC;
  v_alertas_ativos JSONB;
  v_alerta_existente_id UUID;
  v_novo_alerta_id UUID;
  v_titulo_evento TEXT;
  v_severidade_evento TEXT;
BEGIN
  -- 1. Determina dados do veículo caso não passados
  SELECT 
    cliente_id, 
    placa, 
    ultima_latitude, 
    ultima_longitude, 
    velocidade_atual
  INTO 
    v_cliente_id, 
    v_placa, 
    v_ult_lat, 
    v_ult_lon, 
    v_ult_vel
  FROM public.veiculos
  WHERE id = p_veiculo_id;

  IF v_cliente_id IS NULL AND p_cliente_id IS NOT NULL THEN
    v_cliente_id := p_cliente_id;
  END IF;

  IF v_cliente_id IS NULL THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo ou cliente não localizado no sistema.');
  END IF;

  -- 2. Busca user_id do cliente proprietário para direcionamento da notificação push e in-app
  SELECT user_id INTO v_cliente_user_id
  FROM public.clientes
  WHERE id = v_cliente_id
  LIMIT 1;

  -- 3. Resolução e Fallback de Coordenadas (Zero Null Island):
  -- Se o hardware enviou 0, 0 ou nulo (como ocorre em pacotes de status/heartbeat de corte de bateria),
  -- utiliza a última posição física válida já confirmada do veículo
  IF (p_latitude IS NULL OR p_longitude IS NULL OR (p_latitude = 0.0 AND p_longitude = 0.0)) THEN
    IF v_ult_lat IS NOT NULL AND v_ult_lon IS NOT NULL AND (v_ult_lat <> 0.0 OR v_ult_lon <> 0.0) THEN
      p_latitude := v_ult_lat;
      p_longitude := v_ult_lon;
      IF (p_velocidade IS NULL OR p_velocidade = 0) AND v_ult_vel IS NOT NULL THEN
        p_velocidade := ROUND(v_ult_vel)::INT;
      END IF;
    END IF;
  END IF;

  -- 4. Validação estrita das preferências do veículo (regras_veiculo.alertas_ativos):
  -- Permite ao cliente escolher ativar ou desativar cada tipo de notificação
  SELECT alertas_ativos INTO v_alertas_ativos
  FROM public.regras_veiculo
  WHERE veiculo_id = p_veiculo_id
  LIMIT 1;

  IF p_tipo = 'bateria_desconectada' THEN
    IF v_alertas_ativos IS NOT NULL AND COALESCE(
      (v_alertas_ativos->>'bateria_desconectada')::BOOLEAN,
      (v_alertas_ativos->>'baixa_tensao')::BOOLEAN,
      true
    ) = false THEN
      RETURN jsonb_build_object(
        'sucesso', true, 
        'ignorado_por_preferencia', true,
        'mensagem', 'Notificação de desconexão da bateria desativada pelo cliente nas configurações de proteção do veículo.'
      );
    END IF;
  ELSIF p_tipo = 'baixa_tensao' THEN
    IF v_alertas_ativos IS NOT NULL AND COALESCE(
      (v_alertas_ativos->>'baixa_tensao')::BOOLEAN,
      true
    ) = false THEN
      RETURN jsonb_build_object(
        'sucesso', true, 
        'ignorado_por_preferencia', true,
        'mensagem', 'Notificação de baixa tensão desativada pelo cliente nas configurações do veículo.'
      );
    END IF;
  END IF;

  -- 5. Debouncing / Anti-Flood: Evita poluir a central e dispositivos se houver alerta não reconhecido do mesmo tipo nos últimos 3 minutos
  SELECT id INTO v_alerta_existente_id
  FROM public.alertas_seguranca
  WHERE veiculo_id = p_veiculo_id
    AND tipo = p_tipo
    AND reconhecido = FALSE
    AND created_at >= NOW() - INTERVAL '3 minutes'
  LIMIT 1;

  IF v_alerta_existente_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'sucesso', true,
      'alerta_id', v_alerta_existente_id,
      'duplicado', true
    );
  END IF;

  -- 6. Insere na tabela oficial alertas_seguranca
  INSERT INTO public.alertas_seguranca (
    veiculo_id,
    cliente_id,
    tipo,
    gravidade,
    latitude,
    longitude,
    velocidade,
    vibracao_g,
    inclinacao_graus,
    detalhes,
    reconhecido,
    created_at
  ) VALUES (
    p_veiculo_id,
    v_cliente_id,
    p_tipo,
    COALESCE(p_gravidade, 'alta'),
    COALESCE(p_latitude, 0.0),
    COALESCE(p_longitude, 0.0),
    COALESCE(p_velocidade, 0),
    COALESCE(p_vibracao_g, 0.00),
    COALESCE(p_inclinacao_graus, 0),
    p_detalhes,
    FALSE,
    NOW()
  )
  RETURNING id INTO v_novo_alerta_id;

  -- 7. Título padronizado para eventos e notificações
  v_titulo_evento := CASE
    WHEN p_tipo = 'suspeita_jammer' THEN 'Alerta: Suspeita de Jammer / Silenciamento'
    WHEN p_tipo = 'saida_area' THEN 'Alerta: Saída de Cerca Virtual'
    WHEN p_tipo = 'desvio_rota' THEN 'Alerta: Desvio de Rota Monitorada'
    WHEN p_tipo = 'bateria_desconectada' THEN 'Corte / Desconexão da Bateria'
    WHEN p_tipo = 'baixa_tensao' THEN 'Baixa Tensão da Bateria'
    WHEN p_tipo = 'colisao_impacto' THEN 'Alerta: Impacto / Choque Violento'
    WHEN p_tipo = 'capotamento_inclinacao' THEN 'Alerta: Inclinação Excessiva / Capotamento'
    WHEN p_tipo = 'panico' THEN 'Alerta: Botão de Pânico Acionado'
    ELSE 'Alerta de Segurança'
  END;

  v_severidade_evento := CASE
    WHEN p_gravidade = 'critica' THEN 'critico'
    WHEN p_gravidade = 'alta' THEN 'aviso'
    ELSE 'info'
  END;

  -- 8. Grava no histórico de eventos_veiculo (resiliente para timeline)
  BEGIN
    INSERT INTO public.eventos_veiculo (
      veiculo_id,
      cliente_id,
      tipo,
      titulo,
      descricao,
      severidade,
      latitude,
      longitude,
      velocidade,
      data_hora
    ) VALUES (
      p_veiculo_id,
      v_cliente_id,
      p_tipo,
      v_titulo_evento,
      p_detalhes,
      v_severidade_evento,
      p_latitude,
      p_longitude,
      p_velocidade,
      NOW()
    );
  EXCEPTION
    WHEN OTHERS THEN NULL;
  END;

  -- 9. Entrega Automática ao Cliente: Grava em notificacoes_sistema para disparar Realtime e Web Push VAPID via pg_net
  IF v_cliente_user_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        destinatario_cliente_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa,
        lida,
        created_at
      ) VALUES (
        v_cliente_user_id,
        v_cliente_id,
        'GD Rastreamento — Central de Segurança',
        v_titulo_evento || ' — ' || COALESCE(v_placa, 'Veículo'),
        p_detalhes,
        p_tipo,
        '/monitor-gps',
        COALESCE(v_placa, ''),
        false,
        NOW()
      );
    EXCEPTION
      WHEN OTHERS THEN NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'sucesso', true,
    'alerta_id', v_novo_alerta_id,
    'duplicado', false,
    'latitude', p_latitude,
    'longitude', p_longitude
  );
END;
$$;

-- 3. Concessão de permissões de execução da RPC
GRANT EXECUTE ON FUNCTION public.registrar_alerta_seguranca TO authenticated, service_role, anon;

-- 4. Recarrega o cache de schema do PostgREST
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [99/225] MIGRAÇÃO: 20261002133000_hunter_fix_status_rastreador_enum_e_rpc_instalacao.sql
-- ============================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Hunter — Correção do Enum status_rastreador e da RPC salvar_atendimento_instalacao
-- Data: 02/10/2026
-- Objetivo:
-- 1. Elimina erro "invalid input value for enum status_rastreador: 'ativo'".
-- 2. Compatibiliza o enum status_rastreador com o valor 'ativo' por segurança defensiva.
-- 3. Restaura o uso canônico de 'instalado'::public.status_rastreador e 'estoque'::public.status_rastreador na RPC salvar_atendimento_instalacao.
-- ─────────────────────────────────────────────────────────────────────────────

-- 1. Defesa em profundidade: adiciona 'ativo' ao enum status_rastreador caso ainda não exista
ALTER TYPE public.status_rastreador ADD VALUE IF NOT EXISTS 'ativo';

-- 2. Recriação da RPC salvar_atendimento_instalacao com status canônicos
CREATE OR REPLACE FUNCTION public.salvar_atendimento_instalacao(
  p_instalacao_id UUID DEFAULT NULL,
  p_cliente_id UUID DEFAULT NULL,
  p_placa TEXT DEFAULT NULL,
  p_marca TEXT DEFAULT NULL,
  p_modelo TEXT DEFAULT NULL,
  p_ano INT DEFAULT NULL,
  p_cor TEXT DEFAULT NULL,
  p_km_instalacao INT DEFAULT 0,
  p_rastreador_imei TEXT DEFAULT NULL,
  p_rastreador_modelo TEXT DEFAULT 'J16 4G',
  p_chip_iccid TEXT DEFAULT NULL,
  p_chip_operadora TEXT DEFAULT NULL,
  p_posicao_instalacao TEXT DEFAULT NULL,
  p_status TEXT DEFAULT 'nao_instalado',
  p_motivo TEXT DEFAULT NULL,
  p_observacoes TEXT DEFAULT NULL,
  p_bloqueador_instalado BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_instalador_id UUID;
  v_instalacao_id UUID;
  v_veiculo_id UUID := NULL;
  v_rastreador_id UUID := NULL;
  v_chip_id UUID := NULL;
  v_placa_limpa TEXT;
  v_imei_limpo TEXT;
  v_iccid_limpo TEXT;
  v_cliente_instalador_id UUID := NULL;
  v_valor_unitario NUMERIC(10,2) := 0.00;
  v_concluida_at TIMESTAMPTZ := NULL;
  v_bloqueador BOOLEAN := COALESCE(p_bloqueador_instalado, TRUE);
  v_tipo_servico TEXT := 'instalacao';
  v_ordem RECORD;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso nao autenticado.';
  END IF;

  IF p_status NOT IN ('nao_instalado', 'concluida_com_pendencia', 'concluida') THEN
    RAISE EXCEPTION 'Status de atendimento invalido: %', p_status;
  END IF;

  IF p_status IN ('nao_instalado', 'concluida_com_pendencia') AND (p_motivo IS NULL OR TRIM(p_motivo) = '') THEN
    RAISE EXCEPTION 'E obrigatorio informar o motivo para status de pendencia ou nao executado.';
  END IF;

  v_placa_limpa := UPPER(TRIM(p_placa));
  v_imei_limpo := NULLIF(TRIM(p_rastreador_imei), '');
  v_iccid_limpo := NULLIF(TRIM(p_chip_iccid), '');

  IF p_status = 'concluida' AND (v_imei_limpo IS NULL OR v_imei_limpo = '') THEN
    RAISE EXCEPTION 'O IMEI do rastreador e obrigatorio para concluir o atendimento.';
  END IF;

  IF p_instalacao_id IS NOT NULL THEN
    SELECT * INTO v_ordem FROM public.instalacoes WHERE id = p_instalacao_id;
    IF FOUND THEN
      v_tipo_servico := COALESCE(v_ordem.tipo_servico, 'instalacao');
      v_instalacao_id := v_ordem.id;
      v_veiculo_id := v_ordem.veiculo_id;
    END IF;
  END IF;

  -- =========================================================================
  -- CASO A: ORDEM DE RETIRADA / DESINSTALAÇÃO
  -- =========================================================================
  IF v_tipo_servico = 'retirada' THEN
    IF p_status = 'concluida' AND v_concluida_at IS NULL THEN
      v_concluida_at := NOW();
    END IF;

    UPDATE public.instalacoes
    SET
      status = p_status,
      km_instalacao = COALESCE(p_km_instalacao, km_instalacao),
      motivo_pendencia_recusa = p_motivo,
      observacoes = p_observacoes,
      concluida_at = v_concluida_at,
      updated_at = NOW()
    WHERE id = v_instalacao_id;

    INSERT INTO public.instalacoes_historico_atendimentos (
      instalacao_id,
      instalador_id,
      status_atendimento,
      motivo,
      observacoes,
      km_no_atendimento
    ) VALUES (
      v_instalacao_id,
      v_user_id,
      p_status,
      p_motivo,
      p_observacoes,
      p_km_instalacao
    );

    IF p_status = 'concluida' THEN
      IF v_veiculo_id IS NULL AND v_placa_limpa IS NOT NULL THEN
        SELECT id INTO v_veiculo_id FROM public.veiculos WHERE placa = v_placa_limpa LIMIT 1;
      END IF;

      IF v_veiculo_id IS NOT NULL THEN
        UPDATE public.veiculos
        SET
          rastreador_id = NULL,
          rastreador_imei = NULL,
          ativo = FALSE,
          status_operacional = 'desinstalado',
          odometro_km = GREATEST(odometro_km, p_km_instalacao),
          updated_at = NOW()
        WHERE id = v_veiculo_id;
      END IF;

      -- Rastreador físico retirado volta para o estoque
      IF v_imei_limpo IS NOT NULL THEN
        UPDATE public.rastreadores
        SET
          veiculo_id = NULL,
          status = 'estoque'::public.status_rastreador,
          updated_at = NOW()
        WHERE imei = v_imei_limpo;
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'sucesso', TRUE,
      'tipo_servico', 'retirada',
      'instalacao_id', v_instalacao_id,
      'veiculo_id', v_veiculo_id
    );
  END IF;

  -- =========================================================================
  -- CASO B: ORDEM DE INSTALAÇÃO OU REABERTURA
  -- =========================================================================
  -- 1. Auto-provisionamento de Chip SIM
  IF v_iccid_limpo IS NOT NULL THEN
    SELECT id INTO v_chip_id FROM public.chips WHERE iccid = v_iccid_limpo LIMIT 1;
    IF v_chip_id IS NULL THEN
      INSERT INTO public.chips (iccid, operadora, status)
      VALUES (v_iccid_limpo, COALESCE(NULLIF(TRIM(p_chip_operadora), ''), 'Vivo'), 'ativo')
      RETURNING id INTO v_chip_id;
    END IF;
  END IF;

  -- 2. Auto-provisionamento ou vinculação do Rastreador com status canônico
  IF v_imei_limpo IS NOT NULL THEN
    SELECT id INTO v_rastreador_id FROM public.rastreadores WHERE imei = v_imei_limpo LIMIT 1;
    IF v_rastreador_id IS NULL THEN
      INSERT INTO public.rastreadores (imei, modelo, chip_id, status)
      VALUES (
        v_imei_limpo, 
        COALESCE(NULLIF(TRIM(p_rastreador_modelo), ''), 'J16 4G'), 
        v_chip_id, 
        CASE WHEN p_status = 'concluida' THEN 'instalado'::public.status_rastreador ELSE 'estoque'::public.status_rastreador END
      )
      RETURNING id INTO v_rastreador_id;
    ELSE
      UPDATE public.rastreadores
      SET
        chip_id = COALESCE(v_chip_id, chip_id),
        modelo = COALESCE(NULLIF(TRIM(p_rastreador_modelo), ''), modelo),
        status = CASE WHEN p_status = 'concluida' THEN 'instalado'::public.status_rastreador ELSE status END,
        updated_at = NOW()
      WHERE id = v_rastreador_id;
    END IF;
  END IF;

  -- 3. Criação ou Atualização da Instalação
  IF p_instalacao_id IS NULL THEN
    SELECT id INTO v_instalador_id FROM public.profiles WHERE id = v_user_id AND role = 'instalador';
    IF v_instalador_id IS NULL THEN
      SELECT instalador_id INTO v_instalador_id FROM public.clientes WHERE id = p_cliente_id;
      IF v_instalador_id IS NULL THEN
        SELECT id INTO v_instalador_id FROM public.profiles WHERE role = 'instalador' AND ativo = TRUE LIMIT 1;
      END IF;
    END IF;

    IF v_instalador_id IS NULL THEN
      RAISE EXCEPTION 'Nao foi possivel determinar o instalador credenciado.';
    END IF;

    SELECT valor_por_instalacao INTO v_valor_unitario FROM public.profiles WHERE id = v_instalador_id;
    v_valor_unitario := COALESCE(v_valor_unitario, 350.00);

    IF p_status = 'concluida' THEN
      v_concluida_at := NOW();
    END IF;

    INSERT INTO public.instalacoes (
      instalador_id,
      cliente_id,
      placa,
      marca,
      modelo,
      ano,
      cor,
      km_instalacao,
      rastreador_imei,
      rastreador_modelo,
      chip_iccid,
      chip_operadora,
      posicao_instalacao,
      status,
      motivo_pendencia_recusa,
      observacoes,
      valor_instalacao,
      concluida_at,
      bloqueador_instalado
    ) VALUES (
      v_instalador_id,
      p_cliente_id,
      v_placa_limpa,
      p_marca,
      p_modelo,
      p_ano,
      p_cor,
      p_km_instalacao,
      v_imei_limpo,
      COALESCE(NULLIF(TRIM(p_rastreador_modelo), ''), 'J16 4G'),
      v_iccid_limpo,
      p_chip_operadora,
      p_posicao_instalacao,
      p_status,
      p_motivo,
      p_observacoes,
      v_valor_unitario,
      v_concluida_at,
      v_bloqueador
    )
    RETURNING id INTO v_instalacao_id;
  ELSE
    v_instalacao_id := p_instalacao_id;

    IF p_status = 'concluida' AND v_concluida_at IS NULL THEN
      v_concluida_at := NOW();
    END IF;

    UPDATE public.instalacoes
    SET
      cliente_id = COALESCE(p_cliente_id, cliente_id),
      placa = COALESCE(v_placa_limpa, placa),
      marca = COALESCE(p_marca, marca),
      modelo = COALESCE(p_modelo, modelo),
      ano = COALESCE(p_ano, ano),
      cor = COALESCE(p_cor, cor),
      km_instalacao = COALESCE(p_km_instalacao, km_instalacao),
      rastreador_imei = COALESCE(v_imei_limpo, rastreador_imei),
      rastreador_modelo = COALESCE(NULLIF(TRIM(p_rastreador_modelo), ''), rastreador_modelo),
      chip_iccid = COALESCE(v_iccid_limpo, chip_iccid),
      chip_operadora = COALESCE(p_chip_operadora, chip_operadora),
      posicao_instalacao = COALESCE(p_posicao_instalacao, posicao_instalacao),
      status = p_status,
      motivo_pendencia_recusa = p_motivo,
      observacoes = p_observacoes,
      concluida_at = v_concluida_at,
      bloqueador_instalado = v_bloqueador,
      updated_at = NOW()
    WHERE id = v_instalacao_id;
  END IF;

  -- 4. Histórico de Atendimentos
  INSERT INTO public.instalacoes_historico_atendimentos (
    instalacao_id,
    instalador_id,
    status_atendimento,
    motivo,
    observacoes,
    km_no_atendimento
  ) VALUES (
    v_instalacao_id,
    v_user_id,
    p_status,
    p_motivo,
    p_observacoes,
    p_km_instalacao
  );

  -- 5. Atualização ou Criação do Veículo
  IF p_status = 'concluida' THEN
    SELECT id INTO v_veiculo_id FROM public.veiculos WHERE placa = v_placa_limpa LIMIT 1;

    IF v_veiculo_id IS NULL THEN
      INSERT INTO public.veiculos (
        cliente_id,
        placa,
        marca_modelo,
        ano,
        cor,
        odometro_km,
        rastreador_id,
        rastreador_imei,
        status_operacional,
        ativo,
        bloqueador_instalado
      ) VALUES (
        p_cliente_id,
        v_placa_limpa,
        FORMAT('%s %s', p_marca, p_modelo),
        p_ano,
        p_cor,
        p_km_instalacao,
        v_rastreador_id,
        v_imei_limpo,
        'estacionado',
        TRUE,
        v_bloqueador
      ) RETURNING id INTO v_veiculo_id;

      BEGIN
        PERFORM public.inicializar_itens_manutencao_veiculo(v_veiculo_id, p_km_instalacao);
      EXCEPTION
        WHEN OTHERS THEN NULL;
      END;
    ELSE
      UPDATE public.veiculos
      SET
        cliente_id = COALESCE(p_cliente_id, cliente_id),
        odometro_km = GREATEST(odometro_km, p_km_instalacao),
        rastreador_id = COALESCE(v_rastreador_id, rastreador_id),
        rastreador_imei = COALESCE(v_imei_limpo, rastreador_imei),
        status_operacional = 'estacionado',
        ativo = TRUE,
        bloqueador_instalado = v_bloqueador,
        updated_at = NOW()
      WHERE id = v_veiculo_id;
    END IF;

    -- Vincula veículo ao rastreador com status 'instalado'
    IF v_rastreador_id IS NOT NULL AND v_veiculo_id IS NOT NULL THEN
      UPDATE public.rastreadores
      SET
        veiculo_id = v_veiculo_id,
        status = 'instalado'::public.status_rastreador,
        updated_at = NOW()
      WHERE id = v_rastreador_id;
    END IF;

    UPDATE public.instalacoes
    SET veiculo_id = v_veiculo_id
    WHERE id = v_instalacao_id AND (veiculo_id IS NULL OR veiculo_id <> v_veiculo_id);

    IF p_cliente_id IS NOT NULL THEN
      UPDATE public.clientes
      SET
        status = 'ativo',
        status_agendamento = 'concluido',
        updated_at = NOW()
      WHERE id = p_cliente_id AND status <> 'ativo';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'tipo_servico', 'instalacao',
    'instalacao_id', v_instalacao_id,
    'veiculo_id', v_veiculo_id
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.salvar_atendimento_instalacao TO authenticated, service_role;
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [100/225] MIGRAÇÃO: 20261002165000_hunter_add_bloqueador_instalado_columns.sql
-- ============================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Hunter — Adiciona coluna bloqueador_instalado em instalacoes e veiculos
-- Data: 02/10/2026
-- Objetivo:
-- 1. Elimina erro 'column "bloqueador_instalado" of relation "instalacoes" does not exist'.
-- 2. Garante persistência e leitura de bloqueador_instalado tanto nas ordens de serviço
--    quanto na frota/veículos operacionais.
-- ─────────────────────────────────────────────────────────────────────────────

ALTER TABLE public.instalacoes 
ADD COLUMN IF NOT EXISTS bloqueador_instalado BOOLEAN NOT NULL DEFAULT TRUE;

ALTER TABLE public.veiculos 
ADD COLUMN IF NOT EXISTS bloqueador_instalado BOOLEAN NOT NULL DEFAULT TRUE;

ALTER TABLE public.rastreadores 
ADD COLUMN IF NOT EXISTS veiculo_id UUID REFERENCES public.veiculos(id) ON DELETE SET NULL;

-- Notifica o PostgREST para recarregar o schema cache imediatamente
NOTIFY pgrst, 'reload schema';



-- ============================================================================
-- [101/225] MIGRAÇÃO: 20261002175000_hunter_recalculo_odometro_e_filtro_cinematico.sql
-- ============================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Hunter — Recálculo de Odômetro Físico, Filtro Cinemático Anti-Jitter e RPC Ajuste
-- Data: 02/10/2026
-- Objetivo:
-- 1. Elimina acúmulo fantasma de quilometragem quando veículo está parado (velocidade <= 3 km/h).
-- 2. Aplica leis da física cinemática newtoniana (Doppler + consistência velocidade-tempo-espaço).
-- 3. Recalibra o odômetro do veículo AXH0E44 para 182.935,00 km (sincronização com painel físico).
-- 4. Cria a RPC atômica ajustar_odometro_veiculo para sincronização pelo cliente/operador.
-- 5. Adiciona política de RLS em public.veiculos para permitir UPDATE pelos proprietários.
-- 6. Fecha e consolida viagens órfãs em_andamento.
-- ─────────────────────────────────────────────────────────────────────────────

-- 1. Recalibração do veículo AXH0E44 para o valor real do painel físico (final 35 = 182935.00 km)
UPDATE public.veiculos
SET 
  odometro_km = 182935.00,
  updated_at = NOW()
WHERE placa = 'AXH0E44';

-- Atualiza a última posição de telemetria para prosseguir a partir do valor calibrado
UPDATE public.telemetria_posicoes
SET odometro = 182935.00
WHERE id = (
  SELECT id FROM public.telemetria_posicoes
  WHERE veiculo_id = (SELECT id FROM public.veiculos WHERE placa = 'AXH0E44' LIMIT 1)
  ORDER BY data_hora_gps DESC
  LIMIT 1
);

-- Consolida viagens órfãs que ficaram como em_andamento com veículo estacionado
UPDATE public.viagens_trajetos
SET 
  status = 'concluido',
  fim_at = COALESCE(fim_at, NOW())
WHERE veiculo_id = (SELECT id FROM public.veiculos WHERE placa = 'AXH0E44' LIMIT 1)
  AND status = 'em_andamento';

-- 2. Recriação da RPC registrar_posicao_gps_com_odometro com Leis da Física Cinemática
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, integer, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text);

CREATE OR REPLACE FUNCTION public.registrar_posicao_gps_com_odometro(
  p_veiculo_id UUID,
  p_rastreador_id UUID,
  p_latitude DOUBLE PRECISION,
  p_longitude DOUBLE PRECISION,
  p_velocidade NUMERIC,
  p_ignicao BOOLEAN,
  p_satelites INT,
  p_rumo INT,
  p_data_hora_gps TIMESTAMPTZ,
  p_inclinacao_graus INT DEFAULT 0,
  p_vibracao_g NUMERIC DEFAULT 0.0,
  p_bateria_veiculo_v NUMERIC DEFAULT NULL,
  p_bateria_rastreador_pct INT DEFAULT NULL,
  p_bateria_rastreador_status TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_veiculo RECORD;
  v_dist_metros NUMERIC := 0;
  v_delta_km NUMERIC := 0;
  v_novo_odometro NUMERIC(12, 2);
  v_status_op TEXT;
  v_dlat NUMERIC;
  v_dlon NUMERIC;
  v_a NUMERIC;
  v_vel_ms NUMERIC;
  v_max_dist_plausivel NUMERIC;
BEGIN
  -- Trava a linha do veículo para evitar concorrência em alta taxa de telemetria
  SELECT id, ultima_latitude, ultima_longitude, odometro_km, cliente_id, ultima_atualizacao
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado');
  END IF;

  v_novo_odometro := COALESCE(v_veiculo.odometro_km, 0);

  -- ─────────────────────────────────────────────────────────────────────────
  -- FÍSICA CINEMÁTICA ESTATÍSTICA DE VEÍCULOS TERRESTRES (ANTI-JITTER REAL):
  -- 1. Se p_velocidade <= 3.0 km/h: o veículo está fisicamente PARADO (velocidade Doppler nula).
  --    Toda e qualquer variação de latitude/longitude é ruído de antena/ionosfera (Brownian drift).
  --    Portanto, delta_km é estritamente 0.00.
  -- 2. Se p_velocidade > 3.0 km/h: veículo em trânsito comprovado.
  --    Calcula distância geodésica Haversine precisa na superfície elipsoidal WGS84.
  --    Aplica banda morta mínima (>= 3.0 metros) para evitar acumular zigue-zague lateral.
  --    Aplica limite cinemático de plausibilidade: dist <= vel_ms * 60s + 25m e dist < 5000m.
  -- ─────────────────────────────────────────────────────────────────────────
  IF p_velocidade > 3.0 
     AND v_veiculo.ultima_latitude IS NOT NULL 
     AND v_veiculo.ultima_longitude IS NOT NULL 
     AND (v_veiculo.ultima_latitude <> 0 OR v_veiculo.ultima_longitude <> 0)
     AND (p_latitude <> 0 OR p_longitude <> 0) THEN
    
    -- Fórmula Haversine
    v_dlat := radians(p_latitude - v_veiculo.ultima_latitude);
    v_dlon := radians(p_longitude - v_veiculo.ultima_longitude);
    v_a := sin(v_dlat / 2.0)^2 + cos(radians(v_veiculo.ultima_latitude)) * cos(radians(p_latitude)) * sin(v_dlon / 2.0)^2;
    v_dist_metros := 6371000.0 * 2.0 * atan2(sqrt(v_a), sqrt(1.0 - v_a));

    -- Conversão da velocidade reportada para m/s
    v_vel_ms := (p_velocidade / 3.6);
    -- Em um intervalo típico de envio (10s a 60s), a distância máxima plausível com aceleração é:
    v_max_dist_plausivel := GREATEST((v_vel_ms * 60.0) + 25.0, 50.0);

    -- Verifica plausibilidade cinemática: descarta ruídos abaixo de 3m e saltos anômalos
    IF v_dist_metros >= 3.0 AND v_dist_metros <= v_max_dist_plausivel AND v_dist_metros < 5000.0 THEN
      v_delta_km := (v_dist_metros / 1000.0);
      v_novo_odometro := ROUND((v_novo_odometro + v_delta_km)::NUMERIC, 2);
    END IF;
  ELSE
    -- Veículo parado (ou velocidade Doppler <= 3 km/h): acúmulo nulo rigoroso
    v_delta_km := 0.0;
  END IF;

  -- Determina status operacional
  v_status_op := CASE
    WHEN p_velocidade > 3 THEN 'em_movimento'
    WHEN p_ignicao THEN 'parado_ligado'
    ELSE 'estacionado'
  END;

  -- 1. Insere histórico na tabela telemetria_posicoes
  INSERT INTO public.telemetria_posicoes (
    veiculo_id,
    rastreador_id,
    latitude,
    longitude,
    velocidade,
    ignicao,
    odometro,
    satelites,
    rumo,
    data_hora_gps,
    inclinacao_graus,
    vibracao_g,
    bateria_veiculo_v,
    bateria_rastreador_pct,
    bateria_rastreador_status
  ) VALUES (
    p_veiculo_id,
    p_rastreador_id,
    p_latitude,
    p_longitude,
    p_velocidade,
    p_ignicao,
    v_novo_odometro,
    p_satelites,
    p_rumo,
    p_data_hora_gps,
    p_inclinacao_graus,
    p_vibracao_g,
    p_bateria_veiculo_v,
    p_bateria_rastreador_pct,
    p_bateria_rastreador_status
  );

  -- 2. Atualiza os dados instantâneos no veículo (dispara Realtime via WebSocket)
  UPDATE public.veiculos
  SET
    ultima_latitude = p_latitude,
    ultima_longitude = p_longitude,
    velocidade_atual = p_velocidade,
    ignicao_status = p_ignicao,
    odometro_km = v_novo_odometro,
    satelites = p_satelites,
    rumo = p_rumo,
    inclinacao_graus = p_inclinacao_graus,
    vibracao_g = p_vibracao_g,
    bateria_veiculo_v = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status = COALESCE(p_bateria_rastreador_status, bateria_rastreador_status),
    status_operacional = v_status_op,
    ultima_atualizacao = NOW()
  WHERE id = p_veiculo_id;

  -- 3. Atualiza quilometragem da viagem em andamento apenas se houver deslocamento real
  IF v_delta_km > 0 THEN
    UPDATE public.viagens_trajetos
    SET
      km_percorrido = ROUND((COALESCE(km_percorrido, 0) + v_delta_km)::NUMERIC, 2),
      velocidade_maxima = GREATEST(COALESCE(velocidade_maxima, 0), p_velocidade)
    WHERE veiculo_id = p_veiculo_id AND status = 'em_andamento';
  END IF;

  RETURN jsonb_build_object(
    'sucesso', true,
    'odometro_anterior', v_veiculo.odometro_km,
    'delta_km', ROUND(v_delta_km::NUMERIC, 3),
    'novo_odometro', v_novo_odometro
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO authenticated, service_role, anon;

-- 3. RPC Atômica de Calibração / Ajuste do Odômetro pelo Cliente ou Operador
CREATE OR REPLACE FUNCTION public.ajustar_odometro_veiculo(
  p_veiculo_id UUID,
  p_novo_odometro NUMERIC
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_odometro_anterior NUMERIC(12, 2);
  v_placa TEXT;
  v_eh_dono BOOLEAN := FALSE;
  v_eh_admin BOOLEAN := FALSE;
  v_novo_km NUMERIC(12, 2);
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso não autenticado.';
  END IF;

  IF p_novo_odometro IS NULL OR p_novo_odometro < 0 THEN
    RAISE EXCEPTION 'Quilometragem inválida. Deve ser maior ou igual a zero.';
  END IF;

  v_novo_km := ROUND(p_novo_odometro::NUMERIC, 2);

  -- Verifica permissão: SuperADM/Equipe OU titular do veículo
  SELECT 
    v.odometro_km,
    v.placa,
    (c.user_id = v_user_id)
  INTO 
    v_odometro_anterior,
    v_placa,
    v_eh_dono
  FROM public.veiculos v
  JOIN public.clientes c ON c.id = v.cliente_id
  WHERE v.id = p_veiculo_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Veículo não encontrado.';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.profiles 
    WHERE id = v_user_id AND role::text IN ('adm', 'superadmin', 'operador')
  ) INTO v_eh_admin;

  IF NOT (v_eh_dono OR v_eh_admin) THEN
    RAISE EXCEPTION 'Permissão negada. Apenas o proprietário ou a administração podem calibrar o odômetro.';
  END IF;

  -- 1. Atualiza o odômetro no veículo
  UPDATE public.veiculos
  SET 
    odometro_km = v_novo_km,
    ultima_atualizacao = NOW()
  WHERE id = p_veiculo_id;

  -- 2. Sincroniza a última posição de telemetria
  UPDATE public.telemetria_posicoes
  SET odometro = v_novo_km
  WHERE id = (
    SELECT id FROM public.telemetria_posicoes
    WHERE veiculo_id = p_veiculo_id
    ORDER BY data_hora_gps DESC
    LIMIT 1
  );

  -- 3. Registra log forense de auditoria
  INSERT INTO public.system_activity_logs (
    acao,
    usuario_id,
    detalhe
  ) VALUES (
    'AJUSTE_CALIBRACAO_ODOMETRO',
    v_user_id,
    format('Odômetro do veículo %s ajustado de %s km para %s km para sincronização com o painel físico.',
           v_placa,
           COALESCE(v_odometro_anterior::TEXT, '0.00'),
           v_novo_km::TEXT)
  );

  RETURN jsonb_build_object(
    'sucesso', true,
    'veiculo_id', p_veiculo_id,
    'placa', v_placa,
    'odometro_anterior', v_odometro_anterior,
    'novo_odometro', v_novo_km
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.ajustar_odometro_veiculo TO authenticated, service_role;

-- 4. Política de RLS em public.veiculos: permite aos clientes atualizarem seus veículos
DROP POLICY IF EXISTS "Clientes atualizam seus proprios veiculos" ON public.veiculos;
CREATE POLICY "Clientes atualizam seus proprios veiculos"
ON public.veiculos FOR UPDATE TO authenticated
USING (
  cliente_id IN (SELECT id FROM public.clientes WHERE user_id = auth.uid())
)
WITH CHECK (
  cliente_id IN (SELECT id FROM public.clientes WHERE user_id = auth.uid())
);

-- Notifica o PostgREST para recarregar o schema cache imediatamente
NOTIFY pgrst, 'reload schema';


