-- 3. Atualiza RPC listar_equipamentos_habilitados_instalacao para incluir chips e permitir kit_atual
CREATE OR REPLACE FUNCTION public.listar_equipamentos_habilitados_instalacao()
RETURNS TABLE (
  rastreador_id UUID,
  imei TEXT,
  modelo TEXT,
  chip_id UUID,
  iccid TEXT,
  operadora TEXT,
  linha TEXT,
