-- 20261010142500_hunter_notificacao_operadores_historico_cliente.sql
-- Notificação Imediata da Equipe Operação/ADM e Registro Canônico no Histórico do Cliente

-- 1. Permissão de SELECT para clientes em seu próprio histórico de atendimento
DROP POLICY IF EXISTS "Historico visivel para clientes de suas ordens" ON public.instalacoes_historico_atendimentos;
CREATE POLICY "Historico visivel para clientes de suas ordens"
ON public.instalacoes_historico_atendimentos FOR SELECT TO authenticated
USING (
  is_admin_or_superadmin(auth.uid())
  OR EXISTS (
    SELECT 1 FROM public.user_roles ur 
    WHERE ur.user_id = auth.uid() AND ur.role = 'operador'::hunter_role
  )
  OR instalador_id = auth.uid()
  OR instalacao_id IN (
    SELECT i.id FROM public.instalacoes i
    WHERE i.cliente_user_id = auth.uid() 
       OR i.cliente_id = auth.uid()
       OR i.cliente_id IN (SELECT c.id FROM public.clientes c WHERE c.user_id = auth.uid())
  )
);

-- 1.1. Permissão de SELECT em notificacoes_sistema para clientes e operadores
DROP POLICY IF EXISTS "Usuarios podem ler suas proprias notificacoes ou administradores leem todas" ON public.notificacoes_sistema;
CREATE POLICY "Usuarios podem ler suas proprias notificacoes ou administradores leem todas"
  ON public.notificacoes_sistema FOR SELECT TO authenticated
  USING (
    destinatario_user_id = auth.uid()
    OR destinatario_cliente_id IN (
      SELECT id FROM public.clientes WHERE user_id = auth.uid()
    )
    OR remetente_user_id = auth.uid()
    OR public.is_admin_or_superadmin(auth.uid())
    OR EXISTS (
      SELECT 1 FROM public.user_roles ur 
      WHERE ur.user_id = auth.uid() AND ur.role = 'operador'::hunter_role
    )
  );

-- 2. Função RPC para notificar todos os operadores e administradores ativos
CREATE OR REPLACE FUNCTION public.notificar_equipe_operacao(
  p_remetente_id UUID,
  p_remetente_nome TEXT,
  p_titulo TEXT,
  p_mensagem TEXT,
  p_tipo TEXT DEFAULT 'instalacao',
  p_url TEXT DEFAULT '/instalacao',
  p_placa TEXT DEFAULT NULL,
  p_cliente_id UUID DEFAULT NULL
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN (
    SELECT DISTINCT p.id 
    FROM public.profiles p
    LEFT JOIN public.user_roles ur ON ur.user_id = p.id
    WHERE (p.role IN ('superadmin', 'adm', 'operador') OR ur.role IN ('superadmin', 'adm', 'operador'))
      AND p.ativo = TRUE
      AND p.id <> COALESCE(p_remetente_id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) LOOP
    BEGIN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        destinatario_cliente_id,
        remetente_user_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa
      ) VALUES (
        r.id,
        NULL, -- Destinatário é estritamente a equipe interna (r.id), NUNCA o cliente
        p_remetente_id,
        p_remetente_nome,
        p_titulo,
        p_mensagem,
        p_tipo,
        p_url,
        p_placa
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION public.notificar_equipe_operacao(UUID, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, UUID) TO authenticated;

-- 3. Atualização de instalador_definir_agendamento_instalacao com histórico e aviso à equipe
CREATE OR REPLACE FUNCTION public.instalador_definir_agendamento_instalacao(
  p_instalacao_id UUID,
  p_data DATE,
  p_hora TEXT,
  p_local_tipo TEXT DEFAULT 'oficina'::TEXT,
  p_local_endereco TEXT DEFAULT NULL::TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_caller_role TEXT;
  v_caller_nome TEXT;
  v_instalador_id UUID;
  v_cliente_id UUID;
  v_cliente_user_id UUID;
  v_cliente_nome TEXT;
  v_placa TEXT;
  v_rastreador_imei TEXT;
  v_instalador_nome TEXT;
  v_endereco_final TEXT;
  v_tipo_local TEXT;
  v_tipo_acao TEXT := 'Agendamento';
  v_ja_estava_agendado BOOLEAN := FALSE;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role, nome INTO v_caller_role, v_caller_nome 
  FROM public.profiles 
  WHERE id = v_caller_id;

  SELECT 
    i.instalador_id, 
    i.cliente_id, 
    i.placa,
    i.rastreador_imei,
    i.data_agendamento IS NOT NULL,
    c.user_id,
    c.nome_razao_social,
    p.nome,
    p.endereco_instalacao
  INTO 
    v_instalador_id, 
    v_cliente_id, 
    v_placa,
    v_rastreador_imei,
    v_ja_estava_agendado,
    v_cliente_user_id,
    v_cliente_nome,
    v_instalador_nome,
    v_endereco_final
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  LEFT JOIN public.profiles p ON p.id = COALESCE(i.instalador_id, v_caller_id)
  WHERE i.id = p_instalacao_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não encontrada.');
  END IF;

  IF v_rastreador_imei IS NULL 
     OR TRIM(v_rastreador_imei) = '' 
     OR UPPER(TRIM(v_rastreador_imei)) IN (
       'AGUARDANDO ESTOQUE', 
       'AGUARDANDO_ESTOQUE', 
       'PENDENTE', 
       'A DEFINIR', 
       'A_DEFINIR', 
       'SEM RASTREADOR', 
       'SEM_RASTREADOR', 
       'A CONFERIR', 
       'A_CONFERIR', 
       'NENHUM'
     ) THEN
    RETURN jsonb_build_object(
      'success', false, 
      'message', 'Não é possível agendar sem kit disponibilizado para este veículo. O operador deve vincular e disponibilizar o kit antes de definir a data.'
    );
  END IF;

  IF v_instalador_id IS NULL THEN
    IF v_caller_role = 'instalador' THEN
      v_instalador_id := v_caller_id;
      UPDATE public.instalacoes SET instalador_id = v_caller_id WHERE id = p_instalacao_id;
    END IF;
  END IF;

  IF v_caller_role = 'instalador' AND v_instalador_id IS NOT NULL AND v_instalador_id <> v_caller_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Acesso negado: apenas o instalador atribuído ou a equipe de operações podem agendar esta instalação.');
  END IF;

  IF p_data IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'A data do agendamento é obrigatória.');
  END IF;

  IF p_hora IS NULL OR TRIM(p_hora) = '' THEN
    RETURN jsonb_build_object('success', false, 'message', 'O horário do agendamento é obrigatório.');
  END IF;

  v_tipo_local := COALESCE(p_local_tipo, 'oficina');
  IF v_tipo_local = 'local_veiculo' THEN
    v_endereco_final := COALESCE(TRIM(p_local_endereco), v_endereco_final);
  ELSE
    v_endereco_final := COALESCE(TRIM(p_local_endereco), v_endereco_final, 'Oficina Credenciada');
  END IF;

  UPDATE public.instalacoes
  SET 
    data_agendamento = p_data,
    hora_agendamento = TRIM(p_hora),
    status = 'agendada',
    local_tipo = v_tipo_local,
    local_endereco = v_endereco_final,
    solicita_endereco_cliente = FALSE,
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  IF v_cliente_id IS NOT NULL THEN
    UPDATE public.clientes
    SET 
      data_agendamento = p_data,
      hora_agendamento = TRIM(p_hora),
      status_agendamento = 'agendado',
      updated_at = NOW()
    WHERE id = v_cliente_id;
  END IF;

  IF v_ja_estava_agendado THEN
    v_tipo_acao := 'Reagendamento';
  END IF;

  -- Registra no histórico funcional de atendimentos
  BEGIN
    INSERT INTO public.instalacoes_historico_atendimentos (
      instalacao_id,
      instalador_id,
      status_atendimento,
      motivo,
      observacoes
    ) VALUES (
      p_instalacao_id,
      COALESCE(v_instalador_id, v_caller_id),
      'agendada',
      v_tipo_acao,
      format('%s confirmado para %s às %s (%s: %s). Técnico: %s.',
        v_tipo_acao,
        to_char(p_data, 'DD/MM/YYYY'),
        TRIM(p_hora),
        CASE WHEN v_tipo_local = 'local_veiculo' THEN 'Local do Veículo' ELSE 'Oficina' END,
        v_endereco_final,
        COALESCE(v_instalador_nome, v_caller_nome, 'Técnico Responsável')
      )
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- Notifica o CLIENTE (apenas 1 notificação atômica)
  IF v_cliente_user_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        destinatario_cliente_id,
        remetente_user_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa
      ) VALUES (
        v_cliente_user_id,
        v_cliente_id,
        v_caller_id,
        COALESCE(v_instalador_nome, v_caller_nome, 'Técnico Instalador'),
        format('📅 Instalação %s: %s', CASE WHEN v_ja_estava_agendado THEN 'Reagendada' ELSE 'Agendada' END, COALESCE(v_placa, 'Veículo')),
        format('A instalação do seu rastreador no veículo %s foi %s para %s às %s (%s: %s).',
          COALESCE(v_placa, ''),
          CASE WHEN v_ja_estava_agendado THEN 'reagendada' ELSE 'agendada' END,
          to_char(p_data, 'DD/MM/YYYY'),
          TRIM(p_hora),
          CASE WHEN v_tipo_local = 'local_veiculo' THEN 'Local do Veículo' ELSE 'Oficina' END,
          COALESCE(v_endereco_final, 'Oficina Credenciada')
        ),
        'agendamento',
        '/login',
        v_placa
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  -- Notifica imediatamente OPERADORES E ADMINISTRADORES para ciência total
  PERFORM public.notificar_equipe_operacao(
    v_caller_id,
    COALESCE(v_instalador_nome, v_caller_nome, 'Técnico Instalador'),
    format('📅 Instalação %s: %s', CASE WHEN v_ja_estava_agendado THEN 'Reagendada' ELSE 'Agendada' END, COALESCE(v_placa, 'Veículo')),
    format('O técnico %s definiu o agendamento do veículo %s (Cliente: %s) para %s às %s (%s: %s).',
      COALESCE(v_instalador_nome, v_caller_nome, 'Técnico'),
      COALESCE(v_placa, ''),
      COALESCE(v_cliente_nome, 'Cliente'),
      to_char(p_data, 'DD/MM/YYYY'),
      TRIM(p_hora),
      CASE WHEN v_tipo_local = 'local_veiculo' THEN 'Local do Veículo' ELSE 'Oficina' END,
      COALESCE(v_endereco_final, 'Oficina Credenciada')
    ),
    'agendamento',
    '/instalacao',
    v_placa,
    v_cliente_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', format('Instalação do veículo %s agendada com sucesso para %s às %s.', COALESCE(v_placa, ''), to_char(p_data, 'DD/MM/YYYY'), TRIM(p_hora)),
    'instalacao_id', p_instalacao_id,
    'placa', v_placa,
    'data', p_data,
    'hora', TRIM(p_hora),
    'local_tipo', v_tipo_local,
    'local_endereco', v_endereco_final
  );
END;
$$;

-- 4. Atualização de instalador_solicitar_endereco_cliente com histórico e aviso à equipe
CREATE OR REPLACE FUNCTION public.instalador_solicitar_endereco_cliente(p_instalacao_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_role TEXT;
  v_inst RECORD;
  v_instalador_nome TEXT;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role, nome INTO v_role, v_instalador_nome FROM public.profiles WHERE id = v_caller_id;

  SELECT 
    i.id, i.cliente_id, i.placa, i.instalador_id, i.status,
    c.user_id AS cliente_user_id, c.nome_razao_social
  INTO v_inst
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  WHERE i.id = p_instalacao_id;

  IF v_inst.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não localizada.');
  END IF;

  IF v_role = 'instalador' AND v_inst.instalador_id <> v_caller_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Permissão negada. Esta instalação pertence a outro profissional.');
  END IF;

  UPDATE public.instalacoes
  SET 
    solicita_endereco_cliente = TRUE,
    solicitado_endereco_em = NOW(),
    local_tipo = 'local_veiculo',
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  -- Registra no histórico funcional de atendimentos
  BEGIN
    INSERT INTO public.instalacoes_historico_atendimentos (
      instalacao_id,
      instalador_id,
      status_atendimento,
      motivo,
      observacoes
    ) VALUES (
      p_instalacao_id,
      v_caller_id,
      'solicitacao_endereco',
      'Solicitação de Endereço',
      format('Técnico %s solicitou o endereço de atendimento presencial ao cliente para o veículo %s.',
        COALESCE(v_instalador_nome, 'Técnico'),
        COALESCE(v_inst.placa, '')
      )
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- Notifica o CLIENTE (apenas 1 notificação atômica)
  IF v_inst.cliente_user_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        destinatario_cliente_id,
        remetente_user_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa
      ) VALUES (
        v_inst.cliente_user_id,
        v_inst.cliente_id,
        v_caller_id,
        COALESCE(v_instalador_nome, 'Técnico Instalador'),
        format('📍 Endereço Necessário: %s', COALESCE(v_inst.placa, 'Veículo')),
        format('O técnico precisa do endereço onde o veículo %s estará para realizar a instalação presencial. Acesse para informar.', COALESCE(v_inst.placa, '')),
        'agendamento',
        '/login',
        v_inst.placa
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  -- Notifica imediatamente OPERADORES E ADMINISTRADORES
  PERFORM public.notificar_equipe_operacao(
    v_caller_id,
    COALESCE(v_instalador_nome, 'Técnico Instalador'),
    format('📍 Endereço Solicitado: %s', COALESCE(v_inst.placa, 'Veículo')),
    format('O técnico %s solicitou o endereço do veículo %s ao cliente %s para atendimento presencial.',
      COALESCE(v_instalador_nome, 'Técnico'),
      COALESCE(v_inst.placa, ''),
      COALESCE(v_inst.nome_razao_social, 'Cliente')
    ),
    'agendamento',
    '/instalacao',
    v_inst.placa,
    v_inst.cliente_id
  );

  RETURN jsonb_build_object('success', true, 'message', 'Solicitação de endereço enviada ao cliente com sucesso.');
END;
$$;

-- 5. Atualização de cliente_informar_endereco_instalacao com histórico e aviso à equipe
CREATE OR REPLACE FUNCTION public.cliente_informar_endereco_instalacao(
  p_instalacao_id UUID,
  p_endereco TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_cliente_id UUID;
  v_instalador_id UUID;
  v_placa TEXT;
  v_cliente_nome TEXT;
  v_instalador_user_id UUID;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Não autenticado.');
  END IF;

  SELECT 
    i.cliente_id, 
    i.instalador_id, 
    i.placa, 
    c.nome_razao_social,
    i.instalador_id
  INTO 
    v_cliente_id, 
    v_instalador_id, 
    v_placa, 
    v_cliente_nome,
    v_instalador_user_id
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  WHERE i.id = p_instalacao_id
    AND (i.cliente_user_id = v_uid OR i.cliente_id = v_uid OR i.cliente_id IN (SELECT id FROM public.clientes WHERE user_id = v_uid));

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ordem de instalação não localizada para este cliente.');
  END IF;

  UPDATE public.instalacoes
  SET 
    endereco_cliente_informado = TRIM(p_endereco),
    endereco_cliente_informado_em = NOW(),
    solicita_endereco_cliente = FALSE,
    local_endereco = TRIM(p_endereco),
    local_tipo = 'local_veiculo',
    updated_at = NOW()
  WHERE id = p_instalacao_id;

  -- Registra no histórico funcional de atendimentos
  BEGIN
    INSERT INTO public.instalacoes_historico_atendimentos (
      instalacao_id,
      instalador_id,
      status_atendimento,
      motivo,
      observacoes
    ) VALUES (
      p_instalacao_id,
      v_instalador_id,
      'endereco_informado',
      'Endereço Informado pelo Cliente',
      format('Cliente %s informou o endereço de atendimento do veículo %s: %s.',
        COALESCE(v_cliente_nome, 'Cliente'),
        COALESCE(v_placa, ''),
        TRIM(p_endereco)
      )
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  -- Notifica o INSTALADOR (apenas 1 notificação atômica)
  IF v_instalador_user_id IS NOT NULL THEN
    BEGIN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        remetente_user_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa
      ) VALUES (
        v_instalador_user_id,
        v_uid,
        COALESCE(v_cliente_nome, 'Cliente'),
        format('📍 Endereço Informado: %s', COALESCE(v_placa, 'Veículo')),
        format('O cliente %s informou o local para o veículo %s: %s. Disponível para agendamento presencial.',
          COALESCE(v_cliente_nome, ''),
          COALESCE(v_placa, ''),
          TRIM(p_endereco)
        ),
        'agendamento',
        '/instalacao',
        v_placa
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  -- Notifica imediatamente OPERADORES E ADMINISTRADORES
  PERFORM public.notificar_equipe_operacao(
    v_uid,
    COALESCE(v_cliente_nome, 'Cliente'),
    format('📍 Endereço Informado: %s', COALESCE(v_placa, 'Veículo')),
    format('O cliente %s informou o local para atendimento do veículo %s: %s.',
      COALESCE(v_cliente_nome, 'Cliente'),
      COALESCE(v_placa, ''),
      TRIM(p_endereco)
    ),
    'agendamento',
    '/instalacao',
    v_placa,
    v_cliente_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Endereço registrado com sucesso. O instalador e a central de operações foram notificados.'
  );
END;
$$;

NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [137/225] MIGRAÇÃO: 20261010163000_hunter_sincronizacao_troca_instalador_e_anti_duplicacao_notificacoes.sql
-- ============================================================================

-- ==============================================================================
-- HUNTER: SINCRONIZAÇÃO ATÔMICA DE TROCA DE INSTALADOR E ANTI-DUPLICAÇÃO DE NOTIFICAÇÕES
-- ==============================================================================

-- 1. Atualizar RPC admin_atualizar_cliente_completo para propagar atomicamente
--    a troca de instalador para todas as ordens de instalação pendentes do cliente
CREATE OR REPLACE FUNCTION public.admin_atualizar_cliente_completo(
  p_cliente_id UUID,
  p_nome TEXT,
  p_documento TEXT,
  p_email TEXT,
  p_telefone TEXT,
  p_status public.status_cliente,
  p_plano public.plano_cliente,
  p_dia_vencimento INT,
  p_valor_mensalidade NUMERIC,
  p_dias_historico INT,
  p_dias_retencao INT,
  p_senha TEXT DEFAULT NULL,
  p_instalador_id UUID DEFAULT NULL,
  p_meses_contrato INT DEFAULT 12,
  p_data_inicio_contrato DATE DEFAULT CURRENT_DATE,
  p_tipo_renovacao TEXT DEFAULT 'mesma_vigencia',
  p_meses_renovacao INT DEFAULT 12,
  p_foro_comarca TEXT DEFAULT 'Volta Redonda/RJ',
  p_gerar_parcelas_ausentes BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_email_limpo TEXT := lower(trim(coalesce(p_email, '')));
  v_resultado_parcelas JSONB := '[]'::JSONB;
  v_meses_c INT := COALESCE(p_meses_contrato, 12);
  v_data_inicio DATE := COALESCE(p_data_inicio_contrato, CURRENT_DATE);
  v_data_fim DATE;
  v_status_final public.status_cliente := p_status;
  v_status_agendamento_final TEXT;
  r_veiculo RECORD;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem atualizar clientes.';
  END IF;

  SELECT user_id, status_agendamento INTO v_user_id, v_status_agendamento_final
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado.';
  END IF;

  v_data_fim := v_data_inicio + (v_meses_c || ' months')::INTERVAL;

  -- Se foi atribuído ou alterado instalador:
  IF p_instalador_id IS NOT NULL THEN
    IF v_status_agendamento_final IS NULL OR v_status_agendamento_final = 'concluido' THEN
      v_status_agendamento_final := 'aguardando_agendamento';
    END IF;
    -- Se cliente não possui veículos ativos com rastreadores, força status operacional aguardando_instalacao
    IF NOT EXISTS (
      SELECT 1 FROM public.veiculos WHERE cliente_id = p_cliente_id AND ativo = TRUE AND rastreador_id IS NOT NULL
    ) THEN
      v_status_final := 'aguardando_instalacao'::public.status_cliente;
    END IF;

    -- Sincronização atômica imediata no BD:
    -- Atualiza o instalador_id de todas as ordens de serviço pendentes do cliente
    UPDATE public.instalacoes
    SET instalador_id = p_instalador_id,
        updated_at = NOW()
    WHERE cliente_id = p_cliente_id AND status != 'concluida';

    -- Se o cliente possui veículos cadastrados sem ordem de instalação aberta, cria a ordem para o novo instalador
    FOR r_veiculo IN
      SELECT v.id, v.placa, v.marca, v.modelo, v.ano, v.tipo_veiculo
      FROM public.veiculos v
      WHERE v.cliente_id = p_cliente_id
        AND NOT EXISTS (
          SELECT 1 FROM public.instalacoes i 
          WHERE i.veiculo_id = v.id AND i.status != 'cancelada'
        )
    LOOP
      INSERT INTO public.instalacoes (
        cliente_id,
        veiculo_id,
        placa,
        marca,
        modelo,
        ano,
        tipo_veiculo,
        instalador_id,
        status,
        rastreador_imei,
        created_at,
        updated_at
      ) VALUES (
        p_cliente_id,
        r_veiculo.id,
        r_veiculo.placa,
        r_veiculo.marca,
        r_veiculo.modelo,
        r_veiculo.ano,
        COALESCE(r_veiculo.tipo_veiculo, 'carro'),
        p_instalador_id,
        'aguardando_agendamento',
        'AGUARDANDO ESTOQUE',
        NOW(),
        NOW()
      );
    END LOOP;
  END IF;

  -- Atualizar credenciais de auth se aplicável
  IF v_user_id IS NOT NULL THEN
    IF v_email_limpo <> '' THEN
      UPDATE auth.users
      SET email = v_email_limpo,
          raw_user_meta_data = raw_user_meta_data || jsonb_build_object('nome', trim(p_nome), 'email', v_email_limpo),
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE public.profiles
      SET nome = trim(p_nome),
          email = v_email_limpo,
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE auth.identities
      SET identity_data = jsonb_set(identity_data, '{email}', to_jsonb(v_email_limpo)),
          provider_id = v_email_limpo
      WHERE user_id = v_user_id AND provider = 'email';
    ELSE
      UPDATE public.profiles
      SET nome = trim(p_nome),
          updated_at = now()
      WHERE id = v_user_id;

      UPDATE auth.users
      SET raw_user_meta_data = raw_user_meta_data || jsonb_build_object('nome', trim(p_nome)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;

    IF p_senha IS NOT NULL AND length(p_senha) >= 6 THEN
      UPDATE auth.users
      SET encrypted_password = extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
          updated_at = now()
      WHERE id = v_user_id;
    END IF;
  END IF;

  -- Atualizar registro em public.clientes
  UPDATE public.clientes
  SET nome_razao_social = trim(p_nome),
      documento = NULLIF(trim(p_documento), ''),
      email = NULLIF(v_email_limpo, ''),
      telefone = NULLIF(trim(p_telefone), ''),
      user_id = COALESCE(user_id, v_user_id),
      plano = p_plano,
      status = v_status_final,
      dia_vencimento = COALESCE(p_dia_vencimento, dia_vencimento),
      valor_mensalidade = COALESCE(p_valor_mensalidade, valor_mensalidade),
      dias_historico_plano = COALESCE(p_dias_historico, dias_historico_plano),
      dias_retencao_banco = COALESCE(p_dias_retencao, dias_retencao_banco),
      instalador_id = p_instalador_id,
      status_agendamento = COALESCE(v_status_agendamento_final, status_agendamento),
      meses_contrato = v_meses_c,
      data_inicio_contrato = v_data_inicio,
      data_fim_contrato = v_data_fim,
      tipo_renovacao = COALESCE(p_tipo_renovacao, tipo_renovacao),
      meses_renovacao = COALESCE(p_meses_renovacao, meses_renovacao),
      foro_comarca = COALESCE(p_foro_comarca, 'Volta Redonda/RJ'),
      updated_at = now()
  WHERE id = p_cliente_id;

  IF p_gerar_parcelas_ausentes THEN
    v_resultado_parcelas := public.admin_gerar_parcelas_contrato(p_cliente_id);
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Dados do cliente e credenciais atualizados com sucesso.',
    'cliente_id', p_cliente_id,
    'user_id', v_user_id,
    'meses_contrato', v_meses_c,
    'data_inicio_contrato', v_data_inicio,
    'data_fim_contrato', v_data_fim,
    'parcelas', v_resultado_parcelas
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_atualizar_cliente_completo(UUID, TEXT, TEXT, TEXT, TEXT, public.status_cliente, public.plano_cliente, INT, NUMERIC, INT, INT, TEXT, UUID, INT, DATE, TEXT, INT, TEXT, BOOLEAN) TO authenticated;

-- 2. Atualizar o Trigger trg_notificar_atribuicao_instalacao_kit com blindagem anti-duplicação (30 segundos)
CREATE OR REPLACE FUNCTION public.trg_notificar_atribuicao_instalacao_kit()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_tem_kit_valido BOOLEAN;
  v_mudou_kit BOOLEAN;
  v_mudou_instalador BOOLEAN;
  v_concluiu_instalacao BOOLEAN;
  v_cliente_user_id UUID;
  v_cliente_nome TEXT;
  v_instalador_nome TEXT;
BEGIN
  -- Identifica o cliente associado
  IF NEW.cliente_id IS NOT NULL THEN
    SELECT user_id, nome_razao_social INTO v_cliente_user_id, v_cliente_nome
    FROM public.clientes
    WHERE id = NEW.cliente_id;
  END IF;

  -- Identifica o instalador associado
  IF NEW.instalador_id IS NOT NULL THEN
    SELECT nome INTO v_instalador_nome
    FROM public.profiles
    WHERE id = NEW.instalador_id;
  END IF;

  v_tem_kit_valido := (
    NEW.rastreador_imei IS NOT NULL 
    AND NEW.rastreador_imei NOT IN ('PENDENTE', 'AGUARDANDO ESTOQUE', 'A DEFINIR', 'SEM RASTREADOR', '')
  );

  v_mudou_instalador := (
    NEW.instalador_id IS NOT NULL 
    AND (TG_OP = 'INSERT' OR OLD.instalador_id IS DISTINCT FROM NEW.instalador_id)
  );

  v_mudou_kit := (
    v_tem_kit_valido 
    AND (TG_OP = 'INSERT' OR OLD.rastreador_imei IS DISTINCT FROM NEW.rastreador_imei)
  );

  v_concluiu_instalacao := (
    NEW.status = 'concluida' 
    AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'concluida')
  );

  -- 2.1. Se o instalador foi atribuído ou alterado
  IF v_mudou_instalador THEN
    -- Notifica o Instalador (com blindagem anti-duplicação de 30s)
    IF NOT EXISTS (
      SELECT 1 FROM public.notificacoes_sistema
      WHERE destinatario_user_id = NEW.instalador_id
        AND tipo = 'instalacao'
        AND COALESCE(placa, '') = COALESCE(NEW.placa, '')
        AND created_at > NOW() - INTERVAL '30 seconds'
    ) THEN
      INSERT INTO public.notificacoes_sistema (
        destinatario_user_id,
        remetente_nome,
        titulo,
        mensagem,
        tipo,
        url,
        placa,
        lida,
        created_at
      ) VALUES (
        NEW.instalador_id,
        'GD Rastreamento — Central Operacional',
        '🔧 Nova Instalação Atribuída: ' || COALESCE(NEW.placa, 'Veículo'),
        'Você foi designado para realizar a instalação do veículo ' || COALESCE(NEW.placa, '') || ' (' || COALESCE(NEW.marca, '') || ' ' || COALESCE(NEW.modelo, '') || '). ' || 
          CASE 
            WHEN v_tem_kit_valido THEN 'Kit de comodato já atribuído: IMEI ' || NEW.rastreador_imei || '.'
            ELSE 'Aguardando liberação de rastreador pelo operador.'
          END,
        'instalacao',
        '/instalacao',
        NEW.placa,
        FALSE,
        NOW()
      );
    END IF;

    -- Notifica o Cliente Titular (com blindagem anti-duplicação de 30s)
    IF v_cliente_user_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.notificacoes_sistema
        WHERE destinatario_user_id = v_cliente_user_id
          AND tipo = 'instalacao'
          AND COALESCE(placa, '') = COALESCE(NEW.placa, '')
          AND created_at > NOW() - INTERVAL '30 seconds'
      ) THEN
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id,
          destinatario_cliente_id,
          remetente_nome,
          titulo,
          mensagem,
          tipo,
          url,
          placa,
          lida,
          created_at
        ) VALUES (
          v_cliente_user_id,
          NEW.cliente_id,
          'GD Rastreamento — Central Operacional',
          '🔧 Técnico Designado para seu Veículo: ' || COALESCE(NEW.placa, 'Veículo'),
          'O técnico credenciado ' || COALESCE(v_instalador_nome, 'especializado') || ' foi designado para o atendimento do seu veículo ' || COALESCE(NEW.placa, '') || ' (' || COALESCE(NEW.marca, '') || ' ' || COALESCE(NEW.modelo, '') || '). ' ||
            CASE 
              WHEN v_tem_kit_valido THEN 'O kit de rastreador já foi vinculado e preparado para agendamento.'
              ELSE 'Em breve alinharemos os detalhes para instalação.'
            END,
          'instalacao',
          '/login',
          NEW.placa,
          FALSE,
          NOW()
        );
      END IF;
    END IF;
  END IF;

  -- 2.2. Se um kit com IMEI real foi atribuído e já há instalador definido (e não foi o mesmo disparo anterior)
  IF v_mudou_kit AND NOT v_mudou_instalador THEN
    IF NEW.instalador_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.notificacoes_sistema
        WHERE destinatario_user_id = NEW.instalador_id
          AND tipo = 'instalacao'
          AND COALESCE(placa, '') = COALESCE(NEW.placa, '')
          AND created_at > NOW() - INTERVAL '30 seconds'
      ) THEN
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id,
          remetente_nome,
          titulo,
          mensagem,
          tipo,
          url,
          placa,
          lida,
          created_at
        ) VALUES (
          NEW.instalador_id,
          'GD Rastreamento — Central Operacional',
          '📦 Kit Rastreador Vinculado: ' || COALESCE(NEW.placa, 'Veículo'),
          'O operador vinculou o rastreador (IMEI ' || NEW.rastreador_imei || ') ao veículo ' || COALESCE(NEW.placa, '') || '. Equipamento disponível para conferência física e agendamento.',
          'instalacao',
          '/instalacao',
          NEW.placa,
          FALSE,
          NOW()
        );
      END IF;
    END IF;

    -- Notifica o Cliente Titular
    IF v_cliente_user_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.notificacoes_sistema
        WHERE destinatario_user_id = v_cliente_user_id
          AND tipo = 'instalacao'
          AND COALESCE(placa, '') = COALESCE(NEW.placa, '')
          AND created_at > NOW() - INTERVAL '30 seconds'
      ) THEN
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id,
          destinatario_cliente_id,
          remetente_nome,
          titulo,
          mensagem,
          tipo,
          url,
          placa,
          lida,
          created_at
        ) VALUES (
          v_cliente_user_id,
          NEW.cliente_id,
          'GD Rastreamento — Central Operacional',
          '📦 Rastreador Preparado: ' || COALESCE(NEW.placa, 'Veículo'),
          'O rastreador foi vinculado ao seu veículo ' || COALESCE(NEW.placa, '') || '. O equipamento já está liberado para o técnico realizar a conferência e o agendamento.',
          'instalacao',
          '/login',
          NEW.placa,
          FALSE,
          NOW()
        );
      END IF;
    END IF;
  END IF;

  -- 2.3. Se a instalação foi concluída com sucesso
  IF v_concluiu_instalacao THEN
    IF v_cliente_user_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.notificacoes_sistema
        WHERE destinatario_user_id = v_cliente_user_id
          AND tipo = 'instalacao'
          AND COALESCE(placa, '') = COALESCE(NEW.placa, '')
          AND created_at > NOW() - INTERVAL '30 seconds'
      ) THEN
        INSERT INTO public.notificacoes_sistema (
          destinatario_user_id,
          destinatario_cliente_id,
          remetente_nome,
          titulo,
          mensagem,
          tipo,
          url,
          placa,
          lida,
          created_at
        ) VALUES (
          v_cliente_user_id,
          NEW.cliente_id,
          'GD Rastreamento — Central Operacional',
          '🎉 Instalação Concluída: ' || COALESCE(NEW.placa, 'Veículo'),
          'A instalação do rastreador no veículo ' || COALESCE(NEW.placa, '') || ' foi finalizada com sucesso! Seu veículo já está protegido e pronto para acompanhamento em tempo real.',
          'instalacao',
          '/monitor-gps',
          NEW.placa,
          FALSE,
          NOW()
        );
      END IF;
    END IF;

    -- Notifica Administradores e Operadores
    INSERT INTO public.notificacoes_sistema (
      destinatario_user_id,
      remetente_nome,
      titulo,
      mensagem,
      tipo,
      url,
      placa,
      lida,
      created_at
    )
    SELECT 
      p.id,
      'GD Rastreamento — Central Operacional',
      '✅ Instalação Concluída: ' || COALESCE(NEW.placa, 'Veículo'),
      'O técnico ' || COALESCE(v_instalador_nome, 'instalador') || ' concluiu a instalação do veículo ' || COALESCE(NEW.placa, '') || ' (Cliente: ' || COALESCE(v_cliente_nome, 'Cliente') || ').',
      'instalacao',
      '/instalacao',
      NEW.placa,
      FALSE,
      NOW()
    FROM public.profiles p
    WHERE p.role IN ('superadmin', 'adm', 'operador')
      AND NOT EXISTS (
        SELECT 1 FROM public.notificacoes_sistema ns
        WHERE ns.destinatario_user_id = p.id
          AND ns.tipo = 'instalacao'
          AND COALESCE(ns.placa, '') = COALESCE(NEW.placa, '')
          AND ns.created_at > NOW() - INTERVAL '30 seconds'
      );
  END IF;

  RETURN NEW;
END;
$$;

-- 3. Atualizar a RPC instalador_obter_minhas_demandas para contemplar ordens onde o instalador está no cliente
--    ou na ordem de instalação, garantindo que o veículo sempre apareça para o técnico designado
CREATE OR REPLACE FUNCTION public.instalador_obter_minhas_demandas(
  p_instalador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_role TEXT;
  v_alvo_id UUID;
  v_ordens JSONB;
  v_agendamentos JSONB;
  v_resumo JSONB;
  v_total_a_receber NUMERIC(10,2);
  v_total_recebido NUMERIC(10,2);
  v_total_agendados_qtd INT;
  v_total_a_agendar_qtd INT;
  v_valor_previsto_agendados NUMERIC(10,2);
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_caller_id;

  IF v_role IN ('superadmin', 'adm', 'operador') THEN
    v_alvo_id := COALESCE(p_instalador_id, v_caller_id);
  ELSE
    v_alvo_id := v_caller_id;
  END IF;

  -- 1. Coletar Ordens de Instalação Atribuídas (diretamente ou via vínculo do cliente)
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', i.id,
      'cliente_id', i.cliente_id,
      'veiculo_id', i.veiculo_id,
      'instalador_id', COALESCE(i.instalador_id, c.instalador_id),
      'placa', COALESCE(i.placa, v.placa, 'A DEFINIR'),
      'marca', COALESCE(i.marca, split_part(v.marca_modelo, ' ', 1), 'Geral'),
      'modelo', COALESCE(i.modelo, v.marca_modelo, 'Veículo'),
      'ano', COALESCE(i.ano, v.ano),
      'cor', COALESCE(i.cor, v.cor),
      'tipo_veiculo', COALESCE(i.tipo_veiculo, v.tipo_veiculo, 'carro'),
      'km_instalacao', COALESCE(i.km_instalacao, 0),
      'tipo_servico', COALESCE(i.tipo_servico, 'instalacao'),
      'valor_instalacao', i.valor_instalacao,
      'status_pagamento', i.status_pagamento,
      'bloqueador_instalado', COALESCE(i.bloqueador_instalado, false),
      'com_bloqueador', COALESCE(i.bloqueador_instalado, false),
      'status', i.status,
      'posicao_instalacao', i.posicao_instalacao,
      'posicaoInstalacao', i.posicao_instalacao,
      'rastreador_id', COALESCE(i.rastreador_id, v.rastreador_id),
      'rastreador_imei', COALESCE(i.rastreador_imei, v.rastreador_imei, 'PENDENTE'),
      'rastreador_modelo', COALESCE(i.rastreador_modelo, 'J16 4G'),
      'chip_iccid', i.chip_iccid,
      'chip_operadora', i.chip_operadora,
      'data_agendamento', COALESCE(i.data_agendamento, c.data_agendamento),
      'hora_agendamento', COALESCE(i.hora_agendamento, c.hora_agendamento),
      'local_tipo', COALESCE(i.local_tipo, 'oficina'),
      'local_endereco', i.local_endereco,
      'solicita_endereco_cliente', COALESCE(i.solicita_endereco_cliente, false),
      'endereco_cliente_informado', i.endereco_cliente_informado,
      'endereco_cliente_informado_em', i.endereco_cliente_informado_em,
      'solicitado_endereco_em', i.solicitado_endereco_em,
      'kit_confirmado_instalador', COALESCE(i.kit_confirmado_instalador, false),
      'kit_confirmado_em', i.kit_confirmado_em,
      'imei_confirmado', i.imei_confirmado,
      'instalador_nome', COALESCE(p.nome, 'Instalador Técnico'),
      'instalador_chave_pix', p.chave_pix,
      'cliente_nome', COALESCE(c.nome_razao_social, 'Cliente'),
      'cliente_telefone', c.telefone,
      'cliente_documento', c.documento,
      'motivo_pendencia_recusa', i.motivo_pendencia_recusa,
      'observacoes', i.observacoes,
      'created_at', i.created_at,
      'updated_at', i.updated_at,
      'concluida_at', i.concluida_at
    ) ORDER BY i.created_at DESC
  ), '[]'::JSONB)
  INTO v_ordens
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  LEFT JOIN public.veiculos v ON v.id = i.veiculo_id
  LEFT JOIN public.profiles p ON p.id = COALESCE(i.instalador_id, c.instalador_id)
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR i.instalador_id = v_alvo_id
     OR (i.instalador_id IS NULL AND c.instalador_id = v_alvo_id);

  -- 2. Coletar Clientes Agendados ou Aguardando Agendamento
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'nome_razao_social', c.nome_razao_social,
      'documento', c.documento,
      'telefone', c.telefone,
      'email', c.email,
      'status', c.status,
      'plano', c.plano,
      'tem_fidelidade', c.tem_fidelidade,
      'regra_horimetro', c.regra_horimetro,
      'status_agendamento', COALESCE(c.status_agendamento, 'aguardando_agendamento'),
      'data_agendamento', c.data_agendamento,
      'hora_agendamento', c.hora_agendamento,
      'instalador_id', COALESCE(c.instalador_id, v_alvo_id),
      'instalador', jsonb_build_object(
        'id', p.id,
        'nome', p.nome,
        'endereco_instalacao', p.endereco_instalacao,
        'valor_com_bloqueador', p.valor_instalacao_com_bloqueador,
        'valor_sem_bloqueador', p.valor_instalacao_sem_bloqueador
      ),
      'veiculos', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', v.id, 
          'placa', v.placa, 
          'modelo', v.marca_modelo, 
          'tipo_veiculo', v.tipo_veiculo,
          'horimetro_horas', v.horimetro_horas
        ))
        FROM public.veiculos v
        WHERE v.cliente_id = c.id
      ), '[]'::JSONB)
    ) ORDER BY c.created_at DESC
  ), '[]'::JSONB)
  INTO v_agendamentos
  FROM public.clientes c
  LEFT JOIN public.profiles p ON p.id = COALESCE(c.instalador_id, v_alvo_id)
  WHERE (
    (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
    OR c.instalador_id = v_alvo_id
    OR EXISTS (SELECT 1 FROM public.instalacoes inst WHERE inst.cliente_id = c.id AND (inst.instalador_id = v_alvo_id OR (inst.instalador_id IS NULL AND c.instalador_id = v_alvo_id)))
  )
  AND (c.status_agendamento IS DISTINCT FROM 'concluido' OR c.status = 'aguardando_instalacao');

  -- 3. Métricas Financeiras ESTRITAS
  SELECT 
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pendente' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pago' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN status != 'concluida' AND data_agendamento IS NOT NULL THEN valor_instalacao ELSE 0 END), 0.00),
    COUNT(CASE WHEN status != 'concluida' AND data_agendamento IS NOT NULL THEN 1 END),
    COUNT(CASE WHEN status != 'concluida' AND data_agendamento IS NULL THEN 1 END)
  INTO 
    v_total_a_receber,
    v_total_recebido,
    v_valor_previsto_agendados,
    v_total_agendados_qtd,
    v_total_a_agendar_qtd
  FROM public.instalacoes
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR instalador_id = v_alvo_id;

  v_resumo := jsonb_build_object(
    'total_ordens', jsonb_array_length(v_ordens),
    'total_agendamentos', jsonb_array_length(v_agendamentos),
    'a_receber', v_total_a_receber,
    'recebido', v_total_recebido,
    'agendados_qtd', v_total_agendados_qtd,
    'a_agendar_qtd', v_total_a_agendar_qtd,
    'valor_previsto_agendados', v_valor_previsto_agendados
  );

  RETURN jsonb_build_object(
    'success', true,
    'ordens', v_ordens,
    'agendamentos', v_agendamentos,
    'resumo', v_resumo
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_obter_minhas_demandas(UUID) TO authenticated;

-- 5. Trigger Anti-Duplicação na raiz da tabela public.notificacoes_sistema
-- Barreira física de código (Root Cause First): Impede qualquer gravação de notificação duplicada
-- no intervalo de 30 segundos para o mesmo destinatário com o mesmo tipo e placa/título,
-- independentemente de ser disparada por trigger, RPC ou requisição do frontend.
CREATE OR REPLACE FUNCTION public.trg_anti_duplicacao_notificacoes_sistema()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.notificacoes_sistema
    WHERE (
      (destinatario_user_id IS NOT NULL AND destinatario_user_id = NEW.destinatario_user_id)
      OR
      (destinatario_cliente_id IS NOT NULL AND destinatario_cliente_id = NEW.destinatario_cliente_id)
    )
    AND tipo = NEW.tipo
    AND (
      (NEW.placa IS NOT NULL AND NEW.placa <> '' AND COALESCE(placa, '') = NEW.placa)
      OR
      (COALESCE(titulo, '') = COALESCE(NEW.titulo, ''))
    )
    AND created_at > NOW() - INTERVAL '30 seconds'
  ) THEN
    -- Descarta silenciosamente o insert duplicado na raiz do banco
    RETURN NULL;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_anti_duplicacao_notificacoes_sistema ON public.notificacoes_sistema;
CREATE TRIGGER trg_anti_duplicacao_notificacoes_sistema
  BEFORE INSERT ON public.notificacoes_sistema
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_anti_duplicacao_notificacoes_sistema();

-- Invalidação canônica de cache PostgREST (Zero Schema Cache Error)
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [138/225] MIGRAÇÃO: 20261011100000_hunter_odometro_definitivo_e_km_viagem.sql
-- ============================================================================

-- =============================================================================
-- HUNTER — ODÔMETRO DEFINITIVO E KM DE VIAGEM (DJR-NEW / 2026-10-11)
-- =============================================================================
-- CAUSAS RAIZ CORRIGIDAS NESTA MIGRATION:
--
-- 1. ASSINATURA ÚNICA E CANÔNICA: elimina todas as versões anteriores da RPC
--    registrar_posicao_gps_com_odometro com assinaturas divergentes que
--    causavam PGRST204 (schema cache miss) quando o gateway enviava p_sinal_gsm.
--    A nova RPC tem assinatura idêntica ao que o gateway já envia.
--
-- 2. HAVERSINE WGS-84 COM RAIO GEOCÊNTRICO LOCAL: substitui raio fixo arbitrário
--    (6.371.000 m ou 6.374.900 m) por raio calculado dinamicamente conforme a
--    latitude média dos dois pontos usando os semi-eixos oficiais WGS-84.
--    Erro de odômetro corrigido: até 0,3% a menos no centro do Brasil.
--
-- 3. SEGMENTAÇÃO DE GAP TEMPORAL (> 180 s): se Δt entre pacotes for superior a
--    180 segundos (perda de GPRS, túnel, zone morta), a distância geodésica
--    entre os dois pontos não é acumulada — elimina saltos de km em linha reta.
--
-- 4. ZERO DOUBLE-COUNTING: a RPC atualiza km_percorrido na viagem em andamento
--    incrementalmente, pacote a pacote. O gateway NÃO deve mais recalcular
--    km_percorrido no encerramento da viagem (processarCicloIgnicaoViagem).
--    Apenas odometro_km do veículo (acumulado vitalício) continua sendo mantido
--    separadamente e nunca é zerado.
--
-- 5. VALIDAÇÃO CRC IMPLÍCITA: a RPC descarta pontos com coordenadas zero (0,0)
--    ou fora da caixa geográfica do Brasil (-35°N a 5°N, -74°W a -28°W),
--    eliminando posições LBS falsas sem fix GPS.
--
-- 6. FATOR DE SINUOSIDADE VIÁRIA REMOVIDO: o fator 1.06383 era arbitrário e
--    causava superestimação sistemática de ~6,4% no odômetro. O Haversine com
--    raio local WGS-84 já entrega a distância geodésica real. A sinuosidade real
--    é capturada naturalmente pelo sampling de 1 pacote/min da rota real.
--
-- 7. PARÂMETRO p_sinal_gsm RESTAURADO: estava ausente na migration 20261006,
--    causando fallback silencioso no gateway e perda de acumulação de odômetro.
-- =============================================================================

-- ── DROP de todas as versões anteriores (assinaturas divergentes) ──────────
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text, integer);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, timestamp with time zone, numeric, numeric, numeric, numeric);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, timestamp with time zone, numeric, numeric, numeric, numeric, integer);

-- ── Cria a versão canônica definitiva ─────────────────────────────────────
CREATE OR REPLACE FUNCTION public.registrar_posicao_gps_com_odometro(
  p_veiculo_id            UUID,
  p_rastreador_id         UUID        DEFAULT NULL,
  p_latitude              DOUBLE PRECISION DEFAULT 0.0,
  p_longitude             DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade            NUMERIC     DEFAULT 0,
  p_ignicao               BOOLEAN     DEFAULT FALSE,
  p_satelites             INT         DEFAULT 0,
  p_rumo                  INT         DEFAULT 0,
  p_data_hora_gps         TIMESTAMPTZ DEFAULT NOW(),
  p_inclinacao_graus      INT         DEFAULT 0,
  p_vibracao_g            NUMERIC     DEFAULT 0.0,
  p_bateria_veiculo_v     NUMERIC     DEFAULT NULL,
  p_bateria_rastreador_pct INT        DEFAULT NULL,
  p_bateria_rastreador_status TEXT    DEFAULT NULL,
  p_sinal_gsm             INT         DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  -- Constantes WGS-84 reais (metros)
  c_a          CONSTANT DOUBLE PRECISION := 6378137.0;        -- Semi-eixo maior
  c_b          CONSTANT DOUBLE PRECISION := 6356752.314245;   -- Semi-eixo menor
  -- Parâmetros de filtragem
  c_gap_max_s  CONSTANT NUMERIC          := 180.0;  -- Gap máximo entre pacotes (s)
  c_spike_kmh  CONSTANT NUMERIC          := 195.0;  -- Velocidade calculada de spike (km/h)
  c_dist_max_m CONSTANT NUMERIC          := 15000.0;-- Distância máxima num único pacote (m)

  v_veiculo            RECORD;
  v_ultima_telem       RECORD;
  v_dist_metros        DOUBLE PRECISION := 0.0;
  v_delta_km           NUMERIC(12, 4)   := 0.0;
  v_novo_odometro      NUMERIC(12, 3);
  v_status_op          TEXT;
  v_dlat               DOUBLE PRECISION;
  v_dlon               DOUBLE PRECISION;
  v_a_hav              DOUBLE PRECISION;
  v_lat_med_rad        DOUBLE PRECISION;
  v_cos_lat            DOUBLE PRECISION;
  v_sin_lat            DOUBLE PRECISION;
  v_raio_local         DOUBLE PRECISION;
  v_delta_sec          DOUBLE PRECISION := 0.0;
  v_vel_calc_kmh       DOUBLE PRECISION := 0.0;
  v_limiar_m           NUMERIC;
  v_viagem_ativa_id    UUID;
  v_descartado         BOOLEAN          := FALSE;
  v_motivo_descarte    TEXT             := NULL;
BEGIN
  -- ── 1. Trava atômica do veículo ──────────────────────────────────────────
  SELECT id, ultima_latitude, ultima_longitude, odometro_km, ultima_atualizacao
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado');
  END IF;

  v_novo_odometro := COALESCE(v_veiculo.odometro_km, 0);

  -- ── 2. Validação Geográfica (Brasil) — descarta LBS / Fix ausente ────────
  -- Rejeita coordenadas zeradas ou fora da caixa geográfica do Brasil
  IF p_latitude = 0.0 AND p_longitude = 0.0 THEN
    v_descartado := TRUE;
    v_motivo_descarte := 'coordenada_zero';
  ELSIF p_latitude NOT BETWEEN -35.0 AND 5.5
     OR p_longitude NOT BETWEEN -74.0 AND -28.0 THEN
    -- Fora do Brasil: aceita mas não acumula odômetro (pode ser veículo em trânsito internacional)
    -- Apenas grava posição e atualiza status
    v_descartado := TRUE;
    v_motivo_descarte := 'fora_brasil';
  END IF;

  -- ── 3. Cálculo Geodésico (somente se coordenadas válidas e anterior existe) ──
  IF NOT v_descartado
     AND v_veiculo.ultima_latitude  IS NOT NULL
     AND v_veiculo.ultima_longitude IS NOT NULL
     AND (v_veiculo.ultima_latitude  <> 0.0 OR v_veiculo.ultima_longitude <> 0.0)
  THEN
    -- ── 3a. Raio geocêntrico local WGS-84 (latitude média dos dois pontos) ─
    v_lat_med_rad := radians((p_latitude + v_veiculo.ultima_latitude) / 2.0);
    v_cos_lat     := cos(v_lat_med_rad);
    v_sin_lat     := sin(v_lat_med_rad);
    v_raio_local  := sqrt(
      (((c_a * c_a * v_cos_lat)^2) + ((c_b * c_b * v_sin_lat)^2))
      /
      (((c_a * v_cos_lat)^2)       + ((c_b * v_sin_lat)^2))
    );

    -- ── 3b. Haversine ───────────────────────────────────────────────────────
    v_dlat    := radians(p_latitude  - v_veiculo.ultima_latitude);
    v_dlon    := radians(p_longitude - v_veiculo.ultima_longitude);
    v_a_hav   := sin(v_dlat / 2.0)^2
               + cos(radians(v_veiculo.ultima_latitude))
               * cos(radians(p_latitude))
               * sin(v_dlon / 2.0)^2;
    v_dist_metros := v_raio_local * 2.0 * atan2(sqrt(v_a_hav), sqrt(1.0 - v_a_hav));

    -- ── 3c. Intervalo temporal (para detecção de gap e spike) ───────────────
    -- Busca último ponto gravado para calcular Δt real entre pacotes
    SELECT data_hora_gps, velocidade
    INTO v_ultima_telem
    FROM public.telemetria_posicoes
    WHERE veiculo_id = p_veiculo_id
    ORDER BY data_hora_gps DESC
    LIMIT 1;

    IF v_ultima_telem.data_hora_gps IS NOT NULL THEN
      v_delta_sec := GREATEST(0.0, EXTRACT(EPOCH FROM (p_data_hora_gps - v_ultima_telem.data_hora_gps)));
    ELSE
      v_delta_sec := 60.0; -- Assumir 60s no primeiro ponto
    END IF;

    -- ── 3d. Filtros de Qualidade ────────────────────────────────────────────

    -- GAP TEMPORAL: Δt > 180s → não acumula (túnel / perda de GPRS)
    IF v_delta_sec > c_gap_max_s THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'gap_temporal_' || round(v_delta_sec) || 's';

    -- SPIKE GEODÉSICO: velocidade calculada > 195 km/h com velocidade de hardware < 160 km/h
    ELSIF v_delta_sec > 0.5 THEN
      v_vel_calc_kmh := (v_dist_metros / v_delta_sec) * 3.6;
      IF v_vel_calc_kmh > c_spike_kmh AND (p_velocidade IS NULL OR p_velocidade < 160.0) THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'spike_gps_' || round(v_vel_calc_kmh) || 'kmh';
      END IF;
    END IF;

    -- ZERO VELOCITY UPDATE (ZVU): parado com drift menor que limiar
    IF NOT v_descartado THEN
      IF p_velocidade <= 2.5 AND v_dist_metros < 15.0 THEN
        -- GPS em drift estático: ignora deslocamento
        v_descartado      := TRUE;
        v_motivo_descarte := 'zvu_drift_' || round(v_dist_metros::NUMERIC, 1) || 'm';
      END IF;
    END IF;

    -- DISTÂNCIA MÁXIMA IMPLAUSÍVEL (> 15 km num único pacote)
    IF NOT v_descartado AND v_dist_metros >= c_dist_max_m THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'dist_implausive_' || round(v_dist_metros) || 'm';
    END IF;

    -- ── 3e. Limiar mínimo dinâmico de acumulação ────────────────────────────
    IF NOT v_descartado THEN
      -- Em movimento (> 3 km/h): captura deslocamentos a partir de 1,5 m (curvas lentas)
      -- Parado/lento (≤ 3 km/h): exige pelo menos 10 m para descartar oscilação de antena
      v_limiar_m := CASE WHEN p_velocidade > 3.0 THEN 1.5 ELSE 10.0 END;

      IF v_dist_metros >= v_limiar_m THEN
        -- Acumula distância geodésica real sem fator de correção arbitrário
        v_delta_km      := (v_dist_metros / 1000.0);
        v_novo_odometro := ROUND((v_novo_odometro + v_delta_km)::NUMERIC, 3);
      ELSE
        -- Deslocamento abaixo do limiar (jitter de antena)
        v_descartado      := TRUE;
        v_motivo_descarte := COALESCE(v_motivo_descarte, 'jitter_' || round(v_dist_metros::NUMERIC, 1) || 'm');
      END IF;
    END IF;
  END IF;

  -- ── 4. Status operacional ─────────────────────────────────────────────────
  v_status_op := CASE
    WHEN p_velocidade > 3.0  THEN 'em_movimento'
    WHEN p_ignicao           THEN 'parado_ligado'
    ELSE                          'estacionado'
  END;

  -- ── 5. Grava posição histórica ────────────────────────────────────────────
  -- Sempre grava (mesmo pontos descartados para fins de auditoria de rota)
  -- exceto coordenadas absolutamente zeradas
  IF p_latitude <> 0.0 OR p_longitude <> 0.0 THEN
    INSERT INTO public.telemetria_posicoes (
      veiculo_id,
      rastreador_id,
      latitude,
      longitude,
      velocidade,
      ignicao,
      odometro,
      satelites,
      rumo,
      data_hora_gps,
      inclinacao_graus,
      vibracao_g,
      bateria_veiculo_v,
      bateria_rastreador_pct,
      bateria_rastreador_status,
      sinal_gsm
    ) VALUES (
      p_veiculo_id,
      p_rastreador_id,
      p_latitude,
      p_longitude,
      p_velocidade,
      p_ignicao,
      v_novo_odometro,   -- Odômetro acumulado real no momento
      p_satelites,
      p_rumo,
      p_data_hora_gps,
      COALESCE(p_inclinacao_graus, 0),
      COALESCE(p_vibracao_g, 0.0),
      p_bateria_veiculo_v,
      p_bateria_rastreador_pct,
      p_bateria_rastreador_status,
      p_sinal_gsm
    )
    ON CONFLICT DO NOTHING;  -- Idempotente: evita duplicatas por retry do gateway
  END IF;

  -- ── 6. Atualiza veículo (dispara Realtime via WebSocket) ──────────────────
  UPDATE public.veiculos
  SET
    ultima_latitude          = p_latitude,
    ultima_longitude         = p_longitude,
    velocidade_atual         = p_velocidade,
    ignicao_status           = p_ignicao,
    odometro_km              = v_novo_odometro,
    satelites                = p_satelites,
    rumo                     = p_rumo,
    inclinacao_graus         = COALESCE(p_inclinacao_graus, inclinacao_graus),
    vibracao_g               = COALESCE(p_vibracao_g, vibracao_g),
    bateria_veiculo_v        = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct   = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status= COALESCE(p_bateria_rastreador_status, bateria_rastreador_status),
    sinal_gsm                = COALESCE(p_sinal_gsm, sinal_gsm),
    status_operacional       = v_status_op,
    ultima_atualizacao       = p_data_hora_gps,
    updated_at               = NOW()
  WHERE id = p_veiculo_id;

  -- ── 7. Acumula km_percorrido na viagem em andamento (incremental, atômico) ─
  -- IMPORTANTE: apenas a RPC faz este acúmulo. O gateway NÃO deve
  -- recalcular km_percorrido no encerramento da viagem via Haversine sobre
  -- todos os pontos — isso causava double-counting. O encerramento da viagem
  -- apenas consolida status e velocidades, sem alterar km_percorrido.
  IF v_delta_km > 0 THEN
    SELECT id INTO v_viagem_ativa_id
    FROM public.viagens_trajetos
    WHERE veiculo_id = p_veiculo_id
      AND status = 'em_andamento'
    ORDER BY inicio_at DESC
    LIMIT 1;

    IF v_viagem_ativa_id IS NOT NULL THEN
      UPDATE public.viagens_trajetos
      SET
        km_percorrido    = ROUND((COALESCE(km_percorrido, 0) + v_delta_km)::NUMERIC, 3),
        velocidade_maxima= GREATEST(COALESCE(velocidade_maxima, 0), ROUND(p_velocidade)),
        atualizado_em    = NOW()
      WHERE id = v_viagem_ativa_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso',          true,
    'novo_odometro',    v_novo_odometro,
    'delta_km',         ROUND(v_delta_km::NUMERIC, 4),
    'dist_metros',      ROUND(v_dist_metros::NUMERIC, 2),
    'descartado',       v_descartado,
    'motivo_descarte',  v_motivo_descarte,
    'delta_sec',        ROUND(v_delta_sec::NUMERIC, 1),
    'raio_local_m',     ROUND(v_raio_local::NUMERIC),
    'status_operacional', v_status_op
  );
END;
$$;

-- ── Permissões ────────────────────────────────────────────────────────────────
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO authenticated;
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO anon;
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO service_role;

-- ── Invalida cache PostgREST ──────────────────────────────────────────────────
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [139/225] MIGRAÇÃO: 20261011110000_hunter_odometria_fusao_inercial_e_fix_gnss.sql
-- ============================================================================

-- =============================================================================
-- HUNTER — ODOMETRIA DE ALTA ACUIDADE COM FUSÃO INERCIAL E FIX GNSS ESTREITO
-- =============================================================================
-- PROTOCOLO J16 / GT06 — RIGOR CIENTÍFICO E FÍSICO (DJR-NEW / 2026-10-11)
--
-- 1. FIX GNSS ESTREITO:
--    Aceita parâmetro p_gps_fixado BOOLEAN (Bit 4 do byte 1 do Course Status).
--    Se p_gps_fixado for FALSE (LBS ou sem fix), a telemetria é registrada mas
--    o odômetro vitalício e o km_percorrido da viagem NÃO são acumulados.
--
-- 2. ZERO VELOCITY UPDATE (ZVU) ESTRITO:
--    Se p_velocidade = 0 OU v_dist_metros < 3.0m (erro circular CEP nominal GNSS),
--    força Δs = 0 eliminando completamente o drift estático em paradas/semáforos.
--
-- 3. INTEGRAÇÃO NUMÉRICA DE VELOCIDADE (REGRA DO TRAPÉZIO):
--    Integra a velocidade instantânea medida por Doppler do hardware:
--    s_trap = ((v_i + v_{i-1}) / 7.2) * Δt
--
-- 4. CRITÉRIO DE FUSÃO INERCIAL PARA CURVAS:
--    Em curvas fechadas (Δrumo >= 8° e v > 3 km/h), a corda seca geodésica do GPS
--    subestima o arco real percorrido pelas rodas do veículo.
--    O critério de fusão prioriza o avanço inercial validado pelo Doppler (s_trap),
--    eliminando a discrepância histórica de odômetro em percursos sinuosos.
--
-- 5. SEGMENTAÇÃO DE GAPS (> 180s):
--    Se Δt > 180s (túnel / sombra de sinal), a corda cega é descartada (Δs = 0).
-- =============================================================================

-- Adiciona coluna gps_fixado nas tabelas públicas com valor default seguro
ALTER TABLE public.telemetria_posicoes
  ADD COLUMN IF NOT EXISTS gps_fixado BOOLEAN DEFAULT TRUE;

ALTER TABLE public.veiculos
  ADD COLUMN IF NOT EXISTS gps_fixado BOOLEAN DEFAULT TRUE;

-- ── DROP de versões anteriores com assinaturas divergentes ────────────────────
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text, integer, boolean);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text, integer);

-- ── Cria a versão canônica definitiva com fusão inercial e fix GNSS ───────────
CREATE OR REPLACE FUNCTION public.registrar_posicao_gps_com_odometro(
  p_veiculo_id            UUID,
  p_rastreador_id         UUID        DEFAULT NULL,
  p_latitude              DOUBLE PRECISION DEFAULT 0.0,
  p_longitude             DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade            NUMERIC     DEFAULT 0,
  p_ignicao               BOOLEAN     DEFAULT FALSE,
  p_satelites             INT         DEFAULT 0,
  p_rumo                  INT         DEFAULT 0,
  p_data_hora_gps         TIMESTAMPTZ DEFAULT NOW(),
  p_inclinacao_graus      INT         DEFAULT 0,
  p_vibracao_g            NUMERIC     DEFAULT 0.0,
  p_bateria_veiculo_v     NUMERIC     DEFAULT NULL,
  p_bateria_rastreador_pct INT        DEFAULT NULL,
  p_bateria_rastreador_status TEXT    DEFAULT NULL,
  p_sinal_gsm             INT         DEFAULT NULL,
  p_gps_fixado            BOOLEAN     DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  -- Constantes WGS-84 reais (metros)
  c_a          CONSTANT DOUBLE PRECISION := 6378137.0;        -- Semi-eixo maior
  c_b          CONSTANT DOUBLE PRECISION := 6356752.314245;   -- Semi-eixo menor
  -- Parâmetros de filtragem física
  c_gap_max_s  CONSTANT NUMERIC          := 180.0;  -- Gap máximo entre pacotes (s)
  c_spike_kmh  CONSTANT NUMERIC          := 195.0;  -- Velocidade calculada de spike (km/h)
  c_dist_max_m CONSTANT NUMERIC          := 15000.0;-- Distância máxima num único pacote (m)
  c_zvu_m      CONSTANT DOUBLE PRECISION := 3.0;    -- Limiar de ZVU estrito (erro circular CEP)

  v_veiculo            RECORD;
  v_ultima_telem       RECORD;
  v_dist_metros        DOUBLE PRECISION := 0.0;
  v_dist_geom          DOUBLE PRECISION := 0.0;
  v_dist_trap_m        DOUBLE PRECISION := 0.0;
  v_delta_km           NUMERIC(12, 4)   := 0.0;
  v_novo_odometro      NUMERIC(12, 3);
  v_status_op          TEXT;
  v_dlat               DOUBLE PRECISION;
  v_dlon               DOUBLE PRECISION;
  v_a_hav              DOUBLE PRECISION;
  v_lat_med_rad        DOUBLE PRECISION;
  v_cos_lat            DOUBLE PRECISION;
  v_sin_lat            DOUBLE PRECISION;
  v_raio_local         DOUBLE PRECISION;
  v_delta_sec          DOUBLE PRECISION := 0.0;
  v_vel_calc_kmh       DOUBLE PRECISION := 0.0;
  v_delta_rumo         INT              := 0;
  v_limiar_m           NUMERIC;
  v_viagem_ativa_id    UUID;
  v_descartado         BOOLEAN          := FALSE;
  v_motivo_descarte    TEXT             := NULL;
  v_fusao_aplicada     BOOLEAN          := FALSE;
BEGIN
  -- ── 1. Trava atômica do veículo ──────────────────────────────────────────
  SELECT id, ultima_latitude, ultima_longitude, odometro_km, ultima_atualizacao
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado');
  END IF;

  v_novo_odometro := COALESCE(v_veiculo.odometro_km, 0);

  -- ── 2. Validação Estrita de Fix GNSS (Módulo 1) ───────────────────────────
  -- Se o J16 reportar Course Status sem Fix GNSS (Bit 12 = 0), descarta da odometria
  IF NOT COALESCE(p_gps_fixado, TRUE) THEN
    v_descartado      := TRUE;
    v_motivo_descarte := 'sem_fix_gnss_lbs';
  END IF;

  -- ── 3. Validação Geográfica (Brasil) ──────────────────────────────────────
  IF NOT v_descartado THEN
    IF p_latitude = 0.0 AND p_longitude = 0.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'coordenada_zero';
    ELSIF p_latitude NOT BETWEEN -35.0 AND 5.5
       OR p_longitude NOT BETWEEN -74.0 AND -28.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'fora_brasil';
    END IF;
  END IF;

  -- ── 4. Cálculo Geodésico WGS-84 com Raio Local (Módulo 3) ────────────────
  IF NOT v_descartado
     AND v_veiculo.ultima_latitude  IS NOT NULL
     AND v_veiculo.ultima_longitude IS NOT NULL
     AND (v_veiculo.ultima_latitude  <> 0.0 OR v_veiculo.ultima_longitude <> 0.0)
  THEN
    -- 4a. Raio geocêntrico local WGS-84 na latitude média do deslocamento
    v_lat_med_rad := radians((p_latitude + v_veiculo.ultima_latitude) / 2.0);
    v_cos_lat     := cos(v_lat_med_rad);
    v_sin_lat     := sin(v_lat_med_rad);
    v_raio_local  := sqrt(
      (((c_a * c_a * v_cos_lat)^2) + ((c_b * c_b * v_sin_lat)^2))
      /
      (((c_a * v_cos_lat)^2)       + ((c_b * v_sin_lat)^2))
    );

    -- 4b. Distância Geodésica Haversine Elipsoidal
    v_dlat    := radians(p_latitude  - v_veiculo.ultima_latitude);
    v_dlon    := radians(p_longitude - v_veiculo.ultima_longitude);
    v_a_hav   := sin(v_dlat / 2.0)^2
               + cos(radians(v_veiculo.ultima_latitude))
               * cos(radians(p_latitude))
               * sin(v_dlon / 2.0)^2;
    v_dist_geom   := v_raio_local * 2.0 * atan2(sqrt(v_a_hav), sqrt(1.0 - v_a_hav));
    v_dist_metros := v_dist_geom;

    -- 4c. Intervalo temporal real (Δt) e busca de rumo/velocidade anteriores
    SELECT data_hora_gps, velocidade, rumo
    INTO v_ultima_telem
    FROM public.telemetria_posicoes
    WHERE veiculo_id = p_veiculo_id
    ORDER BY data_hora_gps DESC
    LIMIT 1;

    IF v_ultima_telem.data_hora_gps IS NOT NULL THEN
      v_delta_sec := GREATEST(0.0, EXTRACT(EPOCH FROM (p_data_hora_gps - v_ultima_telem.data_hora_gps)));
    ELSE
      v_delta_sec := 60.0;
    END IF;

    -- 4d. Filtro de Gaps Temporais Anômalos (> 180s)
    IF v_delta_sec > c_gap_max_s THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'gap_temporal_' || round(v_delta_sec) || 's';

    -- 4e. Spike Geodésico (> 195 km/h sem respaldo de velocidade de hardware)
    ELSIF v_delta_sec > 0.5 THEN
      v_vel_calc_kmh := (v_dist_metros / v_delta_sec) * 3.6;
      IF v_vel_calc_kmh > c_spike_kmh AND (p_velocidade IS NULL OR p_velocidade < 160.0) THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'spike_gps_' || round(v_vel_calc_kmh) || 'kmh';
      END IF;
    END IF;

    -- 4f. Zero-Velocity Update (ZVU Estrito): velocidade = 0 ou deslocamento < 3m
    IF NOT v_descartado THEN
      IF (p_velocidade IS NULL OR p_velocidade <= 0.5) OR v_dist_metros < c_zvu_m THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'zvu_estrito_' || round(v_dist_metros::NUMERIC, 1) || 'm';
      END IF;
    END IF;

    -- 4g. Distância máxima implausível (> 15 km num único pacote)
    IF NOT v_descartado AND v_dist_metros >= c_dist_max_m THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'dist_implausivel_' || round(v_dist_metros) || 'm';
    END IF;

    -- 4h. Integração Numérica Trapezoidal de Velocidade e Fusão Inercial em Curvas
    IF NOT v_descartado AND v_delta_sec > 0.5 AND v_delta_sec <= c_gap_max_s AND p_velocidade > 2.5 THEN
      -- Integração trapezoidal da velocidade Doppler: s_trap = ((v1 + v2) / 7.2) * Δt
      v_dist_trap_m := ((p_velocidade + COALESCE(v_ultima_telem.velocidade, p_velocidade)) / 7.2) * v_delta_sec;

      -- Variação angular de rumo entre os pacotes
      IF v_ultima_telem.rumo IS NOT NULL AND p_rumo IS NOT NULL THEN
        v_delta_rumo := ABS(p_rumo - v_ultima_telem.rumo);
        IF v_delta_rumo > 180 THEN
          v_delta_rumo := 360 - v_delta_rumo;
        END IF;
      ELSE
        v_delta_rumo := 0;
      END IF;

      -- Critério de Fusão Inercial:
      -- Em curvas (Δrumo >= 8° e v > 3 km/h), a corda seca geodésica subestima o arco real da pista.
      -- Prioriza o deslocamento inercial das rodas (v_dist_trap_m), limitado com segurança física a 1.35x a corda.
      IF v_delta_rumo >= 8 AND v_dist_trap_m > v_dist_geom THEN
        IF v_dist_trap_m <= (v_dist_geom * 1.35) THEN
          v_dist_metros    := v_dist_trap_m;
          v_fusao_aplicada := TRUE;
        ELSE
          v_dist_metros    := v_dist_geom * 1.35;
          v_fusao_aplicada := TRUE;
        END IF;
      END IF;
    END IF;

    -- 4i. Acumulação no Odômetro Vitalício
    IF NOT v_descartado THEN
      v_limiar_m := CASE WHEN p_velocidade > 3.0 THEN 1.5 ELSE 5.0 END;
      IF v_dist_metros >= v_limiar_m THEN
        v_delta_km      := (v_dist_metros / 1000.0);
        v_novo_odometro := ROUND((v_novo_odometro + v_delta_km)::NUMERIC, 3);
      ELSE
        v_descartado      := TRUE;
        v_motivo_descarte := COALESCE(v_motivo_descarte, 'limiar_' || round(v_dist_metros::NUMERIC, 1) || 'm');
      END IF;
    END IF;
  END IF;

  -- ── 5. Determinação do Status Operacional ──────────────────────────────────
  v_status_op := CASE
    WHEN p_velocidade > 3.0  THEN 'em_movimento'
    WHEN p_ignicao           THEN 'parado_ligado'
    ELSE                          'estacionado'
  END;

  -- ── 6. Persistência Histórica em telemetria_posicoes ───────────────────────
  IF p_latitude <> 0.0 OR p_longitude <> 0.0 THEN
    INSERT INTO public.telemetria_posicoes (
      veiculo_id,
      rastreador_id,
      latitude,
      longitude,
      velocidade,
      ignicao,
      odometro,
      satelites,
      rumo,
      data_hora_gps,
      inclinacao_graus,
      vibracao_g,
      bateria_veiculo_v,
      bateria_rastreador_pct,
      bateria_rastreador_status,
      sinal_gsm,
      gps_fixado
    ) VALUES (
      p_veiculo_id,
      p_rastreador_id,
      p_latitude,
      p_longitude,
      p_velocidade,
      p_ignicao,
      v_novo_odometro,
      p_satelites,
      p_rumo,
      p_data_hora_gps,
      COALESCE(p_inclinacao_graus, 0),
      COALESCE(p_vibracao_g, 0.0),
      p_bateria_veiculo_v,
      p_bateria_rastreador_pct,
      p_bateria_rastreador_status,
      p_sinal_gsm,
      COALESCE(p_gps_fixado, TRUE)
    )
    ON CONFLICT DO NOTHING;
  END IF;

  -- ── 7. Atualização de Estado no Veículo ────────────────────────────────────
  UPDATE public.veiculos
  SET
    ultima_latitude          = p_latitude,
    ultima_longitude         = p_longitude,
    velocidade_atual         = p_velocidade,
    ignicao_status           = p_ignicao,
    odometro_km              = v_novo_odometro,
    satelites                = p_satelites,
    rumo                     = p_rumo,
    inclinacao_graus         = COALESCE(p_inclinacao_graus, inclinacao_graus),
    vibracao_g               = COALESCE(p_vibracao_g, vibracao_g),
    bateria_veiculo_v        = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct   = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status= COALESCE(p_bateria_rastreador_status, bateria_rastreador_status),
    sinal_gsm                = COALESCE(p_sinal_gsm, sinal_gsm),
    gps_fixado               = COALESCE(p_gps_fixado, TRUE),
    status_operacional       = v_status_op,
    ultima_atualizacao       = p_data_hora_gps,
    updated_at               = NOW()
  WHERE id = p_veiculo_id;

  -- ── 8. Acumulação Atômica em Viagem Ativa (viagens_trajetos) ───────────────
  IF v_delta_km > 0 THEN
    SELECT id INTO v_viagem_ativa_id
    FROM public.viagens_trajetos
    WHERE veiculo_id = p_veiculo_id
      AND status = 'em_andamento'
    ORDER BY inicio_at DESC
    LIMIT 1;

    IF v_viagem_ativa_id IS NOT NULL THEN
      UPDATE public.viagens_trajetos
      SET
        km_percorrido    = ROUND((COALESCE(km_percorrido, 0) + v_delta_km)::NUMERIC, 3),
        velocidade_maxima= GREATEST(COALESCE(velocidade_maxima, 0), ROUND(p_velocidade)),
        atualizado_em    = NOW()
      WHERE id = v_viagem_ativa_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso',          true,
    'novo_odometro',    v_novo_odometro,
    'delta_km',         ROUND(v_delta_km::NUMERIC, 4),
    'dist_metros',      ROUND(v_dist_metros::NUMERIC, 2),
    'dist_geom',        ROUND(v_dist_geom::NUMERIC, 2),
    'dist_trap',        ROUND(v_dist_trap_m::NUMERIC, 2),
    'fusao_aplicada',   v_fusao_aplicada,
    'delta_rumo',       v_delta_rumo,
    'descartado',       v_descartado,
    'motivo_descarte',  v_motivo_descarte,
    'delta_sec',        ROUND(v_delta_sec::NUMERIC, 1),
    'raio_local_m',     ROUND(v_raio_local::NUMERIC),
    'gps_fixado',       COALESCE(p_gps_fixado, TRUE),
    'status_operacional', v_status_op
  );
END;
$$;

