-- ============================================================================
-- [151/225] MIGRAÇÃO: 20261016153000_hunter_odometria_anti_superestimacao.sql
-- ============================================================================

-- ============================================================================
-- Hunter: Motor de Odometria de Precisão Cirúrgica (Métrica Elipsoidal WGS-84 & Anti-Superestimação)
-- ============================================================================
-- CAUSAS RAIZ DIAGNOSTICADAS E SANADAS:
--   1. Geodésia Elipsoidal: Substituição do modelo esférico/geocêntrico (Haversine com
--      raio geocêntrico r=6375km) pela Métrica Diferencial Elipsoidal Gauss/WGS-84
--      com raios de curvatura reais M(φ) (meridional) e N(φ) (primeiro vertical).
--      Elimina o desvio sistemático de até +0.48% Norte-Sul e +0.19% isotrópico.
--   2. Fusão Inercial Cirúrgica: Teto físico inegociável no arco circular geométrico exato:
--      d_arc = d_geom * (θ/2) / sin(θ/2). A distância jamais excede d_arc,
--      impedindo que acelerações ou ruído de antena injetem quilometragem fantasma.
--   3. ZVU (Zero-Velocity Update) Estrito: se ignição desligada, ou vel < 2.0 km/h,
--      ou dist < 3.5m -> descarte total de ruído de antena (0.00m acumulados).
--   4. Sincronização do Veículo AXH0E44 para 183.341 km (valor físico cravado no painel).
-- ============================================================================

-- Garante existência da coluna de fator individual em veiculos
ALTER TABLE public.veiculos
  ADD COLUMN IF NOT EXISTS fator_calibracao_odometro NUMERIC(8, 6) DEFAULT 1.000000;

-- Remover assinaturas anteriores
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text, integer);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, timestamp with time zone, numeric, numeric, numeric, numeric);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, timestamp with time zone, numeric, numeric, numeric, numeric, integer);
DROP FUNCTION IF EXISTS public.registrar_posicao_gps_com_odometro(uuid, uuid, double precision, double precision, numeric, boolean, integer, integer, timestamp with time zone, integer, numeric, numeric, integer, text, integer, boolean);

CREATE OR REPLACE FUNCTION public.registrar_posicao_gps_com_odometro(
  p_veiculo_id            UUID,
  p_rastreador_id         UUID        DEFAULT NULL,
  p_latitude              DOUBLE PRECISION DEFAULT 0.0,
  p_longitude             DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade            NUMERIC     DEFAULT 0,
  p_ignicao               BOOLEAN     DEFAULT FALSE,
  p_satelites             INT         DEFAULT 0,
  p_rumo                  INT         DEFAULT 0,
  p_data_hora_gps         TIMESTAMPTZ DEFAULT NOW(),
  p_inclinacao_graus      INT         DEFAULT 0,
  p_vibracao_g            NUMERIC     DEFAULT 0.0,
  p_bateria_veiculo_v     NUMERIC     DEFAULT NULL,
  p_bateria_rastreador_pct INT        DEFAULT NULL,
  p_bateria_rastreador_status TEXT    DEFAULT NULL,
  p_sinal_gsm             INT         DEFAULT NULL,
  p_gps_fixado            BOOLEAN     DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  -- Constantes WGS-84 oficiais (metros)
  c_a          CONSTANT DOUBLE PRECISION := 6378137.0;            -- Semi-eixo maior WGS-84
  c_b          CONSTANT DOUBLE PRECISION := 6356752.314245;       -- Semi-eixo menor WGS-84
  c_e2         CONSTANT DOUBLE PRECISION := 0.00669437999014;     -- Excentricidade ao quadrado (a^2 - b^2)/a^2
  -- Parâmetros de filtragem física e cinemática
  c_gap_max_s  CONSTANT NUMERIC          := 180.0;  -- Gap máximo entre pacotes consecutivos (s)
  c_spike_kmh  CONSTANT NUMERIC          := 190.0;  -- Velocidade calculada de spike anômalo (km/h)
  c_dist_max_m CONSTANT NUMERIC          := 15000.0;-- Distância máxima permitida num único pacote (m)
  c_zvu_m      CONSTANT DOUBLE PRECISION := 3.5;    -- Limiar ZVU de deslocamento mínimo (m)
  c_zvu_vel    CONSTANT NUMERIC          := 2.0;    -- Limiar ZVU de velocidade (piso Doppler GNSS)

  v_veiculo            RECORD;
  v_ultima_telem       RECORD;
  v_dist_metros        DOUBLE PRECISION := 0.0;
  v_dist_geom          DOUBLE PRECISION := 0.0;
  v_dist_trap_m        DOUBLE PRECISION := 0.0;
  v_delta_km           NUMERIC(12, 4)   := 0.0;
  v_novo_odometro      NUMERIC(12, 3);
  v_status_op          TEXT;
  v_dlat               DOUBLE PRECISION;
  v_dlon               DOUBLE PRECISION;
  v_lat_med_rad        DOUBLE PRECISION;
  v_cos_lat            DOUBLE PRECISION;
  v_sin_lat            DOUBLE PRECISION;
  v_w2                 DOUBLE PRECISION;
  v_w                  DOUBLE PRECISION;
  v_m_meridiano        DOUBLE PRECISION;
  v_n_normal           DOUBLE PRECISION;
  v_delta_sec          DOUBLE PRECISION := 0.0;
  v_vel_calc_kmh       DOUBLE PRECISION := 0.0;
  v_delta_rumo         INT              := 0;
  v_half_angle_rad     DOUBLE PRECISION;
  v_arc_dist           DOUBLE PRECISION;
  v_limiar_m           NUMERIC;
  v_viagem_ativa_id    UUID;
  v_descartado         BOOLEAN          := FALSE;
  v_motivo_descarte    TEXT             := NULL;
  v_fusao_aplicada     BOOLEAN          := FALSE;
  v_fator_veiculo      NUMERIC(8, 6)    := 1.000000;
BEGIN
  -- ── 1. Trava atômica do veículo ──────────────────────────────────────────
  SELECT id, ultima_latitude, ultima_longitude, odometro_km, ultima_atualizacao,
         fator_calibracao_odometro
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado');
  END IF;

  v_novo_odometro := COALESCE(v_veiculo.odometro_km, 0);

  -- Fator de calibração individual do veículo (blindagem de segurança 0.85 a 1.15)
  IF v_veiculo.fator_calibracao_odometro IS NOT NULL
     AND v_veiculo.fator_calibracao_odometro BETWEEN 0.850000 AND 1.150000 THEN
    v_fator_veiculo := v_veiculo.fator_calibracao_odometro;
  ELSE
    v_fator_veiculo := 1.000000;
  END IF;

  -- ── 2. Validação Estrita de Fix GNSS (Módulo 1) ───────────────────────────
  IF NOT COALESCE(p_gps_fixado, TRUE) THEN
    v_descartado      := TRUE;
    v_motivo_descarte := 'sem_fix_gnss_lbs';
  END IF;

  -- ── 3. Validação Geográfica (Brasil) ──────────────────────────────────────
  IF NOT v_descartado THEN
    IF p_latitude = 0.0 AND p_longitude = 0.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'coordenada_zero';
    ELSIF p_latitude NOT BETWEEN -35.0 AND 5.5
       OR p_longitude NOT BETWEEN -74.0 AND -28.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'fora_brasil';
    END IF;
  END IF;

  -- ── 4. Cálculo Geodésico Elipsoidal WGS-84 com Raios de Curvatura Reais ──
  IF NOT v_descartado
     AND v_veiculo.ultima_latitude  IS NOT NULL
     AND v_veiculo.ultima_longitude IS NOT NULL
     AND (v_veiculo.ultima_latitude  <> 0.0 OR v_veiculo.ultima_longitude <> 0.0)
  THEN
    -- 4a. Métrica Diferencial Elipsoidal Gauss/WGS-84 de Alta Precisão
    v_lat_med_rad := radians((p_latitude + v_veiculo.ultima_latitude) / 2.0);
    v_cos_lat     := cos(v_lat_med_rad);
    v_sin_lat     := sin(v_lat_med_rad);
    v_w2          := 1.0 - (c_e2 * v_sin_lat * v_sin_lat);
    v_w           := sqrt(v_w2);

    -- M(φ): Raio de curvatura do meridiano (deslocamento Norte-Sul)
    v_m_meridiano := (c_a * (1.0 - c_e2)) / (v_w * v_w2);
    -- N(φ): Raio de curvatura do primeiro vertical (deslocamento Leste-Oeste)
    v_n_normal    := c_a / v_w;

    v_dlat        := radians(p_latitude  - v_veiculo.ultima_latitude);
    v_dlon        := radians(p_longitude - v_veiculo.ultima_longitude);
    v_dist_geom   := sqrt(((v_m_meridiano * v_dlat)^2) + ((v_n_normal * v_cos_lat * v_dlon)^2));
    v_dist_metros := v_dist_geom;

    -- 4b. Intervalo temporal real (Δt) e busca de rumo/velocidade anteriores
    SELECT data_hora_gps, velocidade, rumo
    INTO v_ultima_telem
    FROM public.telemetria_posicoes
    WHERE veiculo_id = p_veiculo_id
    ORDER BY data_hora_gps DESC
    LIMIT 1;

    IF v_ultima_telem.data_hora_gps IS NOT NULL THEN
      v_delta_sec := GREATEST(0.0, EXTRACT(EPOCH FROM (p_data_hora_gps - v_ultima_telem.data_hora_gps)));
    ELSE
      v_delta_sec := 60.0;
    END IF;

    -- 4c. Filtro de Gaps Temporais Anômalos (> 180s)
    IF v_delta_sec > c_gap_max_s THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'gap_temporal_' || round(v_delta_sec) || 's';

    -- 4d. Spike Geodésico (> 190 km/h sem respaldo de velocidade de hardware)
    ELSIF v_delta_sec > 0.5 THEN
      v_vel_calc_kmh := (v_dist_metros / v_delta_sec) * 3.6;
      IF v_vel_calc_kmh > c_spike_kmh AND (p_velocidade IS NULL OR p_velocidade < 160.0) THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'spike_gps_' || round(v_vel_calc_kmh) || 'kmh';
      END IF;
    END IF;

    -- 4e. Zero-Velocity Update Estrito (ZVU Cirúrgico):
    --     Se ignição desligada, ou velocidade < 2.0 km/h, ou deslocamento < 3.5m
    --     -> 0.00m acumulados (elimina random walk positivo e ruído térmico)
    IF NOT v_descartado THEN
      IF NOT COALESCE(p_ignicao, TRUE)
         OR (p_velocidade IS NULL OR p_velocidade < c_zvu_vel)
         OR v_dist_metros < c_zvu_m THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'zvu_estrito_' || round(v_dist_metros::NUMERIC, 1) || 'm_v' || round(COALESCE(p_velocidade, 0)::NUMERIC, 1);
      END IF;
    END IF;

    -- 4f. Distância máxima implausível (> 15 km num único pacote)
    IF NOT v_descartado AND v_dist_metros >= c_dist_max_m THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'dist_implausivel_' || round(v_dist_metros) || 'm';
    END IF;

    -- 4g. Fusão Inercial Cirúrgica em Curvas (Cap no Arco Circular Geométrico Exato)
    --     Calcula d_arc = d_geom * (θ/2) / sin(θ/2).
    --     Teto físico inegociável: a distância NUNCA excede d_arc, impedindo
    --     que acelerações em reta ou ruído de antena injetem km fantasma.
    IF NOT v_descartado AND v_delta_sec > 0.5 AND v_delta_sec <= c_gap_max_s AND p_velocidade > 2.5 THEN
      v_dist_trap_m := ((p_velocidade + COALESCE(v_ultima_telem.velocidade, p_velocidade)) / 7.2) * v_delta_sec;

      -- Variação angular de rumo entre os pacotes
      IF v_ultima_telem.rumo IS NOT NULL AND p_rumo IS NOT NULL THEN
        v_delta_rumo := ABS(p_rumo - v_ultima_telem.rumo);
        IF v_delta_rumo > 180 THEN
          v_delta_rumo := 360 - v_delta_rumo;
        END IF;
      ELSE
        v_delta_rumo := 0;
      END IF;

      -- Apenas para curvas reais (Δrumo >= 10°):
      IF v_delta_rumo >= 10 THEN
        v_half_angle_rad := radians(v_delta_rumo / 2.0);
        IF sin(v_half_angle_rad) > 0.001 THEN
          v_arc_dist := v_dist_geom * (v_half_angle_rad / sin(v_half_angle_rad));
          IF v_dist_trap_m > v_dist_geom AND v_dist_trap_m <= v_arc_dist THEN
            v_dist_metros    := v_dist_trap_m;
            v_fusao_aplicada := TRUE;
          ELSE
            v_dist_metros    := v_arc_dist;
            v_fusao_aplicada := TRUE;
          END IF;
        END IF;
      END IF;
    END IF;

    -- 4h. Acumulação no Odômetro Vitalício com Fator Individual
    IF NOT v_descartado THEN
      v_limiar_m := CASE WHEN p_velocidade > 5.0 THEN 3.0 ELSE 5.0 END;
      IF v_dist_metros >= v_limiar_m THEN
        v_delta_km      := (v_dist_metros / 1000.0) * v_fator_veiculo;
        v_novo_odometro := ROUND((v_novo_odometro + v_delta_km)::NUMERIC, 3);
      ELSE
        v_descartado      := TRUE;
        v_motivo_descarte := COALESCE(v_motivo_descarte, 'limiar_' || round(v_dist_metros::NUMERIC, 1) || 'm');
      END IF;
    END IF;
  END IF;

  -- ── 5. Determinação do Status Operacional ──────────────────────────────────
  v_status_op := CASE
    WHEN p_velocidade > 3.0  THEN 'em_movimento'
    WHEN p_ignicao           THEN 'parado_ligado'
    ELSE                          'estacionado'
  END;

  -- ── 6. Persistência Histórica em telemetria_posicoes ───────────────────────
  IF p_latitude <> 0.0 OR p_longitude <> 0.0 THEN
    INSERT INTO public.telemetria_posicoes (
      veiculo_id,
      rastreador_id,
      latitude,
      longitude,
      velocidade,
      ignicao,
      odometro,
      satelites,
      rumo,
      data_hora_gps,
      inclinacao_graus,
      vibracao_g,
      bateria_veiculo_v,
      bateria_rastreador_pct,
      bateria_rastreador_status,
      sinal_gsm,
      gps_fixado
    ) VALUES (
      p_veiculo_id,
      p_rastreador_id,
      p_latitude,
      p_longitude,
      p_velocidade,
      p_ignicao,
      v_novo_odometro,
      p_satelites,
      p_rumo,
      p_data_hora_gps,
      COALESCE(p_inclinacao_graus, 0),
      COALESCE(p_vibracao_g, 0.0),
      p_bateria_veiculo_v,
      p_bateria_rastreador_pct,
      p_bateria_rastreador_status,
      p_sinal_gsm,
      COALESCE(p_gps_fixado, TRUE)
    )
    ON CONFLICT DO NOTHING;
  END IF;

  -- ── 7. Atualização de Estado no Veículo ────────────────────────────────────
  UPDATE public.veiculos
  SET
    ultima_latitude          = p_latitude,
    ultima_longitude         = p_longitude,
    velocidade_atual         = p_velocidade,
    ignicao_status           = p_ignicao,
    odometro_km              = v_novo_odometro,
    satelites                = p_satelites,
    rumo                     = p_rumo,
    inclinacao_graus         = COALESCE(p_inclinacao_graus, inclinacao_graus),
    vibracao_g               = COALESCE(p_vibracao_g, vibracao_g),
    bateria_veiculo_v        = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct   = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status= COALESCE(p_bateria_rastreador_status, bateria_rastreador_status),
    sinal_gsm                = COALESCE(p_sinal_gsm, sinal_gsm),
    gps_fixado               = COALESCE(p_gps_fixado, TRUE),
    status_operacional       = v_status_op,
    ultima_atualizacao       = p_data_hora_gps,
    updated_at               = NOW()
  WHERE id = p_veiculo_id;

  -- ── 8. Acumulação Atômica em Viagem Ativa (viagens_trajetos) ───────────────
  IF v_delta_km > 0 THEN
    SELECT id INTO v_viagem_ativa_id
    FROM public.viagens_trajetos
    WHERE veiculo_id = p_veiculo_id
      AND status = 'em_andamento'
    ORDER BY inicio_at DESC
    LIMIT 1;

    IF v_viagem_ativa_id IS NOT NULL THEN
      UPDATE public.viagens_trajetos
      SET
        km_percorrido    = ROUND((COALESCE(km_percorrido, 0) + v_delta_km)::NUMERIC, 3),
        velocidade_maxima= GREATEST(COALESCE(velocidade_maxima, 0), ROUND(p_velocidade)),
        atualizado_em    = NOW()
      WHERE id = v_viagem_ativa_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso',          true,
    'novo_odometro',    v_novo_odometro,
    'delta_km',         ROUND(v_delta_km::NUMERIC, 4),
    'dist_metros',      ROUND(v_dist_metros::NUMERIC, 2),
    'dist_geom',        ROUND(v_dist_geom::NUMERIC, 2),
    'dist_trap',        ROUND(v_dist_trap_m::NUMERIC, 2),
    'fusao_aplicada',   v_fusao_aplicada,
    'fator_veiculo',    v_fator_veiculo,
    'delta_rumo',       v_delta_rumo,
    'descartado',       v_descartado,
    'motivo_descarte',  v_motivo_descarte,
    'delta_sec',        ROUND(v_delta_sec::NUMERIC, 1),
    'gps_fixado',       COALESCE(p_gps_fixado, TRUE),
    'status_operacional', v_status_op
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO authenticated;
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO anon;
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO service_role;

-- ── 9. Sincronização Cirúrgica do Odômetro com o Painel Físico Real (AXH0E44) ───
UPDATE public.veiculos
SET
  odometro_km = 183341.000,
  updated_at  = NOW()
WHERE placa = 'AXH0E44' OR id = '3f2e1d2b-ca96-420e-88a5-c33fd98b689d';

NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [152/225] MIGRAÇÃO: 20261016170500_hunter_ancora_veiculo_estacionado_anti_deriva.sql
-- ============================================================================

-- ============================================================================
-- HUNTER / GD RASTREAMENTO — ÂNCORA DE VEÍCULO ESTACIONADO E BLINDAGEM ANTI-DERIVA
-- ============================================================================
-- Versão Alvo: 1.11.0.179
-- Root Cause: Quando um veículo está estacionado com a chave desligada (ACC OFF),
--             a oscilação natural/térmica da constelação GNSS ou reflexão de sinal
--             (multipath) em garagens ou cânions urbanos pode gerar pequenas variações
--             de coordenadas (ex: 50m a 130m). Se a função registrar_posicao_gps_com_odometro
--             sobrescrever ultima_latitude e ultima_longitude no veículo enquanto
--             ele está parado (ignição desligada e velocidade 0 km/h), o carro salta
--             no mapa para outra rua ou vizinhança.
--             Além disso, se o alarme interno de deslocamento do hardware (MOVING)
--             for disparado por deriva com velocidade zero, deve ser descartado
--             como falso positivo de reboque.
--
-- Fix Canônico:
-- 1. Na função registrar_posicao_gps_com_odometro, se ignição for desligada e
--    velocidade <= 2.0 km/h, a coordenada âncora anterior é preservada rigidamente,
--    impedindo qualquer salto no mapa com o carro estacionado.
-- 2. Invalidação de schema cache via NOTIFY pgrst.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.registrar_posicao_gps_com_odometro(
  p_veiculo_id            UUID,
  p_rastreador_id         UUID        DEFAULT NULL,
  p_latitude              DOUBLE PRECISION DEFAULT 0.0,
  p_longitude             DOUBLE PRECISION DEFAULT 0.0,
  p_velocidade            NUMERIC     DEFAULT 0,
  p_ignicao               BOOLEAN     DEFAULT FALSE,
  p_satelites             INT         DEFAULT 0,
  p_rumo                  INT         DEFAULT 0,
  p_data_hora_gps         TIMESTAMPTZ DEFAULT NOW(),
  p_inclinacao_graus      INT         DEFAULT 0,
  p_vibracao_g            NUMERIC     DEFAULT 0.0,
  p_bateria_veiculo_v     NUMERIC     DEFAULT NULL,
  p_bateria_rastreador_pct INT        DEFAULT NULL,
  p_bateria_rastreador_status TEXT    DEFAULT NULL,
  p_sinal_gsm             INT         DEFAULT NULL,
  p_gps_fixado            BOOLEAN     DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  -- Constantes WGS-84 oficiais (metros)
  c_a          CONSTANT DOUBLE PRECISION := 6378137.0;            -- Semi-eixo maior WGS-84
  c_b          CONSTANT DOUBLE PRECISION := 6356752.314245;       -- Semi-eixo menor WGS-84
  c_e2         CONSTANT DOUBLE PRECISION := 0.00669437999014;     -- Excentricidade ao quadrado (a^2 - b^2)/a^2
  -- Parâmetros de filtragem física e cinemática
  c_gap_max_s  CONSTANT NUMERIC          := 180.0;  -- Gap máximo entre pacotes consecutivos (s)
  c_spike_kmh  CONSTANT NUMERIC          := 190.0;  -- Velocidade calculada de spike anômalo (km/h)
  c_dist_max_m CONSTANT NUMERIC          := 15000.0;-- Distância máxima permitida num único pacote (m)
  c_zvu_m      CONSTANT DOUBLE PRECISION := 3.5;    -- Limiar ZVU de deslocamento mínimo (m)
  c_zvu_vel    CONSTANT NUMERIC          := 2.0;    -- Limiar ZVU de velocidade (piso Doppler GNSS)

  v_veiculo            RECORD;
  v_ultima_telem       RECORD;
  v_dist_metros        DOUBLE PRECISION := 0.0;
  v_dist_geom          DOUBLE PRECISION := 0.0;
  v_dist_trap_m        DOUBLE PRECISION := 0.0;
  v_delta_km           NUMERIC(12, 4)   := 0.0;
  v_novo_odometro      NUMERIC(12, 3);
  v_status_op          TEXT;
  v_dlat               DOUBLE PRECISION;
  v_dlon               DOUBLE PRECISION;
  v_lat_med_rad        DOUBLE PRECISION;
  v_cos_lat            DOUBLE PRECISION;
  v_sin_lat            DOUBLE PRECISION;
  v_w2                 DOUBLE PRECISION;
  v_w                  DOUBLE PRECISION;
  v_m_meridiano        DOUBLE PRECISION;
  v_n_normal           DOUBLE PRECISION;
  v_delta_sec          DOUBLE PRECISION := 0.0;
  v_vel_calc_kmh       DOUBLE PRECISION := 0.0;
  v_delta_rumo         INT              := 0;
  v_half_angle_rad     DOUBLE PRECISION;
  v_arc_dist           DOUBLE PRECISION;
  v_limiar_m           NUMERIC;
  v_viagem_ativa_id    UUID;
  v_descartado         BOOLEAN          := FALSE;
  v_motivo_descarte    TEXT             := NULL;
  v_fusao_aplicada     BOOLEAN          := FALSE;
  v_fator_veiculo      NUMERIC(8, 6)    := 1.000000;
BEGIN
  -- ── 1. Trava atômica do veículo ──────────────────────────────────────────
  SELECT id, ultima_latitude, ultima_longitude, odometro_km, ultima_atualizacao,
         fator_calibracao_odometro
  INTO v_veiculo
  FROM public.veiculos
  WHERE id = p_veiculo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Veículo não encontrado');
  END IF;

  v_novo_odometro := COALESCE(v_veiculo.odometro_km, 0);

  -- Fator de calibração individual do veículo (blindagem de segurança 0.85 a 1.15)
  IF v_veiculo.fator_calibracao_odometro IS NOT NULL
     AND v_veiculo.fator_calibracao_odometro BETWEEN 0.850000 AND 1.150000 THEN
    v_fator_veiculo := v_veiculo.fator_calibracao_odometro;
  ELSE
    v_fator_veiculo := 1.000000;
  END IF;

  -- ── 2. Validação Estrita de Fix GNSS (Módulo 1) ───────────────────────────
  IF NOT COALESCE(p_gps_fixado, TRUE) THEN
    v_descartado      := TRUE;
    v_motivo_descarte := 'sem_fix_gnss_lbs';
  END IF;

  -- ── 3. Validação Geográfica (Brasil) ──────────────────────────────────────
  IF NOT v_descartado THEN
    IF p_latitude = 0.0 AND p_longitude = 0.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'coordenada_zero';
    ELSIF p_latitude NOT BETWEEN -35.0 AND 5.5
       OR p_longitude NOT BETWEEN -74.0 AND -28.0 THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'fora_brasil';
    END IF;
  END IF;

  -- ── 4. Cálculo Geodésico Elipsoidal WGS-84 com Raios de Curvatura Reais ──
  IF NOT v_descartado
     AND v_veiculo.ultima_latitude  IS NOT NULL
     AND v_veiculo.ultima_longitude IS NOT NULL
     AND (v_veiculo.ultima_latitude  <> 0.0 OR v_veiculo.ultima_longitude <> 0.0)
  THEN
    -- 4a. Métrica Diferencial Elipsoidal Gauss/WGS-84 de Alta Precisão
    v_lat_med_rad := radians((p_latitude + v_veiculo.ultima_latitude) / 2.0);
    v_cos_lat     := cos(v_lat_med_rad);
    v_sin_lat     := sin(v_lat_med_rad);
    v_w2          := 1.0 - (c_e2 * v_sin_lat * v_sin_lat);
    v_w           := sqrt(v_w2);

    -- M(φ): Raio de curvatura do meridiano (deslocamento Norte-Sul)
    v_m_meridiano := (c_a * (1.0 - c_e2)) / (v_w * v_w2);
    -- N(φ): Raio de curvatura do primeiro vertical (deslocamento Leste-Oeste)
    v_n_normal    := c_a / v_w;

    v_dlat        := radians(p_latitude  - v_veiculo.ultima_latitude);
    v_dlon        := radians(p_longitude - v_veiculo.ultima_longitude);
    v_dist_geom   := sqrt(((v_m_meridiano * v_dlat)^2) + ((v_n_normal * v_cos_lat * v_dlon)^2));
    v_dist_metros := v_dist_geom;

    -- 4b. Intervalo temporal real (Δt) e busca de rumo/velocidade anteriores
    SELECT data_hora_gps, velocidade, rumo
    INTO v_ultima_telem
    FROM public.telemetria_posicoes
    WHERE veiculo_id = p_veiculo_id
    ORDER BY data_hora_gps DESC
    LIMIT 1;

    IF v_ultima_telem.data_hora_gps IS NOT NULL THEN
      v_delta_sec := GREATEST(0.0, EXTRACT(EPOCH FROM (p_data_hora_gps - v_ultima_telem.data_hora_gps)));
    ELSE
      v_delta_sec := 60.0;
    END IF;

    -- 4c. Filtro de Gaps Temporais Anômalos (> 180s)
    IF v_delta_sec > c_gap_max_s THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'gap_temporal_' || round(v_delta_sec) || 's';

    -- 4d. Spike Geodésico (> 190 km/h sem respaldo de velocidade de hardware)
    ELSIF v_delta_sec > 0.5 THEN
      v_vel_calc_kmh := (v_dist_metros / v_delta_sec) * 3.6;
      IF v_vel_calc_kmh > c_spike_kmh AND (p_velocidade IS NULL OR p_velocidade < 160.0) THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'spike_gps_' || round(v_vel_calc_kmh) || 'kmh';
      END IF;
    END IF;

    -- 4e. Zero-Velocity Update Estrito (ZVU Cirúrgico):
    --     Se ignição desligada, ou velocidade < 2.0 km/h, ou deslocamento < 3.5m
    --     -> 0.00m acumulados (elimina random walk positivo e ruído térmico)
    IF NOT v_descartado THEN
      IF NOT COALESCE(p_ignicao, TRUE)
         OR (p_velocidade IS NULL OR p_velocidade < c_zvu_vel)
         OR v_dist_metros < c_zvu_m THEN
        v_descartado      := TRUE;
        v_motivo_descarte := 'zvu_estrito_' || round(v_dist_metros::NUMERIC, 1) || 'm_v' || round(COALESCE(p_velocidade, 0)::NUMERIC, 1);
      END IF;
    END IF;

    -- 4f. Distância máxima implausível (> 15 km num único pacote)
    IF NOT v_descartado AND v_dist_metros >= c_dist_max_m THEN
      v_descartado      := TRUE;
      v_motivo_descarte := 'dist_implausivel_' || round(v_dist_metros) || 'm';
    END IF;

    -- 4g. Fusão Inercial Cirúrgica em Curvas (Cap no Arco Circular Geométrico Exato)
    IF NOT v_descartado AND v_delta_sec > 0.5 AND v_delta_sec <= c_gap_max_s AND p_velocidade > 2.5 THEN
      v_dist_trap_m := ((p_velocidade + COALESCE(v_ultima_telem.velocidade, p_velocidade)) / 7.2) * v_delta_sec;

      IF v_ultima_telem.rumo IS NOT NULL AND p_rumo IS NOT NULL THEN
        v_delta_rumo := ABS(p_rumo - v_ultima_telem.rumo);
        IF v_delta_rumo > 180 THEN
          v_delta_rumo := 360 - v_delta_rumo;
        END IF;
      ELSE
        v_delta_rumo := 0;
      END IF;

      IF v_delta_rumo >= 10 THEN
        v_half_angle_rad := radians(v_delta_rumo / 2.0);
        IF sin(v_half_angle_rad) > 0.001 THEN
          v_arc_dist := v_dist_geom * (v_half_angle_rad / sin(v_half_angle_rad));
          IF v_dist_trap_m > v_dist_geom AND v_dist_trap_m <= v_arc_dist THEN
            v_dist_metros    := v_dist_trap_m;
            v_fusao_aplicada := TRUE;
          ELSE
            v_dist_metros    := v_arc_dist;
            v_fusao_aplicada := TRUE;
          END IF;
        END IF;
      END IF;
    END IF;

    -- 4h. Acumulação no Odômetro Vitalício com Fator Individual
    IF NOT v_descartado THEN
      v_limiar_m := CASE WHEN p_velocidade > 5.0 THEN 3.0 ELSE 5.0 END;
      IF v_dist_metros >= v_limiar_m THEN
        v_delta_km      := (v_dist_metros / 1000.0) * v_fator_veiculo;
        v_novo_odometro := ROUND((v_novo_odometro + v_delta_km)::NUMERIC, 3);
      ELSE
        v_descartado      := TRUE;
        v_motivo_descarte := COALESCE(v_motivo_descarte, 'limiar_' || round(v_dist_metros::NUMERIC, 1) || 'm');
      END IF;
    END IF;
  END IF;

  -- ── 5. Determinação do Status Operacional ──────────────────────────────────
  v_status_op := CASE
    WHEN p_velocidade > 3.0  THEN 'em_movimento'
    WHEN p_ignicao           THEN 'parado_ligado'
    ELSE                          'estacionado'
  END;

  -- ── 6. Persistência Histórica em telemetria_posicoes ───────────────────────
  IF p_latitude <> 0.0 OR p_longitude <> 0.0 THEN
    INSERT INTO public.telemetria_posicoes (
      veiculo_id,
      rastreador_id,
      latitude,
      longitude,
      velocidade,
      ignicao,
      odometro,
      satelites,
      rumo,
      data_hora_gps,
      inclinacao_graus,
      vibracao_g,
      bateria_veiculo_v,
      bateria_rastreador_pct,
      bateria_rastreador_status,
      sinal_gsm,
      gps_fixado
    ) VALUES (
      p_veiculo_id,
      p_rastreador_id,
      p_latitude,
      p_longitude,
      p_velocidade,
      p_ignicao,
      v_novo_odometro,
      p_satelites,
      p_rumo,
      p_data_hora_gps,
      COALESCE(p_inclinacao_graus, 0),
      COALESCE(p_vibracao_g, 0.0),
      p_bateria_veiculo_v,
      p_bateria_rastreador_pct,
      p_bateria_rastreador_status,
      p_sinal_gsm,
      COALESCE(p_gps_fixado, TRUE)
    )
    ON CONFLICT DO NOTHING;
  END IF;

  -- ── 7. Atualização de Estado no Veículo com Âncora de Estacionamento ───────
  -- Se o veículo estiver estacionado (ignição desligada e velocidade <= 2.0 km/h)
  -- e já possuir coordenadas anteriores válidas, mantém a coordenada âncora anterior.
  -- Isso impede que derivas de antena GNSS movam o carro parado no mapa!
  UPDATE public.veiculos
  SET
    ultima_latitude          = CASE
                                 WHEN NOT COALESCE(p_ignicao, TRUE)
                                      AND COALESCE(p_velocidade, 0) <= 2.0
                                      AND v_veiculo.ultima_latitude IS NOT NULL
                                      AND v_veiculo.ultima_latitude <> 0.0
                                 THEN v_veiculo.ultima_latitude
                                 ELSE p_latitude
                               END,
    ultima_longitude         = CASE
                                 WHEN NOT COALESCE(p_ignicao, TRUE)
                                      AND COALESCE(p_velocidade, 0) <= 2.0
                                      AND v_veiculo.ultima_longitude IS NOT NULL
                                      AND v_veiculo.ultima_longitude <> 0.0
                                 THEN v_veiculo.ultima_longitude
                                 ELSE p_longitude
                               END,
    velocidade_atual         = p_velocidade,
    ignicao_status           = p_ignicao,
    odometro_km              = v_novo_odometro,
    satelites                = p_satelites,
    rumo                     = p_rumo,
    inclinacao_graus         = COALESCE(p_inclinacao_graus, inclinacao_graus),
    vibracao_g               = COALESCE(p_vibracao_g, vibracao_g),
    bateria_veiculo_v        = COALESCE(p_bateria_veiculo_v, bateria_veiculo_v),
    bateria_rastreador_pct   = COALESCE(p_bateria_rastreador_pct, bateria_rastreador_pct),
    bateria_rastreador_status= COALESCE(p_bateria_rastreador_status, bateria_rastreador_status),
    sinal_gsm                = COALESCE(p_sinal_gsm, sinal_gsm),
    gps_fixado               = COALESCE(p_gps_fixado, TRUE),
    status_operacional       = v_status_op,
    ultima_atualizacao       = p_data_hora_gps,
    updated_at               = NOW()
  WHERE id = p_veiculo_id;

  -- ── 8. Acumulação Atômica em Viagem Ativa (viagens_trajetos) ───────────────
  IF v_delta_km > 0 THEN
    SELECT id INTO v_viagem_ativa_id
    FROM public.viagens_trajetos
    WHERE veiculo_id = p_veiculo_id
      AND status = 'em_andamento'
    ORDER BY inicio_at DESC
    LIMIT 1;

    IF v_viagem_ativa_id IS NOT NULL THEN
      UPDATE public.viagens_trajetos
      SET
        km_percorrido     = ROUND((COALESCE(km_percorrido, 0) + v_delta_km)::NUMERIC, 3),
        velocidade_maxima = GREATEST(COALESCE(velocidade_maxima, 0), p_velocidade),
        fim_at            = p_data_hora_gps
      WHERE id = v_viagem_ativa_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'sucesso',           true,
    'descartado',        v_descartado,
    'motivo_descarte',   v_motivo_descarte,
    'dist_metros',       ROUND(v_dist_metros::NUMERIC, 2),
    'dist_geom_m',       ROUND(v_dist_geom::NUMERIC, 2),
    'delta_km',          v_delta_km,
    'novo_odometro',     v_novo_odometro,
    'fusao_aplicada',    v_fusao_aplicada,
    'status_operacional',v_status_op
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO authenticated;
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO anon;
GRANT EXECUTE ON FUNCTION public.registrar_posicao_gps_com_odometro TO service_role;

NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [153/225] MIGRAÇÃO: 20261016193500_hunter_resolucao_canonica_kit_instalador.sql
-- ============================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Hunter — Resolução Canônica de Kit Atribuído para o Instalador (DJR-NEW)
-- ─────────────────────────────────────────────────────────────────────────────
-- Garante que quando o operador atribuir o kit (seja em instalacoes, veiculos ou clientes),
-- a RPC instalador_obter_minhas_demandas resolva o IMEI real do estoque, eliminando
-- a permanência indevida do estado "Aguardando Kit" e liberando "Conferir Kit" e "Instalar".
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.instalador_obter_minhas_demandas(
  p_instalador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_role TEXT;
  v_alvo_id UUID;
  v_ordens JSONB;
  v_agendamentos JSONB;
  v_resumo JSONB;
  v_total_a_receber NUMERIC(10,2);
  v_total_recebido NUMERIC(10,2);
  v_total_agendados_qtd INT;
  v_total_a_agendar_qtd INT;
  v_valor_previsto_agendados NUMERIC(10,2);
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_caller_id;

  IF v_role IN ('superadmin', 'adm', 'operador') THEN
    v_alvo_id := COALESCE(p_instalador_id, v_caller_id);
  ELSE
    v_alvo_id := v_caller_id;
  END IF;

  -- 1. Coletar Ordens de Instalação Atribuídas com Join em Rastreadores e Chips
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', i.id,
      'cliente_id', i.cliente_id,
      'veiculo_id', i.veiculo_id,
      'instalador_id', COALESCE(i.instalador_id, c.instalador_id),
      'placa', COALESCE(i.placa, v.placa, 'A DEFINIR'),
      'marca', COALESCE(i.marca, split_part(v.marca_modelo, ' ', 1), 'Geral'),
      'modelo', COALESCE(i.modelo, v.marca_modelo, 'Veículo'),
      'ano', COALESCE(i.ano, v.ano),
      'cor', COALESCE(i.cor, v.cor),
      'tipo_veiculo', COALESCE(i.tipo_veiculo, v.tipo_veiculo, 'carro'),
      'km_instalacao', COALESCE(i.km_instalacao, 0),
      'tipo_servico', COALESCE(i.tipo_servico, 'instalacao'),
      'valor_instalacao', i.valor_instalacao,
      'status_pagamento', i.status_pagamento,
      'bloqueador_instalado', COALESCE(i.bloqueador_instalado, false),
      'com_bloqueador', COALESCE(i.bloqueador_instalado, false),
      'status', i.status,
      'posicao_instalacao', i.posicao_instalacao,
      'posicaoInstalacao', i.posicao_instalacao,
      'rastreador_id', COALESCE(i.rastreador_id, v.rastreador_id, c.kit_determinado_id, r.id),
      'rastreador_imei', COALESCE(
        CASE WHEN UPPER(TRIM(i.rastreador_imei)) IN ('PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR', '') THEN NULL ELSE i.rastreador_imei END,
        r.imei,
        CASE WHEN UPPER(TRIM(v.rastreador_imei)) IN ('PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR', '') THEN NULL ELSE v.rastreador_imei END,
        i.rastreador_imei,
        'PENDENTE'
      ),
      'rastreador_modelo', COALESCE(i.rastreador_modelo, r.modelo, 'J16 4G'),
      'chip_iccid', COALESCE(i.chip_iccid, ch.iccid),
      'chip_operadora', COALESCE(i.chip_operadora, ch.operadora),
      'data_agendamento', COALESCE(i.data_agendamento, c.data_agendamento),
      'hora_agendamento', COALESCE(i.hora_agendamento, c.hora_agendamento),
      'local_tipo', COALESCE(i.local_tipo, 'oficina'),
      'local_endereco', i.local_endereco,
      'solicita_endereco_cliente', COALESCE(i.solicita_endereco_cliente, false),
      'endereco_cliente_informado', i.endereco_cliente_informado,
      'endereco_cliente_informado_em', i.endereco_cliente_informado_em,
      'solicitado_endereco_em', i.solicitado_endereco_em,
      'kit_determinado_em', COALESCE(i.kit_determinado_em, CASE WHEN r.id IS NOT NULL THEN NOW() ELSE NULL END),
      'kit_confirmado_instalador', COALESCE(i.kit_confirmado_instalador, false),
      'kit_confirmado_em', i.kit_confirmado_em,
      'imei_confirmado', i.imei_confirmado,
      'instalador_nome', COALESCE(p.nome, 'Instalador Técnico'),
      'instalador_chave_pix', p.chave_pix,
      'cliente_nome', COALESCE(c.nome_razao_social, 'Cliente'),
      'cliente_telefone', c.telefone,
      'cliente_documento', c.documento,
      'motivo_pendencia_recusa', i.motivo_pendencia_recusa,
      'observacoes', i.observacoes,
      'created_at', i.created_at,
      'updated_at', i.updated_at,
      'concluida_at', i.concluida_at
    ) ORDER BY i.created_at DESC
  ), '[]'::JSONB)
  INTO v_ordens
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  LEFT JOIN public.veiculos v ON v.id = i.veiculo_id
  LEFT JOIN public.profiles p ON p.id = COALESCE(i.instalador_id, c.instalador_id)
  LEFT JOIN public.rastreadores r ON r.id = COALESCE(i.rastreador_id, v.rastreador_id, c.kit_determinado_id)
  LEFT JOIN public.chips ch ON ch.id = r.chip_id
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR i.instalador_id = v_alvo_id
     OR (i.instalador_id IS NULL AND c.instalador_id = v_alvo_id);

  -- 2. Coletar Clientes Agendados ou Aguardando Agendamento
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'nome_razao_social', c.nome_razao_social,
      'documento', c.documento,
      'telefone', c.telefone,
      'email', c.email,
      'status', c.status,
      'plano', c.plano,
      'tem_fidelidade', c.tem_fidelidade,
      'regra_horimetro', c.regra_horimetro,
      'kit_determinado_id', c.kit_determinado_id,
      'status_agendamento', COALESCE(c.status_agendamento, 'aguardando_agendamento'),
      'data_agendamento', c.data_agendamento,
      'hora_agendamento', c.hora_agendamento,
      'instalador_id', COALESCE(c.instalador_id, v_alvo_id),
      'instalador', jsonb_build_object(
        'id', p.id,
        'nome', p.nome,
        'endereco_instalacao', p.endereco_instalacao,
        'valor_com_bloqueador', p.valor_instalacao_com_bloqueador,
        'valor_sem_bloqueador', p.valor_instalacao_sem_bloqueador
      ),
      'veiculos', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', v.id, 
          'placa', v.placa, 
          'modelo', v.marca_modelo, 
          'tipo_veiculo', v.tipo_veiculo,
          'horimetro_horas', v.horimetro_horas,
          'rastreador_id', COALESCE(v.rastreador_id, c.kit_determinado_id),
          'rastreador_imei', COALESCE(
            CASE WHEN UPPER(TRIM(v.rastreador_imei)) IN ('PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR', '') THEN NULL ELSE v.rastreador_imei END,
            rk.imei,
            v.rastreador_imei
          )
        ))
        FROM public.veiculos v
        LEFT JOIN public.rastreadores rk ON rk.id = COALESCE(v.rastreador_id, c.kit_determinado_id)
        WHERE v.cliente_id = c.id
      ), '[]'::JSONB)
    ) ORDER BY c.created_at DESC
  ), '[]'::JSONB)
  INTO v_agendamentos
  FROM public.clientes c
  LEFT JOIN public.profiles p ON p.id = COALESCE(c.instalador_id, v_alvo_id)
  WHERE (
    (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
    OR c.instalador_id = v_alvo_id
    OR EXISTS (SELECT 1 FROM public.instalacoes inst WHERE inst.cliente_id = c.id AND (inst.instalador_id = v_alvo_id OR (inst.instalador_id IS NULL AND c.instalador_id = v_alvo_id)))
  )
  AND (c.status_agendamento IS DISTINCT FROM 'concluido' OR c.status = 'aguardando_instalacao');

  -- 3. Métricas Financeiras ESTRITAS
  SELECT 
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pendente' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pago' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN status != 'concluida' AND data_agendamento IS NOT NULL THEN valor_instalacao ELSE 0 END), 0.00),
    COUNT(CASE WHEN status != 'concluida' AND data_agendamento IS NOT NULL THEN 1 END),
    COUNT(CASE WHEN status != 'concluida' AND data_agendamento IS NULL THEN 1 END)
  INTO 
    v_total_a_receber,
    v_total_recebido,
    v_valor_previsto_agendados,
    v_total_agendados_qtd,
    v_total_a_agendar_qtd
  FROM public.instalacoes
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR instalador_id = v_alvo_id;

  v_resumo := jsonb_build_object(
    'a_receber', v_total_a_receber,
    'recebido', v_total_recebido,
    'agendados_qtd', v_total_agendados_qtd,
    'a_agendar_qtd', v_total_a_agendar_qtd,
    'valor_previsto_agendados', v_valor_previsto_agendados
  );

  RETURN jsonb_build_object(
    'success', true,
    'ordens', v_ordens,
    'agendamentos', v_agendamentos,
    'resumo', v_resumo
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_obter_minhas_demandas(UUID) TO authenticated;

-- Invalidação obrigatória de cache PostgREST
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [154/225] MIGRAÇÃO: 20261016194500_hunter_instalador_celular_whatsapp_insumos.sql
-- ============================================================================

-- ==============================================================================
-- Hunter — Migração Canônica: Telefone/Celular do Instalador para WhatsApp,
-- Notificações de Instalação e Edição de Insumos pelo Instalador
-- ==============================================================================

-- 1. Garantir colunas telefone e celular em public.profiles
DO $$ BEGIN
  ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS telefone TEXT;
EXCEPTION WHEN duplicate_column THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS celular TEXT;
EXCEPTION WHEN duplicate_column THEN NULL;
END $$;

-- 2. Garantir sincronização mútua entre telefone e celular se um estiver preenchido
UPDATE public.profiles
SET telefone = COALESCE(telefone, celular),
    celular = COALESCE(celular, telefone)
WHERE telefone IS NOT NULL OR celular IS NOT NULL;

-- 3. Atualizar RPC admin_atualizar_usuario para receber e persistir p_telefone
DROP FUNCTION IF EXISTS public.admin_atualizar_usuario(UUID, TEXT, public.hunter_role, BOOLEAN, public.plano_cliente, TEXT[], NUMERIC, TEXT, TEXT, TEXT, TEXT);
DROP FUNCTION IF EXISTS public.admin_atualizar_usuario(UUID, TEXT, public.hunter_role, BOOLEAN, public.plano_cliente, TEXT[], NUMERIC, TEXT, TEXT, TEXT);

CREATE OR REPLACE FUNCTION public.admin_atualizar_usuario(
  p_usuario_id UUID,
  p_nome TEXT,
  p_role public.hunter_role,
  p_ativo BOOLEAN,
  p_plano public.plano_cliente DEFAULT 'basico',
  p_modulos TEXT[] DEFAULT ARRAY[]::TEXT[],
  p_valor_por_instalacao NUMERIC DEFAULT 0.00,
  p_chave_pix TEXT DEFAULT NULL,
  p_endereco_instalacao TEXT DEFAULT NULL,
  p_email TEXT DEFAULT NULL,
  p_telefone TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_mod TEXT;
  v_email_atual TEXT;
  v_email_novo TEXT;
  v_role_atual public.hunter_role;
  v_telefone_limpo TEXT := NULLIF(trim(p_telefone), '');
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem atualizar usuarios.';
  END IF;

  SELECT email INTO v_email_atual FROM auth.users WHERE id = p_usuario_id;
  SELECT role INTO v_role_atual FROM public.profiles WHERE id = p_usuario_id;

  -- Blindagem canonica do SuperADM (novaes@adm.28bpm.local e novaes@oficial.tec.br):
  IF LOWER(COALESCE(v_email_atual, '')) IN ('novaes@adm.28bpm.local', 'novaes@oficial.tec.br')
     OR p_usuario_id = '00000000-0000-0000-0000-000000000001'::UUID 
     OR v_role_atual = 'superadmin' THEN
    
    UPDATE public.profiles
    SET nome = trim(p_nome),
        role = 'superadmin',
        ativo = TRUE,
        telefone = COALESCE(v_telefone_limpo, telefone),
        celular = COALESCE(v_telefone_limpo, celular),
        updated_at = now()
    WHERE id = p_usuario_id;

    UPDATE auth.users
    SET raw_user_meta_data = raw_user_meta_data || jsonb_build_object(
          'nome', trim(p_nome), 
          'role', 'superadmin',
          'telefone', v_telefone_limpo
        ),
        email_confirmed_at = COALESCE(email_confirmed_at, now()),
        updated_at = now()
    WHERE id = p_usuario_id;

    RETURN jsonb_build_object(
      'success', TRUE,
      'message', 'Perfil SuperADM atualizado com sucesso. Privilegios e governanca mantidos integralmente.'
    );
  END IF;

  -- Proibição absoluta: apenas os dois emails oficiais podem ser SuperADM
  IF p_role = 'superadmin' THEN
    RAISE EXCEPTION 'Apenas as contas oficiais de governanca (novaes@adm.28bpm.local e novaes@oficial.tec.br) podem ser SuperADM.';
  END IF;

  -- Para outros usuarios: processa alteracao de e-mail se informada
  v_email_novo := LOWER(trim(COALESCE(p_email, v_email_atual)));
  IF v_email_novo IS NOT NULL AND v_email_novo <> '' AND v_email_novo <> LOWER(COALESCE(v_email_atual, '')) THEN
    IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = v_email_novo AND id <> p_usuario_id) THEN
      RAISE EXCEPTION 'O e-mail informado ja esta em uso por outro usuario.';
    END IF;

    UPDATE auth.users
    SET email = v_email_novo,
        raw_user_meta_data = raw_user_meta_data || jsonb_build_object('email', v_email_novo),
        updated_at = now()
    WHERE id = p_usuario_id;

    UPDATE auth.identities
    SET identity_data = jsonb_set(identity_data, '{email}', to_jsonb(v_email_novo)),
        provider_id = v_email_novo
    WHERE user_id = p_usuario_id AND provider = 'email';
  END IF;

  UPDATE public.profiles
  SET nome = trim(p_nome),
      email = v_email_novo,
      role = p_role,
      ativo = p_ativo,
      valor_por_instalacao = p_valor_por_instalacao,
      chave_pix = p_chave_pix,
      endereco_instalacao = p_endereco_instalacao,
      telefone = COALESCE(v_telefone_limpo, telefone),
      celular = COALESCE(v_telefone_limpo, celular),
      updated_at = now()
  WHERE id = p_usuario_id;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (p_usuario_id, p_role)
  ON CONFLICT (user_id, role) DO UPDATE SET role = EXCLUDED.role;

  UPDATE auth.users
  SET raw_user_meta_data = jsonb_build_object(
        'nome', trim(p_nome), 
        'role', p_role,
        'telefone', v_telefone_limpo
      ),
      email_confirmed_at = COALESCE(email_confirmed_at, now()),
      updated_at = now()
  WHERE id = p_usuario_id;

  -- Gestão granular de módulos de acesso
  IF p_role = 'instalador' THEN
    p_modulos := ARRAY['instalacao'];
  END IF;

  DELETE FROM public.user_module_access WHERE user_id = p_usuario_id;
  IF p_modulos IS NOT NULL THEN
    FOREACH v_mod IN ARRAY p_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (p_usuario_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Usuario e dados de contato atualizados com sucesso.'
  );
END;
$$;

-- 4. Atualizar RPC admin_cadastrar_usuario para receber e persistir p_telefone
DROP FUNCTION IF EXISTS public.admin_cadastrar_usuario(TEXT, TEXT, TEXT, public.hunter_role, TEXT[], public.plano_cliente, NUMERIC, TEXT, TEXT, TEXT);
DROP FUNCTION IF EXISTS public.admin_cadastrar_usuario(TEXT, TEXT, TEXT, public.hunter_role, TEXT[], public.plano_cliente, NUMERIC, TEXT, TEXT);

CREATE OR REPLACE FUNCTION public.admin_cadastrar_usuario(
  p_nome TEXT,
  p_email TEXT,
  p_senha TEXT,
  p_role public.hunter_role,
  p_modulos TEXT[] DEFAULT ARRAY[]::TEXT[],
  p_plano public.plano_cliente DEFAULT 'basico',
  p_valor_por_instalacao NUMERIC DEFAULT 0.00,
  p_chave_pix TEXT DEFAULT NULL,
  p_endereco_instalacao TEXT DEFAULT NULL,
  p_telefone TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_novo_user_id UUID;
  v_mod TEXT;
  v_email_limpo TEXT := LOWER(trim(p_email));
  v_telefone_limpo TEXT := NULLIF(trim(p_telefone), '');
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem criar novos usuarios.';
  END IF;

  IF v_email_limpo IS NULL OR v_email_limpo = '' THEN
    RAISE EXCEPTION 'O e-mail e obrigatorio.';
  END IF;

  IF p_senha IS NULL OR length(p_senha) < 6 THEN
    RAISE EXCEPTION 'A senha deve conter no minimo 6 caracteres.';
  END IF;

  IF EXISTS (SELECT 1 FROM auth.users WHERE LOWER(email) = v_email_limpo) THEN
    RAISE EXCEPTION 'Ja existe um usuario cadastrado com este e-mail.';
  END IF;

  v_novo_user_id := gen_random_uuid();

  INSERT INTO auth.users (
    id, instance_id, aud, role, email, encrypted_password,
    email_confirmed_at, recovery_sent_at, last_sign_in_at,
    raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
    confirmation_token, email_change, email_change_token_new, recovery_token
  ) VALUES (
    v_novo_user_id,
    '00000000-0000-0000-0000-000000000000',
    'authenticated',
    'authenticated',
    v_email_limpo,
    extensions.crypt(p_senha, extensions.gen_salt('bf', 10)),
    now(), now(), now(),
    '{"provider":"email","providers":["email"]}',
    jsonb_build_object('nome', trim(p_nome), 'role', p_role, 'telefone', v_telefone_limpo),
    now(), now(),
    '', '', '', ''
  );

  -- auth.identities
  IF NOT EXISTS (
    SELECT 1 FROM auth.identities 
    WHERE (provider = 'email' AND provider_id = v_novo_user_id::text)
       OR user_id = v_novo_user_id
  ) THEN
    BEGIN
      INSERT INTO auth.identities (
        id, user_id, identity_data, provider, provider_id,
        last_sign_in_at, created_at, updated_at
      ) VALUES (
        v_novo_user_id::text, v_novo_user_id,
        jsonb_build_object('sub', v_novo_user_id::text, 'email', v_email_limpo),
        'email', v_novo_user_id::text,
        now(), now(), now()
      );
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  INSERT INTO public.profiles (
    id, nome, email, role, valor_por_instalacao, chave_pix, endereco_instalacao, telefone, celular, ativo
  )
  VALUES (
    v_novo_user_id, trim(p_nome), v_email_limpo, p_role, p_valor_por_instalacao, p_chave_pix, p_endereco_instalacao, v_telefone_limpo, v_telefone_limpo, TRUE
  )
  ON CONFLICT (id) DO UPDATE
  SET nome = EXCLUDED.nome,
      role = EXCLUDED.role,
      valor_por_instalacao = EXCLUDED.valor_por_instalacao,
      chave_pix = EXCLUDED.chave_pix,
      endereco_instalacao = EXCLUDED.endereco_instalacao,
      telefone = COALESCE(EXCLUDED.telefone, public.profiles.telefone),
      celular = COALESCE(EXCLUDED.celular, public.profiles.celular),
      ativo = TRUE,
      updated_at = now();

  INSERT INTO public.user_roles (user_id, role)
  VALUES (v_novo_user_id, p_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  IF p_role = 'instalador' THEN
    p_modulos := ARRAY['instalacao'];
  END IF;

  IF p_modulos IS NOT NULL THEN
    FOREACH v_mod IN ARRAY p_modulos LOOP
      INSERT INTO public.user_module_access (user_id, module, ativo)
      VALUES (v_novo_user_id, v_mod, TRUE)
      ON CONFLICT (user_id, module) DO UPDATE SET ativo = TRUE;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Usuario criado com sucesso.',
    'user_id', v_novo_user_id
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_atualizar_usuario TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_cadastrar_usuario TO authenticated;

-- Invalidação compulsória de cache PostgREST
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [155/225] MIGRAÇÃO: 20261016202500_hunter_sincronizacao_instalacoes_veiculo_kit_atribuido.sql
-- ============================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Hunter — Sincronização Atômica de Instalações, Veículos e Kits Atribuídos (DJR-NEW)
-- ─────────────────────────────────────────────────────────────────────────────
-- 1. Sincroniza retroativamente instalações que estavam com veiculo_id nulo para o id do veículo
-- 2. Equaliza rastreador_id, rastreador_imei e kit_determinado_em entre veiculos e instalacoes
-- 3. Atualiza RPC instalador_obter_minhas_demandas com joins resilientes bidirecionais
-- ─────────────────────────────────────────────────────────────────────────────

-- 1. Vincular veiculo_id nas ordens de instalação órfãs onde a placa do cliente bate
UPDATE public.instalacoes i
SET veiculo_id = v.id,
    rastreador_id = COALESCE(i.rastreador_id, v.rastreador_id),
    rastreador_imei = CASE 
      WHEN i.rastreador_imei IS NULL OR UPPER(TRIM(i.rastreador_imei)) IN ('', 'PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR') 
      THEN COALESCE(v.rastreador_imei, i.rastreador_imei, 'AGUARDANDO ESTOQUE')
      ELSE i.rastreador_imei 
    END,
    kit_determinado_em = CASE 
      WHEN i.kit_determinado_em IS NULL AND (COALESCE(i.rastreador_id, v.rastreador_id) IS NOT NULL OR (v.rastreador_imei IS NOT NULL AND UPPER(TRIM(v.rastreador_imei)) NOT IN ('', 'PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR')))
      THEN NOW() 
      ELSE i.kit_determinado_em 
    END,
    updated_at = NOW()
FROM public.veiculos v
WHERE (i.veiculo_id IS NULL OR i.veiculo_id = v.id)
  AND v.cliente_id = i.cliente_id
  AND UPPER(TRIM(v.placa)) = UPPER(TRIM(i.placa))
  AND v.placa NOT IN ('A DEFINIR', 'SEM PLACA', 'SEMPLACA');

-- 2. Atualizar IMEI do rastreador a partir da tabela rastreadores se rastreador_id estiver preenchido
UPDATE public.instalacoes i
SET rastreador_imei = r.imei,
    rastreador_modelo = COALESCE(i.rastreador_modelo, r.modelo, 'J16 4G'),
    kit_determinado_em = COALESCE(i.kit_determinado_em, NOW()),
    updated_at = NOW()
FROM public.rastreadores r
WHERE r.id = i.rastreador_id
  AND (i.rastreador_imei IS NULL OR UPPER(TRIM(i.rastreador_imei)) IN ('', 'PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR'));

-- 3. Atualizar veiculos a partir da instalação quando a instalação possuir rastreador
UPDATE public.veiculos v
SET rastreador_id = i.rastreador_id,
    rastreador_imei = i.rastreador_imei,
    updated_at = NOW()
FROM public.instalacoes i
WHERE (i.veiculo_id = v.id OR (v.cliente_id = i.cliente_id AND UPPER(TRIM(v.placa)) = UPPER(TRIM(i.placa)) AND v.placa NOT IN ('A DEFINIR', 'SEM PLACA', 'SEMPLACA')))
  AND i.rastreador_id IS NOT NULL
  AND i.rastreador_imei IS NOT NULL
  AND UPPER(TRIM(i.rastreador_imei)) NOT IN ('', 'PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR')
  AND (v.rastreador_id IS NULL OR v.rastreador_imei IS NULL);

-- 4. RPC atualizada com joins resilientes para garantir visualização imediata do kit atribuído
CREATE OR REPLACE FUNCTION public.instalador_obter_minhas_demandas(
  p_instalador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_role TEXT;
  v_alvo_id UUID;
  v_ordens JSONB;
  v_agendamentos JSONB;
  v_resumo JSONB;
  v_total_a_receber NUMERIC(10,2);
  v_total_recebido NUMERIC(10,2);
  v_total_agendados_qtd INT;
  v_total_a_agendar_qtd INT;
  v_valor_previsto_agendados NUMERIC(10,2);
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_caller_id;

  IF v_role IN ('superadmin', 'adm', 'operador') THEN
    v_alvo_id := COALESCE(p_instalador_id, v_caller_id);
  ELSE
    v_alvo_id := v_caller_id;
  END IF;

  -- 1. Coletar Ordens de Instalação Atribuídas com Join em Rastreadores, Veículos e Chips
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', i.id,
      'cliente_id', i.cliente_id,
      'veiculo_id', COALESCE(i.veiculo_id, v.id),
      'instalador_id', COALESCE(i.instalador_id, c.instalador_id),
      'placa', COALESCE(i.placa, v.placa, 'A DEFINIR'),
      'marca', COALESCE(i.marca, split_part(v.marca_modelo, ' ', 1), 'Geral'),
      'modelo', COALESCE(i.modelo, v.marca_modelo, 'Veículo'),
      'ano', COALESCE(i.ano, v.ano),
      'cor', COALESCE(i.cor, v.cor),
      'tipo_veiculo', COALESCE(i.tipo_veiculo, v.tipo_veiculo, 'carro'),
      'km_instalacao', COALESCE(i.km_instalacao, 0),
      'tipo_servico', COALESCE(i.tipo_servico, 'instalacao'),
      'valor_instalacao', i.valor_instalacao,
      'status_pagamento', i.status_pagamento,
      'bloqueador_instalado', COALESCE(i.bloqueador_instalado, false),
      'com_bloqueador', COALESCE(i.bloqueador_instalado, false),
      'status', i.status,
      'posicao_instalacao', i.posicao_instalacao,
      'posicaoInstalacao', i.posicao_instalacao,
      'rastreador_id', COALESCE(i.rastreador_id, v.rastreador_id, c.kit_determinado_id, r.id),
      'rastreador_imei', COALESCE(
        CASE WHEN UPPER(TRIM(i.rastreador_imei)) IN ('PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR', '') THEN NULL ELSE i.rastreador_imei END,
        r.imei,
        CASE WHEN UPPER(TRIM(v.rastreador_imei)) IN ('PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR', '') THEN NULL ELSE v.rastreador_imei END,
        i.rastreador_imei,
        'PENDENTE'
      ),
      'rastreador_modelo', COALESCE(i.rastreador_modelo, r.modelo, 'J16 4G'),
      'chip_iccid', COALESCE(i.chip_iccid, ch.iccid),
      'chip_operadora', COALESCE(i.chip_operadora, ch.operadora),
      'data_agendamento', COALESCE(i.data_agendamento, c.data_agendamento),
      'hora_agendamento', COALESCE(i.hora_agendamento, c.hora_agendamento),
      'local_tipo', COALESCE(i.local_tipo, 'oficina'),
      'local_endereco', i.local_endereco,
      'solicita_endereco_cliente', COALESCE(i.solicita_endereco_cliente, false),
      'endereco_cliente_informado', i.endereco_cliente_informado,
      'endereco_cliente_informado_em', i.endereco_cliente_informado_em,
      'solicitado_endereco_em', i.solicitado_endereco_em,
      'kit_determinado_em', COALESCE(i.kit_determinado_em, CASE WHEN COALESCE(i.rastreador_id, v.rastreador_id, c.kit_determinado_id, r.id) IS NOT NULL THEN NOW() ELSE NULL END),
      'kit_confirmado_instalador', COALESCE(i.kit_confirmado_instalador, false),
      'kit_confirmado_em', i.kit_confirmado_em,
      'imei_confirmado', i.imei_confirmado,
      'instalador_nome', COALESCE(p.nome, 'Instalador Técnico'),
      'instalador_chave_pix', p.chave_pix,
      'cliente_nome', COALESCE(c.nome_razao_social, 'Cliente'),
      'cliente_telefone', c.telefone,
      'cliente_documento', c.documento,
      'motivo_pendencia_recusa', i.motivo_pendencia_recusa,
      'observacoes', i.observacoes,
      'created_at', i.created_at,
      'updated_at', i.updated_at,
      'concluida_at', i.concluida_at
    ) ORDER BY i.created_at DESC
  ), '[]'::JSONB)
  INTO v_ordens
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  LEFT JOIN public.veiculos v ON v.id = i.veiculo_id
    OR (i.veiculo_id IS NULL AND v.cliente_id = i.cliente_id AND UPPER(TRIM(v.placa)) = UPPER(TRIM(i.placa)) AND v.placa NOT IN ('A DEFINIR', 'SEM PLACA', 'SEMPLACA'))
  LEFT JOIN public.profiles p ON p.id = COALESCE(i.instalador_id, c.instalador_id)
  LEFT JOIN public.rastreadores r ON r.id = COALESCE(i.rastreador_id, v.rastreador_id, c.kit_determinado_id)
  LEFT JOIN public.chips ch ON ch.id = r.chip_id
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR i.instalador_id = v_alvo_id
     OR (i.instalador_id IS NULL AND c.instalador_id = v_alvo_id);

  -- 2. Coletar Clientes Agendados ou Aguardando Agendamento
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'nome_razao_social', c.nome_razao_social,
      'documento', c.documento,
      'telefone', c.telefone,
      'email', c.email,
      'status', c.status,
      'plano', c.plano,
      'tem_fidelidade', c.tem_fidelidade,
      'regra_horimetro', c.regra_horimetro,
      'kit_determinado_id', c.kit_determinado_id,
      'status_agendamento', COALESCE(c.status_agendamento, 'aguardando_agendamento'),
      'data_agendamento', c.data_agendamento,
      'hora_agendamento', c.hora_agendamento,
      'instalador_id', COALESCE(c.instalador_id, v_alvo_id),
      'instalador', jsonb_build_object(
        'id', p.id,
        'nome', p.nome,
        'endereco_instalacao', p.endereco_instalacao,
        'valor_com_bloqueador', p.valor_instalacao_com_bloqueador,
        'valor_sem_bloqueador', p.valor_instalacao_sem_bloqueador
      ),
      'veiculos', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', v.id, 
          'placa', v.placa, 
          'modelo', v.marca_modelo, 
          'tipo_veiculo', v.tipo_veiculo,
          'horimetro_horas', v.horimetro_horas,
          'rastreador_id', COALESCE(v.rastreador_id, inst_v.rastreador_id, c.kit_determinado_id),
          'rastreador_imei', COALESCE(
            CASE WHEN UPPER(TRIM(v.rastreador_imei)) IN ('PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR', '') THEN NULL ELSE v.rastreador_imei END,
            rk.imei,
            CASE WHEN UPPER(TRIM(inst_v.rastreador_imei)) IN ('PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR', '') THEN NULL ELSE inst_v.rastreador_imei END,
            v.rastreador_imei
          )
        ))
        FROM public.veiculos v
        LEFT JOIN public.instalacoes inst_v ON (inst_v.veiculo_id = v.id OR (inst_v.cliente_id = v.cliente_id AND UPPER(TRIM(inst_v.placa)) = UPPER(TRIM(v.placa)) AND v.placa NOT IN ('A DEFINIR', 'SEM PLACA', 'SEMPLACA')))
        LEFT JOIN public.rastreadores rk ON rk.id = COALESCE(v.rastreador_id, inst_v.rastreador_id, c.kit_determinado_id)
        WHERE v.cliente_id = c.id
      ), '[]'::JSONB)
    ) ORDER BY c.created_at DESC
  ), '[]'::JSONB)
  INTO v_agendamentos
  FROM public.clientes c
  LEFT JOIN public.profiles p ON p.id = COALESCE(c.instalador_id, v_alvo_id)
  WHERE (
    (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
    OR c.instalador_id = v_alvo_id
    OR EXISTS (SELECT 1 FROM public.instalacoes inst WHERE inst.cliente_id = c.id AND (inst.instalador_id = v_alvo_id OR (inst.instalador_id IS NULL AND c.instalador_id = v_alvo_id)))
  )
  AND (c.status_agendamento IS DISTINCT FROM 'concluido' OR c.status = 'aguardando_instalacao');

  -- 3. Métricas Financeiras
  SELECT 
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pendente' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pago' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN status != 'concluida' AND data_agendamento IS NOT NULL THEN valor_instalacao ELSE 0 END), 0.00),
    COUNT(CASE WHEN status != 'concluida' AND data_agendamento IS NOT NULL THEN 1 END),
    COUNT(CASE WHEN status != 'concluida' AND data_agendamento IS NULL THEN 1 END)
  INTO 
    v_total_a_receber,
    v_total_recebido,
    v_valor_previsto_agendados,
    v_total_agendados_qtd,
    v_total_a_agendar_qtd
  FROM public.instalacoes
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR instalador_id = v_alvo_id;

  v_resumo := jsonb_build_object(
    'a_receber', v_total_a_receber,
    'recebido', v_total_recebido,
    'agendados_qtd', v_total_agendados_qtd,
    'a_agendar_qtd', v_total_a_agendar_qtd,
    'valor_previsto_agendados', v_valor_previsto_agendados
  );

  RETURN jsonb_build_object(
    'success', true,
    'ordens', v_ordens,
    'agendamentos', v_agendamentos,
    'resumo', v_resumo
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_obter_minhas_demandas(UUID) TO authenticated;

-- Invalidação obrigatória de cache PostgREST
NOTIFY pgrst, 'reload schema';


