  OR veiculo_id IN (SELECT id FROM public.veiculos WHERE cliente_id = public.get_funcionario_cliente_id())
)
WITH CHECK (
  cliente_id = public.get_funcionario_cliente_id()
  OR veiculo_id IN (SELECT id FROM public.veiculos WHERE cliente_id = public.get_funcionario_cliente_id())
);

