-- [211/225] MIGRAÇÃO: 20261107190000_hunter_hardening_rls_documentos_emitidos.sql
-- ============================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Hunter — Hardening de RLS na Tabela public.documentos_emitidos
-- Versão: 2.1.6.72
-- Data: 07/11/2026
-- Objetivo: Revogar consulta anônima direta ampla em public.documentos_emitidos
--           e garantir que a conferência de autenticidade no portal /verificar
--           ocorra exclusivamente através da RPC segura hunter_verificar_autenticidade_contrato.
-- ─────────────────────────────────────────────────────────────────────────────

-- 1. Remove a política que permitia leitura anônima direta com USING (true)
DROP POLICY IF EXISTS "documentos_emitidos_select_anon_hash" ON public.documentos_emitidos;

-- 2. Revoga SELECT direto na tabela para o papel anônimo (anon)
REVOKE SELECT ON TABLE public.documentos_emitidos FROM anon;

-- 3. Garante que authenticated e service_role mantenham permissões operacionais
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.documentos_emitidos TO authenticated, service_role;

-- 4. Garante políticas restritas para usuários autenticados
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'documentos_emitidos'
      AND policyname = 'documentos_emitidos_select_autenticado'
  ) THEN
    CREATE POLICY "documentos_emitidos_select_autenticado"
    ON public.documentos_emitidos
    FOR SELECT TO authenticated
    USING (
      -- Apenas administradores e operadores podem consultar o acervo geral de documentos
      EXISTS (
        SELECT 1 FROM public.profiles
        WHERE id = auth.uid()
          AND role::text IN ('superadmin', 'adm', 'operador', 'superadmin_auditor')
      )
    );
  END IF;
END $$;

-- 5. Atualiza a RPC hunter_verificar_autenticidade_contrato para operar como SECURITY DEFINER
--    com search_path seguro e acesso concedido ao papel anon
CREATE OR REPLACE FUNCTION public.hunter_verificar_autenticidade_contrato(
  p_identificador TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_contrato RECORD;
  v_cliente RECORD;
  v_doc RECORD;
  v_identificador_limpo TEXT;
BEGIN
  IF p_identificador IS NULL OR TRIM(p_identificador) = '' THEN
    RETURN jsonb_build_object(
      'autentico', false,
      'mensagem', 'Identificador de verificação não informado.'
    );
  END IF;

  v_identificador_limpo := UPPER(TRIM(p_identificador));

  -- 1. Tenta buscar em contratos_clientes
  BEGIN
    SELECT * INTO v_contrato
    FROM public.contratos_clientes
    WHERE selo_autenticidade = v_identificador_limpo
       OR codigo_verificacao = v_identificador_limpo
       OR hash_pdf_assinado = LOWER(v_identificador_limpo)
       OR hash_pdf_original = LOWER(v_identificador_limpo)
    ORDER BY created_at DESC
    LIMIT 1;

    IF FOUND THEN
      -- Busca dados do cliente
      SELECT nome_razao_social, documento, email INTO v_cliente
      FROM public.clientes
      WHERE id = v_contrato.cliente_id;

      RETURN jsonb_build_object(
        'autentico', true,
        'mensagem', 'Contrato autêntico localizado no sistema GD Rastreamento.',
        'contrato_id', v_contrato.id,
        'numero_contrato', v_contrato.numero_contrato,
        'selo_autenticidade', v_contrato.selo_autenticidade,
        'codigo_verificacao', v_contrato.codigo_verificacao,
        'status', v_contrato.status,
        'data_emissao', v_contrato.data_emissao,
        'data_assinatura', v_contrato.data_assinatura,
        'cliente_nome', COALESCE(v_cliente.nome_razao_social, 'N/I'),
        'hash_pdf_original', v_contrato.hash_pdf_original,
        'hash_pdf_assinado', v_contrato.hash_pdf_assinado
      );
    END IF;
  EXCEPTION
    WHEN undefined_table THEN
      NULL;
  END;

  -- 2. Tenta buscar em documentos_emitidos (cadeia de custódia forense global)
  BEGIN
    SELECT * INTO v_doc
    FROM public.documentos_emitidos
    WHERE hash_sha256 = LOWER(v_identificador_limpo)
       OR (metadata->>'selo') = v_identificador_limpo
       OR (metadata->>'codigo') = v_identificador_limpo
       OR (metadata->>'numero_contrato') = v_identificador_limpo
    ORDER BY created_at DESC
    LIMIT 1;

    IF FOUND THEN
      RETURN jsonb_build_object(
        'autentico', true,
        'mensagem', 'Documento oficial autêntico localizado no sistema GD Rastreamento.',
        'contrato_id', v_doc.id,
        'numero_contrato', COALESCE(v_doc.metadata->>'numero_contrato', v_doc.nome_arquivo, 'DOC-OFICIAL'),
        'selo_autenticidade', COALESCE(v_doc.metadata->>'selo', 'SGD-' || UPPER(SUBSTRING(v_doc.id::text FROM 1 FOR 8))),
        'codigo_verificacao', COALESCE(v_doc.metadata->>'codigo', UPPER(SUBSTRING(v_doc.id::text FROM 1 FOR 6))),
        'status', 'assinado',
        'data_emissao', v_doc.created_at,
        'data_assinatura', v_doc.created_at,
        'cliente_nome', COALESCE(v_doc.metadata->>'cliente_nome', v_doc.descricao, 'Cliente'),
        'hash_pdf_original', v_doc.hash_sha256,
        'hash_pdf_assinado', v_doc.hash_sha256
      );
    END IF;
  EXCEPTION
    WHEN undefined_table THEN
      NULL;
  END;

  RETURN jsonb_build_object(
    'autentico', false,
    'mensagem', 'Nenhum documento ou contrato autêntico localizado para o código ou hash informado.'
  );
END;
$$;

-- 6. Concede execução ao papel anônimo para permitir a verificação pontual no portal /verificar
GRANT EXECUTE ON FUNCTION public.hunter_verificar_autenticidade_contrato(TEXT) TO anon, authenticated, service_role;

-- 7. Notifica PostgREST para recarregar o schema imediatamente
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [212/225] MIGRAÇÃO: 20261107191500_hunter_odometro_medidor8_motor_d_compensado.sql
-- ============================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Hunter — Medidor 8: Motor D (Fusão com Compensação de Sombra GNSS / Cold-Start)
-- Versão: 2.1.6.72
-- Data: 07/11/2026
-- Objetivo: Criar o 8º medidor de odômetro mantendo 100% INTACTOS e INALTERADOS
--           os 7 medidores atuais (WGS-84, Cinemático, MCU J16, Motores A, B, C e Medidor 7 Média).
--           O Motor D incorpora compensação cinemática retroativa quando o GPS
--           reaquire sinal com ignição ligada após perda em túneis, garagens ou sombras GNSS.
-- ─────────────────────────────────────────────────────────────────────────────

-- 1. Adiciona as colunas do 8º Medidor (Motor D) na tabela public.veiculos
ALTER TABLE public.veiculos
  ADD COLUMN IF NOT EXISTS odometro_motor_d_km NUMERIC(12, 3),
  ADD COLUMN IF NOT EXISTS odometro_motor_d_estado TEXT DEFAULT 'PARADO_ZVU',
  ADD COLUMN IF NOT EXISTS odometro_motor_d_pesos JSONB DEFAULT '{"gnssOuArco": 50, "cinematico": 30, "compensacaoSombra": 20}'::jsonb;

-- 2. Inicializa o Motor D com base no Motor A para todos os veículos existentes
UPDATE public.veiculos
SET odometro_motor_d_km = COALESCE(odometro_motor_a_km, odometro_motor_media_km, odometro_km)
WHERE odometro_motor_d_km IS NULL;

-- 3. Atualiza a função de calibração atômica para incluir o Motor D
CREATE OR REPLACE FUNCTION public.ajustar_odometro_veiculo(
  p_veiculo_id UUID,
  p_novo_odometro NUMERIC
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_odometro_anterior NUMERIC(12, 2);
  v_placa TEXT;
  v_eh_dono BOOLEAN := FALSE;
  v_eh_admin BOOLEAN := FALSE;
  v_novo_km NUMERIC(12, 2);
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso não autenticado.';
  END IF;

  IF p_novo_odometro IS NULL OR p_novo_odometro < 0 THEN
    RAISE EXCEPTION 'Quilometragem inválida. Deve ser maior ou igual a zero.';
  END IF;

  v_novo_km := ROUND(p_novo_odometro::NUMERIC, 2);

  -- Verifica permissão: SuperADM/Equipe OU titular do veículo
  SELECT 
    COALESCE(v.odometro_motor_media_km, v.odometro_km, 0),
    v.placa,
    (c.user_id = v_user_id)
  INTO 
    v_odometro_anterior,
    v_placa,
    v_eh_dono
  FROM public.veiculos v
  JOIN public.clientes c ON c.id = v.cliente_id
  WHERE v.id = p_veiculo_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Veículo não encontrado.';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.profiles 
    WHERE id = v_user_id AND role::text IN ('adm', 'superadmin', 'operador')
  ) INTO v_eh_admin;

  IF NOT (v_eh_dono OR v_eh_admin) THEN
    RAISE EXCEPTION 'Permissão negada. Apenas o proprietário ou a administração podem calibrar o odômetro.';
  END IF;

  -- 1. Atualiza ATOMICAMENTE TODOS os 8 odômetros no veículo (Medidores 1 a 8)
  UPDATE public.veiculos
  SET 
    odometro_km                     = v_novo_km,
    odometro_motor_media_km         = v_novo_km,
    odometro_wgs84_km               = v_novo_km,
    odometro_cinematico_km          = v_novo_km,
    odometro_motor_a_km             = v_novo_km,
    odometro_motor_b_km             = v_novo_km,
    odometro_motor_c_km             = v_novo_km,
    odometro_motor_d_km             = v_novo_km,           -- Medidor 8
    odometro_hardware_km            = ROUND(v_novo_km),
    odometro_hardware_atualizado_em = NOW(),
    ultima_atualizacao              = NOW()
  WHERE id = p_veiculo_id;

  -- 2. Sincroniza a última posição de telemetria
  UPDATE public.telemetria_posicoes
  SET odometro = v_novo_km
  WHERE id = (
    SELECT id FROM public.telemetria_posicoes
    WHERE veiculo_id = p_veiculo_id
    ORDER BY data_hora_gps DESC
    LIMIT 1
  );

  -- 3. Registra log forense de auditoria
  INSERT INTO public.system_activity_logs (
    acao,
    usuario_id,
    detalhe
  ) VALUES (
    'AJUSTE_CALIBRACAO_ODOMETRO',
    v_user_id,
    format('Odômetro do veículo %s equalizado e sincronizado em todos os 8 motores de %s km para %s km com o painel físico.',
           v_placa,
           COALESCE(v_odometro_anterior::TEXT, '0.00'),
           v_novo_km::TEXT)
  );

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'mensagem', format('Odômetro atualizado atomicamente para %s km nos 8 medidores.', v_novo_km),
    'placa', v_placa,
    'odometro_anterior', v_odometro_anterior,
    'novo_odometro', v_novo_km,
    'motores_sincronizados', 8
  );
END;
$$;

NOTIFY pgrst, 'reload schema';


