-- ============================================================================
-- [220/225] MIGRAÇÃO: 20261111120000_hunter_degustacao_primeiro_acesso_e_revalidacao.sql
-- ============================================================================

-- ============================================================================
-- HUNTER / GD RASTREAMENTO — RELOGIO SERVER-SIDE DE 24H DA DEGUSTACAO APOS 1O ACESSO E REVALIDACAO
-- ============================================================================
-- Migration: 20261111120000_hunter_degustacao_primeiro_acesso_e_revalidacao.sql
-- Objetivo:
--   1. Persistir no servidor (public.profiles) o instante real do 1o acesso do
--      cliente em degustacao, a data de expiracao (+24h) e a marca da ultima
--      revalidacao via WhatsApp (comando REVALIDA).
--   2. Criar RPC SECURITY DEFINER public.registrar_primeiro_acesso_degustacao
--      que carimba as 24h estritamente no 1o login autenticado (sem sobrescrever
--      logins seguintes e funcionando de forma consistente entre dispositivos).
-- ============================================================================

ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS degustacao_primeiro_acesso_em TIMESTAMPTZ DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS degustacao_expira_em TIMESTAMPTZ DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS degustacao_revalidada_em TIMESTAMPTZ DEFAULT NULL;

CREATE OR REPLACE FUNCTION public.registrar_primeiro_acesso_degustacao(
  p_user_id UUID DEFAULT auth.uid()
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_target_user_id  UUID := COALESCE(p_user_id, auth.uid());
  v_role            TEXT;
  v_primeiro_acesso TIMESTAMPTZ;
  v_expira_em       TIMESTAMPTZ;
  v_revalidada      TIMESTAMPTZ;
  v_meta            JSONB := '{}'::jsonb;
  v_is_degustacao   BOOLEAN := FALSE;
  v_agora           TIMESTAMPTZ := NOW();
  v_expirado        BOOLEAN := FALSE;
  v_seg_restantes   INTEGER := 0;
BEGIN
  IF v_target_user_id IS NULL THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Usuário não identificado.');
  END IF;

  IF COALESCE(auth.role(), '') <> 'service_role'
     AND auth.uid() IS DISTINCT FROM v_target_user_id
     AND NOT public.is_adm() THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Acesso negado para registrar acesso de outro usuário.');
  END IF;

  SELECT
    p.role::text,
    p.degustacao_primeiro_acesso_em,
    p.degustacao_expira_em,
    p.degustacao_revalidada_em
  INTO
    v_role,
    v_primeiro_acesso,
    v_expira_em,
    v_revalidada
  FROM public.profiles p
  WHERE p.id = v_target_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Perfil de usuário não encontrado.');
  END IF;

  SELECT u.raw_user_meta_data
  INTO v_meta
  FROM auth.users u
  WHERE u.id = v_target_user_id;

  v_meta := COALESCE(v_meta, '{}'::jsonb);
  v_is_degustacao := (
    COALESCE(v_role, '') IN ('cliente_degustacao', 'superadmin_auditor', 'degustacao')
    OR COALESCE((v_meta->>'degustacao')::BOOLEAN, FALSE)
    OR COALESCE(v_meta->>'role', '') IN ('cliente_degustacao', 'superadmin_auditor', 'degustacao')
  );

  IF NOT v_is_degustacao THEN
    RETURN jsonb_build_object('sucesso', false, 'erro', 'Perfil não está em modo de degustação.');
  END IF;

  -- Se houve revalidacao posterior ao ultimo primeiro acesso gravado, reinicia contagem para o proximo 1o login
  IF v_primeiro_acesso IS NOT NULL
     AND v_revalidada IS NOT NULL
     AND v_revalidada > v_primeiro_acesso THEN
    v_primeiro_acesso := NULL;
    v_expira_em := NULL;
  END IF;

  IF v_primeiro_acesso IS NULL THEN
    v_primeiro_acesso := v_agora;
    v_expira_em := v_agora + INTERVAL '24 hours';

    UPDATE public.profiles
    SET
      degustacao_primeiro_acesso_em = v_primeiro_acesso,
      degustacao_expira_em = v_expira_em,
      updated_at = v_agora
    WHERE id = v_target_user_id;
  ELSIF v_expira_em IS NULL THEN
    v_expira_em := v_primeiro_acesso + INTERVAL '24 hours';

    UPDATE public.profiles
    SET degustacao_expira_em = v_expira_em
    WHERE id = v_target_user_id;
  END IF;

  v_expirado := (v_agora >= v_expira_em);
  v_seg_restantes := GREATEST(0, FLOOR(EXTRACT(EPOCH FROM (v_expira_em - v_agora)))::INTEGER);

  RETURN jsonb_build_object(
    'sucesso', true,
    'user_id', v_target_user_id,
    'primeiro_acesso_em', v_primeiro_acesso,
    'expira_em', v_expira_em,
    'revalidada_em', v_revalidada,
    'expirado', v_expirado,
    'segundos_restantes', v_seg_restantes
  );
END;
$$;

REVOKE ALL ON FUNCTION public.registrar_primeiro_acesso_degustacao(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.registrar_primeiro_acesso_degustacao(UUID) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [221/225] MIGRAÇÃO: 20261112190000_hunter_tipo_veiculo_moto_eletrica_e_placa_flexivel.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — AMPLIAÇÃO CANÔNICA DE chk_tipo_veiculo + PLACA FLEXÍVEL (uq_veiculos_placa_real)
-- Migration: 20261112190000_hunter_tipo_veiculo_moto_eletrica_e_placa_flexivel.sql
-- ============================================================================

-- 1. Atualiza constraint chk_tipo_veiculo em public.veiculos para aceitar todos
--    os tipos oficiais da UI/mapa (incluindo moto_eletrica, quadriciculo/quadriciclo,
--    van, ambulancia, maquina, trator, equipamento e outro)
ALTER TABLE public.veiculos DROP CONSTRAINT IF EXISTS chk_tipo_veiculo;
ALTER TABLE public.veiculos DROP CONSTRAINT IF EXISTS veiculos_tipo_veiculo_check;

ALTER TABLE public.veiculos
  ADD CONSTRAINT chk_tipo_veiculo
  CHECK (
    tipo_veiculo IN (
      'carro',
      'moto',
      'moto_eletrica',
      'caminhao',
      'van',
      'ambulancia',
      'onibus',
      'suv',
      'camionete',
      'quadriciculo',
      'quadriciclo',
      'triciclo',
      'jetski',
      'maquina',
      'trator',
      'equipamento',
      'outro'
    )
  );

-- 2. Substitui a constraint/índice rígido veiculos_placa_key pelo índice único parcial
--    uq_veiculos_placa_real, permitindo múltiplos veículos com placeholders
--    ('SEMPLACA', 'SEM PLACA', 'A DEFINIR', 'S/PLACA') enquanto o instalador não preenche
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'public.veiculos'::regclass AND conname = 'veiculos_placa_key'
  ) THEN
    ALTER TABLE public.veiculos DROP CONSTRAINT veiculos_placa_key;
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE schemaname = 'public' AND tablename = 'veiculos' AND indexname = 'veiculos_placa_key'
  ) THEN
    DROP INDEX public.veiculos_placa_key;
  END IF;
END $$;

DROP INDEX IF EXISTS public.uq_veiculos_placa_real;
CREATE UNIQUE INDEX uq_veiculos_placa_real
  ON public.veiculos (UPPER(TRIM(placa)))
  WHERE placa IS NOT NULL
    AND UPPER(TRIM(placa)) NOT IN ('SEMPLACA', 'SEM PLACA', 'A DEFINIR', 'S/PLACA');

-- 3. Atualiza a RPC public.admin_editar_veiculo (assinatura com p_tipo_veiculo)
CREATE OR REPLACE FUNCTION public.admin_editar_veiculo(
  p_veiculo_id UUID,
  p_placa TEXT,
  p_marca_modelo TEXT,
  p_ano INT DEFAULT NULL,
  p_cor TEXT DEFAULT NULL,
  p_tipo_veiculo TEXT DEFAULT 'carro'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_placa_limpa TEXT;
  v_tipo_sanitizado TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NOT NULL THEN
    SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_user_id;
    IF COALESCE(v_role, '') NOT IN ('superadmin', 'adm', 'operador') THEN
      RAISE EXCEPTION 'Apenas administradores e operadores podem editar veículos.';
    END IF;
  END IF;

  IF UPPER(TRIM(COALESCE(p_placa, ''))) IN ('A DEFINIR', 'SEM PLACA', 'SEMPLACA', 'S/PLACA') THEN
    v_placa_limpa := CASE
      WHEN UPPER(TRIM(p_placa)) = 'A DEFINIR' THEN 'A DEFINIR'
      ELSE 'SEMPLACA'
    END;
  ELSE
    v_placa_limpa := UPPER(REGEXP_REPLACE(COALESCE(p_placa, ''), '[^A-Za-z0-9]', '', 'g'));
  END IF;

  IF v_placa_limpa IS NULL OR LENGTH(v_placa_limpa) < 3 THEN
    RAISE EXCEPTION 'Placa inválida para o veículo.';
  END IF;

  v_tipo_sanitizado := LOWER(TRIM(COALESCE(p_tipo_veiculo, 'carro')));
  IF v_tipo_sanitizado = 'quadriciclo' THEN
    v_tipo_sanitizado := 'quadriciculo';
  END IF;

  IF v_tipo_sanitizado NOT IN (
    'carro', 'moto', 'moto_eletrica', 'caminhao', 'van', 'ambulancia',
    'onibus', 'suv', 'camionete', 'quadriciculo', 'triciclo', 'jetski',
    'maquina', 'trator', 'equipamento', 'outro'
  ) THEN
    v_tipo_sanitizado := 'carro';
  END IF;

  UPDATE public.veiculos
  SET
    placa = v_placa_limpa,
    marca_modelo = TRIM(p_marca_modelo),
    ano = p_ano,
    cor = NULLIF(TRIM(p_cor), ''),
    tipo_veiculo = v_tipo_sanitizado,
    updated_at = NOW()
  WHERE id = p_veiculo_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Veículo não encontrado.';
  END IF;

  RETURN jsonb_build_object(
    'sucesso', true,
    'veiculo_id', p_veiculo_id,
    'placa', v_placa_limpa,
    'tipo_veiculo', v_tipo_sanitizado,
    'mensagem', 'Dados do veículo atualizados com sucesso.'
  );
END;
$$;

REVOKE ALL ON FUNCTION public.admin_editar_veiculo(UUID, TEXT, TEXT, INT, TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_editar_veiculo(UUID, TEXT, TEXT, INT, TEXT, TEXT) TO authenticated, service_role;

-- 4. Atualiza a RPC public.cliente_solicitar_novo_veiculo para suportar moto_eletrica
--    e padronizar placa 'SEMPLACA' + normalização de quadriciclo -> quadriciculo
CREATE OR REPLACE FUNCTION public.cliente_solicitar_novo_veiculo(
  p_cliente_id UUID,
  p_tipo_veiculo TEXT DEFAULT 'carro'::TEXT,
  p_placa TEXT DEFAULT 'A DEFINIR'::TEXT,
  p_marca_modelo TEXT DEFAULT 'Veiculo'::TEXT,
  p_ano INTEGER DEFAULT NULL::INTEGER,
  p_cor TEXT DEFAULT NULL::TEXT,
  p_observacoes TEXT DEFAULT NULL::TEXT,
  p_horimetro NUMERIC DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_role TEXT;
  v_cliente RECORD;
  v_veiculo_id UUID;
  v_placa_final TEXT;
  v_tipo_final TEXT;
  v_is_maquina BOOLEAN;
  v_user_email TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Acesso nao autorizado. Faca login no sistema.';
  END IF;

  SELECT role::TEXT, email INTO v_role, v_user_email FROM public.profiles WHERE id = v_user_id;

  SELECT id, user_id, email, status INTO v_cliente
  FROM public.clientes
  WHERE id = p_cliente_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente nao encontrado.';
  END IF;

  IF COALESCE(v_role, 'cliente') NOT IN ('superadmin', 'adm', 'operador') THEN
    IF v_cliente.user_id IS DISTINCT FROM v_user_id THEN
      IF LOWER(COALESCE(v_cliente.email, '')) = LOWER(COALESCE(v_user_email, '')) THEN
        UPDATE public.clientes SET user_id = v_user_id WHERE id = p_cliente_id;
      ELSE
        RAISE EXCEPTION 'Acesso negado: voce so pode solicitar veiculos para a sua propria conta.';
      END IF;
    END IF;
  END IF;

  v_tipo_final := LOWER(TRIM(COALESCE(p_tipo_veiculo, 'carro')));
  IF v_tipo_final = 'quadriciclo' THEN
    v_tipo_final := 'quadriciculo';
  END IF;

  IF v_tipo_final NOT IN (
    'carro', 'moto', 'moto_eletrica', 'caminhao', 'van', 'ambulancia',
    'onibus', 'suv', 'camionete', 'quadriciculo', 'triciclo', 'jetski',
    'maquina', 'trator', 'equipamento', 'outro'
  ) THEN
    v_tipo_final := 'carro';
  END IF;

  v_is_maquina := (v_tipo_final IN ('maquina', 'trator', 'equipamento', 'moto_eletrica'));

  IF v_is_maquina AND (
    p_placa IS NULL OR TRIM(p_placa) = '' OR UPPER(TRIM(p_placa)) IN ('A DEFINIR', 'SEM PLACA', 'SEMPLACA', 'S/PLACA')
  ) THEN
    v_placa_final := 'SEMPLACA';
  ELSE
    v_placa_final := UPPER(TRIM(COALESCE(NULLIF(TRIM(p_placa), ''), 'A DEFINIR')));
  END IF;

  INSERT INTO public.veiculos (
    cliente_id,
    placa,
    marca_modelo,
    ano,
    cor,
    tipo_veiculo,
    horimetro_horas,
    ativo,
    bloqueado,
    pendente_aprovacao_operador
  ) VALUES (
    p_cliente_id,
    v_placa_final,
    TRIM(COALESCE(NULLIF(TRIM(p_marca_modelo), ''), 'Veiculo')),
    p_ano,
    NULLIF(TRIM(p_cor), ''),
    v_tipo_final,
    COALESCE(p_horimetro, 0),
    FALSE,
    FALSE,
    TRUE
  )
  RETURNING id INTO v_veiculo_id;

  INSERT INTO public.instalacoes (
    cliente_id,
    veiculo_id,
    placa,
    modelo,
    ano,
    cor,
    tipo_veiculo,
    rastreador_imei,
    rastreador_modelo,
    status,
    observacoes
  ) VALUES (
    p_cliente_id,
    v_veiculo_id,
    v_placa_final,
    TRIM(COALESCE(NULLIF(TRIM(p_marca_modelo), ''), 'Veiculo')),
    p_ano,
    NULLIF(TRIM(p_cor), ''),
    v_tipo_final,
    'A DEFINIR',
    'J16 4G',
    'nao_instalado',
    COALESCE(p_observacoes, 'Solicitacao de novo veiculo enviada pelo cliente. Aguardando configuracao do operador.')
  );

  UPDATE public.clientes
  SET pendente_configuracao_operador = TRUE
  WHERE id = p_cliente_id;

  RETURN jsonb_build_object(
    'sucesso', TRUE,
    'veiculo_id', v_veiculo_id,
    'mensagem', 'Solicitacao de novo veiculo enviada com sucesso! Aguardando aprovacao da administracao.'
  );
END;
$$;

REVOKE ALL ON FUNCTION public.cliente_solicitar_novo_veiculo(UUID, TEXT, TEXT, TEXT, INT, TEXT, TEXT, NUMERIC) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.cliente_solicitar_novo_veiculo(UUID, TEXT, TEXT, TEXT, INT, TEXT, TEXT, NUMERIC) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [222/225] MIGRAÇÃO: 20261112194000_hunter_financeiro_caixa_origem_e_guard_liquidacao_cliente.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — ORIGEM DA VERBA / CAIXA EM DESPESAS E GUARDA DE LIQUIDAÇÃO PELO CLIENTE
-- Migration: 20261112194000_hunter_financeiro_caixa_origem_e_guard_liquidacao_cliente.sql
-- ============================================================================

-- 1. Garante colunas canônicas de caixa/origem da verba e ressarcimento em transacoes_financeiras
ALTER TABLE public.transacoes_financeiras
  ADD COLUMN IF NOT EXISTS fonte_pagamento TEXT DEFAULT 'caixa_empresa';

ALTER TABLE public.transacoes_financeiras
  ADD COLUMN IF NOT EXISTS responsavel_pagamento_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL;

ALTER TABLE public.transacoes_financeiras
  ADD COLUMN IF NOT EXISTS responsavel_pagamento_nome TEXT;

ALTER TABLE public.transacoes_financeiras
  ADD COLUMN IF NOT EXISTS status_ressarcimento TEXT DEFAULT 'nao_aplicavel';

ALTER TABLE public.transacoes_financeiras
  ADD COLUMN IF NOT EXISTS data_ressarcimento TIMESTAMPTZ;

CREATE INDEX IF NOT EXISTS idx_transacoes_fonte_pagamento
  ON public.transacoes_financeiras(fonte_pagamento);

CREATE INDEX IF NOT EXISTS idx_transacoes_status_ressarcimento
  ON public.transacoes_financeiras(status_ressarcimento);

CREATE INDEX IF NOT EXISTS idx_transacoes_responsavel_pagamento_id
  ON public.transacoes_financeiras(responsavel_pagamento_id);

-- 2. Backfill seguro para lançamentos antigos que salvaram [FONTE:operador_adm] em observacoes
UPDATE public.transacoes_financeiras
SET
  fonte_pagamento = 'operador_adm',
  status_ressarcimento = CASE
    WHEN observacoes ILIKE '%RESSARC:ressarcido%' THEN 'ressarcido'
    ELSE 'pendente'
  END
WHERE tipo IN ('saida', 'despesa')
  AND (fonte_pagamento IS NULL OR fonte_pagamento = 'caixa_empresa')
  AND observacoes ILIKE '%[FONTE:operador_adm%';

-- 3. Atualiza RPC liquidar_repasse_instalacao_pelo_cliente com guarda estrita:
--    Apenas lançamentos de repasse ao instalador (categoria = 'repasse_instalador' ou instalacao_id NOT NULL)
--    podem ser liquidados como pagos diretamente pelo cliente.
CREATE OR REPLACE FUNCTION public.liquidar_repasse_instalacao_pelo_cliente(
  p_transacao_id TEXT,
  p_instalacao_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_role TEXT;
  v_inst_id UUID := NULL;
  v_trans_uuid UUID := NULL;
  v_trans RECORD;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NOT NULL THEN
    SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_caller_id;
    IF COALESCE(v_role, '') NOT IN ('superadmin', 'adm', 'operador') THEN
      RAISE EXCEPTION 'Acesso negado: apenas administradores e operadores podem liquidar repasses.';
    END IF;
  END IF;

  -- 1. Se p_transacao_id iniciar com 'i-', extrai o UUID da instalacao
  IF p_transacao_id LIKE 'i-%' THEN
    BEGIN
      v_inst_id := substring(p_transacao_id from 3)::UUID;
    EXCEPTION WHEN OTHERS THEN
      v_inst_id := p_instalacao_id;
    END;
  ELSE
    BEGIN
      v_trans_uuid := p_transacao_id::UUID;
    EXCEPTION WHEN OTHERS THEN
      v_trans_uuid := NULL;
    END;
  END IF;

  IF v_inst_id IS NULL AND p_instalacao_id IS NOT NULL THEN
    v_inst_id := p_instalacao_id;
  END IF;

  -- 2. Se for uma ordem de instalação mesclada diretamente
  IF v_inst_id IS NOT NULL AND v_trans_uuid IS NULL THEN
    UPDATE public.instalacoes
    SET pago_direto_cliente = TRUE,
        status_pagamento = 'pago',
        pago_em = NOW(),
        updated_at = NOW()
    WHERE id = v_inst_id;

    RETURN jsonb_build_object(
      'sucesso', true,
      'tipo', 'instalacao',
      'id', v_inst_id,
      'mensagem', 'Repasse de instalação marcado como liquidado diretamente pelo cliente (R$ 0,00 da empresa).'
    );
  END IF;

  -- 3. Se for uma transação na tabela transacoes_financeiras
  IF v_trans_uuid IS NOT NULL THEN
    SELECT id, tipo, categoria, instalacao_id
    INTO v_trans
    FROM public.transacoes_financeiras
    WHERE id = v_trans_uuid;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Transação financeira não encontrada.';
    END IF;

    IF COALESCE(v_trans.tipo, '') NOT IN ('saida', 'despesa')
       OR (
         COALESCE(v_trans.categoria, '') <> 'repasse_instalador'
         AND v_trans.instalacao_id IS NULL
       ) THEN
      RAISE EXCEPTION 'Apenas repasses de instalação para pagamento ao instalador podem ser liquidados pelo cliente.';
    END IF;

    UPDATE public.transacoes_financeiras
    SET liquidado_pelo_cliente = TRUE,
        status = 'concluido',
        valor = 0.00,
        data_pagamento = NOW(),
        fonte_pagamento = 'caixa_empresa',
        status_ressarcimento = 'nao_aplicavel',
        descricao = CASE
          WHEN descricao NOT ILIKE '%(Liquidado pelo Cliente)%' THEN descricao || ' (Liquidado pelo Cliente)'
          ELSE descricao
        END,
        updated_at = NOW()
    WHERE id = v_trans_uuid;

    IF v_trans.instalacao_id IS NOT NULL THEN
      UPDATE public.instalacoes
      SET pago_direto_cliente = TRUE,
          status_pagamento = 'pago',
          pago_em = NOW(),
          updated_at = NOW()
      WHERE id = v_trans.instalacao_id;
    END IF;

    RETURN jsonb_build_object(
      'sucesso', true,
      'tipo', 'transacao',
      'id', v_trans_uuid,
      'mensagem', 'Transação financeira liquidada pelo cliente com valor zerado.'
    );
  END IF;

  RETURN jsonb_build_object(
    'sucesso', false,
    'mensagem', 'Nenhum identificador válido de instalação ou transação fornecido.'
  );
END;
$$;

REVOKE ALL ON FUNCTION public.liquidar_repasse_instalacao_pelo_cliente(TEXT, UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.liquidar_repasse_instalacao_pelo_cliente(TEXT, UUID) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [223/225] MIGRAÇÃO: 20261112200000_hunter_mensalidades_numero_parcela.sql
-- ============================================================================

-- Migration: 20261112200000_hunter_mensalidades_numero_parcela.sql
-- Objetivo:
--   1. Permitir valor >= 0 em transacoes_financeiras (cortesia R$ 0,00 e liquidado_pelo_cliente R$ 0,00).
--   2. Persistir numero_parcela e total_parcelas em public.mensalidades (ex: 01/12, 02/12 ...).
--   3. Atualizar trigger trg_sync_mensalidade_transacao e RPC admin_gerar_mensalidades_mes antes do backfill.
--   4. Preencher (backfill) cronologicamente todas as mensalidades recorrentes existentes por cliente.

-- 1. Ajusta CHECK constraint para suportar valor >= 0 (cortesia e liquidado_pelo_cliente)
ALTER TABLE public.transacoes_financeiras
  DROP CONSTRAINT IF EXISTS transacoes_financeiras_valor_check;

ALTER TABLE public.transacoes_financeiras
  ADD CONSTRAINT transacoes_financeiras_valor_check CHECK (valor >= 0);

-- 2. Adiciona colunas de numeração de parcela em public.mensalidades
ALTER TABLE public.mensalidades
  ADD COLUMN IF NOT EXISTS numero_parcela INT,
  ADD COLUMN IF NOT EXISTS total_parcelas INT;

-- 3. Atualiza trigger de sincronização antes do backfill
CREATE OR REPLACE FUNCTION public.trg_sync_mensalidade_transacao()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_cliente_nome TEXT;
  v_revendedor_id UUID;
  v_vendedor_id UUID;
  v_revendedor_nome TEXT;
  v_vendedor_nome TEXT;
  v_base_sistema NUMERIC(10, 2) := 25.00;
  v_base_vendedor NUMERIC(10, 2) := 40.00;
  v_parte_sistema NUMERIC(10, 2) := 0.00;
  v_parte_revendedor NUMERIC(10, 2) := 0.00;
  v_parte_vendedor NUMERIC(10, 2) := 0.00;
  v_status_trans TEXT;
  v_desc_entrada TEXT;
  v_desc_rev TEXT;
  v_desc_vend TEXT;
  v_num_parcela INT;
  v_tot_parcelas INT;
  v_qtd_anteriores INT;
  v_parcela_fmt TEXT;
  v_ja_existe_trans BOOLEAN;
BEGIN
  -- Evita poluir transacoes_financeiras com cortesia R$ 0,00 que nunca teve lançamento lá
  IF COALESCE(NEW.valor, 0) <= 0 THEN
    SELECT EXISTS (
      SELECT 1 FROM public.transacoes_financeiras
      WHERE mensalidade_id = NEW.id AND tipo = 'entrada' AND categoria = 'mensalidade'
    ) INTO v_ja_existe_trans;
    IF NOT v_ja_existe_trans THEN
      RETURN NEW;
    END IF;
  END IF;

  SELECT
    nome_razao_social,
    revendedor_id,
    vendedor_id
  INTO
    v_cliente_nome,
    v_revendedor_id,
    v_vendedor_id
  FROM public.clientes
  WHERE id = NEW.cliente_id;

  IF COALESCE(NEW.mes_referencia, 0) > 0 THEN
    v_num_parcela := NEW.numero_parcela;
    v_tot_parcelas := COALESCE(NULLIF(NEW.total_parcelas, 0), 12);

    IF v_num_parcela IS NULL OR v_num_parcela <= 0 THEN
      SELECT COUNT(*) INTO v_qtd_anteriores
      FROM public.mensalidades m_prev
      WHERE m_prev.cliente_id = NEW.cliente_id
        AND m_prev.mes_referencia > 0
        AND m_prev.id <> NEW.id
        AND (
          m_prev.ano_referencia < NEW.ano_referencia
          OR (m_prev.ano_referencia = NEW.ano_referencia AND m_prev.mes_referencia < NEW.mes_referencia)
        );
      v_num_parcela := ((COALESCE(v_qtd_anteriores, 0) % GREATEST(1, v_tot_parcelas)) + 1);
    END IF;

    v_parcela_fmt := LPAD(v_num_parcela::TEXT, 2, '0') || '/' || LPAD(v_tot_parcelas::TEXT, 2, '0');
    v_desc_entrada := 'Mensalidade ' || LPAD(NEW.mes_referencia::TEXT, 2, '0') || '/' || NEW.ano_referencia::TEXT ||
                      ' (' || v_parcela_fmt || ') - ' || COALESCE(v_cliente_nome, 'Cliente');
  ELSE
    v_num_parcela := NULL;
    v_tot_parcelas := NULL;
    v_desc_entrada := 'Taxa de Ativação (' || NEW.ano_referencia::TEXT || ') - ' || COALESCE(v_cliente_nome, 'Cliente');
  END IF;

  IF NEW.status = 'pago' THEN
    v_status_trans := 'concluido';
  ELSE
    v_status_trans := 'pendente';
  END IF;

  INSERT INTO public.transacoes_financeiras (
    tipo, categoria, descricao, valor, data_competencia, data_vencimento,
    data_pagamento, status, mensalidade_id, cliente_id, revendedor_id, vendedor_id,
    comprovante_url, parcela_atual, total_parcelas, updated_at
  ) VALUES (
    'entrada', 'mensalidade', v_desc_entrada, NEW.valor,
    make_date(NEW.ano_referencia, GREATEST(1, NEW.mes_referencia), 1),
    NEW.data_vencimento, NEW.data_pagamento, v_status_trans,
    NEW.id, NEW.cliente_id, v_revendedor_id, v_vendedor_id,
    NEW.comprovante_url, v_num_parcela, v_tot_parcelas, NOW()
  )
  ON CONFLICT (mensalidade_id, tipo, categoria) DO UPDATE SET
    valor = EXCLUDED.valor,
    descricao = EXCLUDED.descricao,
    data_vencimento = EXCLUDED.data_vencimento,
    data_pagamento = EXCLUDED.data_pagamento,
    status = EXCLUDED.status,
    comprovante_url = EXCLUDED.comprovante_url,
    revendedor_id = EXCLUDED.revendedor_id,
    vendedor_id = EXCLUDED.vendedor_id,
    parcela_atual = COALESCE(EXCLUDED.parcela_atual, public.transacoes_financeiras.parcela_atual),
    total_parcelas = COALESCE(EXCLUDED.total_parcelas, public.transacoes_financeiras.total_parcelas),
    updated_at = NOW();

  IF v_revendedor_id IS NOT NULL AND COALESCE(NEW.mes_referencia, 0) > 0 AND COALESCE(NEW.valor, 0) > 0 THEN
    SELECT nome, COALESCE(valor_base_sistema, 25.00)
    INTO v_revendedor_nome, v_base_sistema
    FROM public.revendedores
    WHERE id = v_revendedor_id;

    IF v_vendedor_id IS NOT NULL THEN
      SELECT nome, COALESCE(valor_base_vendedor, 40.00)
      INTO v_vendedor_nome, v_base_vendedor
      FROM public.vendedores
      WHERE id = v_vendedor_id;

      v_parte_sistema := v_base_sistema;
      v_parte_vendedor := GREATEST(0, NEW.valor - v_base_vendedor);
      v_parte_revendedor := GREATEST(0, v_base_vendedor - v_base_sistema);

      IF v_parte_vendedor > 0 THEN
        v_desc_vend := 'Comissão Vendedor (' || COALESCE(v_vendedor_nome, 'Equipe') || ') - Ref. ' ||
                       LPAD(NEW.mes_referencia::TEXT, 2, '0') || '/' || NEW.ano_referencia::TEXT ||
                       ' (' || v_parcela_fmt || ' - ' || COALESCE(v_cliente_nome, 'Cliente') || ')';

        INSERT INTO public.transacoes_financeiras (
          tipo, categoria, descricao, valor, data_competencia, data_vencimento,
          status, mensalidade_id, cliente_id, revendedor_id, vendedor_id, updated_at
        ) VALUES (
          'saida', 'repasse_vendedor', v_desc_vend, v_parte_vendedor,
          make_date(NEW.ano_referencia, GREATEST(1, NEW.mes_referencia), 1),
          NEW.data_vencimento, 'pendente',
          NEW.id, NEW.cliente_id, v_revendedor_id, v_vendedor_id, NOW()
        )
        ON CONFLICT (mensalidade_id, tipo, categoria) DO UPDATE SET
          valor = EXCLUDED.valor,
          descricao = EXCLUDED.descricao,
          data_vencimento = EXCLUDED.data_vencimento,
          revendedor_id = EXCLUDED.revendedor_id,
          vendedor_id = EXCLUDED.vendedor_id,
          updated_at = NOW();
      END IF;
    ELSE
      v_parte_sistema := v_base_sistema;
      v_parte_revendedor := GREATEST(0, NEW.valor - v_base_sistema);
      v_parte_vendedor := 0;
    END IF;

    IF v_parte_revendedor > 0 THEN
      v_desc_rev := 'Repasse Franquia (' || COALESCE(v_revendedor_nome, 'Revendedor') || ') - Ref. ' ||
                    LPAD(NEW.mes_referencia::TEXT, 2, '0') || '/' || NEW.ano_referencia::TEXT ||
                    ' (' || v_parcela_fmt || ' - ' || COALESCE(v_cliente_nome, 'Cliente') || ')';

      INSERT INTO public.transacoes_financeiras (
        tipo, categoria, descricao, valor, data_competencia, data_vencimento,
        status, mensalidade_id, cliente_id, revendedor_id, updated_at
      ) VALUES (
        'saida', 'repasse_revendedor', v_desc_rev, v_parte_revendedor,
        make_date(NEW.ano_referencia, GREATEST(1, NEW.mes_referencia), 1),
        NEW.data_vencimento, 'pendente',
        NEW.id, NEW.cliente_id, v_revendedor_id, NOW()
      )
      ON CONFLICT (mensalidade_id, tipo, categoria) DO UPDATE SET
        valor = EXCLUDED.valor,
        descricao = EXCLUDED.descricao,
        data_vencimento = EXCLUDED.data_vencimento,
        revendedor_id = EXCLUDED.revendedor_id,
        updated_at = NOW();
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

-- 4. Backfill cronológico por cliente para mensalidades recorrentes (mes_referencia > 0)
WITH numeradas AS (
  SELECT
    m.id,
    ROW_NUMBER() OVER (
      PARTITION BY m.cliente_id
      ORDER BY m.ano_referencia ASC, m.mes_referencia ASC, m.data_vencimento ASC, m.created_at ASC
    )::INT AS pos,
    GREATEST(12, COUNT(*) OVER (PARTITION BY m.cliente_id))::INT AS total_cli
  FROM public.mensalidades m
  WHERE m.mes_referencia > 0
)
UPDATE public.mensalidades m
SET
  numero_parcela = CASE
    WHEN n.total_cli > 12 THEN (((n.pos - 1) % 12) + 1)
    ELSE n.pos
  END,
  total_parcelas = CASE
    WHEN n.total_cli > 12 THEN 12
    ELSE GREATEST(12, n.total_cli)
  END
FROM numeradas n
WHERE m.id = n.id
  AND (m.numero_parcela IS NULL OR m.total_parcelas IS NULL);

-- 5. Atualiza RPC de geração em lote para já gravar numero_parcela e total_parcelas
CREATE OR REPLACE FUNCTION public.admin_gerar_mensalidades_mes(
  p_mes INT,
  p_ano INT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_cliente RECORD;
  v_dia_max INT;
  v_dia_final INT;
  v_data_venc DATE;
  v_status_inicial public.status_mensalidade;
  v_total_clientes INT := 0;
  v_geradas INT := 0;
  v_ja_existentes INT := 0;
  v_qtd_anteriores INT := 0;
  v_num_parcela INT := 1;
BEGIN
  IF NOT public.is_adm() THEN
    RAISE EXCEPTION 'Acesso negado: apenas administradores podem gerar mensalidades em lote.';
  END IF;

  IF p_mes < 1 OR p_mes > 12 THEN
    RAISE EXCEPTION 'Mês de referência inválido: deve estar entre 1 e 12.';
  END IF;

  IF p_ano < 2024 OR p_ano > 2099 THEN
    RAISE EXCEPTION 'Ano de referência inválido.';
  END IF;

  v_dia_max := EXTRACT(DAY FROM (DATE_TRUNC('month', make_date(p_ano, p_mes, 1)) + INTERVAL '1 month - 1 day'))::INT;

  FOR v_cliente IN
    SELECT c.id, c.dia_vencimento, c.valor_mensalidade, c.nome_razao_social
    FROM public.clientes c
    WHERE c.status <> 'bloqueado'
      AND c.status <> 'aguardando_instalacao'
      AND c.valor_mensalidade > 0
      AND EXISTS (
        SELECT 1 FROM public.veiculos v
        WHERE v.cliente_id = c.id
          AND v.ativo = TRUE
      )
  LOOP
    v_total_clientes := v_total_clientes + 1;

    v_dia_final := LEAST(COALESCE(v_cliente.dia_vencimento, 10), v_dia_max);
    v_data_venc := make_date(p_ano, p_mes, v_dia_final);

    IF v_data_venc < CURRENT_DATE THEN
      v_status_inicial := 'vencido';
    ELSE
      v_status_inicial := 'pendente';
    END IF;

    SELECT COUNT(*) INTO v_qtd_anteriores
    FROM public.mensalidades m_prev
    WHERE m_prev.cliente_id = v_cliente.id
      AND m_prev.mes_referencia > 0
      AND (
        m_prev.ano_referencia < p_ano
        OR (m_prev.ano_referencia = p_ano AND m_prev.mes_referencia < p_mes)
      );

    v_num_parcela := ((COALESCE(v_qtd_anteriores, 0) % 12) + 1);

    INSERT INTO public.mensalidades (
      cliente_id,
      mes_referencia,
      ano_referencia,
      numero_parcela,
      total_parcelas,
      valor,
      data_vencimento,
      status,
      created_at,
      updated_at
    ) VALUES (
      v_cliente.id,
      p_mes,
      p_ano,
      v_num_parcela,
      12,
      v_cliente.valor_mensalidade,
      v_data_venc,
      v_status_inicial,
      NOW(),
      NOW()
    )
    ON CONFLICT (cliente_id, mes_referencia, ano_referencia) DO NOTHING;

    IF FOUND THEN
      v_geradas := v_geradas + 1;
    ELSE
      v_ja_existentes := v_ja_existentes + 1;
    END IF;
  END LOOP;

  INSERT INTO public.system_activity_logs (
    user_id,
    acao,
    detalhe,
    created_at
  ) VALUES (
    auth.uid(),
    'GERACAO_MENSALIDADES_LOTE',
    'Competência: ' || LPAD(p_mes::TEXT, 2, '0') || '/' || p_ano::TEXT ||
    ' | Geradas: ' || v_geradas::TEXT ||
    ' | Já existentes: ' || v_ja_existentes::TEXT ||
    ' | Clientes com veículo ativo: ' || v_total_clientes::TEXT,
    NOW()
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'geradas', v_geradas,
    'ja_existentes', v_ja_existentes,
    'total_clientes', v_total_clientes,
    'message', v_geradas || ' mensalidades geradas com sucesso para a competência ' || LPAD(p_mes::TEXT, 2, '0') || '/' || p_ano::TEXT || '.'
  );
END;
$$;

-- 6. Atualiza transações já sincronizadas com mensalidades
UPDATE public.transacoes_financeiras t
SET
  parcela_atual = m.numero_parcela,
  total_parcelas = m.total_parcelas,
  descricao = CASE
    WHEN t.descricao NOT LIKE '%(' || LPAD(m.numero_parcela::TEXT, 2, '0') || '/' || LPAD(m.total_parcelas::TEXT, 2, '0') || ')%'
      THEN 'Mensalidade ' || LPAD(m.mes_referencia::TEXT, 2, '0') || '/' || m.ano_referencia::TEXT ||
           ' (' || LPAD(m.numero_parcela::TEXT, 2, '0') || '/' || LPAD(m.total_parcelas::TEXT, 2, '0') || ') - ' ||
           COALESCE(c.nome_razao_social, 'Cliente')
    ELSE t.descricao
  END,
  updated_at = NOW()
FROM public.mensalidades m
JOIN public.clientes c ON c.id = m.cliente_id
WHERE t.mensalidade_id = m.id
  AND t.categoria = 'mensalidade'
  AND m.mes_referencia > 0
  AND m.numero_parcela IS NOT NULL
  AND m.total_parcelas IS NOT NULL;

NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- [224/225] MIGRAÇÃO: 20261112203000_hunter_fix_agendamento_herdado_e_marca_instalacao.sql
-- ============================================================================

-- ============================================================================
-- HUNTER — CORREÇÃO DE AGENDAMENTO HERDADO EM NOVOS VEÍCULOS E MARCA/ANO DE INSTALAÇÕES
-- Migration: 20261112203000_hunter_fix_agendamento_herdado_e_marca_instalacao.sql
-- ============================================================================
-- 1. Impede que trg_sync_cliente_instalador_instalacao copie agendamento legado
--    de clientes que já possuem instalação concluída (ou status_agendamento='concluido')
--    para ordens recém-criadas de novos veículos, nem grave 'A DEFINIR' em marca.
-- 2. Atualiza instalador_obter_minhas_demandas para não fazer fallback cego para
--    clientes.data_agendamento quando o cliente já teve instalação concluída e
--    sanitizar marca placeholder ('A DEFINIR', 'GERAL') na listagem.
-- 3. Higieniza registros existentes afetados (sem apagar agendamentos novos reais).
-- ============================================================================

-- 1. Atualizar Trigger trg_sync_cliente_instalador_instalacao
CREATE OR REPLACE FUNCTION public.trg_sync_cliente_instalador_instalacao()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_veiculo RECORD;
  v_valor_unitario NUMERIC(10,2) := 50.00;
  v_instalacao_id UUID := NULL;
  v_tem_veiculo_pendente BOOLEAN := FALSE;
  v_todos_veiculos_concluidos BOOLEAN := FALSE;
  v_cliente_ja_possui_concluida BOOLEAN := FALSE;
  v_pode_herdar_agendamento BOOLEAN := FALSE;
  v_marca_calc TEXT;
  v_modelo_calc TEXT;
BEGIN
  IF NEW.instalador_id IS NOT NULL THEN

    -- Verifica se todos os veículos deste cliente já possuem instalação concluída ou estão ativos
    IF EXISTS (
      SELECT 1 FROM public.veiculos v
      WHERE v.cliente_id = NEW.id
    ) AND NOT EXISTS (
      SELECT 1 FROM public.veiculos v
      WHERE v.cliente_id = NEW.id
        AND v.ativo = FALSE
        AND NOT EXISTS (
          SELECT 1 FROM public.instalacoes i
          WHERE (i.veiculo_id = v.id OR (v.placa IS NOT NULL AND v.placa NOT IN ('A DEFINIR', 'SEM PLACA', 'SEMPLACA', '') AND i.placa = v.placa))
            AND i.status IN ('concluida', 'concluida_com_pendencia')
        )
    ) THEN
      v_todos_veiculos_concluidos := TRUE;
    END IF;

    IF v_todos_veiculos_concluidos THEN
      UPDATE public.instalacoes
      SET instalador_id = NEW.instalador_id,
          updated_at = NOW()
      WHERE cliente_id = NEW.id AND status NOT IN ('concluida', 'concluida_com_pendencia');

      RETURN NEW;
    END IF;

    v_cliente_ja_possui_concluida := (NEW.status_agendamento = 'concluido') OR EXISTS (
      SELECT 1 FROM public.instalacoes
      WHERE cliente_id = NEW.id
        AND status IN ('concluida', 'concluida_com_pendencia')
    );

    v_pode_herdar_agendamento := (
      NOT v_cliente_ja_possui_concluida
      AND NEW.data_agendamento IS NOT NULL
    );

    -- Obter valor de repasse configurado para o instalador
    SELECT COALESCE(valor_por_instalacao, 50.00) INTO v_valor_unitario
    FROM public.profiles
    WHERE id = NEW.instalador_id;

    -- Verificar se já existe uma ordem aberta/agendada para este cliente
    SELECT id INTO v_instalacao_id
    FROM public.instalacoes
    WHERE cliente_id = NEW.id AND status NOT IN ('concluida', 'concluida_com_pendencia')
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_instalacao_id IS NOT NULL THEN
      UPDATE public.instalacoes
      SET
        instalador_id = NEW.instalador_id,
        valor_instalacao = CASE WHEN valor_instalacao <= 0 THEN COALESCE(v_valor_unitario, 50.00) ELSE valor_instalacao END,
        data_agendamento = CASE
          WHEN v_pode_herdar_agendamento AND (OLD.data_agendamento IS DISTINCT FROM NEW.data_agendamento)
          THEN COALESCE(data_agendamento, NEW.data_agendamento)
          ELSE data_agendamento
        END,
        hora_agendamento = CASE
          WHEN v_pode_herdar_agendamento AND (OLD.hora_agendamento IS DISTINCT FROM NEW.hora_agendamento)
          THEN COALESCE(hora_agendamento, NEW.hora_agendamento)
          ELSE hora_agendamento
        END,
        updated_at = NOW()
      WHERE id = v_instalacao_id;
    ELSE
      FOR v_veiculo IN
        SELECT v.id, v.placa, v.marca_modelo, v.tipo_veiculo
        FROM public.veiculos v
        WHERE v.cliente_id = NEW.id
          AND v.ativo = FALSE
          AND NOT EXISTS (
            SELECT 1 FROM public.instalacoes i
            WHERE (i.veiculo_id = v.id OR (v.placa IS NOT NULL AND v.placa NOT IN ('A DEFINIR', 'SEM PLACA', 'SEMPLACA', '') AND i.placa = v.placa))
              AND i.status IN ('concluida', 'concluida_com_pendencia', 'agendada', 'aberta', 'nao_instalado')
          )
      LOOP
        v_tem_veiculo_pendente := TRUE;

        IF UPPER(TRIM(COALESCE(v_veiculo.marca_modelo, ''))) IN ('', 'VEÍCULO PADRÃO', 'VEICULO PADRAO', 'VEÍCULO', 'VEICULO', 'A DEFINIR', 'GERAL') THEN
          v_marca_calc := '';
          v_modelo_calc := COALESCE(NULLIF(TRIM(v_veiculo.marca_modelo), ''), 'Veículo Padrão');
        ELSE
          v_marca_calc := split_part(TRIM(v_veiculo.marca_modelo), ' ', 1);
          v_modelo_calc := COALESCE(NULLIF(TRIM(SUBSTRING(TRIM(v_veiculo.marca_modelo) FROM LENGTH(v_marca_calc) + 2)), ''), v_marca_calc);
        END IF;

        INSERT INTO public.instalacoes (
          cliente_id,
          instalador_id,
          veiculo_id,
          placa,
          marca,
          modelo,
          tipo_veiculo,
          status,
          status_pagamento,
          valor_instalacao,
          data_agendamento,
          hora_agendamento,
          observacoes,
          created_at,
          updated_at
        ) VALUES (
          NEW.id,
          NEW.instalador_id,
          v_veiculo.id,
          COALESCE(v_veiculo.placa, 'A DEFINIR'),
          v_marca_calc,
          v_modelo_calc,
          COALESCE(v_veiculo.tipo_veiculo, 'carro'),
          CASE WHEN v_pode_herdar_agendamento THEN 'agendada' ELSE 'nao_instalado' END,
          'pendente',
          COALESCE(v_valor_unitario, 50.00),
          CASE WHEN v_pode_herdar_agendamento THEN NEW.data_agendamento ELSE NULL END,
          CASE WHEN v_pode_herdar_agendamento THEN NEW.hora_agendamento ELSE NULL END,
          'Ordem gerada automaticamente para veículo pendente de instalação.',
          NOW(),
          NOW()
        );
      END LOOP;
    END IF;

  ELSIF NEW.instalador_id IS NULL AND OLD.instalador_id IS NOT NULL THEN
    UPDATE public.instalacoes
    SET instalador_id = NULL, updated_at = NOW()
    WHERE cliente_id = NEW.id AND status NOT IN ('concluida', 'concluida_com_pendencia');
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_cliente_instalador_instalacao ON public.clientes;
CREATE TRIGGER trg_sync_cliente_instalador_instalacao
  AFTER INSERT OR UPDATE OF instalador_id, data_agendamento, hora_agendamento, status, status_agendamento, kit_determinado_id
  ON public.clientes
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_sync_cliente_instalador_instalacao();

-- 2. Atualizar RPC instalador_obter_minhas_demandas sem fallback de data antiga em clientes já instalados
CREATE OR REPLACE FUNCTION public.instalador_obter_minhas_demandas(
  p_instalador_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_role TEXT;
  v_alvo_id UUID;
  v_ordens JSONB;
  v_agendamentos JSONB;
  v_resumo JSONB;
  v_total_a_receber NUMERIC(10,2);
  v_total_recebido NUMERIC(10,2);
  v_total_agendados_qtd INT;
  v_total_a_agendar_qtd INT;
  v_valor_previsto_agendados NUMERIC(10,2);
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  END IF;

  SELECT role::TEXT INTO v_role FROM public.profiles WHERE id = v_caller_id;

  IF v_role IN ('superadmin', 'adm', 'operador') THEN
    v_alvo_id := COALESCE(p_instalador_id, v_caller_id);
  ELSE
    v_alvo_id := v_caller_id;
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', i.id,
      'cliente_id', i.cliente_id,
      'veiculo_id', COALESCE(i.veiculo_id, v.id),
      'instalador_id', COALESCE(i.instalador_id, c.instalador_id),
      'placa', COALESCE(i.placa, v.placa, 'A DEFINIR'),
      'marca', CASE
        WHEN UPPER(TRIM(COALESCE(i.marca, ''))) IN ('A DEFINIR', 'GERAL', 'VEICULO', 'VEÍCULO', '') THEN
          CASE
            WHEN UPPER(TRIM(COALESCE(v.marca_modelo, ''))) IN ('', 'VEÍCULO PADRÃO', 'VEICULO PADRAO', 'VEÍCULO', 'VEICULO', 'A DEFINIR') THEN ''
            ELSE COALESCE(split_part(TRIM(v.marca_modelo), ' ', 1), '')
          END
        ELSE i.marca
      END,
      'modelo', COALESCE(i.modelo, v.marca_modelo, 'Veículo'),
      'ano', COALESCE(i.ano, v.ano),
      'cor', COALESCE(i.cor, v.cor),
      'tipo_veiculo', COALESCE(i.tipo_veiculo, v.tipo_veiculo, 'carro'),
      'km_instalacao', COALESCE(i.km_instalacao, 0),
      'tipo_servico', COALESCE(i.tipo_servico, 'instalacao'),
      'valor_instalacao', i.valor_instalacao,
      'status_pagamento', i.status_pagamento,
      'bloqueador_instalado', COALESCE(i.bloqueador_instalado, false),
      'com_bloqueador', COALESCE(i.bloqueador_instalado, false),
      'status', i.status,
      'posicao_instalacao', i.posicao_instalacao,
      'posicaoInstalacao', i.posicao_instalacao,
      'rastreador_id', COALESCE(i.rastreador_id, v.rastreador_id, c.kit_determinado_id, r.id),
      'rastreador_imei', COALESCE(
        CASE WHEN UPPER(TRIM(i.rastreador_imei)) IN ('PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR', '') THEN NULL ELSE i.rastreador_imei END,
        r.imei,
        CASE WHEN UPPER(TRIM(v.rastreador_imei)) IN ('PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR', '') THEN NULL ELSE v.rastreador_imei END,
        i.rastreador_imei,
        'PENDENTE'
      ),
      'rastreador_modelo', COALESCE(i.rastreador_modelo, r.modelo, 'J16 4G'),
      'chip_iccid', COALESCE(i.chip_iccid, ch.iccid),
      'chip_operadora', COALESCE(i.chip_operadora, ch.operadora),
      'data_agendamento', CASE
        WHEN i.data_agendamento IS NOT NULL THEN i.data_agendamento
        WHEN c.status_agendamento IS DISTINCT FROM 'concluido'
          AND NOT EXISTS (
            SELECT 1 FROM public.instalacoes ic
            WHERE ic.cliente_id = i.cliente_id
              AND ic.id <> i.id
              AND ic.status IN ('concluida', 'concluida_com_pendencia')
          )
        THEN c.data_agendamento
        ELSE NULL
      END,
      'hora_agendamento', CASE
        WHEN i.data_agendamento IS NOT NULL THEN i.hora_agendamento
        WHEN c.status_agendamento IS DISTINCT FROM 'concluido'
          AND NOT EXISTS (
            SELECT 1 FROM public.instalacoes ic
            WHERE ic.cliente_id = i.cliente_id
              AND ic.id <> i.id
              AND ic.status IN ('concluida', 'concluida_com_pendencia')
          )
        THEN c.hora_agendamento
        ELSE NULL
      END,
      'local_tipo', COALESCE(i.local_tipo, 'oficina'),
      'local_endereco', i.local_endereco,
      'solicita_endereco_cliente', COALESCE(i.solicita_endereco_cliente, false),
      'endereco_cliente_informado', i.endereco_cliente_informado,
      'endereco_cliente_informado_em', i.endereco_cliente_informado_em,
      'solicitado_endereco_em', i.solicitado_endereco_em,
      'kit_determinado_em', COALESCE(i.kit_determinado_em, CASE WHEN COALESCE(i.rastreador_id, v.rastreador_id, c.kit_determinado_id, r.id) IS NOT NULL THEN NOW() ELSE NULL END),
      'kit_confirmado_instalador', COALESCE(i.kit_confirmado_instalador, false),
      'kit_confirmado_em', i.kit_confirmado_em,
      'imei_confirmado', i.imei_confirmado,
      'instalador_nome', COALESCE(p.nome, 'Instalador Técnico'),
      'instalador_chave_pix', p.chave_pix,
      'cliente_nome', COALESCE(c.nome_razao_social, 'Cliente'),
      'cliente_telefone', c.telefone,
      'cliente_documento', c.documento,
      'motivo_pendencia_recusa', i.motivo_pendencia_recusa,
      'observacoes', i.observacoes,
      'created_at', i.created_at,
      'updated_at', i.updated_at,
      'concluida_at', i.concluida_at
    ) ORDER BY i.created_at DESC
  ), '[]'::JSONB)
  INTO v_ordens
  FROM public.instalacoes i
  LEFT JOIN public.clientes c ON c.id = i.cliente_id
  LEFT JOIN public.veiculos v ON v.id = i.veiculo_id
    OR (i.veiculo_id IS NULL AND v.cliente_id = i.cliente_id AND UPPER(TRIM(v.placa)) = UPPER(TRIM(i.placa)) AND v.placa NOT IN ('A DEFINIR', 'SEM PLACA', 'SEMPLACA'))
  LEFT JOIN public.profiles p ON p.id = COALESCE(i.instalador_id, c.instalador_id)
  LEFT JOIN public.rastreadores r ON r.id = COALESCE(i.rastreador_id, v.rastreador_id, c.kit_determinado_id)
  LEFT JOIN public.chips ch ON ch.id = r.chip_id
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR i.instalador_id = v_alvo_id
     OR (i.instalador_id IS NULL AND c.instalador_id = v_alvo_id);

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', c.id,
      'nome_razao_social', c.nome_razao_social,
      'documento', c.documento,
      'telefone', c.telefone,
      'email', c.email,
      'status', c.status,
      'plano', c.plano,
      'tem_fidelidade', c.tem_fidelidade,
      'regra_horimetro', c.regra_horimetro,
      'kit_determinado_id', c.kit_determinado_id,
      'status_agendamento', COALESCE(c.status_agendamento, 'aguardando_agendamento'),
      'data_agendamento', c.data_agendamento,
      'hora_agendamento', c.hora_agendamento,
      'instalador_id', COALESCE(c.instalador_id, v_alvo_id),
      'instalador', jsonb_build_object(
        'id', p.id,
        'nome', p.nome,
        'endereco_instalacao', p.endereco_instalacao,
        'valor_com_bloqueador', p.valor_instalacao_com_bloqueador,
        'valor_sem_bloqueador', p.valor_instalacao_sem_bloqueador
      ),
      'veiculos', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', v.id,
          'placa', v.placa,
          'modelo', v.marca_modelo,
          'tipo_veiculo', v.tipo_veiculo,
          'horimetro_horas', v.horimetro_horas,
          'rastreador_id', COALESCE(v.rastreador_id, inst_v.rastreador_id, c.kit_determinado_id),
          'rastreador_imei', COALESCE(
            CASE WHEN UPPER(TRIM(v.rastreador_imei)) IN ('PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR', '') THEN NULL ELSE v.rastreador_imei END,
            rk.imei,
            CASE WHEN UPPER(TRIM(inst_v.rastreador_imei)) IN ('PENDENTE', 'A DEFINIR', 'AGUARDANDO ESTOQUE', 'A CONFERIR', 'SEM RASTREADOR', '') THEN NULL ELSE inst_v.rastreador_imei END,
            v.rastreador_imei
          )
        ))
        FROM public.veiculos v
        LEFT JOIN public.instalacoes inst_v ON (inst_v.veiculo_id = v.id OR (inst_v.cliente_id = v.cliente_id AND UPPER(TRIM(inst_v.placa)) = UPPER(TRIM(v.placa)) AND v.placa NOT IN ('A DEFINIR', 'SEM PLACA', 'SEMPLACA')))
        LEFT JOIN public.rastreadores rk ON rk.id = COALESCE(v.rastreador_id, inst_v.rastreador_id, c.kit_determinado_id)
        WHERE v.cliente_id = c.id
      ), '[]'::JSONB)
    ) ORDER BY c.created_at DESC
  ), '[]'::JSONB)
  INTO v_agendamentos
  FROM public.clientes c
  LEFT JOIN public.profiles p ON p.id = COALESCE(c.instalador_id, v_alvo_id)
  WHERE (
    (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
    OR c.instalador_id = v_alvo_id
    OR EXISTS (SELECT 1 FROM public.instalacoes inst WHERE inst.cliente_id = c.id AND (inst.instalador_id = v_alvo_id OR (inst.instalador_id IS NULL AND c.instalador_id = v_alvo_id)))
  )
  AND (c.status_agendamento IS DISTINCT FROM 'concluido' OR c.status = 'aguardando_instalacao');

  SELECT
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pendente' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN (status = 'concluida' OR status = 'concluida_com_pendencia') AND status_pagamento = 'pago' THEN valor_instalacao ELSE 0 END), 0.00),
    COALESCE(SUM(CASE WHEN status NOT IN ('concluida', 'concluida_com_pendencia') AND data_agendamento IS NOT NULL THEN valor_instalacao ELSE 0 END), 0.00),
    COUNT(CASE WHEN status NOT IN ('concluida', 'concluida_com_pendencia') AND data_agendamento IS NOT NULL THEN 1 END),
    COUNT(CASE WHEN status NOT IN ('concluida', 'concluida_com_pendencia') AND data_agendamento IS NULL THEN 1 END)
  INTO
    v_total_a_receber,
    v_total_recebido,
    v_valor_previsto_agendados,
    v_total_agendados_qtd,
    v_total_a_agendar_qtd
  FROM public.instalacoes
  WHERE (v_role IN ('superadmin', 'adm', 'operador') AND p_instalador_id IS NULL)
     OR instalador_id = v_alvo_id;

  v_resumo := jsonb_build_object(
    'a_receber', v_total_a_receber,
    'recebido', v_total_recebido,
    'agendados_qtd', v_total_agendados_qtd,
    'a_agendar_qtd', v_total_a_agendar_qtd,
    'valor_previsto_agendados', v_valor_previsto_agendados
  );

  RETURN jsonb_build_object(
    'success', true,
    'ordens', v_ordens,
    'agendamentos', v_agendamentos,
    'resumo', v_resumo
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.instalador_obter_minhas_demandas(UUID) TO authenticated;

-- 3. Higienização idempotente dos registros com marca/modelo/ano sujos
--    Preserva o agendamento real (ex: 2026-11-13) já definido pelo instalador.
UPDATE public.instalacoes i
SET
  marca = 'GM',
  modelo = 'MONTANA SPORT',
  ano = COALESCE(i.ano, v.ano),
  updated_at = NOW()
FROM public.veiculos v
WHERE i.id = '6577b629-2557-4a22-99ba-4e0467ef30e7'
  AND v.id = i.veiculo_id
  AND UPPER(TRIM(COALESCE(i.marca, ''))) IN ('A DEFINIR', 'GERAL', '');

UPDATE public.instalacoes
SET
  marca = '',
  updated_at = NOW()
WHERE UPPER(TRIM(COALESCE(marca, ''))) = 'A DEFINIR';

NOTIFY pgrst, 'reload schema';


